        </div>
      </div>

      {percentage >= 100 && (
          <div className="absolute top-0 right-0 bg-emerald-500 text-white text-[8px] font-black px-3 py-1 uppercase tracking-widest rounded-bl-xl shadow-lg animate-bounce">
            Meta Batida! 🏆
