import React, { useMemo, useState, useEffect } from 'react';
import type { ReadingStats, Book, DateFilter, Recommendation } from '../types';
import { StatCard } from './StatCard';
import { CurrentlyReading } from './CurrentlyReading';
import { MonthlyChart } from './MonthlyChart';
import { TypePieChart } from './TypePieChart';
import { ReadingGoal } from './ReadingGoal';
import { Recommendations } from './Recommendations';
import { BookOpenIcon, ChartBarIcon, StarIcon, TagIcon, HeartIcon } from './Icons';
import { getAIRecommendations } from '../services/geminiService';

interface DashboardProps {
  stats: ReadingStats;
  currentlyReading: Book | null;
  updateBook: (book: Book) => void;
  dateFilter: DateFilter;
  setDateFilter: (filter: DateFilter) => void;
  selectedYear: number;
  setSelectedYear: (year: number) => void;
  availableYears: number[];
  books: Book[];
  customRange?: { start: string; end: string };
  setCustomRange?: (range: { start: string; end: string }) => void;
}

export const Dashboard: React.FC<DashboardProps> = ({ 
  stats, 
  currentlyReading, 
  updateBook, 
  dateFilter, 
  setDateFilter,
  selectedYear,
  setSelectedYear,
  availableYears,
  books,
  customRange,
  setCustomRange 
}) => {
  const [readingGoal, setReadingGoal] = useState(() => {
    const saved = localStorage.getItem('biblio_tech_goal');
    return saved ? parseInt(saved, 10) : 12;
  });

  const [aiRecs, setAiRecs] = useState<Recommendation[]>([]);
  const [isLoadingRecs, setIsLoadingRecs] = useState(false);

  useEffect(() => {
    localStorage.setItem('biblio_tech_goal', readingGoal.toString());
  }, [readingGoal]);

  const fetchRecs = async () => {
    setIsLoadingRecs(true);
    const readBooks = books
      .filter(b => b.status === 'Lido')
      .map(b => ({ title: b.title, genre: b.genre }));

    if (readBooks.length > 0) {
      const recs = await getAIRecommendations(readBooks);
      setAiRecs(recs);
    }
    setIsLoadingRecs(false);
  };

  useEffect(() => {
    // Busca automática se houver livros lidos e nenhuma recomendação salva
    if (aiRecs.length === 0) {
        fetchRecs();
    }
  }, []);

  const formatDate = (dateStr?: string) => {
    if (!dateStr) return '';
    const [y, m, d] = dateStr.split('-');
    return `${d}/${m}/${y.substring(2)}`;
  };

  const periodTitle = useMemo(() => {
    if (dateFilter === 'thisYear') return 'Ano Atual';
    if (dateFilter === 'allTime') return 'Todo o Período';
    if (dateFilter === 'specificYear') return `Ano de ${selectedYear}`;
    if (dateFilter === 'custom' && customRange) {
        return `De ${formatDate(customRange.start)} a ${formatDate(customRange.end)}`;
    }
    return '';
  }, [dateFilter, customRange, selectedYear]);

  return (
    <div className="max-w-7xl mx-auto space-y-12 pb-16">
      {/* --- Cabeçalho e Filtros --- */}
      <div className="flex flex-col xl:flex-row justify-between items-start xl:items-center gap-6">
        <div>
            <h2 className="text-3xl font-bold font-serif text-slate-900 tracking-tight">Visão Geral</h2>
            <p className="text-slate-500 text-sm font-medium mt-1">Sua jornada intelectual em números e descobertas.</p>
        </div>

        <div className="flex flex-col sm:flex-row items-stretch sm:items-center gap-4 bg-white p-2 rounded-2xl border border-slate-200 shadow-sm w-full sm:w-auto">
            <div className="flex items-center p-1 bg-slate-50 rounded-xl border border-slate-100">
                <button
                    onClick={() => setDateFilter('thisYear')}
                    className={`px-4 py-2 text-xs font-black uppercase tracking-wider rounded-lg transition-all ${dateFilter === 'thisYear' ? 'bg-primary text-white shadow-md' : 'text-slate-400 hover:text-primary'}`}
                >
                    Ano
                </button>
                <button
                    onClick={() => setDateFilter('specificYear')}
                    className={`px-4 py-2 text-xs font-black uppercase tracking-wider rounded-lg transition-all ${dateFilter === 'specificYear' ? 'bg-primary text-white shadow-md' : 'text-slate-400 hover:text-primary'}`}
                >
                    Anos
                </button>
                <button
                    onClick={() => setDateFilter('allTime')}
                    className={`px-4 py-2 text-xs font-black uppercase tracking-wider rounded-lg transition-all ${dateFilter === 'allTime' ? 'bg-primary text-white shadow-md' : 'text-slate-400 hover:text-primary'}`}
                >
                    Tudo
                </button>
                <button
                    onClick={() => setDateFilter('custom')}
                    className={`px-4 py-2 text-xs font-black uppercase tracking-wider rounded-lg transition-all ${dateFilter === 'custom' ? 'bg-primary text-white shadow-md' : 'text-slate-400 hover:text-primary'}`}
                >
                    Agenda
                </button>
            </div>

            {dateFilter === 'specificYear' && (
                <div className="flex items-center gap-2 animate-in fade-in slide-in-from-right-4 duration-500">
                    <select 
                        value={selectedYear}
                        onChange={(e) => setSelectedYear(Number(e.target.value))}
                        className="bg-white border border-slate-200 rounded-lg px-3 py-1.5 text-xs font-black uppercase tracking-widest text-slate-700 outline-none focus:border-primary transition-colors cursor-pointer"
                    >
                        {availableYears.map(year => (
                            <option key={year} value={year}>{year}</option>
                        ))}
                    </select>
                </div>
            )}
        </div>
      </div>

      {/* --- Grid Principal Superior --- */}
      <div className="grid grid-cols-1 lg:grid-cols-12 gap-8">
        <div className="lg:col-span-8">
          {currentlyReading ? (
            <CurrentlyReading book={currentlyReading} updateBook={updateBook} />
          ) : (
            <div className="bg-white border-2 border-dashed border-slate-200 p-12 rounded-[2.5rem] flex flex-col items-center justify-center text-center h-full">
              <div className="bg-slate-50 p-4 rounded-full mb-4">
                <BookOpenIcon className="h-10 w-10 text-slate-300" />
              </div>
              <h2 className="text-xl font-bold text-slate-900 mb-2">Nenhuma leitura ativa</h2>
              <p className="text-slate-400 max-w-xs">Sua estante está cheia de aventuras esperando por você.</p>
            </div>
          )}
        </div>
        <div className="lg:col-span-4 flex flex-col gap-6">
          <ReadingGoal 
            current={stats.yearly.booksRead} 
            goal={readingGoal} 
            onSetGoal={setReadingGoal} 
          />
          <StatCard 
            icon={<StarIcon className="h-6 w-6" />} 
            title="Avaliação Média" 
            value={stats.yearly.avgRating.toFixed(1)}
            subtitle="estrelas"
          />
        </div>
      </div>

      {/* --- Estatísticas em Linha --- */}
      <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-6">
        <StatCard 
            icon={<BookOpenIcon className="h-6 w-6" />} 
            title="Total Lidos"
            value={stats.yearly.booksRead.toString()} 
            subtitle={periodTitle}
        />
        <StatCard 
            icon={<TagIcon className="h-6 w-6" />} 
            title="Páginas Lidas"
            value={stats.yearly.pagesRead.toLocaleString('pt-BR')}
            subtitle={periodTitle}
        />
        <StatCard 
            icon={<ChartBarIcon className="h-6 w-6" />} 
            title="Na Fila (TBR)" 
            value={stats.tbrCount.toString()}
            subtitle="livros p/ ler"
        />
        <StatCard 
            icon={<HeartIcon className="h-6 w-6" />} 
            title="Lista de Desejos" 
            value={stats.wishlistCount.toString()}
            subtitle="interesse futuro"
        />
      </div>

      {/* --- Recomendações de IA --- */}
      <Recommendations 
        suggestions={aiRecs} 
        isLoading={isLoadingRecs} 
        onRefresh={fetchRecs} 
      />

      {/* --- Gráfico de Evolução --- */}
      <div className="bg-white p-8 rounded-[2.5rem] shadow-soft border border-slate-100 transition-all hover:shadow-xl">
        <div className="flex flex-col md:flex-row justify-between items-start md:items-center mb-8 gap-4">
          <div>
            <h2 className="text-2xl font-bold font-serif text-slate-900">Evolução de Leitura</h2>
            <p className="text-slate-400 text-sm mt-1 font-medium italic">Dados baseados no período: {periodTitle}</p>
          </div>
          <div className="flex gap-6">
            <div className="flex items-center gap-2">
                <div className="w-3 h-3 rounded-sm bg-primary"></div>
                <span className="text-[10px] font-bold text-slate-500 uppercase tracking-widest">Livros</span>
            </div>
            <div className="flex items-center gap-2">
                <div className="w-3 h-3 rounded-full bg-slate-200 border border-slate-300"></div>
                <span className="text-[10px] font-bold text-slate-500 uppercase tracking-widest">Páginas</span>
            </div>
          </div>
        </div>
        <MonthlyChart data={stats.monthly} />
      </div>

      {/* --- Distribuição por Categoria --- */}
      <div className="bg-white p-8 rounded-[2.5rem] shadow-soft border border-slate-100">
          <h2 className="text-xl font-bold font-serif text-slate-900 mb-6">Distribuição por Categoria</h2>
          <div className="h-[300px]">
              <TypePieChart data={stats.byType} />
          </div>
      </div>
    </div>
  );
};

import React, { useState, useMemo } from 'react';
import { useBookData } from './hooks/useBookData';
import { Header } from './components/Header';
import { Dashboard } from './components/Dashboard';
import { AddBookModal } from './components/AddBookModal';
import { PlusIcon } from './components/Icons';
import type { Book, NewBook } from './types';
import { BookList } from './components/BookList';
import { ConfirmationModal } from './confirmationModal';
import { BookStatus } from './types';
import { Wishlist } from './components/Wishlist';
import { BottomNav } from './components/BottomNav';

export default function App() {
  const { 
    books, 
    stats, 
    currentlyReading, 
    addBook, 
    updateBook, 
    deleteBook, 
    dateFilter, 
    setDateFilter,
    selectedYear,
    setSelectedYear,
    availableYears,
    customRange,
    setCustomRange,
    isLocalMode,
    isLoading
  } = useBookData();

  const [isModalOpen, setIsModalOpen] = useState(false);
  const [view, setView] = useState<'dashboard' | 'list' | 'wishlist'>('dashboard');
  const [editingBook, setEditingBook] = useState<Book | null>(null);
  const [deletingBook, setDeletingBook] = useState<Book | null>(null);
  const [defaultStatusForModal, setDefaultStatusForModal] = useState<BookStatus | undefined>();
  const [toastMessage, setToastMessage] = useState<string | null>(null);

  const showToast = (message: string) => {
    setToastMessage(message);
    setTimeout(() => setToastMessage(null), 3500);
  };

  const handleAddBook = async (newBook: NewBook) => {
    try {
      await addBook(newBook);
      setIsModalOpen(false);
      setEditingBook(null);
      showToast(`"${newBook.title}" salvo com sucesso!`);
    } catch (error) {
      showToast("Erro ao salvar o livro.");
    }
  };

  const handleUpdateBook = async (updatedBook: Book) => {
    try {
      await updateBook(updatedBook);
      setIsModalOpen(false);
      setEditingBook(null);
      if (updatedBook.status === BookStatus.Read) {
          showToast(`Progresso salvo: Parabéns por concluir "${updatedBook.title}"!`);
      } else {
          showToast(`"${updatedBook.title}" atualizado.`);
      }
    } catch (error) {
      showToast("Erro ao atualizar o livro.");
    }
  };

  const openAddModal = (defaultStatus?: BookStatus) => {
    setEditingBook(null);
    setDefaultStatusForModal(defaultStatus);
    setIsModalOpen(true);
  };

  const shelfBooks = useMemo(() => books.filter(book => book.status !== BookStatus.Wishlist), [books]);
  const wishlistBooks = useMemo(() => books.filter(book => book.status === BookStatus.Wishlist), [books]);

  const [isFading, setIsFading] = useState(false);

  const handleSetView = (newView: 'dashboard' | 'list' | 'wishlist') => {
    if (view !== newView) {
      setIsFading(true);
      setTimeout(() => {
        setView(newView);
        setIsFading(false);
      }, 200);
    }
  };

  if (isLoading) {
    return (
      <div className="min-h-screen bg-background flex flex-col items-center justify-center p-4">
          <div className="w-12 h-12 border-4 border-primary border-t-transparent rounded-full animate-spin mb-4"></div>
          <p className="text-[10px] font-black uppercase tracking-[0.2em] text-slate-400">Sincronizando Biblioteca...</p>
      </div>
    );
  }

  return (
    <div className="min-h-screen bg-background text-text-main pb-24 relative">
      <Header onLogoClick={() => handleSetView('dashboard')} />

      {isLocalMode && (
        <div className="bg-amber-50 border-b border-amber-100 px-6 py-2 flex items-center justify-center gap-3">
            <span className="w-2 h-2 rounded-full bg-amber-400 animate-pulse"></span>
            <p className="text-[9px] font-black uppercase tracking-widest text-amber-700">
                Modo Local Ativo: Configure a tabela 'books' no Supabase para sincronização em nuvem.
            </p>
        </div>
      )}

      <main className={`p-4 md:p-8 transition-all duration-300 transform ${isFading ? 'opacity-0 -translate-y-2' : 'opacity-100 translate-y-0'}`}>
        {view === 'dashboard' && (
          <Dashboard 
            stats={stats} 
            currentlyReading={currentlyReading} 
            updateBook={handleUpdateBook}
            dateFilter={dateFilter}
            setDateFilter={setDateFilter} 
            selectedYear={selectedYear}
            setSelectedYear={setSelectedYear}
            availableYears={availableYears}
            books={books}
            customRange={customRange}
            setCustomRange={setCustomRange}
