      {deletingBook && (
        <ConfirmationModal
          isOpen={!!deletingBook}
          onClose={() => setDeletingBook(null)}
          onConfirm={async () => { 
            const title = deletingBook.title;
            await deleteBook(deletingBook.id); 
            setDeletingBook(null); 
            showToast(`"${title}" removido.`);
          }}
          title="Excluir Registro"
