import type { Book } from '../types';
import { supabase } from './supabase';

const TABLE_NAME = 'books';
const LOCAL_STORAGE_KEY = 'biblio_tech_local_db';

export class DatabaseService {
  private useLocalStorage = false;

  private getLocalBooks(): Book[] {
    const data = localStorage.getItem(LOCAL_STORAGE_KEY);
    return data ? JSON.parse(data) : [];
  }

  private saveLocalBooks(books: Book[]): void {
    localStorage.setItem(LOCAL_STORAGE_KEY, JSON.stringify(books));
  }

  async getAllBooks(): Promise<Book[]> {
    try {
      const { data, error } = await supabase
        .from(TABLE_NAME)
        .select('*')
        .order('dateAdded', { ascending: false });

      if (error) {
        // Erro 42P01: Tabela não existe
        if (error.code === '42P01' || error.message?.includes('relation "books" does not exist')) {
          this.logSchemaAdvice('table');
          this.useLocalStorage = true;
          return this.getLocalBooks();
        }
        throw error;
      }

      this.useLocalStorage = false;
      return (data as Book[]) || [];
    } catch (err: any) {
      console.warn('Fallback para Armazenamento Local:', err.message);
      this.useLocalStorage = true;
      return this.getLocalBooks();
    }
  }

  async saveBook(book: Book): Promise<void> {
    if (this.useLocalStorage) {
      this.updateLocalEntry(book);
      return;
    }

    try {
      const { error } = await supabase
        .from(TABLE_NAME)
        .upsert(book);

      if (error) {
        // Erro de coluna ausente (geralmente erro 42703 no Postgres)
        if (error.message?.includes('column') && error.message?.includes('not found')) {
            const columnName = error.message.match(/'([^']+)'/)?.[1] || 'notes';
            this.logSchemaAdvice('column', columnName);
        }
        throw error;
      }
    } catch (err: any) {
      console.error('Erro de sincronização, salvando localmente:', err.message);
      this.updateLocalEntry(book);
    }
  }

  private updateLocalEntry(book: Book) {
    const books = this.getLocalBooks();
    const index = books.findIndex(b => b.id === book.id);
    if (index >= 0) {
      books[index] = book;
    } else {
      books.unshift(book);
    }
    this.saveLocalBooks(books);
  }

  async deleteBook(id: string): Promise<void> {
    if (this.useLocalStorage) {
      const books = this.getLocalBooks().filter(b => b.id !== id);
      this.saveLocalBooks(books);
      return;
    }

    try {
      const { error } = await supabase
        .from(TABLE_NAME)
        .delete()
        .eq('id', id);

      if (error) throw error;
    } catch (err: any) {
      console.error('Erro ao deletar:', err.message);
    }
  }

  private logSchemaAdvice(type: 'table' | 'column', detail?: string) {
    const title = type === 'table' ? 'TABELA NÃO ENCONTRADA' : 'COLUNA FALTANDO';
    const message = type === 'table' 
        ? "Abra o SQL Editor no Supabase e execute o script de criação da tabela 'books'."
        : `A coluna '${detail}' não existe na tabela 'books'. Execute o comando de migração no SQL Editor.`;
    const sql = type === 'table' 
        ? "Consulte o arquivo 'instrucoes_sql.txt' para o script completo."
        : `ALTER TABLE public.books ADD COLUMN IF NOT EXISTS "${detail}" TEXT;`;

    console.log(`
%c 💡 ${title} %c
${message}

%c SQL Sugerido: %c
${sql}

%c Nota: %c Após rodar o SQL, recarregue a página para limpar o cache do Supabase.
`, 
'color: #ffffff; background: #2563eb; padding: 2px 5px; border-radius: 3px; font-weight: bold;', 
'color: #475569;',
'color: #059669; font-weight: bold;',
'color: #059669; font-style: italic;',
'color: #e11d48; font-weight: bold;',
'color: #475569;');
  }
}

export const dbService = new DatabaseService();

import { useState, useMemo, useCallback, useEffect, useRef } from 'react';
import type { Book, ReadingStats, NewBook, DateFilter, MonthlyStat, TypeStat } from '../types';
import { BookStatus, BookType } from '../types';
import { dbService } from '../services/database';
import { generateBookCover } from '../services/geminiService';

const INITIAL_BOOKS: Book[] = [
  {
    id: '1',
    title: 'O Senhor dos Anéis - A Sociedade do Anel',
    author: 'J.R.R. Tolkien',
    pages: 434,
    genre: 'Aventura, Fantasia',
    type: BookType.Book,
    status: BookStatus.Reading,
    currentPage: 152,
    dateAdded: '2024-01-15',
    dateStarted: '2024-01-10',
    coverImageUrl: 'https://picsum.photos/seed/lotr/400/600',
    summary: 'Em uma terra fantástica e única, um hobbit recebe de presente de seu tio um anel mágico e maligno.',
  }
];

const MONTHS = ['Janeiro', 'Fevereiro', 'Março', 'Abril', 'Maio', 'Junho', 'Julho', 'Agosto', 'Setembro', 'Outubro', 'Novembro', 'Dezembro'];

export const useBookData = () => {
  const [books, setBooks] = useState<Book[]>([]);
  const [isLoading, setIsLoading] = useState(true);
  const [isLocalMode, setIsLocalMode] = useState(false);
  const [dateFilter, setDateFilter] = useState<DateFilter>('allTime');
  const [selectedYear, setSelectedYear] = useState<number>(new Date().getFullYear());
  const [customRange, setCustomRange] = useState({ 
    start: new Date(new Date().getFullYear(), 0, 1).toISOString().split('T')[0],
    end: new Date().toISOString().split('T')[0]
  });

  const autoGenRunning = useRef(false);

  const loadData = useCallback(async () => {
    setIsLoading(true);
    try {
      const storedBooks = await dbService.getAllBooks();
      if (storedBooks.length === 0) {
        setBooks(INITIAL_BOOKS);
      } else {
        setBooks(storedBooks);
      }
    } catch (error: any) {
      console.error('Erro ao carregar dados:', error.message || 'Erro desconhecido');
      setBooks(INITIAL_BOOKS);
      setIsLocalMode(true);
    } finally {
      setIsLoading(false);
    }
  }, []);

  // Efeito para carregar dados iniciais
  useEffect(() => {
    loadData();
  }, [loadData]);

  // Função para atualizar um livro (usada internamente e exportada)
  const updateBook = useCallback(async (updatedBook: Book) => {
    await dbService.saveBook(updatedBook);
    setBooks(prev => prev.map(b => b.id === updatedBook.id ? updatedBook : b));
  }, []);

  // Efeito para geração automática de capas ausentes
  useEffect(() => {
    if (isLoading || books.length === 0 || autoGenRunning.current) return;

    const generateCovers = async () => {
      autoGenRunning.current = true;

      // Filtra livros que não têm capa ou usam o placeholder do picsum
      const booksWithoutCover = books.filter(b => 
        !b.coverImageUrl || 
        b.coverImageUrl.includes('picsum.photos')
      );

      if (booksWithoutCover.length > 0) {
        console.log(`[BiblioTech] Detectados ${booksWithoutCover.length} livros sem capa. Iniciando geração via IA...`);

        // Processa sequencialmente para evitar excesso de requisições simultâneas
        for (const book of booksWithoutCover) {
          try {
            // Gera a capa baseada no título, gênero e tipo
            const newCoverUrl = await generateBookCover(book.title, book.genre, book.type);

            // Se a imagem gerada for diferente da atual (e não for erro)
            if (newCoverUrl && !newCoverUrl.includes('picsum.photos')) {
              await updateBook({ ...book, coverImageUrl: newCoverUrl });
              console.log(`[BiblioTech] Capa gerada para: ${book.title}`);
            }
          } catch (err) {
            console.error(`[BiblioTech] Falha ao gerar capa para ${book.title}:`, err);
          }
          // Pequeno delay entre gerações para estabilidade
          await new Promise(r => setTimeout(r, 500));
        }
      }

      autoGenRunning.current = false;
    };

    generateCovers();
  }, [isLoading, books.length, updateBook]);

  const availableYears = useMemo(() => {
    const years = new Set<number>();
    years.add(new Date().getFullYear());
    books.forEach(b => {
      const date = b.dateFinished || b.dateAdded;
      if (date) {
          const year = new Date(date).getFullYear();
          if (!isNaN(year)) years.add(year);
      }
    });
    return Array.from(years).sort((a, b) => b - a);
  }, [books]);

  const stats: ReadingStats = useMemo(() => {
    const filtered = books.filter(b => {
      if (b.status !== BookStatus.Read) return false;
      const date = b.dateFinished ? new Date(b.dateFinished) : null;
      if (!date) return false;

      if (dateFilter === 'thisYear') {
        return date.getFullYear() === new Date().getFullYear();
      }
      if (dateFilter === 'specificYear') {
        return date.getFullYear() === selectedYear;
      }
      if (dateFilter === 'custom') {
        const start = new Date(customRange.start);
        const end = new Date(customRange.end);
        return date >= start && date <= end;
      }
      return true;
    });

    const yearly = {
      booksRead: filtered.length,
      pagesRead: filtered.reduce((acc, b) => acc + (b.pages || 0), 0),
      avgRating: filtered.length > 0 ? filtered.reduce((acc, b) => acc + (b.rating || 0), 0) / filtered.length : 0
    };

    const monthly: MonthlyStat[] = MONTHS.map((m, idx) => {
      const monthBooks = filtered.filter(b => {
        const dateStr = b.dateFinished;
        if (!dateStr) return false;
        return new Date(dateStr).getMonth() === idx;
      });
      return {
        month: m,
        booksRead: monthBooks.length,
        pagesRead: monthBooks.reduce((acc, b) => acc + (b.pages || 0), 0),
        avgRating: monthBooks.length > 0 ? monthBooks.reduce((acc, b) => acc + (b.rating || 0), 0) / monthBooks.length : 0
      };
    });

    const byType: TypeStat[] = [BookType.Book, BookType.HQ].map(type => {
      const typeBooks = filtered.filter(b => b.type === type);
      return {
        type,
        count: typeBooks.length,
        pages: typeBooks.reduce((acc, b) => acc + (b.pages || 0), 0),
        avgRating: typeBooks.length > 0 ? typeBooks.reduce((acc, b) => acc + (b.rating || 0), 0) / typeBooks.length : 0
      };
    });

    return {
      tbrCount: books.filter(b => b.status === BookStatus.TBR).length,
      wishlistCount: books.filter(b => b.status === BookStatus.Wishlist).length,
      yearly,
      monthly,
      byType
    };
  }, [books, dateFilter, selectedYear, customRange]);

  const currentlyReading = useMemo(() => {
    return books.find(b => b.status === BookStatus.Reading) || null;
  }, [books]);

  const addBook = async (newBook: NewBook) => {
    const book: Book = {
      ...newBook,
      id: crypto.randomUUID(),
      dateAdded: new Date().toISOString().split('T')[0]
    };
    await dbService.saveBook(book);
    setBooks(prev => [book, ...prev]);
  };

  const deleteBook = async (id: string) => {
    await dbService.deleteBook(id);
    setBooks(prev => prev.filter(b => b.id !== id));
  };

  return {
    books,
    stats,
    currentlyReading,
    addBook,
    updateBook,
    deleteBook,
    dateFilter,
    setDateFilter,
    selectedYear,
    setSelectedYear,
    availableYears,
    customRange,
    setCustomRange,
    isLoading,
    isLocalMode
  };
};

import { GoogleGenAI, GenerateContentResponse, Type } from "@google/genai";
import { Recommendation } from "../types";

const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

export const generateBookSummary = async (title: string, author: string): Promise<string> => {
  if (!process.env.API_KEY) return "A IA está indisponível no momento.";
  try {
    const prompt = `Escreva um resumo curto (um parágrafo) e envolvente em Português para o livro "${title}" de ${author}. Não dê spoilers.`;
    const response: GenerateContentResponse = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: prompt,
    });
    return response.text || "Não foi possível gerar um resumo.";
  } catch (error) {
    console.error("Error generating book summary:", error);
    return "Erro ao gerar resumo. Tente novamente.";
  }
};

export const generateBookCover = async (title: string, genre: string, type: string): Promise<string> => {
  if (!process.env.API_KEY) return `https://picsum.photos/seed/${encodeURIComponent(title)}/400/600`;
  try {
    const prompt = `Capa de livro profissional para a obra "${title}". 
    Gênero principal: ${genre}. 
    Formato: ${type}. 
    Estilo visual: Minimalista, cinematográfico e evocativo. 
    A arte deve capturar a essência do título e ser esteticamente agradável. Sem texto na imagem, apenas arte conceitual de alta qualidade.`;

    const response: GenerateContentResponse = await ai.models.generateContent({
        model: 'gemini-2.5-flash-image',
        contents: {
            parts: [{ text: prompt }]
        },
        config: {
            imageConfig: {
                aspectRatio: "3:4"
            }
        }
    });

    if (response.candidates?.[0]?.content?.parts) {
      for (const part of response.candidates[0].content.parts) {
          if (part.inlineData) {
              const base64EncodeString: string = part.inlineData.data;
              return `data:image/png;base64,${base64EncodeString}`;
          }
      }
    }

    return `https://picsum.photos/seed/${encodeURIComponent(title)}/400/600`;
  } catch (error) {
    console.error("Error generating book cover:", error);
    return `https://picsum.photos/seed/${encodeURIComponent(title)}/400/600`;
  }
};

export const getAIRecommendations = async (readBooks: { title: string, genre: string }[]): Promise<Recommendation[]> => {
  if (!process.env.API_KEY || readBooks.length === 0) return [];

  const booksDescription = readBooks.map(b => `${b.title} (${b.genre})`).join(', ');
  const prompt = `Com base nos seguintes livros que eu já li: ${booksDescription}. Recomende 3 livros novos que eu possa gostar. Explique o motivo de forma curta e direta em Português.`;

  try {
    const response: GenerateContentResponse = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: prompt,
      config: {
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.ARRAY,
          items: {
            type: Type.OBJECT,
            properties: {
              title: { type: Type.STRING },
              author: { type: Type.STRING },
              reason: { type: Type.STRING },
              genre: { type: Type.STRING },
            },
            required: ["title", "author", "reason", "genre"]
          }
        }
      }
    });

    return JSON.parse(response.text || '[]');
  } catch (error) {
    console.error("Error fetching AI recommendations:", error);
    return [];
  }
};

