import type { Book } from '../types';
import { supabase } from './supabase';

const TABLE_NAME = 'books';
const LOCAL_STORAGE_KEY = 'biblio_tech_local_db';

export class DatabaseService {
  private useLocalStorage = false;
  private onSchemaErrorCallback?: (type: 'table' | 'column', detail?: string) => void;

  setSchemaErrorCallback(cb: (type: 'table' | 'column', detail?: string) => void) {
    this.onSchemaErrorCallback = cb;
  }

  private getLocalBooks(): Book[] {
    const data = localStorage.getItem(LOCAL_STORAGE_KEY);
    return data ? JSON.parse(data) : [];
  }

  private saveLocalBooks(books: Book[]): void {
    localStorage.setItem(LOCAL_STORAGE_KEY, JSON.stringify(books));
  }

  async getAllBooks(): Promise<Book[]> {
    try {
      const { data, error } = await supabase
        .from(TABLE_NAME)
        .select('*')
        .order('dateAdded', { ascending: false });

      if (error) {
        // Erro 42P01: Tabela não existe
        if (error.code === '42P01' || error.message?.includes('relation "books" does not exist')) {
          this.handleSchemaError('table');
          this.useLocalStorage = true;
          return this.getLocalBooks();
        }
        throw error;
      }

      this.useLocalStorage = false;
      return (data as Book[]) || [];
    } catch (err: any) {
      console.warn('Fallback para Armazenamento Local:', err.message);
      this.useLocalStorage = true;
      return this.getLocalBooks();
    }
  }

  async saveBook(book: Book): Promise<void> {
    if (this.useLocalStorage) {
      this.updateLocalEntry(book);
      return;
    }

    try {
      const { error } = await supabase
        .from(TABLE_NAME)
        .upsert(book);

      if (error) {
        // Erro de coluna ausente (42703 ou erro de cache do PostgREST)
        if (error.message?.includes('column') && (error.message?.includes('not found') || error.message?.includes('schema cache'))) {
            const columnName = error.message.match(/'([^']+)'/)?.[1] || 'notes';
            this.handleSchemaError('column', columnName);
            // Fallback imediato após erro de esquema para garantir persistência
            this.useLocalStorage = true;
        }
        throw error;
      }
    } catch (err: any) {
      console.error('Erro de sincronização, salvando localmente:', err.message);
      this.updateLocalEntry(book);
    }
  }

  private updateLocalEntry(book: Book) {
    const books = this.getLocalBooks();
    const index = books.findIndex(b => b.id === book.id);
    if (index >= 0) {
      books[index] = book;
    } else {
      books.unshift(book);
    }
    this.saveLocalBooks(books);
  }

  async deleteBook(id: string): Promise<void> {
    if (this.useLocalStorage) {
      const books = this.getLocalBooks().filter(b => b.id !== id);
      this.saveLocalBooks(books);
      return;
    }

    try {
      const { error } = await supabase
        .from(TABLE_NAME)
        .delete()
        .eq('id', id);

      if (error) throw error;
    } catch (err: any) {
      console.error('Erro ao deletar:', err.message);
    }
  }

  private handleSchemaError(type: 'table' | 'column', detail?: string) {
    this.logSchemaAdvice(type, detail);
    if (this.onSchemaErrorCallback) {
        this.onSchemaErrorCallback(type, detail);
    }
  }

  private logSchemaAdvice(type: 'table' | 'column', detail?: string) {
    const title = type === 'table' ? 'TABELA NÃO ENCONTRADA' : 'COLUNA FALTANDO OU CACHE EXPIRADO';
    const message = type === 'table' 
        ? "Abra o SQL Editor no Supabase e execute o script de criação da tabela 'books'."
        : `A coluna '${detail}' não foi encontrada na tabela 'books'. Execute o comando de migração e recarregue a página.`;
    const sql = type === 'table' 
        ? "Consulte o arquivo 'instrucoes_sql.txt' para o script completo."
        : `ALTER TABLE public.books ADD COLUMN IF NOT EXISTS "${detail}" TEXT;`;

    console.log(`
%c 💡 ${title} %c
${message}

%c SQL Sugerido: %c
${sql}

%c Nota: %c Se você já executou o SQL, recarregue a página para limpar o cache do Supabase.
`, 
'color: #ffffff; background: #2563eb; padding: 2px 5px; border-radius: 3px; font-weight: bold;', 
'color: #475569;',
'color: #059669; font-weight: bold;',
'color: #059669; font-style: italic;',
'color: #e11d48; font-weight: bold;',
'color: #475569;');
  }
}

