import { useState, useMemo, useCallback, useEffect, useRef } from 'react';
import type { Book, ReadingStats, NewBook, DateFilter, MonthlyStat, TypeStat } from '../types';
import { BookStatus, BookType } from '../types';
import { dbService } from '../services/database';
import { generateBookCover } from '../services/geminiService';

const INITIAL_BOOKS: Book[] = [
  {
    id: '1',
    title: 'O Senhor dos Anéis - A Sociedade do Anel',
    author: 'J.R.R. Tolkien',
    pages: 434,
    genre: 'Aventura, Fantasia',
    type: BookType.Book,
    status: BookStatus.Reading,
    currentPage: 152,
    dateAdded: '2024-01-15',
    dateStarted: '2024-01-10',
    coverImageUrl: 'https://picsum.photos/seed/lotr/400/600',
    summary: 'Em uma terra fantástica e única, um hobbit recebe de presente de seu tio um anel mágico e maligno.',
  }
];

const MONTHS = ['Janeiro', 'Fevereiro', 'Março', 'Abril', 'Maio', 'Junho', 'Julho', 'Agosto', 'Setembro', 'Outubro', 'Novembro', 'Dezembro'];

export const useBookData = () => {
  const [books, setBooks] = useState<Book[]>([]);
  const [isLoading, setIsLoading] = useState(true);
  const [isLocalMode, setIsLocalMode] = useState(false);
  const [schemaError, setSchemaError] = useState<{type: 'table' | 'column', detail?: string} | null>(null);
  const [dateFilter, setDateFilter] = useState<DateFilter>('allTime');
  const [selectedYear, setSelectedYear] = useState<number>(new Date().getFullYear());
  const [customRange, setCustomRange] = useState({ 
    start: new Date(new Date().getFullYear(), 0, 1).toISOString().split('T')[0],
    end: new Date().toISOString().split('T')[0]
  });

  const autoGenRunning = useRef(false);

  // Load books from database or fallback to initial data
  const loadData = useCallback(async () => {
    setIsLoading(true);
    try {
      dbService.setSchemaErrorCallback((type, detail) => {
          setSchemaError({ type, detail });
          setIsLocalMode(true);
      });

      const storedBooks = await dbService.getAllBooks();
      if (storedBooks.length === 0) {
        setBooks(INITIAL_BOOKS);
      } else {
        setBooks(storedBooks);
      }
    } catch (error: any) {
      console.error('Erro ao carregar dados:', error.message || 'Erro desconhecido');
      setBooks(INITIAL_BOOKS);
      setIsLocalMode(true);
    } finally {
      setIsLoading(false);
    }
  }, []);

  useEffect(() => {
    loadData();
  }, [loadData]);

  // CRUD Operations
  const addBook = useCallback(async (newBook: NewBook) => {
    const book: Book = {
      ...newBook,
      id: Math.random().toString(36).substring(2, 9),
      dateAdded: new Date().toISOString().split('T')[0],
    };
    await dbService.saveBook(book);
    setBooks(prev => [book, ...prev]);
  }, []);

  const updateBook = useCallback(async (updatedBook: Book) => {
    await dbService.saveBook(updatedBook);
    setBooks(prev => prev.map(b => b.id === updatedBook.id ? updatedBook : b));
  }, []);

  const deleteBook = useCallback(async (id: string) => {
    await dbService.deleteBook(id);
    setBooks(prev => prev.filter(b => b.id !== id));
  }, []);

  // Automatic cover generation for missing covers
  useEffect(() => {
    if (isLoading || books.length === 0 || autoGenRunning.current) return;

    const generateCovers = async () => {
      autoGenRunning.current = true;
      const booksWithoutCover = books.filter(b => 
        !b.coverImageUrl || 
        b.coverImageUrl.includes('picsum.photos')
      );

      if (booksWithoutCover.length > 0) {
        for (const book of booksWithoutCover) {
          try {
            const newCoverUrl = await generateBookCover(book.title, book.genre, book.type);
            if (newCoverUrl && !newCoverUrl.includes('picsum.photos')) {
              await updateBook({ ...book, coverImageUrl: newCoverUrl });
            }
          } catch (err) {
            console.error(`Erro ao gerar capa para ${book.title}:`, err);
          }
        }
      }
      autoGenRunning.current = false;
    };

    generateCovers();
  }, [isLoading, books, updateBook]);

  // UI Derived State
  const availableYears = useMemo(() => {
    const years = new Set<number>();
    years.add(new Date().getFullYear());
    books.forEach(book => {
      if (book.dateFinished) years.add(new Date(book.dateFinished).getFullYear());
      if (book.dateAdded) years.add(new Date(book.dateAdded).getFullYear());
    });
    return Array.from(years).sort((a, b) => b - a);
  }, [books]);

  const filteredBooks = useMemo(() => {
    return books.filter(book => {
      if (book.status !== BookStatus.Read) return true;
      if (!book.dateFinished) return true;

      const finishDate = new Date(book.dateFinished);
      if (dateFilter === 'thisYear') {
        return finishDate.getFullYear() === new Date().getFullYear();
      }
      if (dateFilter === 'specificYear') {
        return finishDate.getFullYear() === selectedYear;
      }
      if (dateFilter === 'custom') {
        const start = new Date(customRange.start);
        const end = new Date(customRange.end);
        return finishDate >= start && finishDate <= end;
      }
      return true;
    });
  }, [books, dateFilter, selectedYear, customRange]);

  // Statistics calculation for the dashboard
  const stats: ReadingStats = useMemo(() => {
    const readBooks = filteredBooks.filter(b => b.status === BookStatus.Read);

    const yearly = {
      booksRead: readBooks.length,
      pagesRead: readBooks.reduce((acc, b) => acc + (b.pages || 0), 0),
      avgRating: readBooks.length > 0 
        ? readBooks.reduce((acc, b) => acc + (b.rating || 0), 0) / (readBooks.filter(b => b.rating).length || 1)
        : 0
    };

    const monthly: MonthlyStat[] = MONTHS.map((month, index) => {
      const monthBooks = readBooks.filter(b => {
        if (!b.dateFinished) return false;
        return new Date(b.dateFinished).getMonth() === index;
      });
      return {
        month,
        booksRead: monthBooks.length,
        pagesRead: monthBooks.reduce((acc, b) => acc + (b.pages || 0), 0),
        avgRating: monthBooks.length > 0 
          ? monthBooks.reduce((acc, b) => acc + (b.rating || 0), 0) / (monthBooks.filter(b => b.rating).length || 1)
          : 0
      };
    });

    const byType: TypeStat[] = [BookType.Book, BookType.HQ].map(type => {
      const typeBooks = readBooks.filter(b => b.type === type);
      return {
        type,
        count: typeBooks.length,
        pages: typeBooks.reduce((acc, b) => acc + (b.pages || 0), 0),
        avgRating: typeBooks.length > 0 
          ? typeBooks.reduce((acc, b) => acc + (b.rating || 0), 0) / (typeBooks.filter(b => b.rating).length || 1)
          : 0
      };
    });

    return {
      tbrCount: books.filter(b => b.status === BookStatus.TBR).length,
      wishlistCount: books.filter(b => b.status === BookStatus.Wishlist).length,
      yearly,
      monthly,
      byType
    };
  }, [books, filteredBooks]);

  const currentlyReading = useMemo(() => {
    return books.find(b => b.status === BookStatus.Reading) || null;
  }, [books]);

  return {
    books,
    stats,
    currentlyReading,
    addBook,
    updateBook,
    deleteBook,
    dateFilter,
    setDateFilter,
    selectedYear,
    setSelectedYear,
    availableYears,
    customRange,
    setCustomRange,
    isLocalMode,
    isLoading
  };
};

import type { Book } from '../types';
import { supabase } from './supabase';

const TABLE_NAME = 'books';
const LOCAL_STORAGE_KEY = 'biblio_tech_local_db';

export class DatabaseService {
  private useLocalStorage = false;
  private onSchemaErrorCallback?: (type: 'table' | 'column', detail?: string) => void;

  setSchemaErrorCallback(cb: (type: 'table' | 'column', detail?: string) => void) {
    this.onSchemaErrorCallback = cb;
  }

  private getLocalBooks(): Book[] {
    const data = localStorage.getItem(LOCAL_STORAGE_KEY);
    return data ? JSON.parse(data) : [];
  }

  private saveLocalBooks(books: Book[]): void {
    localStorage.setItem(LOCAL_STORAGE_KEY, JSON.stringify(books));
  }

  async getAllBooks(): Promise<Book[]> {
    try {
      const { data, error } = await supabase
        .from(TABLE_NAME)
        .select('*')
        .order('dateAdded', { ascending: false });

      if (error) {
        // Erro 42P01: Tabela não existe ou erro de cache
        if (error.code === '42P01' || error.message?.includes('relation "books" does not exist') || error.message?.includes('schema cache')) {
          const type = error.message?.includes('column') ? 'column' : 'table';
          const detail = error.message.match(/'([^']+)'/)?.[1];
          this.handleSchemaError(type as any, detail);
          this.useLocalStorage = true;
          return this.getLocalBooks();
        }
        throw error;
      }

      this.useLocalStorage = false;
      return (data as Book[]) || [];
    } catch (err: any) {
      console.warn('Fallback para Armazenamento Local durante carregamento:', err.message);
      this.useLocalStorage = true;
      return this.getLocalBooks();
    }
  }

  async saveBook(book: Book): Promise<void> {
    if (this.useLocalStorage) {
      this.updateLocalEntry(book);
      return;
    }

    try {
      const { error } = await supabase
        .from(TABLE_NAME)
        .upsert(book);

      if (error) {
        // Detecção específica de erros de esquema (coluna ausente ou cache PostgREST)
        const isSchemaError = 
          error.code === '42703' || 
          error.message?.includes('column') || 
          error.message?.includes('schema cache');

        if (isSchemaError) {
            const columnName = error.message.match(/'([^']+)'/)?.[1] || 'notes';
            this.handleSchemaError('column', columnName);
            this.useLocalStorage = true; // Switch to local mode permanently for this session
            this.updateLocalEntry(book);
            return; // Prevent further throw to avoid redundant generic sync error logs
        }
        throw error;
      }
    } catch (err: any) {
      // Se não for um erro de esquema já tratado, loga como erro de sincronização genérico
      if (!this.useLocalStorage) {
        console.error('Erro de sincronização, salvando localmente:', err.message);
        this.updateLocalEntry(book);
      }
    }
  }

  private updateLocalEntry(book: Book) {
    const books = this.getLocalBooks();
    const index = books.findIndex(b => b.id === book.id);
    if (index >= 0) {
      books[index] = book;
    } else {
      books.unshift(book);
    }
    this.saveLocalBooks(books);
  }

  async deleteBook(id: string): Promise<void> {
    if (this.useLocalStorage) {
      const books = this.getLocalBooks().filter(b => b.id !== id);
      this.saveLocalBooks(books);
      return;
    }

    try {
      const { error } = await supabase
        .from(TABLE_NAME)
        .delete()
        .eq('id', id);

      if (error) throw error;
    } catch (err: any) {
      console.error('Erro ao deletar:', err.message);
    }
  }

  private handleSchemaError(type: 'table' | 'column', detail?: string) {
    this.logSchemaAdvice(type, detail);
    if (this.onSchemaErrorCallback) {
        this.onSchemaErrorCallback(type, detail);
    }
  }

  private logSchemaAdvice(type: 'table' | 'column', detail?: string) {
    const title = type === 'table' ? 'TABELA NÃO ENCONTRADA' : 'COLUNA FALTANDO OU CACHE EXPIRADO';
    const message = type === 'table' 
        ? "A tabela 'books' não foi encontrada no Supabase."
        : `A coluna '${detail}' causou um erro de cache ou não existe.`;

    const sql = type === 'table' 
        ? "Execute o script de criação em 'instrucoes_sql.txt'."
        : `ALTER TABLE public.books ADD COLUMN IF NOT EXISTS "${detail}" TEXT;`;

    console.log(`
%c 💡 ${title} %c
${message}

%c SQL Corretivo: %c
${sql}

%c DICA: %c Se o SQL já foi executado, o cache do Supabase está obsoleto. 
Vá em 'Project Settings' > 'API' e clique em 'Reload PostgREST Schema' ou execute:
NOTIFY pgrst, 'reload_schema';
`, 
'color: #ffffff; background: #2563eb; padding: 2px 5px; border-radius: 3px; font-weight: bold;', 
'color: #475569;',
'color: #059669; font-weight: bold;',
'color: #059669; font-style: italic;',
'color: #e11d48; font-weight: bold;',
'color: #475569;');
  }
}

