import React, { useState, useEffect, useMemo } from 'react';
import type { Book } from '../types';
import { BookStatus } from '../types';
import { StarIcon, StarIconFilled } from './Icons';

interface CurrentlyReadingProps {
  book: Book;
  updateBook: (book: Book) => void;
}

const calculateDaysReading = (startDate?: string) => {
    if (!startDate) return 0;
    const start = new Date(startDate);
    const today = new Date();
    today.setHours(0,0,0,0);
    start.setHours(0,0,0,0);
    const diffTime = today.getTime() - start.getTime();
    const diffDays = Math.ceil(diffTime / (1000 * 60 * 60 * 24));
    return diffDays >= 0 ? diffDays : 0;
}

export const CurrentlyReading: React.FC<CurrentlyReadingProps> = ({ book, updateBook }) => {
    const [currentPage, setCurrentPage] = useState(book.currentPage || 0);
    const [dateStarted, setDateStarted] = useState(book.dateStarted || new Date().toISOString().split('T')[0]);
    const [isFinishing, setIsFinishing] = useState(false);
    const [selectedRating, setSelectedRating] = useState<number>(book.rating || 0);
    const [hoverRating, setHoverRating] = useState<number>(0);

    const daysReading = useMemo(() => calculateDaysReading(dateStarted), [dateStarted]);
    const progressPercentage = book.pages > 0 ? (currentPage / book.pages) * 100 : 0;
    const pagesRemaining = book.pages - currentPage;

    const pagesPerDay = useMemo(() => {
        const days = daysReading || 1;
        return Math.round((currentPage / days) * 10) / 10;
    }, [currentPage, daysReading]);

    const estDaysToFinish = useMemo(() => {
        if (pagesPerDay <= 0) return null;
        return Math.ceil(pagesRemaining / pagesPerDay);
    }, [pagesRemaining, pagesPerDay]);

    useEffect(() => {
        setCurrentPage(book.currentPage || 0);
        setDateStarted(book.dateStarted || new Date().toISOString().split('T')[0]);
        setIsFinishing(false);
        setSelectedRating(0);
    }, [book.id]);

    const handleProgressChange = (e: React.ChangeEvent<HTMLInputElement>) => {
        const value = parseInt(e.target.value, 10);
        if (!isNaN(value) && value >= 0 && value <= book.pages) {
            setCurrentPage(value);
        } else if (e.target.value === '') {
            setCurrentPage(0);
        }
    };

    const handleUpdateClick = () => {
        updateBook({ ...book, currentPage, dateStarted });
    };

    const handleConfirmFinish = () => {
        updateBook({ 
            ...book, 
            currentPage: book.pages, 
            status: BookStatus.Read,
            rating: selectedRating,
            dateFinished: new Date().toISOString().split('T')[0]
        });
    };

    const genresList = book.genre ? book.genre.split(',').map(g => g.trim()).filter(g => g !== '') : [];

  return (
    <div className="bg-white dark:bg-slate-900 p-8 rounded-[2.5rem] shadow-soft border border-slate-100 dark:border-slate-800 h-full flex flex-col relative overflow-hidden group animate-in zoom-in-95 duration-500">
      <div className="absolute -top-24 -right-24 w-64 h-64 bg-primary/5 dark:bg-primary/10 rounded-full blur-3xl pointer-events-none"></div>

      <div className="flex justify-between items-center mb-8 relative z-10">
        <div className="flex gap-2">
            <span className="bg-primary text-white text-[10px] font-black uppercase tracking-[0.15em] px-4 py-1.5 rounded-full shadow-lg shadow-primary/20">
              Lendo agora
            </span>
            {daysReading > 0 && (
              <span className="bg-slate-100 dark:bg-slate-800 text-slate-500 dark:text-slate-400 text-[10px] font-bold uppercase tracking-widest px-4 py-1.5 rounded-full border border-slate-200 dark:border-slate-700">
                 Jornada de {daysReading} {daysReading === 1 ? 'dia' : 'dias'}
              </span>
            )}
        </div>
      </div>

      <div className="flex flex-col lg:flex-row gap-10 items-center lg:items-start relative z-10">
        <div className="relative group/cover flex-shrink-0">
            <img
              src={book.coverImageUrl}
              alt={book.title}
              className="w-48 h-72 object-cover rounded-2xl shadow-xl transition-all duration-700 group-hover/cover:scale-[1.02] relative z-10"
            />
        </div>

        <div className="flex-1 w-full text-center lg:text-left">
          {!isFinishing ? (
            <>
              <div className="mb-6">
                <h3 className="text-3xl font-black text-slate-900 dark:text-slate-50 mb-2 leading-tight font-serif italic">{book.title}</h3>
                <p className="text-xl text-slate-400 dark:text-slate-500 font-medium">{book.author}</p>
              </div>

              <div className="flex flex-wrap justify-center lg:justify-start gap-2 mb-8">
                  {genresList.map(g => (
                    <span key={g} className="bg-slate-50 dark:bg-slate-800 text-slate-500 dark:text-slate-400 px-4 py-1.5 rounded-xl border border-slate-100 dark:border-slate-700 text-[10px] font-black uppercase tracking-widest">
                        {g}
                    </span>
                  ))}
                  <span className="bg-blue-50 dark:bg-blue-900/20 text-primary px-4 py-1.5 rounded-xl border border-blue-100 dark:border-blue-800/50 text-[10px] font-black uppercase tracking-widest">
                    {book.pages} páginas totais
                  </span>
              </div>

              <div className="mb-10">
                <div className="flex justify-between items-end mb-3">
                    <div className="flex items-baseline gap-2">
                        <span className="text-4xl font-black text-slate-900 dark:text-slate-50 tracking-tighter">{progressPercentage.toFixed(0)}%</span>
                        <span className="text-xs font-bold text-slate-400 dark:text-slate-500 uppercase tracking-widest">Completo</span>
                    </div>
                </div>

                <div className="w-full bg-slate-100 dark:bg-slate-800 rounded-2xl h-4 mb-4 overflow-hidden p-1 border border-slate-200/50 dark:border-slate-700">
                  <div 
                      className="bg-gradient-to-r from-primary to-blue-400 h-full rounded-xl transition-all duration-1000 ease-out" 
                      style={{ width: `${progressPercentage}%` }}
                  ></div>
                </div>

                <div className="grid grid-cols-2 sm:grid-cols-3 gap-4">
                    <div className="bg-slate-50/80 dark:bg-slate-800/80 p-3 rounded-2xl border border-slate-100 dark:border-slate-700">
                        <p className="text-[9px] font-black text-slate-400 dark:text-slate-500 uppercase tracking-widest mb-1">Ritmo Médio</p>
                        <p className="text-sm font-bold text-slate-700 dark:text-slate-300">{pagesPerDay} <span className="text-[10px] text-slate-400 dark:text-slate-500">pág/dia</span></p>
                    </div>
                    <div className="bg-slate-50/80 dark:bg-slate-800/80 p-3 rounded-2xl border border-slate-100 dark:border-slate-700">
                        <p className="text-[9px] font-black text-slate-400 dark:text-slate-500 uppercase tracking-widest mb-1">Previsão</p>
                        <p className="text-sm font-bold text-slate-700 dark:text-slate-300">{estDaysToFinish ? `+${estDaysToFinish} dias` : '--'}</p>
                    </div>
                    <div className="hidden sm:block bg-slate-50/80 dark:bg-slate-800/80 p-3 rounded-2xl border border-slate-100 dark:border-slate-700">
                        <p className="text-[9px] font-black text-slate-400 dark:text-slate-500 uppercase tracking-widest mb-1">Página Atual</p>
                        <p className="text-sm font-bold text-slate-700 dark:text-slate-300">{currentPage} <span className="text-[10px] text-slate-400 dark:text-slate-500">de {book.pages}</span></p>
                    </div>
                </div>
              </div>

              <div className="flex flex-col sm:flex-row gap-4">
                <div className="flex flex-1 gap-2">
                    <input 
                        type="number"
                        value={currentPage}
                        onChange={handleProgressChange}
                        className="w-24 bg-white dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-2xl px-4 py-3 text-slate-900 dark:text-slate-100 font-black focus:border-primary transition-all outline-none text-center"
                        aria-label="Página atual"
                    />
                    <button
                        onClick={handleUpdateClick}
                        className="flex-1 px-4 py-3 text-[10px] font-black rounded-2xl bg-slate-900 dark:bg-slate-100 text-white dark:text-slate-900 hover:bg-primary dark:hover:bg-primary dark:hover:text-white shadow-xl transition-all active:scale-95 uppercase tracking-widest"
                    >
                        Salvar Progresso
                    </button>
                </div>
                <button
                    onClick={() => setIsFinishing(true)}
                    className="px-8 py-3 text-[10px] font-black rounded-2xl bg-emerald-500 text-white hover:bg-emerald-600 shadow-xl shadow-emerald-200 dark:shadow-emerald-900/20 transition-all active:scale-95 uppercase tracking-widest"
                >
                    Concluir Leitura
                </button>
              </div>
            </>
          ) : (
            <div className="animate-in slide-in-from-right-8 duration-500">
                <h3 className="text-2xl font-black text-slate-900 dark:text-slate-50 mb-2 leading-tight font-serif italic">Parabéns pela conclusão!</h3>
                <p className="text-slate-500 dark:text-slate-400 mb-8 font-medium italic">Como você avalia sua experiência com "{book.title}"?</p>

                <div className="flex flex-col items-center lg:items-start gap-6 mb-10">
                    <div className="flex items-center gap-1.5 p-4 bg-slate-50 dark:bg-slate-800/50 rounded-3xl border border-slate-100 dark:border-slate-700">
                        {[...Array(10)].map((_, i) => {
                            const ratingValue = i + 1;
                            const isActive = ratingValue <= (hoverRating || selectedRating);
                            return (
                                <button
                                    key={i}
                                    type="button"
                                    onClick={() => setSelectedRating(ratingValue)}
                                    onMouseEnter={() => setHoverRating(ratingValue)}
                                    onMouseLeave={() => setHoverRating(0)}
                                    className="p-0.5 transition-transform hover:scale-125"
                                >
                                    {isActive ? (
                                        <StarIconFilled className="h-7 w-7 text-amber-400" />
                                    ) : (
                                        <StarIcon className="h-7 w-7 text-slate-300 dark:text-slate-600" />
                                    )}
                                </button>
                            );
                        })}
                        <span className="ml-4 text-xl font-black text-amber-500 min-w-[2ch]">
                            {selectedRating || '-'}
                        </span>
                    </div>
                </div>

                <div className="flex gap-4">
                    <button
                        onClick={handleConfirmFinish}
                        disabled={selectedRating === 0}
                        className="flex-1 px-8 py-4 text-[11px] font-black rounded-2xl bg-emerald-500 text-white hover:bg-emerald-600 shadow-xl shadow-emerald-200 dark:shadow-emerald-900/20 transition-all active:scale-95 uppercase tracking-widest disabled:opacity-50 disabled:grayscale"
                    >
                        Confirmar e Finalizar
                    </button>
                    <button
                        onClick={() => setIsFinishing(false)}
                        className="px-8 py-4 text-[11px] font-black rounded-2xl bg-slate-100 dark:bg-slate-800 text-slate-500 dark:text-slate-400 hover:bg-slate-200 transition-all uppercase tracking-widest"
                    >
                        Voltar
                    </button>
                </div>
            </div>
          )}
        </div>
      </div>
    </div>
  );
};

import React, { useState, useCallback } from 'react';
import type { NewBook, Book, StatusConfigs } from '../types';
import { BookStatus, BookType, GENRES, STATUS_CONFIGS } from '../types';
import { XMarkIcon, BookOpenIcon, StarIcon, StarIconFilled } from './Icons';
import { generateBookSummary, generateBookCover } from '../services/geminiService';

interface AddBookModalProps {
  onClose: () => void;
  onAddBook: (book: NewBook) => Promise<void>;
  onUpdateBook: (book: Book) => Promise<void>;
  bookToEdit?: Book | null;
  defaultStatus?: BookStatus;
  existingBooks: Book[];
  statusConfigs?: StatusConfigs;
}

interface FormErrors {
  title?: string;
  author?: string;
  genre?: string;
}

export const AddBookModal: React.FC<AddBookModalProps> = ({ 
  onClose, 
  onAddBook, 
  onUpdateBook, 
  bookToEdit, 
  defaultStatus, 
  existingBooks, 
  statusConfigs = STATUS_CONFIGS 
}) => {
  const isEditMode = !!bookToEdit;

  const [title, setTitle] = useState(bookToEdit?.title || '');
  const [author, setAuthor] = useState(bookToEdit?.author || '');
  const [pages, setPages] = useState(bookToEdit?.pages || 0);
  const [selectedGenres, setSelectedGenres] = useState<string[]>(
    bookToEdit?.genre ? bookToEdit.genre.split(',').map(g => g.trim()).filter(g => g !== '') : []
  );
  const [type, setType] = useState<BookType>(bookToEdit?.type || BookType.Book);
  const [status, setStatus] = useState<BookStatus>(bookToEdit?.status || defaultStatus || BookStatus.TBR);
  const [rating, setRating] = useState<number>(bookToEdit?.rating || 0);
  const [hoverRating, setHoverRating] = useState<number>(0);
  const [summary, setSummary] = useState(bookToEdit?.summary || '');
  const [notes, setNotes] = useState(bookToEdit?.notes || '');
  const [estimatedPrice, setEstimatedPrice] = useState(bookToEdit?.estimatedPrice?.toString() || '');
  const [buyLink, setBuyLink] = useState(bookToEdit?.buyLink || '');
  const [coverImageUrl, setCoverImageUrl] = useState<string | undefined>(bookToEdit?.coverImageUrl);
  const [isGeneratingCover, setIsGeneratingCover] = useState(false);
  const [isGeneratingSummary, setIsGeneratingSummary] = useState(false);
  const [isSubmitting, setIsSubmitting] = useState(false);
  const [dateAdded] = useState(bookToEdit?.dateAdded || new Date().toISOString().split('T')[0]);
  const [errors, setErrors] = useState<FormErrors>({});
  const [isShaking, setIsShaking] = useState(false);

  const handleTitleChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    setTitle(e.target.value);
    if (errors.title) setErrors(prev => ({ ...prev, title: undefined }));
  };

  const handleAuthorChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    setAuthor(e.target.value);
    if (errors.author) setErrors(prev => ({ ...prev, author: undefined }));
  };

  const toggleGenre = (genreName: string) => {
    setSelectedGenres(prev => {
      const isSelected = prev.includes(genreName);
      const newList = isSelected ? prev.filter(g => g !== genreName) : [...prev, genreName];
      if (newList.length > 0 && errors.genre) {
        setErrors(prevErr => ({ ...prevErr, genre: undefined }));
      }
      return newList;
    });
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    if (isSubmitting) return;
    const newErrors: FormErrors = {};
    if (!title.trim()) newErrors.title = "O título é obrigatório";
    if (!author.trim()) newErrors.author = "O autor é obrigatório";
    if (selectedGenres.length === 0) newErrors.genre = "Selecione ao menos um gênero";
    if (Object.keys(newErrors).length > 0) {
      setErrors(newErrors);
      setIsShaking(true);
      setTimeout(() => setIsShaking(false), 500);
      return;
    }
    setIsSubmitting(true);
    try {
        const bookData = { 
            title: title.trim(), 
            author: author.trim(), 
            pages, 
            genre: selectedGenres.join(', '), 
            type, 
            status, 
            summary, 
            notes,
            rating: rating || undefined,
            estimatedPrice: estimatedPrice ? parseFloat(estimatedPrice) : undefined,
            buyLink: buyLink.trim() || undefined,
            coverImageUrl, 
            dateAdded,
            currentPage: bookToEdit?.currentPage,
            dateStarted: bookToEdit?.dateStarted,
            dateFinished: bookToEdit?.dateFinished
        };
        if (isEditMode) {
            await onUpdateBook({ ...bookToEdit, ...bookData });
        } else {
            await onAddBook(bookData);
        }
    } finally {
        setIsSubmitting(false);
    }
  };

  const handleGenerateCover = useCallback(async () => {
    if (!title || selectedGenres.length === 0) return;
    setIsGeneratingCover(true);
    const result = await generateBookCover(title, selectedGenres[0], type);
    setCoverImageUrl(result);
    setIsGeneratingCover(false);
  }, [title, selectedGenres, type]);

  const handleGenerateSummary = useCallback(async () => {
    if (!title || !author) return;
    setIsGeneratingSummary(true);
    const result = await generateBookSummary(title, author);
    setSummary(result);
    setIsGeneratingSummary(false);
  }, [title, author]);

  const labelClass = (isRequired: boolean) => 
    `block text-[10px] font-black uppercase tracking-[0.15em] mb-1.5 ml-1 flex items-center gap-1 ${isRequired ? 'text-slate-500 dark:text-slate-400' : 'text-slate-400 dark:text-slate-500'}`;

  return (
    <div className="fixed inset-0 bg-slate-900/60 backdrop-blur-sm flex items-center justify-center z-50 p-4">
      <div 
        className={`bg-white dark:bg-slate-900 rounded-[2.5rem] shadow-2xl w-full max-w-2xl max-h-[90vh] overflow-hidden flex flex-col border border-white/20 dark:border-slate-800 transition-transform duration-500 ${isShaking ? 'animate-shake' : ''}`}
        style={{ animation: isShaking ? 'shake 0.4s cubic-bezier(.36,.07,.19,.97) both' : 'none' }}
      >
        <style>{`
          @keyframes shake {
            10%, 90% { transform: translate3d(-1px, 0, 0); }
            20%, 80% { transform: translate3d(2px, 0, 0); }
            30%, 50%, 70% { transform: translate3d(-4px, 0, 0); }
            40%, 60% { transform: translate3d(4px, 0, 0); }
          }
        `}</style>

        <div className="p-7 border-b border-slate-100 dark:border-slate-800 flex justify-between items-center bg-slate-50/50 dark:bg-slate-800/30">
            <h2 className="text-2xl font-black font-serif text-slate-900 dark:text-slate-50 tracking-tight">{isEditMode ? 'Editar Registro' : 'Novo Registro'}</h2>
            <button onClick={onClose} disabled={isSubmitting} className="p-2.5 rounded-full hover:bg-slate-200 dark:hover:bg-slate-700 text-slate-400 transition-all hover:rotate-90 disabled:opacity-30">
                <XMarkIcon className="h-5 w-5" />
            </button>
        </div>

        <form onSubmit={handleSubmit} className="p-8 space-y-8 overflow-y-auto custom-scrollbar">
            <div className={`grid grid-cols-1 md:grid-cols-2 gap-8 ${isSubmitting ? 'opacity-50 pointer-events-none' : ''}`}>
                <div className="md:col-span-2">
                    <label className={labelClass(true)}>
                      Título <span className="text-red-500">*</span>
                    </label>
                    <input 
                      type="text" 
                      value={title} 
                      onChange={handleTitleChange} 
                      placeholder="Ex: Cem Anos de Solidão"
                      className={`w-full bg-slate-50 dark:bg-slate-800 border rounded-2xl px-5 py-3.5 outline-none transition-all focus:ring-4 focus:ring-primary/5 ${errors.title ? 'border-red-400 bg-red-50/30 dark:bg-red-950/20' : 'border-slate-200 dark:border-slate-700 focus:border-primary'}`} 
                    />
                    {errors.title && <p className="text-[10px] text-red-500 font-bold mt-2 uppercase tracking-wide ml-1">{errors.title}</p>}
                </div>

                <div>
                    <label className={labelClass(true)}>
                      Autor <span className="text-red-500">*</span>
                    </label>
                    <input 
                      type="text" 
                      value={author} 
                      onChange={handleAuthorChange} 
                      placeholder="Ex: Gabriel García Márquez"
                      className={`w-full bg-slate-50 dark:bg-slate-800 border rounded-2xl px-5 py-3.5 outline-none transition-all focus:ring-4 focus:ring-primary/5 ${errors.author ? 'border-red-400 bg-red-50/30 dark:bg-red-950/20' : 'border-slate-200 dark:border-slate-700 focus:border-primary'}`} 
                    />
                    {errors.author && <p className="text-[10px] text-red-500 font-bold mt-2 uppercase tracking-wide ml-1">{errors.author}</p>}
                </div>

                <div>
                    <label className={labelClass(false)}>Status</label>
                    <select value={status} onChange={(e) => setStatus(e.target.value as BookStatus)} className="w-full bg-slate-50 dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-2xl px-5 py-3.5 outline-none focus:ring-4 focus:ring-primary/5 focus:border-primary cursor-pointer font-bold text-slate-700 dark:text-slate-300">
                        <option value={BookStatus.TBR}>{statusConfigs[BookStatus.TBR].label}</option>
                        <option value={BookStatus.Reading}>{statusConfigs[BookStatus.Reading].label}</option>
                        <option value={BookStatus.Read}>{statusConfigs[BookStatus.Read].label}</option>
                        <option value={BookStatus.Wishlist}>{statusConfigs[BookStatus.Wishlist].label}</option>
                    </select>
                </div>

                <div className="md:col-span-2">
                    <label className={labelClass(true)}>Gêneros <span className="text-red-500">*</span></label>
                    <div className={`p-5 bg-slate-50/50 dark:bg-slate-800/20 border rounded-[2rem] transition-all ${errors.genre ? 'border-red-400 ring-4 ring-red-500/5 bg-red-50/10' : 'border-slate-200 dark:border-slate-700'}`}>
                        <div className="flex flex-wrap gap-2.5 mb-5 min-h-[38px]">
                            {selectedGenres.length > 0 ? (
                                selectedGenres.map(g => (
                                    <span key={g} className="bg-primary text-white text-[10px] font-black uppercase tracking-widest px-4 py-2 rounded-xl flex items-center gap-2 shadow-md animate-in fade-in zoom-in duration-300">
                                        {g}
                                        <button type="button" onClick={() => toggleGenre(g)} className="hover:text-blue-200 transition-colors p-0.5">
                                            <XMarkIcon className="h-3.5 w-3.5" />
                                        </button>
                                    </span>
                                ))
                            ) : (
                                <span className="text-slate-400 dark:text-slate-500 text-xs italic ml-1 mt-2">Escolha as categorias da obra...</span>
                            )}
                        </div>
                        <div className="flex flex-wrap gap-2 pt-5 border-t border-slate-200/60 dark:border-slate-700/60 max-h-48 overflow-y-auto pr-2 custom-scrollbar">
                            {GENRES.map(g => {
                                const isSelected = selectedGenres.includes(g);
                                return (
                                    <button
                                        key={g}
                                        type="button"
                                        onClick={() => toggleGenre(g)}
                                        className={`px-4 py-2 rounded-xl text-[10px] font-black uppercase tracking-[0.1em] transition-all ${
                                            isSelected 
                                                ? 'bg-primary text-white border border-primary scale-95 shadow-sm' 
                                                : 'bg-white dark:bg-slate-900 text-slate-500 dark:text-slate-400 border border-slate-200 dark:border-slate-700 hover:border-primary/40 hover:bg-slate-50 dark:hover:bg-slate-800'
                                        }`}
                                    >
                                        {g}
                                    </button>
                                );
                            })}
                        </div>
                    </div>
                    {errors.genre && <p className="text-[10px] text-red-500 font-bold mt-3 uppercase tracking-wide ml-1">{errors.genre}</p>}
                </div>

                <div>
                    <label className={labelClass(false)}>Total de Páginas</label>
                    <input type="number" min="0" value={pages} onChange={(e) => setPages(Number(e.target.value))} className="w-full bg-slate-50 dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-2xl px-5 py-3.5 outline-none focus:border-primary font-bold text-slate-700 dark:text-slate-300" />
                </div>
                <div>
                    <label className={labelClass(false)}>Tipo de Mídia</label>
                    <select value={type} onChange={(e) => setType(e.target.value as BookType)} className="w-full bg-slate-50 dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-2xl px-5 py-3.5 outline-none focus:border-primary font-bold text-slate-700 dark:text-slate-300">
                        <option value={BookType.Book}>Livro</option>
                        <option value={BookType.HQ}>HQ</option>
                    </select>
                </div>

