import type { Book } from '../types';
import { supabase } from './supabase';

const TABLE_NAME = 'books';
const LOCAL_STORAGE_KEY = 'biblio_tech_local_db';

export class DatabaseService {
  private isSchemaBroken = false;
  private onSchemaErrorCallback?: (type: 'table' | 'column', detail?: string) => void;

  setSchemaErrorCallback(cb: (type: 'table' | 'column', detail?: string) => void) {
    this.onSchemaErrorCallback = cb;
  }

  private getLocalBooks(): Book[] {
    const data = localStorage.getItem(LOCAL_STORAGE_KEY);
    return data ? JSON.parse(data) : [];
  }

  private saveLocalBooks(books: Book[]): void {
    localStorage.setItem(LOCAL_STORAGE_KEY, JSON.stringify(books));
  }

  async getAllBooks(): Promise<Book[]> {
    try {
      const { data, error } = await supabase
        .from(TABLE_NAME)
        .select('*')
        .order('dateAdded', { ascending: false });

      if (error) {
        if (error.code === '42P01' || error.message?.includes('relation "books" does not exist') || error.message?.includes('schema cache')) {
          const type = error.message?.includes('column') ? 'column' : 'table';
          const detail = error.message.match(/'([^']+)'/)?.[1];
          this.handleSchemaError(type as any, detail);
          this.isSchemaBroken = true;
          return this.getLocalBooks();
        }
        throw error;
      }

      this.isSchemaBroken = false;
      // Sincroniza local storage com o que veio do banco para backup offline
      this.saveLocalBooks(data as Book[] || []);
      return (data as Book[]) || [];
    } catch (err: any) {
      console.warn('Serviço remoto indisponível. Usando backup local.', err.message);
      return this.getLocalBooks();
    }
  }

  async saveBook(book: Book): Promise<void> {
    // Sempre salva localmente primeiro para garantir que o usuário não perca nada
    this.updateLocalEntry(book);

    // Se o esquema estiver quebrado (ex: coluna faltando), não tentamos o Supabase para evitar erros de console
    if (this.isSchemaBroken) return;

    try {
      // O upsert do Supabase lida com Insert ou Update baseado na Primary Key (id)
      const { error } = await supabase
        .from(TABLE_NAME)
        .upsert({
          id: book.id,
          title: book.title,
          author: book.author,
          pages: book.pages,
          genre: book.genre,
          type: book.type,
          status: book.status,
          rating: book.rating,
          coverImageUrl: book.coverImageUrl,
          summary: book.summary,
          notes: book.notes,
          estimatedPrice: book.estimatedPrice,
          buyLink: book.buyLink,
          currentPage: book.currentPage,
          dateAdded: book.dateAdded,
          dateStarted: book.dateStarted,
          dateFinished: book.dateFinished
        });

      if (error) {
        const isSchemaError = 
          error.code === '42703' || 
          error.message?.includes('column') || 
          error.message?.includes('schema cache');

        if (isSchemaError) {
            const columnName = error.message.match(/'([^']+)'/)?.[1] || 'unknown';
            this.handleSchemaError('column', columnName);
            this.isSchemaBroken = true; 
            return;
        }
        throw error;
      }

      this.isSchemaBroken = false;
    } catch (err: any) {
      console.error('Falha na sincronização imediata com Supabase:', err.message);
    }
  }

  private updateLocalEntry(book: Book) {
    const books = this.getLocalBooks();
    const index = books.findIndex(b => b.id === book.id);
    if (index >= 0) {
      books[index] = book;
    } else {
      books.unshift(book);
    }
    this.saveLocalBooks(books);
  }

  async deleteBook(id: string): Promise<void> {
    // Remove localmente
    const books = this.getLocalBooks().filter(b => b.id !== id);
    this.saveLocalBooks(books);

    if (this.isSchemaBroken) return;

    try {
      const { error } = await supabase
        .from(TABLE_NAME)
        .delete()
        .eq('id', id);

      if (error) throw error;
    } catch (err: any) {
      console.error('Erro ao deletar no Supabase:', err.message);
    }
  }

  private handleSchemaError(type: 'table' | 'column', detail?: string) {
    this.logSchemaAdvice(type, detail);
    if (this.onSchemaErrorCallback) {
        this.onSchemaErrorCallback(type, detail);
    }
  }

  private logSchemaAdvice(type: 'table' | 'column', detail?: string) {
    const title = type === 'table' ? 'TABELA NÃO ENCONTRADA' : 'COLUNA FALTANDO';
    const message = type === 'table' 
        ? "A tabela 'books' não foi encontrada."
        : `A coluna '${detail}' não existe no banco de dados.`;

    const sql = type === 'table' 
        ? "Execute o script de criação em 'instrucoes_sql.txt'."
        : `ALTER TABLE public.books ADD COLUMN IF NOT EXISTS "${detail}" TEXT;`;

    console.group(`%c 💡 BIBLIO TECH: ${title} `, 'color: white; background: #2563eb; padding: 4px; border-radius: 4px;');
    console.log(message);
    console.log("%c Comando SQL para corrigir: ", 'font-weight: bold; color: #059669;');
    console.log(`%c ${sql} `, 'font-family: monospace; background: #f1f5f9; padding: 4px; border: 1px solid #e2e8f0;');
    console.groupEnd();
  }
}

