import React, { useState, useMemo, useEffect } from 'react';
import { useBookData } from './hooks/useBookData';
import { Header } from './components/Header';
import { Dashboard } from './components/Dashboard';
import { AddBookModal } from './components/AddBookModal';
import { PlusIcon } from './components/Icons';
import type { Book, NewBook } from './types';
import { BookList } from './components/BookList';
import { ConfirmationModal } from './components/ConfirmationModal';
import { BookStatus } from './types';
import { Wishlist } from './components/Wishlist';
import { BottomNav } from './components/BottomNav';

export default function App() {
  const { 
    books, 
    stats, 
    currentlyReading, 
    addBook, 
    updateBook, 
    deleteBook, 
    dateFilter, 
    setDateFilter,
    selectedYear,
    setSelectedYear,
    availableYears,
    customRange,
    setCustomRange,
    isLocalMode,
    schemaError,
    isLoading
  } = useBookData();

  const [theme, setTheme] = useState<'light' | 'dark'>(() => {
    return (localStorage.getItem('theme') as 'light' | 'dark') || 'light';
  });

  const [isModalOpen, setIsModalOpen] = useState(false);
  const [view, setView] = useState<'dashboard' | 'list' | 'wishlist'>('dashboard');
  const [editingBook, setEditingBook] = useState<Book | null>(null);
  const [deletingBook, setDeletingBook] = useState<Book | null>(null);
  const [defaultStatusForModal, setDefaultStatusForModal] = useState<BookStatus | undefined>();
  const [toastMessage, setToastMessage] = useState<string | null>(null);

  useEffect(() => {
    if (theme === 'dark') {
      document.documentElement.classList.add('dark');
    } else {
      document.documentElement.classList.remove('dark');
    }
    localStorage.setItem('theme', theme);
  }, [theme]);

  const toggleTheme = () => {
    setTheme(prev => prev === 'light' ? 'dark' : 'light');
  };

  const showToast = (message: string) => {
    setToastMessage(message);
    setTimeout(() => setToastMessage(null), 3500);
  };

  const handleAddBook = async (newBook: NewBook) => {
    try {
      await addBook(newBook);
      setIsModalOpen(false);
      setEditingBook(null);
      showToast(`"${newBook.title}" salvo com sucesso!`);
    } catch (error) {
      showToast("Erro ao salvar o livro.");
    }
  };

  const handleUpdateBook = async (updatedBook: Book) => {
    try {
      await updateBook(updatedBook);
      setIsModalOpen(false);
      setEditingBook(null);
      if (updatedBook.status === BookStatus.Read) {
          showToast(`Parabéns por concluir "${updatedBook.title}"!`);
      } else {
          showToast(`"${updatedBook.title}" atualizado.`);
      }
    } catch (error) {
      showToast("Erro ao atualizar o livro.");
    }
  };

  const openAddModal = (defaultStatus?: BookStatus) => {
    setEditingBook(null);
    setDefaultStatusForModal(defaultStatus);
    setIsModalOpen(true);
  };

  const shelfBooks = useMemo(() => books.filter(book => book.status !== BookStatus.Wishlist), [books]);
  const wishlistBooks = useMemo(() => books.filter(book => book.status === BookStatus.Wishlist), [books]);

  const [isFading, setIsFading] = useState(false);

  const handleSetView = (newView: 'dashboard' | 'list' | 'wishlist') => {
    if (view !== newView) {
      setIsFading(true);
      setTimeout(() => {
        setView(newView);
        setIsFading(false);
      }, 200);
    }
  };

  if (isLoading) {
    return (
      <div className="min-h-screen bg-background dark:bg-slate-950 flex flex-col items-center justify-center p-4">
          <div className="w-12 h-12 border-4 border-primary border-t-transparent rounded-full animate-spin mb-4"></div>
          <p className="text-[10px] font-black uppercase tracking-[0.2em] text-slate-400 dark:text-slate-500">Sincronizando Biblioteca...</p>
      </div>
    );
  }

  return (
    <div className="min-h-screen bg-background dark:bg-slate-950 text-text-main dark:text-slate-200 pb-24 relative transition-colors duration-300">
      <Header 
        onLogoClick={() => handleSetView('dashboard')} 
        theme={theme} 
        toggleTheme={toggleTheme} 
        isConnected={!isLocalMode}
      />

      {isLocalMode && (
        <div className="bg-amber-50 dark:bg-amber-950/30 border-b border-amber-100 dark:border-amber-900/50 px-6 py-2.5 flex flex-col sm:flex-row items-center justify-center gap-2 sm:gap-4 animate-in slide-in-from-top duration-500">
            <div className="flex items-center gap-2">
                <span className="w-2 h-2 rounded-full bg-amber-400 animate-pulse"></span>
                <p className="text-[9px] font-black uppercase tracking-widest text-amber-700 dark:text-amber-400">
                    {schemaError?.type === 'column' 
                      ? `Erro: Coluna '${schemaError.detail}' não encontrada. Sincronização desativada.`
                      : 'Modo Local Ativo: Banco de dados remoto offline ou desconfigurado.'}
                </p>
            </div>
            {schemaError?.type === 'column' && (
              <p className="text-[8px] font-bold text-amber-600 dark:text-amber-500 uppercase tracking-tight italic">
                Dica: Execute o SQL de migração e recarregue a página.
              </p>
            )}
        </div>
      )}

      <main className={`p-4 md:p-8 transition-all duration-300 transform ${isFading ? 'opacity-0 -translate-y-2' : 'opacity-100 translate-y-0'}`}>
        {view === 'dashboard' && (
          <Dashboard 
            stats={stats} 
            currentlyReading={currentlyReading} 
            updateBook={handleUpdateBook}
            dateFilter={dateFilter}
            setDateFilter={setDateFilter} 
            selectedYear={selectedYear}
            setSelectedYear={setSelectedYear}
            availableYears={availableYears}
            books={books}
            customRange={customRange}
            setCustomRange={setCustomRange}
          />
        )}
        {view === 'list' && (
          <BookList 
            books={shelfBooks} 
            onEdit={(b) => { setEditingBook(b); setIsModalOpen(true); }} 
            onDelete={setDeletingBook} 
            onUpdateBook={handleUpdateBook}
          />
        )}
        {view === 'wishlist' && (
          <Wishlist 
            books={wishlistBooks} 
            onEdit={(b) => { setEditingBook(b); setIsModalOpen(true); }} 
            onDelete={setDeletingBook} 
            onMoveToShelf={(b) => handleUpdateBook({ ...b, status: BookStatus.TBR })} 
            onAddWishlistItem={() => openAddModal(BookStatus.Wishlist)}
          />
        )}
      </main>

      <button
        onClick={() => openAddModal()}
        className="fixed bottom-24 right-6 bg-primary text-background p-4 rounded-full shadow-2xl hover:bg-blue-700 transition-all z-40 active:scale-90"
      >
        <PlusIcon className="h-6 w-6" />
      </button>

      <BottomNav view={view} setView={handleSetView} />

      {toastMessage && (
        <div className="fixed bottom-32 left-1/2 -translate-x-1/2 z-[60] animate-in fade-in slide-in-from-bottom-4 duration-500">
          <div className="bg-slate-900/95 dark:bg-slate-800/95 backdrop-blur-md text-white px-6 py-3.5 rounded-2xl shadow-2xl border border-white/10 flex items-center gap-3">
            <div className="bg-emerald-500 rounded-full p-1 shadow-sm">
              <svg xmlns="http://www.w3.org/2000/svg" className="h-3.5 w-3.5 text-white" fill="none" viewBox="0 0 24 24" stroke="currentColor" strokeWidth={3}>
                <path strokeLinecap="round" strokeLinejoin="round" d="M5 13l4 4L19 7" />
              </svg>
            </div>
            <p className="text-[11px] font-black uppercase tracking-widest">
              {toastMessage}
            </p>
          </div>
        </div>
      )}

      {isModalOpen && (
        <AddBookModal
          onClose={() => { setIsModalOpen(false); setEditingBook(null); }}
          onAddBook={handleAddBook}
          onUpdateBook={handleUpdateBook}
          bookToEdit={editingBook}
          defaultStatus={defaultStatusForModal}
          existingBooks={books}
        />
      )}

      {deletingBook && (
        <ConfirmationModal
          isOpen={!!deletingBook}
          onClose={() => setDeletingBook(null)}
          onConfirm={async () => { 
            const title = deletingBook.title;
            await deleteBook(deletingBook.id); 
            setDeletingBook(null); 
            showToast(`"${title}" removido.`);
          }}
          title="Excluir Registro"
          message={`Tem certeza que deseja apagar "${deletingBook.title}"?`}
        />
      )}
    </div>
  );
}

import type { Book } from '../types';
import { supabase } from './supabase';

const TABLE_NAME = 'books';
const LOCAL_STORAGE_KEY = 'biblio_tech_local_db';

export class DatabaseService {
  private isSchemaBroken = false;
  private onSchemaErrorCallback?: (type: 'table' | 'column' | 'permission', detail?: string) => void;

  setSchemaErrorCallback(cb: (type: 'table' | 'column' | 'permission', detail?: string) => void) {
    this.onSchemaErrorCallback = cb;
  }

  private getLocalBooks(): Book[] {
    const data = localStorage.getItem(LOCAL_STORAGE_KEY);
    return data ? JSON.parse(data) : [];
  }

  private saveLocalBooks(books: Book[]): void {
    localStorage.setItem(LOCAL_STORAGE_KEY, JSON.stringify(books));
  }

  async getAllBooks(): Promise<Book[]> {
    try {
      const { data, error } = await supabase
        .from(TABLE_NAME)
        .select('*')
        .order('dateAdded', { ascending: false });

      if (error) {
        this.handleSupabaseError(error);
        return this.getLocalBooks();
      }

      this.isSchemaBroken = false;
      this.saveLocalBooks(data as Book[] || []);
      return (data as Book[]) || [];
    } catch (err: any) {
      console.warn('Backup local ativado devido a erro de conexão.');
      return this.getLocalBooks();
    }
  }

  async saveBook(book: Book): Promise<void> {
    // Validação de segurança básica no cliente
    const sanitizedBook = {
        ...book,
        pages: Math.max(0, book.pages || 0),
        currentPage: Math.max(0, book.currentPage || 0),
        rating: book.rating ? Math.min(10, Math.max(0, book.rating)) : null,
        estimatedPrice: book.estimatedPrice ? Math.max(0, book.estimatedPrice) : null
    };

    this.updateLocalEntry(sanitizedBook);

    if (this.isSchemaBroken) return;

    try {
      const { error } = await supabase
        .from(TABLE_NAME)
        .upsert({
          id: sanitizedBook.id,
          title: sanitizedBook.title.trim(),
          author: sanitizedBook.author.trim(),
          pages: sanitizedBook.pages,
          genre: sanitizedBook.genre,
          type: sanitizedBook.type,
          status: sanitizedBook.status,
          rating: sanitizedBook.rating,
          coverImageUrl: sanitizedBook.coverImageUrl,
          summary: sanitizedBook.summary,
          notes: sanitizedBook.notes,
          estimatedPrice: sanitizedBook.estimatedPrice,
          buyLink: sanitizedBook.buyLink,
          currentPage: sanitizedBook.currentPage,
          dateAdded: sanitizedBook.dateAdded,
          dateStarted: sanitizedBook.dateStarted,
          dateFinished: sanitizedBook.dateFinished
        });

      if (error) {
        this.handleSupabaseError(error);
      } else {
        this.isSchemaBroken = false;
      }
    } catch (err: any) {
      console.error('Falha de segurança ou rede ao salvar:', err.message);
    }
  }

  private updateLocalEntry(book: Book) {
    const books = this.getLocalBooks();
    const index = books.findIndex(b => b.id === book.id);
    if (index >= 0) {
      books[index] = book;
    } else {
      books.unshift(book);
    }
    this.saveLocalBooks(books);
  }

  async deleteBook(id: string): Promise<void> {
    const books = this.getLocalBooks().filter(b => b.id !== id);
    this.saveLocalBooks(books);

    if (this.isSchemaBroken) return;

    try {
      const { error } = await supabase
        .from(TABLE_NAME)
        .delete()
        .eq('id', id);

      if (error) this.handleSupabaseError(error);
    } catch (err: any) {
      console.error('Erro ao deletar:', err.message);
    }
  }

  private handleSupabaseError(error: any) {
    console.error('Erro Supabase detectado:', error);

    // Erro 42P01: Tabela não existe
    if (error.code === '42P01' || error.message?.includes('relation "books" does not exist')) {
      this.isSchemaBroken = true;
      this.onSchemaErrorCallback?.('table');
      return;
    }

    // Erro 42703: Coluna não existe
    if (error.code === '42703' || error.message?.includes('column')) {
      this.isSchemaBroken = true;
      const detail = error.message.match(/'([^']+)'/)?.[1] || 'desconhecida';
      this.onSchemaErrorCallback?.('column', detail);
      return;
    }

    // Erro 42501: Violação de RLS (Permissão Negada)
    if (error.code === '42501') {
      console.warn('Violação de RLS: Acesso negado pelo banco de dados.');
      this.onSchemaErrorCallback?.('permission');
      return;
    }
  }
}

export const dbService = new DatabaseService();

import React, { useState, useMemo, useEffect } from 'react';
import { useBookData } from './hooks/useBookData';
import { Header } from './components/Header';
import { Dashboard } from './components/Dashboard';
import { AddBookModal } from './components/AddBookModal';
import { PlusIcon } from './components/Icons';
import type { Book, NewBook } from './types';
import { BookList } from './components/BookList';
import { ConfirmationModal } from './components/ConfirmationModal';
import { BookStatus } from './types';
import { Wishlist } from './components/Wishlist';
import { BottomNav } from './components/BottomNav';

export default function App() {
  const { 
    books, 
    stats, 
    currentlyReading, 
    addBook, 
    updateBook, 
    deleteBook, 
    dateFilter, 
    setDateFilter,
    selectedYear,
    setSelectedYear,
    availableYears,
    customRange,
    setCustomRange,
    isLocalMode,
    schemaError,
    isLoading
  } = useBookData();

  const [theme, setTheme] = useState<'light' | 'dark'>(() => {
    return (localStorage.getItem('theme') as 'light' | 'dark') || 'light';
  });

  const [isModalOpen, setIsModalOpen] = useState(false);
  const [view, setView] = useState<'dashboard' | 'list' | 'wishlist'>('dashboard');
  const [editingBook, setEditingBook] = useState<Book | null>(null);
  const [deletingBook, setDeletingBook] = useState<Book | null>(null);
  const [defaultStatusForModal, setDefaultStatusForModal] = useState<BookStatus | undefined>();
  const [toastMessage, setToastMessage] = useState<string | null>(null);

  useEffect(() => {
    if (theme === 'dark') {
      document.documentElement.classList.add('dark');
    } else {
      document.documentElement.classList.remove('dark');
    }
    localStorage.setItem('theme', theme);
  }, [theme]);

  const toggleTheme = () => {
    setTheme(prev => prev === 'light' ? 'dark' : 'light');
  };

  const showToast = (message: string) => {
    setToastMessage(message);
    setTimeout(() => setToastMessage(null), 3500);
  };

  const handleAddBook = async (newBook: NewBook) => {
    try {
      await addBook(newBook);
      setIsModalOpen(false);
      setEditingBook(null);
      showToast(`"${newBook.title}" salvo com sucesso!`);
    } catch (error) {
      showToast("Erro de segurança ou rede ao salvar.");
    }
  };

  const handleUpdateBook = async (updatedBook: Book) => {
    try {
      await updateBook(updatedBook);
      setIsModalOpen(false);
      setEditingBook(null);
      if (updatedBook.status === BookStatus.Read) {
          showToast(`Parabéns por concluir "${updatedBook.title}"!`);
      } else {
          showToast(`"${updatedBook.title}" atualizado.`);
      }
    } catch (error) {
      showToast("Ação negada ou erro no banco.");
    }
  };

  const openAddModal = (defaultStatus?: BookStatus) => {
    setEditingBook(null);
    setDefaultStatusForModal(defaultStatus);
    setIsModalOpen(true);
  };

  const shelfBooks = useMemo(() => books.filter(book => book.status !== BookStatus.Wishlist), [books]);
  const wishlistBooks = useMemo(() => books.filter(book => book.status === BookStatus.Wishlist), [books]);

  const [isFading, setIsFading] = useState(false);

  const handleSetView = (newView: 'dashboard' | 'list' | 'wishlist') => {
    if (view !== newView) {
      setIsFading(true);
      setTimeout(() => {
        setView(newView);
        setIsFading(false);
      }, 200);
    }
  };

  if (isLoading) {
    return (
      <div className="min-h-screen bg-background dark:bg-slate-950 flex flex-col items-center justify-center p-4">
          <div className="w-12 h-12 border-4 border-primary border-t-transparent rounded-full animate-spin mb-4"></div>
          <p className="text-[10px] font-black uppercase tracking-[0.2em] text-slate-400 dark:text-slate-500">Sincronizando Biblioteca...</p>
      </div>
    );
  }

  return (
    <div className="min-h-screen bg-background dark:bg-slate-950 text-text-main dark:text-slate-200 pb-24 relative transition-colors duration-300">
      <Header 
        onLogoClick={() => handleSetView('dashboard')} 
        theme={theme} 
        toggleTheme={toggleTheme} 
        isConnected={!isLocalMode}
      />

      {isLocalMode && (
        <div className="bg-amber-50 dark:bg-amber-950/30 border-b border-amber-100 dark:border-amber-900/50 px-6 py-2.5 flex flex-col sm:flex-row items-center justify-center gap-2 sm:gap-4 animate-in slide-in-from-top duration-500">
            <div className="flex items-center gap-2">
                <span className="w-2 h-2 rounded-full bg-amber-400 animate-pulse"></span>
                <p className="text-[9px] font-black uppercase tracking-widest text-amber-700 dark:text-amber-400">
                    {schemaError?.type === 'column' 
                      ? `Atenção: Coluna '${schemaError.detail}' faltando. Verifique o SQL.`
                      : schemaError?.type === 'permission'
                      ? 'Erro de Permissão (RLS): O banco negou a operação.'
                      : 'Modo Offline: Usando banco de dados local.'}
                </p>
            </div>
        </div>
      )}

      <main className={`p-4 md:p-8 transition-all duration-300 transform ${isFading ? 'opacity-0 -translate-y-2' : 'opacity-100 translate-y-0'}`}>
        {view === 'dashboard' && (
          <Dashboard 
            stats={stats} 
            currentlyReading={currentlyReading} 
            updateBook={handleUpdateBook}
            dateFilter={dateFilter}
            setDateFilter={setDateFilter} 
            selectedYear={selectedYear}
            setSelectedYear={setSelectedYear}
            availableYears={availableYears}
            books={books}
            customRange={customRange}
            setCustomRange={setCustomRange}
          />
        )}
        {view === 'list' && (
          <BookList 
            books={shelfBooks} 
            onEdit={(b) => { setEditingBook(b); setIsModalOpen(true); }} 
            onDelete={setDeletingBook} 
            onUpdateBook={handleUpdateBook}
          />
        )}
        {view === 'wishlist' && (
          <Wishlist 
            books={wishlistBooks} 
            onEdit={(b) => { setEditingBook(b); setIsModalOpen(true); }} 
            onDelete={setDeletingBook} 
            onMoveToShelf={(b) => handleUpdateBook({ ...b, status: BookStatus.TBR })} 
            onAddWishlistItem={() => openAddModal(BookStatus.Wishlist)}
          />
        )}
      </main>

      <button
        onClick={() => openAddModal()}
        className="fixed bottom-24 right-6 bg-primary text-background p-4 rounded-full shadow-2xl hover:bg-blue-700 transition-all z-40 active:scale-90"
      >
        <PlusIcon className="h-6 w-6" />
      </button>

      <BottomNav view={view} setView={handleSetView} />

      {toastMessage && (
        <div className="fixed bottom-32 left-1/2 -translate-x-1/2 z-[60] animate-in fade-in slide-in-from-bottom-4 duration-500">
          <div className="bg-slate-900/95 dark:bg-slate-800/95 backdrop-blur-md text-white px-6 py-3.5 rounded-2xl shadow-2xl border border-white/10 flex items-center gap-3">
            <div className="bg-emerald-500 rounded-full p-1 shadow-sm">
              <svg xmlns="http://www.w3.org/2000/svg" className="h-3.5 w-3.5 text-white" fill="none" viewBox="0 0 24 24" stroke="currentColor" strokeWidth={3}>
                <path strokeLinecap="round" strokeLinejoin="round" d="M5 13l4 4L19 7" />
              </svg>
            </div>
            <p className="text-[11px] font-black uppercase tracking-widest">
              {toastMessage}
            </p>
          </div>
        </div>
      )}

      {isModalOpen && (
        <AddBookModal
          onClose={() => { setIsModalOpen(false); setEditingBook(null); }}
          onAddBook={handleAddBook}
          onUpdateBook={handleUpdateBook}
          bookToEdit={editingBook}
          defaultStatus={defaultStatusForModal}
          existingBooks={books}
        />
      )}

      {deletingBook && (
        <ConfirmationModal
          isOpen={!!deletingBook}
          onClose={() => setDeletingBook(null)}
          onConfirm={async () => { 
            const title = deletingBook.title;
            await deleteBook(deletingBook.id); 
            setDeletingBook(null); 
            showToast(`"${title}" removido.`);
          }}
          title="Excluir Registro"
          message={`Tem certeza que deseja apagar "${deletingBook.title}"?`}
        />
      )}
    </div>
  );
}

--- SCRIPT SQL PARA MULTI-USUÁRIO E PRIVACIDADE ---
--- Execute este código no 'SQL Editor' do seu projeto Supabase ---

-- 1. Adicionar coluna user_id vinculada ao sistema de autenticação
ALTER TABLE public.books 
ADD COLUMN IF NOT EXISTS user_id UUID REFERENCES auth.users DEFAULT auth.uid();

-- 2. Garantir que o user_id seja obrigatório para novos registros
-- (Se você já tem dados sem user_id, limpe a tabela ou preencha-os antes de tornar NOT NULL)
-- ALTER TABLE public.books ALTER COLUMN user_id SET NOT NULL;

-- 3. Habilitar Segurança (RLS)
ALTER TABLE public.books ENABLE ROW LEVEL SECURITY;

-- 4. Limpeza de políticas antigas (públicas)
DROP POLICY IF EXISTS "Leitura_Publica" ON public.books;
DROP POLICY IF EXISTS "Insercao_Publica" ON public.books;
DROP POLICY IF EXISTS "Atualizacao_Publica" ON public.books;
DROP POLICY IF EXISTS "Exclusao_Publica" ON public.books;

-- 5. Criação de Novas Políticas PRIVADAS (Baseadas no Usuário Logado)

-- SELECT: O usuário só vê o que ele criou
CREATE POLICY "Usuarios_Leem_Proprios_Livros" 
ON public.books FOR SELECT 
USING (auth.uid() = user_id);

-- INSERT: O usuário só insere registros para si mesmo
CREATE POLICY "Usuarios_Inserem_Proprios_Livros" 
ON public.books FOR INSERT 
WITH CHECK (auth.uid() = user_id);

-- UPDATE: O usuário só atualiza seus próprios registros
CREATE POLICY "Usuarios_Atualizam_Proprios_Livros" 
ON public.books FOR UPDATE 
USING (auth.uid() = user_id)
WITH CHECK (auth.uid() = user_id);

-- DELETE: O usuário só deleta seus próprios registros
CREATE POLICY "Usuarios_Deletam_Proprios_Livros" 
ON public.books FOR DELETE 
USING (auth.uid() = user_id);

