            {mode === 'login' ? 'Não tem conta? Cadastre-se' : 'Já tem conta? Faça login'}
          </button>
        </div>
      </div>
    </div>
  );
};

import React, { useState, useMemo, useEffect } from 'react';
import { useBookData } from './hooks/useBookData';
import { Header } from './components/Header';
import { Dashboard } from './components/Dashboard';
import { AddBookModal } from './components/AddBookModal';
import { PlusIcon } from './components/Icons';
import type { Book, NewBook } from './types';
import { BookList } from './components/BookList';
import { ConfirmationModal } from './components/ConfirmationModal';
import { BookStatus } from './types';
import { Wishlist } from './components/Wishlist';
import { BottomNav } from './components/BottomNav';
import { Auth } from './components/Auth';
import { supabase } from './services/supabase';

export default function App() {
  const [session, setSession] = useState<any>(null);
  const [isAuthLoading, setIsAuthLoading] = useState(true);

  useEffect(() => {
    supabase.auth.getSession().then(({ data: { session } }) => {
      setSession(session);
      setIsAuthLoading(false);
    });

    const { data: { subscription } } = supabase.auth.onAuthStateChange((_event, session) => {
      setSession(session);
    });

    return () => subscription.unsubscribe();
  }, []);

  const { 
    books, 
    stats, 
    currentlyReading, 
    addBook, 
    updateBook, 
    deleteBook, 
    dateFilter, 
    setDateFilter,
    selectedYear,
    setSelectedYear,
    availableYears,
    customRange,
    setCustomRange,
    isLocalMode,
    schemaError,
    isLoading
  } = useBookData();

  const [theme, setTheme] = useState<'light' | 'dark'>(() => {
    return (localStorage.getItem('theme') as 'light' | 'dark') || 'light';
  });

  const [isModalOpen, setIsModalOpen] = useState(false);
  const [view, setView] = useState<'dashboard' | 'list' | 'wishlist'>('dashboard');
  const [editingBook, setEditingBook] = useState<Book | null>(null);
  const [deletingBook, setDeletingBook] = useState<Book | null>(null);
  const [defaultStatusForModal, setDefaultStatusForModal] = useState<BookStatus | undefined>();
  const [toastMessage, setToastMessage] = useState<string | null>(null);

  useEffect(() => {
    if (theme === 'dark') {
      document.documentElement.classList.add('dark');
    } else {
      document.documentElement.classList.remove('dark');
    }
    localStorage.setItem('theme', theme);
  }, [theme]);

  const toggleTheme = () => {
    setTheme(prev => prev === 'light' ? 'dark' : 'light');
  };

  const showToast = (message: string) => {
    setToastMessage(message);
    setTimeout(() => setToastMessage(null), 3500);
  };

  const handleAddBook = async (newBook: NewBook) => {
    try {
      await addBook(newBook);
      setIsModalOpen(false);
      setEditingBook(null);
      showToast(`"${newBook.title}" salvo com sucesso!`);
    } catch (error) {
      showToast("Erro de segurança ou rede ao salvar.");
    }
  };

  const handleUpdateBook = async (updatedBook: Book) => {
    try {
      await updateBook(updatedBook);
      setIsModalOpen(false);
      setEditingBook(null);
      if (updatedBook.status === BookStatus.Read) {
          showToast(`Parabéns por concluir "${updatedBook.title}"!`);
      } else {
          showToast(`"${updatedBook.title}" atualizado.`);
      }
    } catch (error) {
      showToast("Ação negada ou erro no banco.");
    }
  };

  const openAddModal = (defaultStatus?: BookStatus) => {
    setEditingBook(null);
    setDefaultStatusForModal(defaultStatus);
    setIsModalOpen(true);
  };

  const shelfBooks = useMemo(() => books.filter(book => book.status !== BookStatus.Wishlist), [books]);
  const wishlistBooks = useMemo(() => books.filter(book => book.status === BookStatus.Wishlist), [books]);

  const [isFading, setIsFading] = useState(false);

  const handleSetView = (newView: 'dashboard' | 'list' | 'wishlist') => {
    if (view !== newView) {
      setIsFading(true);
      setTimeout(() => {
        setView(newView);
        setIsFading(false);
      }, 200);
    }
  };

  if (isAuthLoading) {
    return (
      <div className="min-h-screen bg-background dark:bg-slate-950 flex items-center justify-center">
        <div className="w-10 h-10 border-4 border-primary border-t-transparent rounded-full animate-spin"></div>
      </div>
    );
  }

  if (!session) {
    return <Auth />;
  }

  if (isLoading) {
    return (
      <div className="min-h-screen bg-background dark:bg-slate-950 flex flex-col items-center justify-center p-4">
          <div className="w-12 h-12 border-4 border-primary border-t-transparent rounded-full animate-spin mb-4"></div>
          <p className="text-[10px] font-black uppercase tracking-[0.2em] text-slate-400 dark:text-slate-500">Sincronizando Biblioteca...</p>
      </div>
    );
  }

  return (
    <div className="min-h-screen bg-background dark:bg-slate-950 text-text-main dark:text-slate-200 pb-24 relative transition-colors duration-300">
      <Header 
        onLogoClick={() => handleSetView('dashboard')} 
        theme={theme} 
        toggleTheme={toggleTheme} 
        isConnected={!isLocalMode}
      />

      {isLocalMode && (
        <div className="bg-amber-50 dark:bg-amber-950/30 border-b border-amber-100 dark:border-amber-900/50 px-6 py-2.5 flex flex-col sm:flex-row items-center justify-center gap-2 sm:gap-4 animate-in slide-in-from-top duration-500">
            <div className="flex items-center gap-2">
                <span className="w-2 h-2 rounded-full bg-amber-400 animate-pulse"></span>
                <p className="text-[9px] font-black uppercase tracking-widest text-amber-700 dark:text-amber-400">
                    {schemaError?.type === 'column' 
                      ? `Atenção: Coluna '${schemaError.detail}' faltando. Verifique o SQL.`
                      : schemaError?.type === 'permission'
                      ? 'Erro de Permissão (RLS): O banco negou a operação.'
                      : 'Modo Offline: Usando banco de dados local.'}
                </p>
            </div>
            <button 
              onClick={() => supabase.auth.signOut()}
              className="text-[9px] font-black text-amber-700 hover:underline uppercase"
            >
              Sair da Conta
            </button>
        </div>
      )}

      <main className={`p-4 md:p-8 transition-all duration-300 transform ${isFading ? 'opacity-0 -translate-y-2' : 'opacity-100 translate-y-0'}`}>
        {view === 'dashboard' && (
          <Dashboard 
            stats={stats} 
            currentlyReading={currentlyReading} 
            updateBook={handleUpdateBook}
            dateFilter={dateFilter}
            setDateFilter={setDateFilter} 
            selectedYear={selectedYear}
            setSelectedYear={setSelectedYear}
            availableYears={availableYears}
            books={books}
            customRange={customRange}
            setCustomRange={setCustomRange}
          />
        )}
        {view === 'list' && (
          <BookList 
            books={shelfBooks} 
            onEdit={(b) => { setEditingBook(b); setIsModalOpen(true); }} 
            onDelete={setDeletingBook} 
            onUpdateBook={handleUpdateBook}
          />
        )}
        {view === 'wishlist' && (
          <Wishlist 
            books={wishlistBooks} 
            onEdit={(b) => { setEditingBook(b); setIsModalOpen(true); }} 
            onDelete={setDeletingBook} 
            onMoveToShelf={(b) => handleUpdateBook({ ...b, status: BookStatus.TBR })} 
            onAddWishlistItem={() => openAddModal(BookStatus.Wishlist)}
          />
        )}
      </main>

      <div className="fixed bottom-24 right-6 flex flex-col gap-3">
        <button
            onClick={() => supabase.auth.signOut()}
            className="bg-white dark:bg-slate-800 text-slate-400 p-4 rounded-full shadow-lg hover:text-red-500 transition-all z-40"
            title="Sair"
        >
            <svg xmlns="http://www.w3.org/2000/svg" className="h-6 w-6" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M17 16l4-4m0 0l-4-4m4 4H7m6 4v1a3 3 0 01-3 3H6a3 3 0 01-3-3V7a3 3 0 013-3h4a3 3 0 013 3v1" />
            </svg>
        </button>
        <button
            onClick={() => openAddModal()}
            className="bg-primary text-background p-4 rounded-full shadow-2xl hover:bg-blue-700 transition-all z-40 active:scale-90"
        >
            <PlusIcon className="h-6 w-6" />
        </button>
      </div>

      <BottomNav view={view} setView={handleSetView} />

      {toastMessage && (
        <div className="fixed bottom-32 left-1/2 -translate-x-1/2 z-[60] animate-in fade-in slide-in-from-bottom-4 duration-500">
          <div className="bg-slate-900/95 dark:bg-slate-800/95 backdrop-blur-md text-white px-6 py-3.5 rounded-2xl shadow-2xl border border-white/10 flex items-center gap-3">
            <div className="bg-emerald-500 rounded-full p-1 shadow-sm">
              <svg xmlns="http://www.w3.org/2000/svg" className="h-3.5 w-3.5 text-white" fill="none" viewBox="0 0 24 24" stroke="currentColor" strokeWidth={3}>
                <path strokeLinecap="round" strokeLinejoin="round" d="M5 13l4 4L19 7" />
              </svg>
            </div>
            <p className="text-[11px] font-black uppercase tracking-widest">
              {toastMessage}
            </p>
          </div>
        </div>
      )}

      {isModalOpen && (
        <AddBookModal
          onClose={() => { setIsModalOpen(false); setEditingBook(null); }}
          onAddBook={handleAddBook}
          onUpdateBook={handleUpdateBook}
          bookToEdit={editingBook}
          defaultStatus={defaultStatusForModal}
          existingBooks={books}
        />
      )}

      {deletingBook && (
        <ConfirmationModal
          isOpen={!!deletingBook}
          onClose={() => setDeletingBook(null)}
          onConfirm={async () => { 
            const title = deletingBook.title;
            await deleteBook(deletingBook.id); 
            setDeletingBook(null); 
            showToast(`"${title}" removido.`);
          }}
          title="Excluir Registro"
          message={`Tem certeza que deseja apagar "${deletingBook.title}"?`}
        />
      )}
    </div>
  );
}

import { useState, useMemo, useCallback, useEffect, useRef } from 'react';
import type { Book, ReadingStats, NewBook, DateFilter, MonthlyStat, TypeStat } from '../types';
import { BookStatus, BookType } from '../types';
import { dbService } from '../services/database';
import { generateBookCover } from '../services/geminiService';

const INITIAL_BOOKS: Book[] = [
  {
    id: '11111111-1111-1111-1111-111111111111',
    // Added user_id to fix TypeScript error on line 9
    user_id: 'initial-placeholder',
    title: 'O Senhor dos Anéis - A Sociedade do Anel',
    author: 'J.R.R. Tolkien',
    pages: 434,
    genre: 'Aventura, Fantasia',
    type: BookType.Book,
    status: BookStatus.Reading,
    currentPage: 152,
    dateAdded: '2024-01-15',
    dateStarted: '2024-01-10',
    coverImageUrl: 'https://picsum.photos/seed/lotr/400/600',
    summary: 'Em uma terra fantástica e única, um hobbit recebe de presente de seu tio um anel mágico e maligno.',
  }
];

const MONTHS = ['Janeiro', 'Fevereiro', 'Março', 'Abril', 'Maio', 'Junho', 'Julho', 'Agosto', 'Setembro', 'Outubro', 'Novembro', 'Dezembro'];

export const useBookData = () => {
  const [books, setBooks] = useState<Book[]>([]);
  const [isLoading, setIsLoading] = useState(true);
  const [isLocalMode, setIsLocalMode] = useState(false);
  const [schemaError, setSchemaError] = useState<{type: 'table' | 'column', detail?: string} | null>(null);
  const [dateFilter, setDateFilter] = useState<DateFilter>('allTime');
  const [selectedYear, setSelectedYear] = useState<number>(new Date().getFullYear());
  const [customRange, setCustomRange] = useState({ 
    start: new Date(new Date().getFullYear(), 0, 1).toISOString().split('T')[0],
    end: new Date().toISOString().split('T')[0]
  });

  const autoGenRunning = useRef(false);

  const loadData = useCallback(async () => {
    setIsLoading(true);
    try {
      dbService.setSchemaErrorCallback((type, detail) => {
          setSchemaError({ type, detail });
          setIsLocalMode(true);
      });

      const storedBooks = await dbService.getAllBooks();
      if (storedBooks.length === 0) {
        setBooks(INITIAL_BOOKS);
      } else {
        setBooks(storedBooks);
      }
    } catch (error: any) {
      console.error('Erro crítico ao carregar dados:', error.message);
      setBooks(INITIAL_BOOKS);
      setIsLocalMode(true);
    } finally {
      setIsLoading(false);
    }
  }, []);

  useEffect(() => {
    loadData();
  }, [loadData]);

  const addBook = useCallback(async (newBook: NewBook) => {
    // Added user_id placeholder to fix TypeScript error on line 69. 
    // dbService.saveBook will correctly set the authenticated user_id before persisting.
    const book: Book = {
      ...newBook,
      id: crypto.randomUUID(),
      user_id: '',
      dateAdded: new Date().toISOString().split('T')[0],
    };

    // Sincronização imediata
    setBooks(prev => [book, ...prev]);
    await dbService.saveBook(book);
  }, []);

  const updateBook = useCallback(async (updatedBook: Book) => {
    setBooks(prev => prev.map(b => b.id === updatedBook.id ? updatedBook : b));
    await dbService.saveBook(updatedBook);
  }, []);

  const deleteBook = useCallback(async (id: string) => {
    setBooks(prev => prev.filter(b => b.id !== id));
    await dbService.deleteBook(id);
  }, []);

  useEffect(() => {
    if (isLoading || books.length === 0 || autoGenRunning.current) return;

    const generateCovers = async () => {
      autoGenRunning.current = true;
      const booksWithoutCover = books.filter(b => 
        !b.coverImageUrl || 
        b.coverImageUrl.includes('picsum.photos')
      );

      if (booksWithoutCover.length > 0) {
        for (const book of booksWithoutCover) {
          try {
            const newCoverUrl = await generateBookCover(book.title, book.genre, book.type);
            if (newCoverUrl && !newCoverUrl.includes('picsum.photos')) {
              await updateBook({ ...book, coverImageUrl: newCoverUrl });
            }
          } catch (err) {
            console.error(`Erro ao gerar capa para ${book.title}:`, err);
          }
        }
      }
      autoGenRunning.current = false;
    };

    generateCovers();
  }, [isLoading, books.length, updateBook]);

  const availableYears = useMemo(() => {
    const years = new Set<number>();
    years.add(new Date().getFullYear());
    books.forEach(book => {
      if (book.dateFinished) years.add(new Date(book.dateFinished).getFullYear());
      if (book.dateAdded) years.add(new Date(book.dateAdded).getFullYear());
    });
    return Array.from(years).sort((a, b) => b - a);
  }, [books]);

  const filteredBooks = useMemo(() => {
    return books.filter(book => {
      if (book.status !== BookStatus.Read) return true;
      if (!book.dateFinished) return true;

      const finishDate = new Date(book.dateFinished);
      if (dateFilter === 'thisYear') {
        return finishDate.getFullYear() === new Date().getFullYear();
      }
      if (dateFilter === 'specificYear') {
        return finishDate.getFullYear() === selectedYear;
      }
      if (dateFilter === 'custom') {
        const start = new Date(customRange.start);
        const end = new Date(customRange.end);
        return finishDate >= start && finishDate <= end;
      }
      return true;
    });
  }, [books, dateFilter, selectedYear, customRange]);

  const stats: ReadingStats = useMemo(() => {
    const readBooks = filteredBooks.filter(b => b.status === BookStatus.Read);

    const yearly = {
      booksRead: readBooks.length,
      pagesRead: readBooks.reduce((acc, b) => acc + (b.pages || 0), 0),
      avgRating: readBooks.length > 0 
        ? readBooks.reduce((acc, b) => acc + (b.rating || 0), 0) / (readBooks.filter(b => b.rating).length || 1)
        : 0
    };

    const monthly: MonthlyStat[] = MONTHS.map((month, index) => {
      const monthBooks = readBooks.filter(b => {
        if (!b.dateFinished) return false;
        return new Date(b.dateFinished).getMonth() === index;
      });
      return {
        month,
        booksRead: monthBooks.length,
        pagesRead: monthBooks.reduce((acc, b) => acc + (b.pages || 0), 0),
        avgRating: monthBooks.length > 0 
          ? monthBooks.reduce((acc, b) => acc + (b.rating || 0), 0) / (monthBooks.filter(b => b.rating).length || 1)
          : 0
      };
    });

    const byType: TypeStat[] = [BookType.Book, BookType.HQ].map(type => {
      const typeBooks = readBooks.filter(b => b.type === type);
      return {
        type,
        count: typeBooks.length,
        pages: typeBooks.reduce((acc, b) => acc + (b.pages || 0), 0),
        avgRating: typeBooks.length > 0 
          ? typeBooks.reduce((acc, b) => acc + (b.rating || 0), 0) / (typeBooks.filter(b => b.rating).length || 1)
          : 0
      };
    });

    return {
      tbrCount: books.filter(b => b.status === BookStatus.TBR).length,
      wishlistCount: books.filter(b => b.status === BookStatus.Wishlist).length,
      yearly,
      monthly,
      byType
    };
  }, [books, filteredBooks]);

  const currentlyReading = useMemo(() => {
    return books.find(b => b.status === BookStatus.Reading) || null;
  }, [books]);

  return {
    books,
    stats,
    currentlyReading,
    addBook,
    updateBook,
    deleteBook,
    dateFilter,
    setDateFilter,
    selectedYear,
    setSelectedYear,
    availableYears,
    customRange,
    setCustomRange,
    isLocalMode,
    schemaError,
    isLoading
  };
};

