import React, { useState } from 'react';
import { supabase } from '../services/supabase';
import { BookOpenIcon } from './Icons';

export const Auth: React.FC = () => {
  const [loading, setLoading] = useState(false);
  const [email, setEmail] = useState('');
  const [password, setPassword] = useState('');
  const [fullName, setFullName] = useState('');
  const [mode, setMode] = useState<'login' | 'signup'>('login');
  const [errorMsg, setErrorMsg] = useState<string | null>(null);

  const handleAuth = async (e: React.FormEvent) => {
    e.preventDefault();
    setLoading(true);
    setErrorMsg(null);

    try {
      if (mode === 'login') {
        const { error } = await supabase.auth.signInWithPassword({ email, password });
        if (error) throw error;
      } else {
        // No cadastro, enviamos o full_name nos metadados para o trigger do banco
        const { error, data } = await supabase.auth.signUp({ 
          email, 
          password,
          options: {
            data: {
              full_name: fullName
            }
          }
        });

        if (error) throw error;

        // Se o email confirmation estiver desabilitado no Supabase, o data.session existirá.
        // Caso esteja habilitado, ele precisará confirmar antes do redirect.
        if (data.user && !data.session) {
           alert('Verifique seu e-mail para confirmar o cadastro e acessar sua estante!');
        }
      }
    } catch (error: any) {
      setErrorMsg(error.message || 'Erro ao processar autenticação');
    } finally {
      setLoading(false);
    }
  };

  return (
