import type { Book } from '../types';
import { supabase } from './supabase';

const TABLE_NAME = 'books';
const LOCAL_STORAGE_KEY = 'biblio_tech_local_db';

export class DatabaseService {
  private isSchemaBroken = false;
  private onSchemaErrorCallback?: (type: 'table' | 'column' | 'permission', detail?: string) => void;

  setSchemaErrorCallback(cb: (type: 'table' | 'column' | 'permission', detail?: string) => void) {
    this.onSchemaErrorCallback = cb;
  }

  private getLocalBooks(): Book[] {
    const data = localStorage.getItem(LOCAL_STORAGE_KEY);
    return data ? JSON.parse(data) : [];
  }

  private saveLocalBooks(books: Book[]): void {
    localStorage.setItem(LOCAL_STORAGE_KEY, JSON.stringify(books));
  }

  async getAllBooks(): Promise<Book[]> {
    try {
      const { data, error } = await supabase
        .from(TABLE_NAME)
        .select('*')
        .order('dateAdded', { ascending: false });

      if (error) {
        this.handleSupabaseError(error);
        return this.getLocalBooks();
      }

      this.isSchemaBroken = false;
      this.saveLocalBooks(data as Book[] || []);
      return (data as Book[]) || [];
    } catch (err: any) {
      return this.getLocalBooks();
    }
  }

  async saveBook(book: Partial<Book>): Promise<void> {
    const { data: { user } } = await supabase.auth.getUser();
    if (!user) throw new Error("Usuário não autenticado");

    const sanitizedBook = {
        ...book,
        user_id: user.id,
        pages: Math.max(0, book.pages || 0),
        currentPage: Math.max(0, book.currentPage || 0),
        rating: book.rating ? Math.min(10, Math.max(0, book.rating)) : null,
        estimatedPrice: book.estimatedPrice ? Math.max(0, book.estimatedPrice) : null
    };

    // Atualiza cópia local primeiro (UX rápida)
    const books = this.getLocalBooks();
    const index = books.findIndex(b => b.id === sanitizedBook.id);
    if (index >= 0) {
      books[index] = sanitizedBook as Book;
    } else {
      books.unshift(sanitizedBook as Book);
    }
    this.saveLocalBooks(books);

    if (this.isSchemaBroken) return;

    try {
      const { error } = await supabase
        .from(TABLE_NAME)
        .upsert({
          id: sanitizedBook.id,
          user_id: user.id,
          title: sanitizedBook.title?.trim(),
          author: sanitizedBook.author?.trim(),
          pages: sanitizedBook.pages,
          genre: sanitizedBook.genre,
          type: sanitizedBook.type,
          status: sanitizedBook.status,
          rating: sanitizedBook.rating,
          coverImageUrl: sanitizedBook.coverImageUrl,
          summary: sanitizedBook.summary,
          notes: sanitizedBook.notes,
          estimatedPrice: sanitizedBook.estimatedPrice,
          buyLink: sanitizedBook.buyLink,
          currentPage: sanitizedBook.currentPage,
          dateAdded: sanitizedBook.dateAdded,
          dateStarted: sanitizedBook.dateStarted,
          dateFinished: sanitizedBook.dateFinished
        });

      if (error) this.handleSupabaseError(error);
    } catch (err: any) {
      console.error('Erro de rede:', err.message);
    }
  }

  async deleteBook(id: string): Promise<void> {
    const books = this.getLocalBooks().filter(b => b.id !== id);
    this.saveLocalBooks(books);

    if (this.isSchemaBroken) return;

    try {
      const { error } = await supabase
        .from(TABLE_NAME)
        .delete()
        .eq('id', id);

      if (error) this.handleSupabaseError(error);
    } catch (err: any) {
      console.error('Erro ao deletar:', err.message);
    }
  }

  private handleSupabaseError(error: any) {
    // Tabela não existe
    if (error.code === '42P01') {
      this.isSchemaBroken = true;
      this.onSchemaErrorCallback?.('table');
      return;
    }
    // Erro de permissão (RLS)
    if (error.code === '42501') {
      this.onSchemaErrorCallback?.('permission');
      return;
    }
    // Coluna não existe na tabela
    if (error.code === '42703') {
       const columnName = error.message.match(/"(.*?)"/)?.[1] || 'desconhecida';
       this.onSchemaErrorCallback?.('column', columnName);
       return;
    }
  }
}

