import React, { useEffect, useState } from 'react';
import { BookOpenIcon, SunIcon, MoonIcon, LogoutIcon } from './Icons';
import { supabase } from '../services/supabase';
import type { Profile } from '../types';

interface HeaderProps {
  onLogoClick: () => void;
  theme: 'light' | 'dark';
  toggleTheme: () => void;
  isConnected?: boolean;
}

export const Header: React.FC<HeaderProps> = ({ onLogoClick, theme, toggleTheme, isConnected = true }) => {
  const [profile, setProfile] = useState<Profile | null>(null);

  useEffect(() => {
    let isMounted = true;

    const fetchProfile = async () => {
      const { data: { user } } = await supabase.auth.getUser();
      if (user && isMounted) {
        const { data, error } = await supabase
          .from('profiles')
          .select('*')
          .eq('id', user.id)
          .single();

        if (data && isMounted) {
          setProfile(data);
        } else if (error && isMounted) {
          // Fallback caso o trigger ainda esteja processando ou algo falhou
          setProfile({
             id: user.id,
             full_name: user.user_metadata?.full_name || 'Usuário'
          });
        }
      }
    };

    fetchProfile();
    return () => { isMounted = false; };
  }, []);

  const handleLogout = async () => {
    await supabase.auth.signOut();
  };

  const userInitial = profile?.full_name?.charAt(0).toUpperCase() || '?';

  return (
    <header className="bg-white/80 dark:bg-slate-900/80 backdrop-blur-md border-b border-slate-200/60 dark:border-slate-800 sticky top-0 z-30 px-6 py-4">
      <div className="max-w-7xl mx-auto flex items-center justify-between">
        <div 
          className="flex items-center gap-3 cursor-pointer group" 
          onClick={onLogoClick}
        >
            <div className="bg-primary p-2 rounded-xl shadow-lg shadow-primary/20 group-hover:rotate-6 transition-transform duration-500">
                <BookOpenIcon className="h-6 w-6 text-white" />
            </div>
            <h1 className="text-xl font-black font-serif text-slate-900 dark:text-slate-50 tracking-tight">
              Biblio<span className="text-primary">Tech</span>
            </h1>
        </div>

        <div className="flex items-center gap-2 sm:gap-4">
          <div className="hidden lg:flex items-center gap-2 px-3 py-1.5 rounded-full bg-slate-50 dark:bg-slate-800 border border-slate-200 dark:border-slate-700">
            <div className={`w-1.5 h-1.5 rounded-full ${isConnected ? 'bg-emerald-500 animate-pulse' : 'bg-amber-500'}`}></div>
            <span className="text-[9px] font-black uppercase tracking-widest text-slate-500 dark:text-slate-400">
              {isConnected ? 'Sincronizado' : 'Modo Local'}
            </span>
          </div>

          <button 
            onClick={toggleTheme}
            className="p-2.5 rounded-xl bg-slate-50 dark:bg-slate-800 border border-slate-200 dark:border-slate-700 text-slate-500 dark:text-slate-400 hover:text-primary dark:hover:text-primary transition-all active:scale-95"
            title="Mudar Tema"
          >
            {theme === 'light' ? <MoonIcon className="h-5 w-5" /> : <SunIcon className="h-5 w-5" />}
          </button>

          <button 
            onClick={handleLogout}
            className="p-2.5 rounded-xl bg-slate-50 dark:bg-slate-800 border border-slate-200 dark:border-slate-700 text-slate-400 hover:text-red-500 dark:hover:text-red-400 transition-all active:scale-95 group/logout"
            title="Sair da Conta"
          >
            <LogoutIcon className="h-5 w-5 group-hover:translate-x-0.5 transition-transform" />
          </button>

          <div className="flex items-center gap-3 pl-2 border-l border-slate-100 dark:border-slate-800">
            <div className="hidden sm:flex flex-col items-end">
              <span className="text-[10px] font-black uppercase tracking-widest text-slate-900 dark:text-slate-100 truncate max-w-[120px]">
                {profile?.full_name || 'Usuário'}
              </span>
              <span className="text-[8px] font-bold text-slate-400 uppercase tracking-tighter">Membro BiblioTech</span>
            </div>
            <div className="w-10 h-10 rounded-full bg-primary/10 border border-primary/20 flex items-center justify-center text-primary font-black text-sm shadow-inner overflow-hidden">
               {userInitial}
            </div>
          </div>
        </div>
      </div>
    </header>
  );
};

import React, { useState, useMemo, useEffect } from 'react';
import { useBookData } from './hooks/useBookData';
import { Header } from './components/Header';
import { Dashboard } from './components/Dashboard';
import { AddBookModal } from './components/AddBookModal';
import { PlusIcon } from './components/Icons';
import type { Book, NewBook } from './types';
import { BookList } from './components/BookList';
import { ConfirmationModal } from './components/ConfirmationModal';
import { BookStatus } from './types';
import { Wishlist } from './components/Wishlist';
import { BottomNav } from './components/BottomNav';
import { Auth } from './components/Auth';
import { supabase } from './services/supabase';

export default function App() {
  const [session, setSession] = useState<any>(null);
  const [isAuthLoading, setIsAuthLoading] = useState(true);

  useEffect(() => {
    supabase.auth.getSession().then(({ data: { session } }) => {
      setSession(session);
      setIsAuthLoading(false);
    });

    const { data: { subscription } } = supabase.auth.onAuthStateChange((_event, session) => {
      setSession(session);
    });

    return () => subscription.unsubscribe();
  }, []);

  const { 
    books, 
    stats, 
    currentlyReading, 
    addBook, 
    updateBook, 
    deleteBook, 
    dateFilter, 
    setDateFilter,
    selectedYear,
    setSelectedYear,
    availableYears,
    customRange,
    setCustomRange,
    isLocalMode,
    schemaError,
    isLoading
  } = useBookData();

  const [theme, setTheme] = useState<'light' | 'dark'>(() => {
    return (localStorage.getItem('theme') as 'light' | 'dark') || 'light';
  });

  const [isModalOpen, setIsModalOpen] = useState(false);
  const [view, setView] = useState<'dashboard' | 'list' | 'wishlist'>('dashboard');
  const [editingBook, setEditingBook] = useState<Book | null>(null);
  const [deletingBook, setDeletingBook] = useState<Book | null>(null);
  const [defaultStatusForModal, setDefaultStatusForModal] = useState<BookStatus | undefined>();
  const [toastMessage, setToastMessage] = useState<string | null>(null);

  useEffect(() => {
    if (theme === 'dark') {
      document.documentElement.classList.add('dark');
    } else {
      document.documentElement.classList.remove('dark');
    }
    localStorage.setItem('theme', theme);
  }, [theme]);

  const toggleTheme = () => {
    setTheme(prev => prev === 'light' ? 'dark' : 'light');
  };

  const showToast = (message: string) => {
    setToastMessage(message);
    setTimeout(() => setToastMessage(null), 3500);
  };

  const handleAddBook = async (newBook: NewBook) => {
    try {
      await addBook(newBook);
      setIsModalOpen(false);
      setEditingBook(null);
      showToast(`"${newBook.title}" salvo com sucesso!`);
    } catch (error) {
      showToast("Erro de segurança ou rede ao salvar.");
    }
  };

  const handleUpdateBook = async (updatedBook: Book) => {
    try {
      await updateBook(updatedBook);
      setIsModalOpen(false);
      setEditingBook(null);
      if (updatedBook.status === BookStatus.Read) {
          showToast(`Parabéns por concluir "${updatedBook.title}"!`);
      } else {
          showToast(`"${updatedBook.title}" atualizado.`);
      }
    } catch (error) {
      showToast("Ação negada ou erro no banco.");
    }
  };

  const openAddModal = (defaultStatus?: BookStatus) => {
    setEditingBook(null);
    setDefaultStatusForModal(defaultStatus);
    setIsModalOpen(true);
  };

  const shelfBooks = useMemo(() => books.filter(book => book.status !== BookStatus.Wishlist), [books]);
  const wishlistBooks = useMemo(() => books.filter(book => book.status === BookStatus.Wishlist), [books]);

  const [isFading, setIsFading] = useState(false);

  const handleSetView = (newView: 'dashboard' | 'list' | 'wishlist') => {
    if (view !== newView) {
      setIsFading(true);
      setTimeout(() => {
        setView(newView);
        setIsFading(false);
      }, 200);
    }
  };

  if (isAuthLoading) {
    return (
      <div className="min-h-screen bg-background dark:bg-slate-950 flex items-center justify-center">
        <div className="w-10 h-10 border-4 border-primary border-t-transparent rounded-full animate-spin"></div>
      </div>
    );
  }

  if (!session) {
    return <Auth />;
  }

  if (isLoading) {
    return (
      <div className="min-h-screen bg-background dark:bg-slate-950 flex flex-col items-center justify-center p-4">
          <div className="w-12 h-12 border-4 border-primary border-t-transparent rounded-full animate-spin mb-4"></div>
          <p className="text-[10px] font-black uppercase tracking-[0.2em] text-slate-400 dark:text-slate-500">Sincronizando Biblioteca...</p>
      </div>
    );
  }

  return (
    <div className="min-h-screen bg-background dark:bg-slate-950 text-text-main dark:text-slate-200 pb-24 relative transition-colors duration-300">
      <Header 
        onLogoClick={() => handleSetView('dashboard')} 
        theme={theme} 
        toggleTheme={toggleTheme} 
        isConnected={!isLocalMode}
      />

      {isLocalMode && (
        <div className="bg-amber-50 dark:bg-amber-950/30 border-b border-amber-100 dark:border-amber-900/50 px-6 py-2.5 flex flex-col sm:flex-row items-center justify-center gap-2 sm:gap-4 animate-in slide-in-from-top duration-500">
            <div className="flex items-center gap-2">
                <span className="w-2 h-2 rounded-full bg-amber-400 animate-pulse"></span>
                <p className="text-[9px] font-black uppercase tracking-widest text-amber-700 dark:text-amber-400">
                    {schemaError?.type === 'column' 
                      ? `Atenção: Coluna '${schemaError.detail}' faltando. Verifique o SQL.`
                      : schemaError?.type === 'permission'
                      ? 'Erro de Permissão (RLS): O banco negou a operação.'
                      : 'Modo Offline: Usando banco de dados local.'}
                </p>
            </div>
            <button 
              onClick={() => supabase.auth.signOut()}
              className="text-[9px] font-black text-amber-700 hover:underline uppercase"
            >
              Sair da Conta
            </button>
        </div>
      )}

      <main className={`p-4 md:p-8 transition-all duration-300 transform ${isFading ? 'opacity-0 -translate-y-2' : 'opacity-100 translate-y-0'}`}>
        {view === 'dashboard' && (
          <Dashboard 
            stats={stats} 
            currentlyReading={currentlyReading} 
            updateBook={handleUpdateBook}
            dateFilter={dateFilter}
            setDateFilter={setDateFilter} 
            selectedYear={selectedYear}
            setSelectedYear={setSelectedYear}
            availableYears={availableYears}
            books={books}
            customRange={customRange}
            setCustomRange={setCustomRange}
          />
        )}
        {view === 'list' && (
          <BookList 
            books={shelfBooks} 
            onEdit={(b) => { setEditingBook(b); setIsModalOpen(true); }} 
            onDelete={setDeletingBook} 
            onUpdateBook={handleUpdateBook}
          />
        )}
        {view === 'wishlist' && (
          <Wishlist 
            books={wishlistBooks} 
            onEdit={(b) => { setEditingBook(b); setIsModalOpen(true); }} 
            onDelete={setDeletingBook} 
            onMoveToShelf={(b) => handleUpdateBook({ ...b, status: BookStatus.TBR })} 
            onAddWishlistItem={() => openAddModal(BookStatus.Wishlist)}
          />
        )}
      </main>

      <div className="fixed bottom-24 right-6 flex flex-col gap-3">
        <button
            onClick={() => openAddModal()}
            className="bg-primary text-background p-4 rounded-full shadow-2xl hover:bg-blue-700 transition-all z-40 active:scale-95 flex items-center justify-center"
            title="Adicionar Livro"
        >
            <PlusIcon className="h-6 w-6" />
        </button>
      </div>

      <BottomNav view={view} setView={handleSetView} />

      {toastMessage && (
        <div className="fixed bottom-32 left-1/2 -translate-x-1/2 z-[60] animate-in fade-in slide-in-from-bottom-4 duration-500">
          <div className="bg-slate-900/95 dark:bg-slate-800/95 backdrop-blur-md text-white px-6 py-3.5 rounded-2xl shadow-2xl border border-white/10 flex items-center gap-3">
            <div className="bg-emerald-500 rounded-full p-1 shadow-sm">
              <svg xmlns="http://www.w3.org/2000/svg" className="h-3.5 w-3.5 text-white" fill="none" viewBox="0 0 24 24" stroke="currentColor" strokeWidth={3}>
                <path strokeLinecap="round" strokeLinejoin="round" d="M5 13l4 4L19 7" />
              </svg>
            </div>
            <p className="text-[11px] font-black uppercase tracking-widest">
              {toastMessage}
            </p>
          </div>
        </div>
      )}

      {isModalOpen && (
        <AddBookModal
          onClose={() => { setIsModalOpen(false); setEditingBook(null); }}
          onAddBook={handleAddBook}
          onUpdateBook={handleUpdateBook}
          bookToEdit={editingBook}
          defaultStatus={defaultStatusForModal}
          existingBooks={books}
        />
      )}

      {deletingBook && (
        <ConfirmationModal
          isOpen={!!deletingBook}
          onClose={() => setDeletingBook(null)}
          onConfirm={async () => { 
            const title = deletingBook.title;
            await deleteBook(deletingBook.id); 
            setDeletingBook(null); 
            showToast(`"${title}" removido.`);
          }}
          title="Excluir Registro"
          message={`Tem certeza que deseja apagar "${deletingBook.title}"?`}
        />
      )}
    </div>
  );
}

