          </div>
        </div>

        <div className="p-7 bg-slate-50 dark:bg-slate-800/30 border-t border-slate-100 dark:border-slate-800 flex justify-end gap-3">
          <button 
            onClick={onClose}
            className="px-6 py-3 rounded-xl text-slate-500 dark:text-slate-400 font-black text-[10px] uppercase tracking-widest hover:bg-slate-200 dark:hover:bg-slate-700 transition-all"
          >
            Cancelar
          </button>
          <button 
            onClick={handleSave}
            className="px-8 py-3 rounded-xl bg-primary text-white font-black text-[10px] uppercase tracking-widest hover:bg-slate-900 dark:hover:bg-white dark:hover:text-slate-900 shadow-xl shadow-primary/20 transition-all active:scale-95"
          >
            Salvar Configurações
          </button>
        </div>
      </div>
    </div>
  );
};

import React, { useState, useMemo, useEffect } from 'react';
import { useBookData } from './hooks/useBookData';
import { Header } from './components/Header';
import { Dashboard } from './components/Dashboard';
import { AddBookModal } from './components/AddBookModal';
import { SettingsModal } from './components/SettingsModal';
import { PlusIcon } from './components/Icons';
import type { Book, NewBook } from './types';
import { BookList } from './components/BookList';
import { ConfirmationModal } from './components/ConfirmationModal';
import { BookStatus } from './types';
import { Wishlist } from './components/Wishlist';
import { BottomNav } from './components/BottomNav';
import { Auth } from './components/Auth';
import { supabase } from './services/supabase';

export default function App() {
  const [session, setSession] = useState<any>(null);
  const [isAuthLoading, setIsAuthLoading] = useState(true);

  useEffect(() => {
    supabase.auth.getSession().then(({ data: { session } }) => {
      setSession(session);
      setIsAuthLoading(false);
    });

    const { data: { subscription } } = supabase.auth.onAuthStateChange((_event, session) => {
      setSession(session);
    });

    return () => subscription.unsubscribe();
  }, []);

  const { 
    books, 
    stats, 
    currentlyReading, 
    addBook, 
    updateBook, 
    deleteBook, 
    dateFilter, 
    setDateFilter,
    selectedYear,
    setSelectedYear,
    availableYears,
    customRange,
    setCustomRange,
    isLocalMode,
    schemaError,
    isLoading
  } = useBookData();

  const [theme, setTheme] = useState<'light' | 'dark'>(() => {
    return (localStorage.getItem('theme') as 'light' | 'dark') || 'light';
  });

  const [readingGoal, setReadingGoal] = useState(() => {
    const saved = localStorage.getItem('biblio_tech_goal');
    return saved ? parseInt(saved, 10) : 12;
  });

  useEffect(() => {
    localStorage.setItem('biblio_tech_goal', readingGoal.toString());
  }, [readingGoal]);

  const [isModalOpen, setIsModalOpen] = useState(false);
  const [isSettingsOpen, setIsSettingsOpen] = useState(false);
  const [view, setView] = useState<'dashboard' | 'list' | 'wishlist'>('dashboard');
  const [editingBook, setEditingBook] = useState<Book | null>(null);
  const [deletingBook, setDeletingBook] = useState<Book | null>(null);
  const [defaultStatusForModal, setDefaultStatusForModal] = useState<BookStatus | undefined>();
  const [toastMessage, setToastMessage] = useState<string | null>(null);

  useEffect(() => {
    if (theme === 'dark') {
      document.documentElement.classList.add('dark');
    } else {
      document.documentElement.classList.remove('dark');
    }
    localStorage.setItem('theme', theme);
  }, [theme]);

  const toggleTheme = () => {
    setTheme(prev => prev === 'light' ? 'dark' : 'light');
  };

  const showToast = (message: string) => {
    setToastMessage(message);
    setTimeout(() => setToastMessage(null), 3500);
  };

  const handleAddBook = async (newBook: NewBook) => {
    try {
      await addBook(newBook);
      setIsModalOpen(false);
      setEditingBook(null);
      showToast(`"${newBook.title}" salvo com sucesso!`);
    } catch (error) {
      showToast("Erro de segurança ou rede ao salvar.");
    }
  };

  const handleUpdateBook = async (updatedBook: Book) => {
    try {
      await updateBook(updatedBook);
      setIsModalOpen(false);
      setEditingBook(null);
      if (updatedBook.status === BookStatus.Read) {
          showToast(`Parabéns por concluir "${updatedBook.title}"!`);
      } else {
          showToast(`"${updatedBook.title}" atualizado.`);
      }
    } catch (error) {
      showToast("Ação negada ou erro no banco.");
    }
  };

  const openAddModal = (defaultStatus?: BookStatus) => {
    setEditingBook(null);
    setDefaultStatusForModal(defaultStatus);
    setIsModalOpen(true);
  };

  const shelfBooks = useMemo(() => books.filter(book => book.status !== BookStatus.Wishlist), [books]);
  const wishlistBooks = useMemo(() => books.filter(book => book.status === BookStatus.Wishlist), [books]);

  const [isFading, setIsFading] = useState(false);

  const handleSetView = (newView: 'dashboard' | 'list' | 'wishlist') => {
    if (view !== newView) {
      setIsFading(true);
      setTimeout(() => {
        setView(newView);
        setIsFading(false);
      }, 200);
    }
  };

  if (isAuthLoading) {
    return (
      <div className="min-h-screen bg-background dark:bg-slate-950 flex items-center justify-center">
        <div className="w-10 h-10 border-4 border-primary border-t-transparent rounded-full animate-spin"></div>
      </div>
    );
  }

  if (!session) {
    return <Auth />;
  }

  if (isLoading) {
    return (
      <div className="min-h-screen bg-background dark:bg-slate-950 flex flex-col items-center justify-center p-4">
          <div className="w-12 h-12 border-4 border-primary border-t-transparent rounded-full animate-spin mb-4"></div>
          <p className="text-[10px] font-black uppercase tracking-[0.2em] text-slate-400 dark:text-slate-500">Sincronizando Biblioteca...</p>
      </div>
    );
  }

  return (
    <div className="min-h-screen bg-background dark:bg-slate-950 text-text-main dark:text-slate-200 pb-24 relative transition-colors duration-300">
      <Header 
        onLogoClick={() => handleSetView('dashboard')} 
        onSettingsClick={() => setIsSettingsOpen(true)}
        theme={theme} 
        toggleTheme={toggleTheme} 
        isConnected={!isLocalMode}
      />

      {isLocalMode && (
        <div className="bg-amber-50 dark:bg-amber-950/30 border-b border-amber-100 dark:border-amber-900/50 px-6 py-2.5 flex flex-col sm:flex-row items-center justify-center gap-2 sm:gap-4 animate-in slide-in-from-top duration-500">
            <div className="flex items-center gap-2">
                <span className="w-2 h-2 rounded-full bg-amber-400 animate-pulse"></span>
                <p className="text-[9px] font-black uppercase tracking-widest text-amber-700 dark:text-amber-400">
                    {schemaError?.type === 'column' 
                      ? `Atenção: Coluna '${schemaError.detail}' faltando. Verifique o SQL.`
                      : schemaError?.type === 'permission'
                      ? 'Erro de Permissão (RLS): O banco negou a operação.'
                      : 'Modo Offline: Usando banco de dados local.'}
                </p>
            </div>
            <button 
              onClick={() => supabase.auth.signOut()}
              className="text-[9px] font-black text-amber-700 hover:underline uppercase"
            >
              Sair da Conta
            </button>
        </div>
      )}

      <main className={`p-4 md:p-8 transition-all duration-300 transform ${isFading ? 'opacity-0 -translate-y-2' : 'opacity-100 translate-y-0'}`}>
        {view === 'dashboard' && (
          <Dashboard 
            stats={stats} 
            currentlyReading={currentlyReading} 
            updateBook={handleUpdateBook}
            dateFilter={dateFilter}
            setDateFilter={setDateFilter} 
            selectedYear={selectedYear}
            setSelectedYear={setSelectedYear}
            availableYears={availableYears}
            books={books}
            customRange={customRange}
            setCustomRange={setCustomRange}
            readingGoal={readingGoal}
            onSetReadingGoal={setReadingGoal}
          />
        )}
        {view === 'list' && (
          <BookList 
            books={shelfBooks} 
            onEdit={(b) => { setEditingBook(b); setIsModalOpen(true); }} 
            onDelete={setDeletingBook} 
            onUpdateBook={handleUpdateBook}
          />
        )}
        {view === 'wishlist' && (
          <Wishlist 
            books={wishlistBooks} 
            onEdit={(b) => { setEditingBook(b); setIsModalOpen(true); }} 
            onDelete={setDeletingBook} 
            onMoveToShelf={(b) => handleUpdateBook({ ...b, status: BookStatus.TBR })} 
            onAddWishlistItem={() => openAddModal(BookStatus.Wishlist)}
          />
        )}
      </main>

      <div className="fixed bottom-24 right-6 flex flex-col gap-3">
        <button
            onClick={() => openAddModal()}
            className="bg-primary text-background p-4 rounded-full shadow-2xl hover:bg-blue-700 transition-all z-40 active:scale-95 flex items-center justify-center"
            title="Adicionar Livro"
        >
            <PlusIcon className="h-6 w-6" />
        </button>
      </div>

      <BottomNav view={view} setView={handleSetView} />

      {toastMessage && (
        <div className="fixed bottom-32 left-1/2 -translate-x-1/2 z-[60] animate-in fade-in slide-in-from-bottom-4 duration-500">
          <div className="bg-slate-900/95 dark:bg-slate-800/95 backdrop-blur-md text-white px-6 py-3.5 rounded-2xl shadow-2xl border border-white/10 flex items-center gap-3">
            <div className="bg-emerald-500 rounded-full p-1 shadow-sm">
              <svg xmlns="http://www.w3.org/2000/svg" className="h-3.5 w-3.5 text-white" fill="none" viewBox="0 0 24 24" stroke="currentColor" strokeWidth={3}>
                <path strokeLinecap="round" strokeLinejoin="round" d="M5 13l4 4L19 7" />
              </svg>
            </div>
            <p className="text-[11px] font-black uppercase tracking-widest">
              {toastMessage}
            </p>
          </div>
        </div>
      )}

      {isModalOpen && (
        <AddBookModal
          onClose={() => { setIsModalOpen(false); setEditingBook(null); }}
          onAddBook={handleAddBook}
          onUpdateBook={handleUpdateBook}
          bookToEdit={editingBook}
          defaultStatus={defaultStatusForModal}
          existingBooks={books}
        />
      )}

      {isSettingsOpen && (
        <SettingsModal
          onClose={() => setIsSettingsOpen(false)}
          readingGoal={readingGoal}
          onSetReadingGoal={setReadingGoal}
        />
      )}

      {deletingBook && (
        <ConfirmationModal
          isOpen={!!deletingBook}
          onClose={() => setDeletingBook(null)}
          onConfirm={async () => { 
            const title = deletingBook.title;
            await deleteBook(deletingBook.id); 
            setDeletingBook(null); 
            showToast(`"${title}" removido.`);
          }}
          title="Excluir Registro"
          message={`Tem certeza que deseja apagar "${deletingBook.title}"?`}
        />
      )}
    </div>
  );
}

import React, { useMemo, useState, useEffect } from 'react';
import type { ReadingStats, Book, DateFilter, Recommendation } from '../types';
import { BookStatus } from '../types';
import { StatCard } from './StatCard';
import { CurrentlyReading } from './CurrentlyReading';
import { MonthlyChart } from './MonthlyChart';
import { TypePieChart } from './TypePieChart';
import { ReadingGoal } from './ReadingGoal';
import { Recommendations } from './Recommendations';
import { LatestReadings } from './LatestReadings';
import { BookOpenIcon, ChartBarIcon, StarIcon, TagIcon, HeartIcon } from './Icons';
import { getAIRecommendations } from '../services/geminiService';

interface DashboardProps {
  stats: ReadingStats;
  currentlyReading: Book | null;
  updateBook: (book: Book) => void;
  dateFilter: DateFilter;
  setDateFilter: (filter: DateFilter) => void;
  selectedYear: number;
  setSelectedYear: (year: number) => void;
  availableYears: number[];
  books: Book[];
  customRange?: { start: string; end: string };
  setCustomRange?: (range: { start: string; end: string }) => void;
  readingGoal: number;
  onSetReadingGoal: (val: number) => void;
}

export const Dashboard: React.FC<DashboardProps> = ({ 
  stats, 
  currentlyReading, 
  updateBook, 
  dateFilter, 
  setDateFilter,
  selectedYear,
  setSelectedYear,
  availableYears,
  books,
  customRange,
  setCustomRange,
  readingGoal,
  onSetReadingGoal
}) => {
  const [aiRecs, setAiRecs] = useState<Recommendation[]>([]);
  const [isLoadingRecs, setIsLoadingRecs] = useState(false);

  const fetchRecs = async () => {
    setIsLoadingRecs(true);
    const readBooks = books
      .filter(b => b.status === BookStatus.Read)
      .map(b => ({ title: b.title, genre: b.genre }));

    if (readBooks.length > 0) {
      const recs = await getAIRecommendations(readBooks);
      setAiRecs(recs);
    }
    setIsLoadingRecs(false);
  };

  useEffect(() => {
    if (aiRecs.length === 0) {
        fetchRecs();
    }
  }, []);

  const formatDateForTitle = (dateStr?: string) => {
    if (!dateStr) return '';
    const [y, m, d] = dateStr.split('-');
    return `${d}/${m}/${y.substring(2)}`;
  };

  const periodTitle = useMemo(() => {
    if (dateFilter === 'thisYear') return 'Ano Atual';
    if (dateFilter === 'allTime') return 'Todo o Período';
    if (dateFilter === 'specificYear') return `Ano de ${selectedYear}`;
    if (dateFilter === 'custom' && customRange) {
        return `De ${formatDateForTitle(customRange.start)} a ${formatDateForTitle(customRange.end)}`;
    }
    return '';
  }, [dateFilter, customRange, selectedYear]);

  const latestReadBooks = useMemo(() => {
    return books
      .filter(b => b.status === BookStatus.Read && b.dateFinished)
      .sort((a, b) => (b.dateFinished || '').localeCompare(a.dateFinished || ''))
      .slice(0, 5);
  }, [books]);

  return (
    <div className="max-w-7xl mx-auto space-y-12 pb-16">
      <div className="flex flex-col xl:flex-row justify-between items-start xl:items-center gap-6">
        <div>
            <h2 className="text-3xl font-bold font-serif text-slate-900 dark:text-slate-50 tracking-tight">Visão Geral</h2>
            <p className="text-slate-500 dark:text-slate-400 text-sm font-medium mt-1">Sua jornada intelectual em números e descobertas.</p>
        </div>

        <div className="flex flex-col sm:flex-row items-stretch sm:items-center gap-4 bg-white dark:bg-slate-900 p-2 rounded-2xl border border-slate-200 dark:border-slate-800 shadow-sm w-full sm:w-auto">
            <div className="flex items-center p-1 bg-slate-50 dark:bg-slate-800 rounded-xl border border-slate-100 dark:border-slate-700">
                <button
                    onClick={() => setDateFilter('thisYear')}
                    className={`px-4 py-2 text-xs font-black uppercase tracking-wider rounded-lg transition-all ${dateFilter === 'thisYear' ? 'bg-primary text-white shadow-md' : 'text-slate-400 dark:text-slate-500 hover:text-primary dark:hover:text-primary'}`}
                >
                    Ano
                </button>
                <button
                    onClick={() => setDateFilter('specificYear')}
                    className={`px-4 py-2 text-xs font-black uppercase tracking-wider rounded-lg transition-all ${dateFilter === 'specificYear' ? 'bg-primary text-white shadow-md' : 'text-slate-400 dark:text-slate-500 hover:text-primary dark:hover:text-primary'}`}
                >
                    Anos
                </button>
                <button
                    onClick={() => setDateFilter('allTime')}
                    className={`px-4 py-2 text-xs font-black uppercase tracking-wider rounded-lg transition-all ${dateFilter === 'allTime' ? 'bg-primary text-white shadow-md' : 'text-slate-400 dark:text-slate-500 hover:text-primary dark:hover:text-primary'}`}
                >
                    Tudo
                </button>
                <button
                    onClick={() => setDateFilter('custom')}
                    className={`px-4 py-2 text-xs font-black uppercase tracking-wider rounded-lg transition-all ${dateFilter === 'custom' ? 'bg-primary text-white shadow-md' : 'text-slate-400 dark:text-slate-500 hover:text-primary dark:hover:text-primary'}`}
                >
                    Agenda
                </button>
            </div>

            {dateFilter === 'specificYear' && (
                <div className="flex items-center gap-2 animate-in fade-in slide-in-from-right-4 duration-500">
                    <select 
                        value={selectedYear}
                        onChange={(e) => setSelectedYear(Number(e.target.value))}
                        className="bg-white dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-lg px-3 py-1.5 text-xs font-black uppercase tracking-widest text-slate-700 dark:text-slate-300 outline-none focus:border-primary transition-colors cursor-pointer"
                    >
                        {availableYears.map(year => (
                            <option key={year} value={year}>{year}</option>
                        ))}
                    </select>
                </div>
            )}
        </div>
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-12 gap-8">
        <div className="lg:col-span-8">
          {currentlyReading ? (
            <CurrentlyReading book={currentlyReading} updateBook={updateBook} />
          ) : (
            <div className="bg-white dark:bg-slate-900 border-2 border-dashed border-slate-200 dark:border-slate-800 p-12 rounded-[2.5rem] flex flex-col items-center justify-center text-center h-full">
              <div className="bg-slate-50 dark:bg-slate-800 p-4 rounded-full mb-4">
                <BookOpenIcon className="h-10 w-10 text-slate-300 dark:text-slate-600" />
              </div>
              <h2 className="text-xl font-bold text-slate-900 dark:text-slate-50 mb-2">Nenhuma leitura ativa</h2>
              <p className="text-slate-400 dark:text-slate-500 max-w-xs">Sua estante está cheia de aventuras esperando por você.</p>
            </div>
          )}
        </div>
        <div className="lg:col-span-4 flex flex-col gap-6">
          <ReadingGoal 
            current={stats.yearly.booksRead} 
            goal={readingGoal} 
            onSetGoal={onSetReadingGoal} 
          />
          <StatCard 
            icon={<StarIcon className="h-6 w-6" />} 
            title="Avaliação Média" 
            value={stats.yearly.avgRating.toFixed(1)}
            subtitle="estrelas"
          />
        </div>
      </div>

      <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-6">
        <StatCard 
            icon={<BookOpenIcon className="h-6 w-6" />} 
            title="Total Lidos"
            value={stats.yearly.booksRead.toString()} 
            subtitle={periodTitle}
        />
        <StatCard 
            icon={<TagIcon className="h-6 w-6" />} 
            title="Páginas Lidas"
            value={stats.yearly.pagesRead.toLocaleString('pt-BR')}
            subtitle={periodTitle}
        />
        <StatCard 
            icon={<ChartBarIcon className="h-6 w-6" />} 
            title="Na Fila (TBR)" 
            value={stats.tbrCount.toString()}
            subtitle="livros p/ ler"
        />
        <StatCard 
            icon={<HeartIcon className="h-6 w-6" />} 
            title="Lista de Desejos" 
            value={stats.wishlistCount.toString()}
            subtitle="interesse futuro"
        />
      </div>

      <LatestReadings books={latestReadBooks} />

      <Recommendations 
        suggestions={aiRecs} 
        isLoading={isLoadingRecs} 
        onRefresh={fetchRecs} 
      />

      <div className="bg-white dark:bg-slate-900 p-8 rounded-[2.5rem] shadow-soft border border-slate-100 dark:border-slate-800 transition-all hover:shadow-xl">
        <div className="flex flex-col md:flex-row justify-between items-start md:items-center mb-8 gap-4">
          <div>
            <h2 className="text-2xl font-bold font-serif text-slate-900 dark:text-slate-50">Evolução de Leitura</h2>
            <p className="text-slate-400 dark:text-slate-500 text-sm mt-1 font-medium italic">Dados baseados no período: {periodTitle}</p>
          </div>
          <div className="flex gap-6">
            <div className="flex items-center gap-2">
                <div className="w-3 h-3 rounded-sm bg-primary"></div>
                <span className="text-[10px] font-bold text-slate-500 dark:text-slate-400 uppercase tracking-widest">Livros</span>
            </div>
            <div className="flex items-center gap-2">
                <div className="w-3 h-3 rounded-full bg-slate-200 dark:bg-slate-700 border border-slate-300 dark:bg-slate-600"></div>
                <span className="text-[10px] font-bold text-slate-500 dark:text-slate-400 uppercase tracking-widest">Páginas</span>
            </div>
          </div>
        </div>
        <MonthlyChart data={stats.monthly} />
      </div>

      <div className="bg-white dark:bg-slate-900 p-8 rounded-[2.5rem] shadow-soft border border-slate-100 dark:border-slate-800">
          <h2 className="text-xl font-bold font-serif text-slate-900 dark:text-slate-50 mb-6">Distribuição por Categoria</h2>
          <div className="h-[300px]">
              <TypePieChart data={stats.byType} />
          </div>
      </div>
    </div>
  );
};

import type { Book } from '../types';
import { supabase } from './supabase';

const TABLE_NAME = 'books';
const BASE_LOCAL_STORAGE_KEY = 'biblio_tech_cache_';

export class DatabaseService {
  private isSchemaBroken = false;
  private onSchemaErrorCallback?: (type: 'table' | 'column' | 'permission', detail?: string) => void;

  setSchemaErrorCallback(cb: (type: 'table' | 'column' | 'permission', detail?: string) => void) {
    this.onSchemaErrorCallback = cb;
  }

  // Gera uma chave de cache única para cada usuário logado
  private async getCacheKey(): Promise<string | null> {
    const { data: { user } } = await supabase.auth.getUser();
    return user ? `${BASE_LOCAL_STORAGE_KEY}${user.id}` : null;
  }

  private async getLocalBooks(): Promise<Book[]> {
    const key = await this.getCacheKey();
    if (!key) return [];
    const data = localStorage.getItem(key);
    return data ? JSON.parse(data) : [];
  }

  private async saveLocalBooks(books: Book[]): Promise<void> {
    const key = await this.getCacheKey();
    if (key) {
      localStorage.setItem(key, JSON.stringify(books));
    }
  }

  async getAllBooks(): Promise<Book[]> {
    try {
      const { data, error } = await supabase
        .from(TABLE_NAME)
        .select('*')
        .order('dateAdded', { ascending: false });

      if (error) {
        this.handleSupabaseError(error);
        return await this.getLocalBooks();
      }

      this.isSchemaBroken = false;
      const books = (data as Book[]) || [];
      await this.saveLocalBooks(books);
      return books;
    } catch (err: any) {
      return await this.getLocalBooks();
    }
  }

  async saveBook(book: Partial<Book>): Promise<void> {
    const { data: { user } } = await supabase.auth.getUser();
    if (!user) throw new Error("Acesso negado: Usuário não autenticado.");

    // Garante que o objeto enviado ao Supabase esteja limpo e com os tipos corretos
    const sanitizedBook = {
        ...book,
        user_id: user.id,
        pages: Math.max(0, book.pages || 0),
        currentPage: Math.max(0, book.currentPage || 0),
        rating: book.rating ? Math.min(10, Math.max(0, book.rating)) : null,
        estimatedPrice: book.estimatedPrice ? Math.max(0, book.estimatedPrice) : null,
        daysToFinish: book.daysToFinish !== undefined && book.daysToFinish !== null ? Math.max(0, Number(book.daysToFinish)) : null
    };

    // UX: Atualiza cache local primeiro
    const books = await this.getLocalBooks();
    const index = books.findIndex(b => b.id === sanitizedBook.id);
    if (index >= 0) {
      books[index] = sanitizedBook as Book;
    } else {
      books.unshift(sanitizedBook as Book);
    }
    await this.saveLocalBooks(books);

    if (this.isSchemaBroken) return;

    try {
      const { error } = await supabase
        .from(TABLE_NAME)
        .upsert(sanitizedBook);

      if (error) this.handleSupabaseError(error);
    } catch (err: any) {
      console.error('Erro de rede:', err.message);
    }
  }

  async deleteBook(id: string): Promise<void> {
    const books = (await this.getLocalBooks()).filter(b => b.id !== id);
    await this.saveLocalBooks(books);

    if (this.isSchemaBroken) return;

    try {
      const { error } = await supabase
        .from(TABLE_NAME)
        .delete()
        .eq('id', id);

      if (error) this.handleSupabaseError(error);
    } catch (err: any) {
      console.error('Erro ao deletar:', err.message);
    }
  }

  private handleSupabaseError(error: any) {
    if (error.code === '42P01') {
      this.isSchemaBroken = true;
      this.onSchemaErrorCallback?.('table');
      return;
    }
    if (error.code === '42501') {
      this.onSchemaErrorCallback?.('permission');
      return;
    }
    if (error.code === '42703') {
       const columnName = error.message.match(/"(.*?)"/)?.[1] || 'desconhecida';
       this.onSchemaErrorCallback?.('column', columnName);
       return;
    }
  }
}

export const dbService = new DatabaseService();

import React, { useState, useCallback, useEffect } from 'react';
import type { NewBook, Book, StatusConfigs } from '../types';
import { BookStatus, BookType, GENRES, STATUS_CONFIGS } from '../types';
import { XMarkIcon, BookOpenIcon, StarIcon, StarIconFilled } from './Icons';
import { generateBookSummary, generateBookCover } from '../services/geminiService';

interface AddBookModalProps {
  onClose: () => void;
  onAddBook: (book: NewBook) => Promise<void>;
  onUpdateBook: (book: Book) => Promise<void>;
  bookToEdit?: Book | null;
  defaultStatus?: BookStatus;
  existingBooks: Book[];
  statusConfigs?: StatusConfigs;
}

interface FormErrors {
  title?: string;
  author?: string;
  genre?: string;
}

export const AddBookModal: React.FC<AddBookModalProps> = ({ 
  onClose, 
  onAddBook, 
  onUpdateBook, 
  bookToEdit, 
  defaultStatus, 
  existingBooks, 
  statusConfigs = STATUS_CONFIGS 
}) => {
  const isEditMode = !!bookToEdit;

  const [title, setTitle] = useState(bookToEdit?.title || '');
  const [author, setAuthor] = useState(bookToEdit?.author || '');
  const [pages, setPages] = useState(bookToEdit?.pages || 0);
  const [selectedGenres, setSelectedGenres] = useState<string[]>(
    bookToEdit?.genre ? bookToEdit.genre.split(',').map(g => g.trim()).filter(g => g !== '') : []
  );
  const [type, setType] = useState<BookType>(bookToEdit?.type || BookType.Book);
  const [status, setStatus] = useState<BookStatus>(bookToEdit?.status || defaultStatus || BookStatus.TBR);
  const [rating, setRating] = useState<number>(bookToEdit?.rating || 0);
  const [hoverRating, setHoverRating] = useState<number>(0);
  const [summary, setSummary] = useState(bookToEdit?.summary || '');
  const [notes, setNotes] = useState(bookToEdit?.notes || '');
  const [estimatedPrice, setEstimatedPrice] = useState(bookToEdit?.estimatedPrice?.toString() || '');
  const [buyLink, setBuyLink] = useState(bookToEdit?.buyLink || '');
  const [coverImageUrl, setCoverImageUrl] = useState<string | undefined>(bookToEdit?.coverImageUrl);
  const [isGeneratingCover, setIsGeneratingCover] = useState(false);
  const [isGeneratingSummary, setIsGeneratingSummary] = useState(false);
  const [isSubmitting, setIsSubmitting] = useState(false);
  const [dateAdded] = useState(bookToEdit?.dateAdded || new Date().toISOString().split('T')[0]);

  // Novos campos para Status Lido
  const [dateFinished, setDateFinished] = useState(bookToEdit?.dateFinished || new Date().toISOString().split('T')[0]);
  const [daysToFinish, setDaysToFinish] = useState(bookToEdit?.daysToFinish?.toString() || '');

  const [errors, setErrors] = useState<FormErrors>({});
  const [isShaking, setIsShaking] = useState(false);

  const handleTitleChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    setTitle(e.target.value);
    if (errors.title) setErrors(prev => ({ ...prev, title: undefined }));
  };

  const handleAuthorChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    setAuthor(e.target.value);
    if (errors.author) setErrors(prev => ({ ...prev, author: undefined }));
  };

  const toggleGenre = (genreName: string) => {
    setSelectedGenres(prev => {
      const isSelected = prev.includes(genreName);
      const newList = isSelected ? prev.filter(g => g !== genreName) : [...prev, genreName];
      if (newList.length > 0 && errors.genre) {
        setErrors(prevErr => ({ ...prevErr, genre: undefined }));
      }
      return newList;
    });
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    if (isSubmitting) return;
    const newErrors: FormErrors = {};
    if (!title.trim()) newErrors.title = "O título é obrigatório";
    if (!author.trim()) newErrors.author = "O autor é obrigatório";
    if (selectedGenres.length === 0) newErrors.genre = "Selecione ao menos um gênero";
    if (Object.keys(newErrors).length > 0) {
      setErrors(newErrors);
      setIsShaking(true);
      setTimeout(() => setIsShaking(false), 500);
      return;
    }
    setIsSubmitting(true);
    try {
        const bookData = { 
            title: title.trim(), 
            author: author.trim(), 
            pages, 
            genre: selectedGenres.join(', '), 
            type, 
            status, 
            summary, 
            notes,
            rating: rating || undefined,
            estimatedPrice: estimatedPrice ? parseFloat(estimatedPrice) : undefined,
            buyLink: buyLink.trim() || undefined,
            coverImageUrl, 
            dateAdded,
            currentPage: status === BookStatus.Read ? pages : bookToEdit?.currentPage,
            dateStarted: bookToEdit?.dateStarted,
            dateFinished: status === BookStatus.Read ? dateFinished : undefined,
            daysToFinish: status === BookStatus.Read && daysToFinish ? parseInt(daysToFinish, 10) : null
        };
        if (isEditMode) {
            await onUpdateBook({ ...bookToEdit, ...bookData });
        } else {
            await onAddBook(bookData);
        }
    } finally {
        setIsSubmitting(false);
    }
  };

  const handleGenerateCover = useCallback(async () => {
    if (!title || selectedGenres.length === 0) return;
    setIsGeneratingCover(true);
    const result = await generateBookCover(title, selectedGenres[0], type);
    setCoverImageUrl(result);
    setIsGeneratingCover(false);
  }, [title, selectedGenres, type]);

  const handleGenerateSummary = useCallback(async () => {
    if (!title || !author) return;
    setIsGeneratingSummary(true);
    try {
      const result = await generateBookSummary(title, author);
      if (result) setSummary(result);
    } catch (err) {
      console.error("Erro ao gerar resumo:", err);
    } finally {
      setIsGeneratingSummary(false);
    }
  }, [title, author]);

  const labelClass = (isRequired: boolean) => 
    `block text-[10px] font-black uppercase tracking-[0.15em] mb-1.5 ml-1 flex items-center gap-1 ${isRequired ? 'text-slate-500 dark:text-slate-400' : 'text-slate-400 dark:text-slate-500'}`;

  return (
    <div className="fixed inset-0 bg-slate-900/60 backdrop-blur-sm flex items-center justify-center z-50 p-4">
      <div 
        className={`bg-white dark:bg-slate-900 rounded-[2.5rem] shadow-2xl w-full max-w-2xl max-h-[90vh] overflow-hidden flex flex-col border border-white/20 dark:border-slate-800 transition-transform duration-500 ${isShaking ? 'animate-shake' : ''}`}
        style={{ animation: isShaking ? 'shake 0.4s cubic-bezier(.36,.07,.19,.97) both' : 'none' }}
      >
        <style>{`
          @keyframes shake {
            10%, 90% { transform: translate3d(-1px, 0, 0); }
            20%, 80% { transform: translate3d(2px, 0, 0); }
            30%, 50%, 70% { transform: translate3d(-4px, 0, 0); }
            40%, 60% { transform: translate3d(4px, 0, 0); }
          }
        `}</style>

        <div className="p-7 border-b border-slate-100 dark:border-slate-800 flex justify-between items-center bg-slate-50/50 dark:bg-slate-800/30">
            <h2 className="text-2xl font-black font-serif text-slate-900 dark:text-slate-50 tracking-tight">{isEditMode ? 'Editar Registro' : 'Novo Registro'}</h2>
            <button onClick={onClose} disabled={isSubmitting} className="p-2.5 rounded-full hover:bg-slate-200 dark:hover:bg-slate-700 text-slate-400 transition-all hover:rotate-90 disabled:opacity-30">
                <XMarkIcon className="h-5 w-5" />
            </button>
        </div>

        <form onSubmit={handleSubmit} className="p-8 space-y-8 overflow-y-auto custom-scrollbar">
            <div className={`grid grid-cols-1 md:grid-cols-2 gap-8 ${isSubmitting ? 'opacity-50 pointer-events-none' : ''}`}>
                <div className="md:col-span-2">
                    <label className={labelClass(true)}>
                      Título <span className="text-red-500">*</span>
                    </label>
                    <input 
                      type="text" 
                      value={title} 
                      onChange={handleTitleChange} 
                      placeholder="Ex: Cem Anos de Solidão"
                      className={`w-full bg-slate-50 dark:bg-slate-800 border rounded-2xl px-5 py-3.5 outline-none transition-all focus:ring-4 focus:ring-primary/5 ${errors.title ? 'border-red-400 bg-red-50/30 dark:bg-red-950/20' : 'border-slate-200 dark:border-slate-700 focus:border-primary'}`} 
                    />
                    {errors.title && <p className="text-[10px] text-red-500 font-bold mt-2 uppercase tracking-wide ml-1">{errors.title}</p>}
                </div>

                <div>
                    <label className={labelClass(true)}>
                      Autor <span className="text-red-500">*</span>
                    </label>
                    <input 
                      type="text" 
                      value={author} 
                      onChange={handleAuthorChange} 
                      placeholder="Ex: Gabriel García Márquez"
                      className={`w-full bg-slate-50 dark:bg-slate-800 border rounded-2xl px-5 py-3.5 outline-none transition-all focus:ring-4 focus:ring-primary/5 ${errors.author ? 'border-red-400 bg-red-50/30 dark:bg-red-950/20' : 'border-slate-200 dark:border-slate-700 focus:border-primary'}`} 
                    />
                    {errors.author && <p className="text-[10px] text-red-500 font-bold mt-2 uppercase tracking-wide ml-1">{errors.author}</p>}
                </div>

                <div>
                    <label className={labelClass(false)}>Status</label>
                    <select value={status} onChange={(e) => setStatus(e.target.value as BookStatus)} className="w-full bg-slate-50 dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-2xl px-5 py-3.5 outline-none focus:ring-4 focus:ring-primary/5 focus:border-primary cursor-pointer font-bold text-slate-700 dark:text-slate-300">
                        <option value={BookStatus.TBR}>{statusConfigs[BookStatus.TBR].label}</option>
                        <option value={BookStatus.Reading}>{statusConfigs[BookStatus.Reading].label}</option>
                        <option value={BookStatus.Read}>{statusConfigs[BookStatus.Read].label}</option>
                        <option value={BookStatus.Wishlist}>{statusConfigs[BookStatus.Wishlist].label}</option>
                    </select>
                </div>

                {status === BookStatus.Read && (
                  <div className="md:col-span-2 grid grid-cols-1 md:grid-cols-2 gap-8 animate-in slide-in-from-top-4 duration-300">
                    <div>
                      <label className={labelClass(false)}>Data de Conclusão</label>
                      <input 
                        type="date" 
                        value={dateFinished} 
                        onChange={(e) => setDateFinished(e.target.value)} 
                        className="w-full bg-slate-50 dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-2xl px-5 py-3.5 outline-none focus:border-primary font-bold text-slate-700 dark:text-slate-300" 
                      />
                    </div>
                    <div>
                      <label className={labelClass(false)}>Dias para Conclusão</label>
                      <input 
                        type="number" 
                        min="0"
                        placeholder="Ex: 15"
                        value={daysToFinish} 
                        onChange={(e) => setDaysToFinish(e.target.value)} 
                        className="w-full bg-slate-50 dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-2xl px-5 py-3.5 outline-none focus:border-primary font-bold text-slate-700 dark:text-slate-300" 
                      />
                    </div>
                  </div>
                )}

                <div className="md:col-span-2">
                    <label className={labelClass(true)}>Gêneros <span className="text-red-500">*</span></label>
                    <div className={`p-5 bg-slate-50/50 dark:bg-slate-800/20 border rounded-[2rem] transition-all ${errors.genre ? 'border-red-400 ring-4 ring-red-500/5 bg-red-50/10' : 'border-slate-200 dark:border-slate-700'}`}>
                        <div className="flex flex-wrap gap-2.5 mb-5 min-h-[38px]">
                            {selectedGenres.length > 0 ? (
                                selectedGenres.map(g => (
                                    <span key={g} className="bg-primary text-white text-[10px] font-black uppercase tracking-widest px-4 py-2 rounded-xl flex items-center gap-2 shadow-md animate-in fade-in zoom-in duration-300">
                                        {g}
                                        <button type="button" onClick={() => toggleGenre(g)} className="hover:text-blue-200 transition-colors p-0.5">
                                            <XMarkIcon className="h-3.5 w-3.5" />
                                        </button>
                                    </span>
                                ))
                            ) : (
                                <span className="text-slate-400 dark:text-slate-500 text-xs italic ml-1 mt-2">Escolha as categorias da obra...</span>
                            )}
                        </div>
                        <div className="flex flex-wrap gap-2 pt-5 border-t border-slate-200/60 dark:border-slate-700/60 max-h-48 overflow-y-auto pr-2 custom-scrollbar">
                            {GENRES.map(g => {
                                const isSelected = selectedGenres.includes(g);
                                return (
                                    <button
                                        key={g}
                                        type="button"
                                        onClick={() => toggleGenre(g)}
                                        className={`px-4 py-2 rounded-xl text-[10px] font-black uppercase tracking-[0.1em] transition-all ${
                                            isSelected 
                                                ? 'bg-primary text-white border border-primary scale-95 shadow-sm' 
                                                : 'bg-white dark:bg-slate-900 text-slate-500 dark:text-slate-400 border border-slate-200 dark:border-slate-700 hover:border-primary/40 hover:bg-slate-50 dark:hover:bg-slate-800'
                                        }`}
                                    >
                                        {g}
                                    </button>
                                );
                            })}
                        </div>
                    </div>
                    {errors.genre && <p className="text-[10px] text-red-500 font-bold mt-3 uppercase tracking-wide ml-1">{errors.genre}</p>}
                </div>

                <div>
                    <label className={labelClass(false)}>Total de Páginas</label>
                    <input type="number" min="0" value={pages} onChange={(e) => setPages(Number(e.target.value))} className="w-full bg-slate-50 dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-2xl px-5 py-3.5 outline-none focus:border-primary font-bold text-slate-700 dark:text-slate-300" />
                </div>
                <div>
                    <label className={labelClass(false)}>Tipo de Mídia</label>
                    <select value={type} onChange={(e) => setType(e.target.value as BookType)} className="w-full bg-slate-50 dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-2xl px-5 py-3.5 outline-none focus:border-primary font-bold text-slate-700 dark:text-slate-300">
                        <option value={BookType.Book}>Livro</option>
                        <option value={BookType.HQ}>HQ</option>
                    </select>
                </div>

                <div className="md:col-span-2">
                    <label className={labelClass(false)}>Avaliação / Nota</label>
                    <div className="flex items-center gap-1.5 p-4 bg-slate-50 dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-2xl">
                        {[...Array(10)].map((_, i) => {
                            const val = i + 1;
                            const isActive = val <= (hoverRating || rating);
                            return (
                                <button
                                    key={i}
                                    type="button"
                                    onClick={() => setRating(val)}
                                    onMouseEnter={() => setHoverRating(val)}
                                    onMouseLeave={() => setHoverRating(0)}
                                    className="p-0.5 transition-transform hover:scale-110"
                                >
                                    {isActive ? (
                                        <StarIconFilled className="h-6 w-6 text-amber-400" />
                                    ) : (
                                        <StarIcon className="h-6 w-6 text-slate-300 dark:text-slate-600" />
                                    )}
                                </button>
                            );
                        })}
                        <span className="ml-4 text-sm font-black text-amber-500 min-w-[2ch]">
                            {rating || '-'}
                        </span>
                    </div>
                </div>

                <div>
                    <label className={labelClass(false)}>Valor Estimado (R$)</label>
                    <input 
                      type="number" 
                      step="0.01" 
                      value={estimatedPrice} 
                      onChange={(e) => setEstimatedPrice(e.target.value)} 
                      placeholder="0,00"
                      className="w-full bg-slate-50 dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-2xl px-5 py-3.5 outline-none focus:border-primary font-bold text-slate-700 dark:text-slate-300" 
                    />
                </div>
                <div>
                    <label className={labelClass(false)}>Link de Compra</label>
                    <input 
                      type="text" 
                      value={buyLink} 
                      onChange={(e) => setBuyLink(e.target.value)} 
                      placeholder="https://..."
                      className="w-full bg-slate-50 dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-2xl px-5 py-3.5 outline-none focus:border-primary font-bold text-slate-700 dark:text-slate-300" 
                    />
                </div>
            </div>

            <div className="p-7 bg-blue-50/40 dark:bg-blue-900/10 rounded-[2.5rem] border border-blue-100 dark:border-blue-800/50 flex flex-col sm:flex-row items-center gap-8 shadow-inner">
                <div className="relative group flex-shrink-0">
                    {coverImageUrl ? (
                        <img src={coverImageUrl} alt="Capa" className="w-24 h-36 object-cover rounded-xl shadow-xl transition-transform group-hover:scale-110 duration-500"/>
                    ) : (
                        <div className="w-24 h-36 bg-slate-200 dark:bg-slate-800 rounded-xl flex items-center justify-center border-2 border-dashed border-slate-300 dark:border-slate-700">
                            <BookOpenIcon className="h-8 w-8 text-slate-400 dark:text-slate-600" />
                        </div>
                    )}
                </div>
                <div className="text-center sm:text-left flex-1">
                    <h4 className="text-sm font-black text-slate-800 dark:text-slate-200 mb-2 uppercase tracking-wide">✦ Inteligência BiblioTech</h4>
                    <p className="text-[11px] text-slate-500 dark:text-slate-400 mb-5 leading-relaxed font-medium uppercase tracking-tight">Deixe a IA criar um resumo inicial envolvente ou uma arte de capa personalizada para sua estante.</p>
                    <div className="flex flex-wrap gap-3 justify-center sm:justify-start">
                        <button 
                            type="button" 
                            onClick={handleGenerateSummary} 
                            disabled={isGeneratingSummary || isSubmitting || !title || !author} 
                            className="px-6 py-3 text-[10px] font-black uppercase tracking-widest rounded-xl bg-primary text-white hover:bg-slate-900 dark:hover:bg-slate-100 dark:hover:text-slate-900 transition-all shadow-md active:scale-95 disabled:opacity-50 flex items-center gap-2"
                        >
                            {isGeneratingSummary ? 'Processando...' : '✦ Gerar Resumo com IA'}
                        </button>
                        <button 
                            type="button" 
                            onClick={handleGenerateCover} 
                            disabled={isGeneratingCover || isSubmitting || !title || selectedGenres.length === 0} 
                            className="px-6 py-3 text-[10px] font-black uppercase tracking-widest rounded-xl bg-white dark:bg-slate-800 text-primary border border-blue-200 dark:border-blue-800/50 hover:bg-primary hover:text-white transition-all shadow-md active:scale-95 disabled:opacity-50 flex items-center gap-2"
                        >
                            {isGeneratingCover ? 'Criando Arte...' : 'Gerar Arte de Capa'}
                        </button>
                    </div>
                </div>
            </div>

            <div className="space-y-3">
                <label className={labelClass(false)}>Resumo & Sinopse</label>
                <textarea 
                  value={summary} 
                  onChange={(e) => setSummary(e.target.value)} 
                  rows={4} 
                  className="w-full bg-slate-50 dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-[1.5rem] px-5 py-4 outline-none focus:border-primary focus:ring-4 focus:ring-primary/5 text-sm leading-relaxed text-slate-600 dark:text-slate-300 font-medium" 
                  placeholder="Como você descreveria esta jornada?..."
                ></textarea>
            </div>

            <div className="space-y-3">
                <label className={labelClass(false)}>Notas Pessoais</label>
                <textarea 
                    value={notes} 
                    onChange={(e) => setNotes(e.target.value)} 
                    rows={4} 
                    className="w-full bg-slate-50 dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-[1.5rem] px-5 py-4 outline-none focus:border-primary focus:ring-4 focus:ring-primary/5 text-sm leading-relaxed text-slate-600 dark:text-slate-300 font-medium" 
                    placeholder="Anotações sobre a leitura, personagens favoritos, citações..."
                ></textarea>
            </div>

            <div className="flex justify-end gap-4 pt-8 border-t border-slate-100 dark:border-slate-800 mt-6">
                <button 
                  type="button" 
                  onClick={onClose} 
                  disabled={isSubmitting}
                  className="px-8 py-3.5 rounded-2xl text-slate-500 dark:text-slate-400 font-black text-[11px] uppercase tracking-widest hover:bg-slate-100 dark:hover:bg-slate-800 transition-all disabled:opacity-30"
                >
                  Cancelar
                </button>
                <button 
                  type="submit" 
                  disabled={isSubmitting}
                  className="px-10 py-3.5 rounded-2xl bg-slate-900 dark:bg-slate-100 text-white dark:text-slate-900 font-black text-[11px] uppercase tracking-widest hover:bg-primary dark:hover:bg-primary dark:hover:text-white shadow-2xl transition-all active:scale-95 shadow-primary/20 disabled:bg-slate-400 flex items-center gap-3"
                >
                  {isSubmitting && (
                    <svg className="animate-spin h-4 w-4 text-white dark:text-slate-900" xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24">
                        <circle className="opacity-25" cx="12" cy="12" r="10" stroke="currentColor" strokeWidth="4"></circle>
                        <path className="opacity-75" fill="currentColor" d="M4 12a8 8 0 018-8V0C5.373 0 0 5.373 0 12h4zm2 5.291A7.962 7.962 0 014 12H0c0 3.042 1.135 5.824 3 7.938l3-2.647z"></path>
                    </svg>
                  )}
                  {isSubmitting ? 'Salvando...' : (isEditMode ? 'Salvar Alterações' : 'Salvar no Banco')}
                </button>
            </div>
        </form>
      </div>
    </div>
  );
};

