import type { Book, Profile } from '../types';
import { supabase } from './supabase';

const TABLE_NAME = 'books';
const BASE_LOCAL_STORAGE_KEY = 'biblio_tech_cache_';

export class DatabaseService {
  private isSchemaBroken = false;
  private onSchemaErrorCallback?: (type: 'table' | 'column' | 'permission', detail?: string) => void;

  setSchemaErrorCallback(cb: (type: 'table' | 'column' | 'permission', detail?: string) => void) {
    this.onSchemaErrorCallback = cb;
  }

  private async getCacheKey(): Promise<string | null> {
    const { data: { user } } = await supabase.auth.getUser();
    return user ? `${BASE_LOCAL_STORAGE_KEY}${user.id}` : null;
  }

  private async getLocalBooks(): Promise<Book[]> {
    const key = await this.getCacheKey();
    if (!key) return [];
    const data = localStorage.getItem(key);
    return data ? JSON.parse(data) : [];
  }

  private async saveLocalBooks(books: Book[]): Promise<void> {
    const key = await this.getCacheKey();
    if (key) {
      localStorage.setItem(key, JSON.stringify(books));
    }
  }

  async getAllBooks(): Promise<Book[]> {
    try {
      const { data, error } = await supabase
        .from(TABLE_NAME)
        .select('*')
        .order('dateAdded', { ascending: false });

      if (error) {
        this.handleSupabaseError(error);
        return await this.getLocalBooks();
      }

      this.isSchemaBroken = false;
      const books = (data as Book[]) || [];
      await this.saveLocalBooks(books);
      return books;
    } catch (err: any) {
      return await this.getLocalBooks();
    }
  }

  async saveBook(book: Partial<Book>): Promise<void> {
    const { data: { user } } = await supabase.auth.getUser();
    if (!user) throw new Error("Acesso negado: Usuário não autenticado.");

    const sanitizedBook = {
        ...book,
        user_id: user.id,
        pages: Math.max(0, book.pages || 0),
        currentPage: Math.max(0, book.currentPage || 0),
        rating: book.rating ? Math.min(10, Math.max(0, book.rating)) : null,
        estimatedPrice: book.estimatedPrice ? Math.max(0, book.estimatedPrice) : null,
        daysToFinish: book.daysToFinish !== undefined && book.daysToFinish !== null ? Math.max(0, Number(book.daysToFinish)) : null,
        timesRead: book.timesRead !== undefined && book.timesRead !== null ? Math.max(0, Number(book.timesRead)) : 1
    };

    // Cache local imediato
    const books = await this.getLocalBooks();
    const index = books.findIndex(b => b.id === sanitizedBook.id);
    if (index >= 0) {
      books[index] = sanitizedBook as Book;
    } else {
      books.unshift(sanitizedBook as Book);
    }
    await this.saveLocalBooks(books);

    if (this.isSchemaBroken) return;

    try {
      const { error } = await supabase
        .from(TABLE_NAME)
        .upsert(sanitizedBook);

      if (error) {
        console.error("Erro ao salvar livro no Supabase:", error.message, error.details);
        this.handleSupabaseError(error);
      }
    } catch (err: any) {
      console.error('Erro crítico de rede ao salvar livro:', err.message);
    }
  }

  async deleteBook(id: string): Promise<void> {
    const books = (await this.getLocalBooks()).filter(b => b.id !== id);
    await this.saveLocalBooks(books);

    if (this.isSchemaBroken) return;

    try {
      const { error } = await supabase
        .from(TABLE_NAME)
        .delete()
        .eq('id', id);

      if (error) this.handleSupabaseError(error);
    } catch (err: any) {
      console.error('Erro ao deletar:', err.message);
    }
  }

  async updateReadingGoal(goal: number): Promise<void> {
    const { data: { user } } = await supabase.auth.getUser();
    if (!user) return;

    try {
      const { error } = await supabase
        .from('profiles')
        .upsert({ 
          id: user.id, 
          reading_goal: goal, 
          updated_at: new Date().toISOString() 
        });

      if (error) {
        console.error("Erro ao atualizar meta (UPSERT profiles):", error.message);
      }
    } catch (err) {
      console.error("Falha de rede ao atualizar meta:", err);
    }
  }

  async updateProfile(profile: Partial<Profile>): Promise<void> {
    const { data: { user } } = await supabase.auth.getUser();
    if (!user) return;

    try {
      const { error } = await supabase
        .from('profiles')
        .upsert({ 
          id: user.id, 
          ...profile, 
          updated_at: new Date().toISOString() 
        });

      if (error) {
        console.error("Erro ao atualizar perfil (UPSERT profiles):", error.message);
        throw error;
      }
    } catch (err) {
      console.error("Falha de rede ao atualizar perfil:", err);
      throw err;
    }
  }

  async getProfile(): Promise<Profile | null> {
    const { data: { user } } = await supabase.auth.getUser();
    if (!user) return null;

    try {
        const { data, error } = await supabase
          .from('profiles')
          .select('*')
          .eq('id', user.id)
          .single();

        if (error || !data) {
            console.warn("Perfil não encontrado, usando metadados do Auth.");
            return { 
                id: user.id, 
                full_name: user.user_metadata?.full_name || 'Novo Leitor',
                reading_goal: 12
            };
        }
        return data;
    } catch (err) {
        return { id: user.id, full_name: 'Novo Leitor', reading_goal: 12 };
    }
  }

  private handleSupabaseError(error: any) {
    if (error.code === '42P01') {
      this.isSchemaBroken = true;
      this.onSchemaErrorCallback?.('table');
      return;
    }
    if (error.code === '42501') {
      this.onSchemaErrorCallback?.('permission');
      return;
    }
    if (error.code === '42703') {
       const columnName = error.message.match(/"(.*?)"/)?.[1] || 'desconhecida';
       this.onSchemaErrorCallback?.('column', columnName);
       return;
    }
  }
}

