import type { Book, Profile } from '../types';
import { supabase } from './supabase';

const TABLE_NAME = 'books';
const BASE_LOCAL_STORAGE_KEY = 'biblio_tech_cache_';

export class DatabaseService {
  private isSchemaBroken = false;
  private onSchemaErrorCallback?: (type: 'table' | 'column' | 'permission', detail?: string) => void;

  setSchemaErrorCallback(cb: (type: 'table' | 'column' | 'permission', detail?: string) => void) {
    this.onSchemaErrorCallback = cb;
  }

  private async getCacheKey(): Promise<string | null> {
    const { data: { user } } = await supabase.auth.getUser();
    return user ? `${BASE_LOCAL_STORAGE_KEY}${user.id}` : null;
  }

  private async getLocalBooks(): Promise<Book[]> {
    const key = await this.getCacheKey();
    if (!key) return [];
    const data = localStorage.getItem(key);
    return data ? JSON.parse(data) : [];
  }

  private async saveLocalBooks(books: Book[]): Promise<void> {
    const key = await this.getCacheKey();
    if (key) {
      localStorage.setItem(key, JSON.stringify(books));
    }
  }

  async getAllBooks(): Promise<Book[]> {
    try {
      const { data, error } = await supabase
        .from(TABLE_NAME)
        .select('*')
        .order('dateAdded', { ascending: false });

      if (error) {
        this.handleSupabaseError(error);
        return await this.getLocalBooks();
      }

      this.isSchemaBroken = false;
      const books = (data as Book[]) || [];
      await this.saveLocalBooks(books);
      return books;
    } catch (err: any) {
      return await this.getLocalBooks();
    }
  }

  async saveBook(book: Partial<Book>): Promise<void> {
    const { data: { user } } = await supabase.auth.getUser();
    if (!user) throw new Error("Acesso negado: Usuário não autenticado.");

    const sanitizedBook = {
        ...book,
        user_id: user.id,
        pages: Number(book.pages) || 0,
        currentPage: Number(book.currentPage) || 0,
        rating: book.rating ? Math.min(10, Math.max(0, Number(book.rating))) : null,
        estimatedPrice: book.estimatedPrice ? Number(book.estimatedPrice) : null,
        daysToFinish: (book.daysToFinish !== undefined && book.daysToFinish !== null) ? Number(book.daysToFinish) : null,
        timesRead: (book.timesRead !== undefined && book.timesRead !== null) ? Number(book.timesRead) : 1
    };

    // Cache local imediato
    const books = await this.getLocalBooks();
    const index = books.findIndex(b => b.id === sanitizedBook.id);
    if (index >= 0) {
      books[index] = sanitizedBook as Book;
    } else {
      books.unshift(sanitizedBook as Book);
    }
    await this.saveLocalBooks(books);

    if (this.isSchemaBroken) return;

    try {
      // Upsert sem onConflict explícito (Supabase usa a PK do SQL)
      const { error } = await supabase
        .from(TABLE_NAME)
        .upsert(sanitizedBook);

      if (error) {
        console.error("Supabase Save Error:", error.message, error.details);
        this.handleSupabaseError(error);
        throw error;
      }
    } catch (err: any) {
      console.error('Critical Database Error:', err.message);
      throw err;
    }
  }

  async deleteBook(id: string): Promise<void> {
    const books = (await this.getLocalBooks()).filter(b => b.id !== id);
    await this.saveLocalBooks(books);

    if (this.isSchemaBroken) return;

    try {
      const { error } = await supabase
        .from(TABLE_NAME)
        .delete()
        .eq('id', id);

      if (error) {
        this.handleSupabaseError(error);
        throw error;
      }
    } catch (err: any) {
      console.error('Delete Error:', err.message);
      throw err;
    }
  }

  async updateReadingGoal(goal: number): Promise<void> {
    const { data: { user } } = await supabase.auth.getUser();
    if (!user) return;

    try {
      const { error } = await supabase
        .from('profiles')
        .upsert({ 
          id: user.id, 
          reading_goal: goal, 
          updated_at: new Date().toISOString() 
        });

      if (error) {
        console.error("Goal Update Error:", error.message);
        throw error;
      }
    } catch (err) {
      throw err;
    }
  }

  async updateProfile(profile: Partial<Profile>): Promise<void> {
    const { data: { user } } = await supabase.auth.getUser();
    if (!user) return;

    try {
      const { error } = await supabase
        .from('profiles')
        .upsert({ 
          id: user.id, 
          ...profile, 
          updated_at: new Date().toISOString() 
        });

      if (error) {
        console.error("Profile Update Error:", error.message);
        throw error;
      }
    } catch (err) {
      throw err;
    }
  }

  async getProfile(): Promise<Profile | null> {
    const { data: { user } } = await supabase.auth.getUser();
    if (!user) return null;

    try {
        const { data, error } = await supabase
          .from('profiles')
          .select('*')
          .eq('id', user.id)
          .single();

        if (error || !data) {
            return { 
                id: user.id, 
                full_name: user.user_metadata?.full_name || 'Leitor',
                reading_goal: 12
            };
        }
        return data;
    } catch (err) {
        return { id: user.id, full_name: 'Leitor', reading_goal: 12 };
    }
  }

  private handleSupabaseError(error: any) {
    if (error.code === '42P01') {
      this.isSchemaBroken = true;
      this.onSchemaErrorCallback?.('table');
      return;
    }
    if (error.code === '42501') {
      this.onSchemaErrorCallback?.('permission');
      return;
    }
    if (error.code === '42703') {
       const columnName = error.message.match(/"(.*?)"/)?.[1] || 'desconhecida';
       this.onSchemaErrorCallback?.('column', columnName);
       return;
    }
  }
}

export const dbService = new DatabaseService();

import React, { useState, useEffect } from 'react';
import { supabase } from '../services/supabase';
import { BookOpenIcon, XMarkIcon } from './Icons';

export const Auth: React.FC = () => {
  const [loading, setLoading] = useState(false);
  const [email, setEmail] = useState('');
  const [password, setPassword] = useState('');
  const [showPassword, setShowPassword] = useState(false);
  const [fullName, setFullName] = useState('');
  const [mode, setMode] = useState<'login' | 'signup'>('login');
  const [errorMsg, setErrorMsg] = useState<string | null>(null);
  const [needsEmailConfirmation, setNeedsEmailConfirmation] = useState(false);
  const [showHelp, setShowHelp] = useState(false);
  const [highlightSignup, setHighlightSignup] = useState(false);

  const currentKey = (supabase as any).supabaseKey || '';
  const isStripeKey = currentKey.startsWith('sb_');

  const handleAuth = async (e: React.FormEvent) => {
    e.preventDefault();
    setLoading(true);
    setErrorMsg(null);
    setHighlightSignup(false);

    if (isStripeKey) {
        setErrorMsg("Erro de Configuração: Você está usando uma chave do Stripe (começa com 'sb_'). O login só funciona com a chave 'anon public' do Supabase (começa com 'eyJ').");
        setLoading(false);
        return;
    }

    try {
      if (mode === 'login') {
        const { error, data } = await supabase.auth.signInWithPassword({ email, password });
        if (error) {
          if (error.message.includes('Invalid login credentials') || error.status === 400 || error.status === 401) {
             setHighlightSignup(true);
             throw new Error('Não encontramos sua conta ou a senha está incorreta. Se você ainda não criou sua conta, clique no botão azul "CRIAR CONTA" abaixo!');
          }
          throw error;
        }
      } else {
        if (password.length < 6) throw new Error('A senha precisa ter no mínimo 6 caracteres.');

        const { error, data } = await supabase.auth.signUp({ 
          email, 
          password,
          options: { data: { full_name: fullName } }
        });

        if (error) throw error;

        if (data.user && !data.session) {
           setNeedsEmailConfirmation(true);
        }
      }
    } catch (error: any) {
      console.error("Auth Error:", error);
      setErrorMsg(error.message || "Erro desconhecido. Verifique sua conexão.");
    } finally {
      setLoading(false);
    }
  };

  if (needsEmailConfirmation) {
    return (
      <div className="min-h-screen bg-background dark:bg-slate-950 flex flex-col items-center justify-center p-6">
        <div className="w-full max-w-md bg-white dark:bg-slate-900 rounded-[2.5rem] shadow-2xl border border-emerald-100 dark:border-emerald-900/30 p-10 text-center animate-in zoom-in duration-500">
          <div className="bg-emerald-500 w-16 h-16 rounded-full flex items-center justify-center mx-auto mb-6 shadow-lg">
            <svg xmlns="http://www.w3.org/2000/svg" className="h-8 w-8 text-white" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={3} d="M5 13l4 4L19 7" />
            </svg>
          </div>
          <h2 className="text-2xl font-black text-slate-900 dark:text-slate-50 mb-4 font-serif italic">Verifique seu E-mail!</h2>
          <p className="text-slate-500 dark:text-slate-400 text-sm leading-relaxed mb-8">
            Enviamos um link de confirmação para <b>{email}</b>. <br/> 
            Você precisa clicar no link do e-mail para ativar sua senha e conseguir logar.
          </p>
          <button 
            onClick={() => setNeedsEmailConfirmation(false)}
            className="w-full py-4 bg-slate-100 dark:bg-slate-800 rounded-2xl text-[10px] font-black uppercase tracking-widest text-slate-600 dark:text-slate-400 hover:bg-slate-200 transition-all"
          >
            Voltar para a tela de Login
          </button>
        </div>
      </div>
    );
  }

  return (
    <div className="min-h-screen bg-background dark:bg-slate-950 flex flex-col items-center justify-center p-6 font-sans">
      <div className="w-full max-w-md bg-white dark:bg-slate-900 rounded-[2.5rem] shadow-2xl border border-slate-100 dark:border-slate-800 p-10 transition-all relative overflow-hidden">

        <div className="flex flex-col items-center mb-10 pt-4">
            <div className="bg-primary p-3 rounded-2xl shadow-xl shadow-primary/20 mb-4 transition-transform hover:scale-110">
                <BookOpenIcon className="h-8 w-8 text-white" />
            </div>
            <h1 className="text-2xl font-black font-serif text-slate-900 dark:text-slate-50 tracking-tight italic">
              Biblio<span className="text-primary">Tech</span>
            </h1>
            <div className="flex gap-4 mt-6">
                <button 
                    onClick={() => { setMode('login'); setErrorMsg(null); }}
                    className={`text-[10px] font-black uppercase tracking-widest pb-1 border-b-2 transition-all ${mode === 'login' ? 'text-primary border-primary' : 'text-slate-400 border-transparent hover:text-slate-600'}`}
                >
                    Entrar
                </button>
                <button 
                    onClick={() => { setMode('signup'); setErrorMsg(null); }}
                    className={`text-[10px] font-black uppercase tracking-widest pb-1 border-b-2 transition-all ${mode === 'signup' ? 'text-primary border-primary' : 'text-slate-400 border-transparent hover:text-slate-600'} ${highlightSignup ? 'animate-bounce text-blue-600' : ''}`}
                >
                    Cadastrar
                </button>
            </div>
        </div>

        <form onSubmit={handleAuth} className="space-y-6">
          {mode === 'signup' && (
            <div className="animate-in slide-in-from-top-2 duration-300">
              <label className="block text-[10px] font-black uppercase tracking-widest text-slate-400 mb-2 ml-1">Como devemos te chamar?</label>
              <input
                type="text"
                placeholder="Ex: João Silva"
                value={fullName}
                onChange={(e) => setFullName(e.target.value)}
                className="w-full bg-slate-50 dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-2xl px-5 py-3.5 outline-none focus:border-primary font-medium dark:text-white transition-all shadow-sm"
                required={mode === 'signup'}
              />
            </div>
