              value={password}
              onChange={(e) => setPassword(e.target.value)}
              className="w-full bg-slate-50 dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-2xl px-5 py-3.5 outline-none focus:border-primary font-medium dark:text-white transition-all shadow-sm"
              required
            />
          </div>

          {errorMsg && (
            <div className="bg-red-50 dark:bg-red-900/20 text-red-500 text-[10px] font-bold uppercase p-5 rounded-2xl border border-red-100 dark:border-red-900/30 animate-shake space-y-3">
              <p className="leading-relaxed">{errorMsg}</p>
              {highlightSignup && (
                  <button 
                    type="button"
                    onClick={() => { setMode('signup'); setErrorMsg(null); }}
                    className="w-full bg-blue-600 text-white py-2 rounded-lg text-[9px] tracking-widest shadow-md hover:bg-blue-700 transition-all"
                  >
                    CRIAR MINHA CONTA AGORA
                  </button>
