  }

  private async getLocalBooks(): Promise<Book[]> {
    const key = await this.getCacheKey();
    if (!key) return [];
    const data = localStorage.getItem(key);
    return data ? JSON.parse(data) : [];
  }

  private async saveLocalBooks(books: Book[]): Promise<void> {
    const key = await this.getCacheKey();
    if (key) {
      localStorage.setItem(key, JSON.stringify(books));
    }
  }

  async getAllBooks(): Promise<Book[]> {
    try {
      const { data, error } = await supabase
        .from(TABLE_NAME)
        .select('*')
        .order('dateAdded', { ascending: false });

      if (error) {
        this.handleSupabaseError(error);
        return await this.getLocalBooks();
      }

      this.isSchemaBroken = false;
      const books = (data as Book[]) || [];
      await this.saveLocalBooks(books);
      return books;
    } catch (err: any) {
      return await this.getLocalBooks();
    }
  }

  async saveBook(book: Partial<Book>): Promise<void> {
    const { data: { user } } = await supabase.auth.getUser();
    if (!user) throw new Error("Acesso negado: Usuário não autenticado.");

    // Sanitização rigorosa para evitar erros de tipo no banco
    const sanitizedBook = {
        ...book,
        user_id: user.id,
        pages: parseInt(String(book.pages || 0), 10),
        currentPage: parseInt(String(book.currentPage || 0), 10),
        rating: book.rating ? parseInt(String(book.rating), 10) : null,
        estimatedPrice: book.estimatedPrice ? parseFloat(String(book.estimatedPrice)) : null,
        daysToFinish: (book.daysToFinish !== undefined && book.daysToFinish !== null) ? parseInt(String(book.daysToFinish), 10) : null,
        timesRead: (book.timesRead !== undefined && book.timesRead !== null) ? parseInt(String(book.timesRead), 10) : 1
    };

    const books = await this.getLocalBooks();
    const index = books.findIndex(b => b.id === sanitizedBook.id);
    if (index >= 0) {
      books[index] = sanitizedBook as Book;
    } else {
      books.unshift(sanitizedBook as Book);
    }
    await this.saveLocalBooks(books);

    if (this.isSchemaBroken) return;

    try {
      const { error } = await supabase
        .from(TABLE_NAME)
        .upsert(sanitizedBook);

      if (error) {
        this.handleSupabaseError(error);
        const errorMsg = error.message || JSON.stringify(error);
        throw new Error(`Erro ao salvar no Supabase: ${errorMsg}`);
      }
    } catch (err: any) {
      const msg = err.message || JSON.stringify(err);
      console.error('Critical Database Error:', msg);
      throw new Error(msg);
    }
  }

  async deleteBook(id: string): Promise<void> {
    const books = (await this.getLocalBooks()).filter(b => b.id !== id);
    await this.saveLocalBooks(books);

    if (this.isSchemaBroken) return;

    try {
      const { error } = await supabase
        .from(TABLE_NAME)
        .delete()
        .eq('id', id);

      if (error) {
        this.handleSupabaseError(error);
        throw new Error(error.message);
      }
    } catch (err: any) {
      const msg = err.message || JSON.stringify(err);
      console.error('Delete Error:', msg);
      throw new Error(msg);
    }
  }

  async updateReadingGoal(goal: number): Promise<void> {
    const { data: { user } } = await supabase.auth.getUser();
    if (!user) return;

    try {
      const { error } = await supabase
        .from('profiles')
        .upsert({ 
          id: user.id, 
          reading_goal: parseInt(String(goal), 10), 
          updated_at: new Date().toISOString() 
        });

      if (error) {
        const errorMsg = error.message || JSON.stringify(error);
        console.error("Goal Update Error:", errorMsg);
        throw new Error(errorMsg);
      }
    } catch (err: any) {
      throw new Error(err.message || String(err));
    }
  }

  async updateProfile(profile: Partial<Profile>): Promise<void> {
    const { data: { user } } = await supabase.auth.getUser();
    if (!user) return;

    try {
      const { error } = await supabase
        .from('profiles')
        .upsert({ 
          id: user.id, 
          ...profile, 
          updated_at: new Date().toISOString() 
        });

      if (error) {
        const errorMsg = error.message || JSON.stringify(error);
        console.error("Profile Update Error:", errorMsg);
        throw new Error(errorMsg);
      }
    } catch (err: any) {
      throw new Error(err.message || String(err));
    }
  }

  async getProfile(): Promise<Profile | null> {
    const { data: { user } } = await supabase.auth.getUser();
    if (!user) return null;

    try {
        const { data, error } = await supabase
          .from('profiles')
          .select('*')
          .eq('id', user.id)
          .single();

        if (error || !data) {
            return { 
                id: user.id, 
                full_name: user.user_metadata?.full_name || 'Leitor',
                reading_goal: 12
            };
        }
        return data;
    } catch (err) {
        return { id: user.id, full_name: 'Leitor', reading_goal: 12 };
    }
  }

  private handleSupabaseError(error: any) {
    if (error.code === '42P01') {
      this.isSchemaBroken = true;
      this.onSchemaErrorCallback?.('table');
      return;
    }
    if (error.code === '42501') {
      this.onSchemaErrorCallback?.('permission');
      return;
    }
    if (error.code === '42703') {
       const columnName = error.message.match(/"(.*?)"/)?.[1] || 'desconhecida';
       this.onSchemaErrorCallback?.('column', columnName);
       return;
    }
  }
}

