    return `https://picsum.photos/seed/${encodeURIComponent(title)}/400/600`;
  }
};

export const getAIRecommendations = async (readBooks: { title: string, genre: string }[]): Promise<Recommendation[]> => {
  if (!process.env.API_KEY || readBooks.length === 0) return [];

  try {
    const ai = getAI();
    const booksDescription = readBooks.map(b => `${b.title} (${b.genre})`).join(', ');
    const prompt = `Com base nos seguintes livros que eu já li: ${booksDescription}. Recomende 3 livros novos que eu possa gostar. Explique o motivo de forma curta e direta em Português.`;

    const response: GenerateContentResponse = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: prompt,
      config: {
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.ARRAY,
          items: {
            type: Type.OBJECT,
            properties: {
              title: { type: Type.STRING },
              author: { type: Type.STRING },
              reason: { type: Type.STRING },
              genre: { type: Type.STRING },
            },
            propertyOrdering: ["title", "author", "reason", "genre"],
            required: ["title", "author", "reason", "genre"]
          }
        }
      }
    });

    return JSON.parse(response.text || '[]');
  } catch (error: any) {
    const errorMsg = stringifyError(error);
    console.error("Error fetching AI recommendations:", errorMsg);
    return [];
  }
};

