export class DatabaseService {
  private isSchemaBroken = false;
  private onSchemaErrorCallback?: (type: 'table' | 'column' | 'permission', detail?: string) => void;

  setSchemaErrorCallback(cb: (type: 'table' | 'column' | 'permission', detail?: string) => void) {
    this.onSchemaErrorCallback = cb;
  }

  private async getCacheKey(): Promise<string | null> {
    const { data: { user } } = await supabase.auth.getUser();
    return user ? `${BASE_LOCAL_STORAGE_KEY}${user.id}` : null;
  }

  private async getLocalBooks(): Promise<Book[]> {
    const key = await this.getCacheKey();
    if (!key) return [];
    try {
      const data = localStorage.getItem(key);
      return data ? JSON.parse(data) : [];
    } catch (e) {
      return [];
    }
  }

  private async saveLocalBooks(books: Book[]): Promise<void> {
    const key = await this.getCacheKey();
    if (!key) return;

    try {
      localStorage.setItem(key, JSON.stringify(books));
    } catch (e: any) {
      // Se a cota do LocalStorage for atingida (comum com imagens Base64)
      if (e.name === 'QuotaExceededError' || e.name === 'NS_ERROR_DOM_QUOTA_REACHED') {
        console.warn("BiblioTech: Cota de cache local atingida. Otimizando armazenamento...");

        // Estratégia: Salvar versão sem as imagens em Base64 (que são as mais pesadas)
        const lightBooks = books.map(book => ({
          ...book,
          coverImageUrl: (book.coverImageUrl?.startsWith('data:')) ? null : book.coverImageUrl
        }));

        try {
          localStorage.setItem(key, JSON.stringify(lightBooks));
        } catch (innerError) {
          // Se nem a versão leve couber, removemos o cache desse usuário
          localStorage.removeItem(key);
        }
      }
    }
  }

  async getAllBooks(): Promise<Book[]> {
    try {
      const { data, error } = await supabase
        .from(TABLE_NAME)
        .select('*')
        .order('date_added', { ascending: false });

      if (error) {
        this.handleSupabaseError(error);
        return await this.getLocalBooks();
      }

      this.isSchemaBroken = false;
      const books = (data || []).map(mapDbToBook);
      await this.saveLocalBooks(books);
      return books;
    } catch (err) {
      return await this.getLocalBooks();
    }
  }

  async saveBook(book: Partial<Book>): Promise<void> {
    const { data: { user } } = await supabase.auth.getUser();
    if (!user) throw new Error("Acesso negado: Usuário não autenticado.");

    const dbPayload = mapBookToDb(book);
    dbPayload.user_id = user.id;

    // Cache local (Sempre atualizamos o estado em memória via hooks antes)
    const books = await this.getLocalBooks();
    const index = books.findIndex(b => b.id === book.id);
    const updatedBookState = mapDbToBook(dbPayload);

    if (index >= 0) books[index] = updatedBookState;
    else books.unshift(updatedBookState);

    // Tentamos salvar o cache, mas não deixamos o erro de cota travar o salvamento no banco real
    await this.saveLocalBooks(books);

    if (this.isSchemaBroken) return;

    try {
      const { error } = await supabase.from(TABLE_NAME).upsert(dbPayload);
      if (error) {
        this.handleSupabaseError(error);
        throw error;
      }
    } catch (err: any) {
      console.error("Erro ao salvar no banco:", err.message);
      throw err; // Repassamos o erro do banco real, mas ignoramos o de cache acima
    }
  }

  async deleteBook(id: string): Promise<void> {
    const books = (await this.getLocalBooks()).filter(b => b.id !== id);
    await this.saveLocalBooks(books);

    if (this.isSchemaBroken) return;
    try {
      const { error } = await supabase.from(TABLE_NAME).delete().eq('id', id);
      if (error) this.handleSupabaseError(error);
    } catch (err) {}
  }

  async updateReadingGoal(goal: number): Promise<void> {
    const { data: { user } } = await supabase.auth.getUser();
    if (!user) return;
    try {
      await supabase.from('profiles').upsert({ 
        id: user.id, 
        reading_goal: parseInt(String(goal), 10), 
        updated_at: new Date().toISOString() 
      });
    } catch (err) {}
  }

  async updateProfile(profile: Partial<Profile>): Promise<void> {
    const { data: { user } } = await supabase.auth.getUser();
    if (!user) return;
    try {
      const dbPayload = mapProfileToDb(profile);
      await supabase.from('profiles').upsert({ 
        id: user.id, 
        ...dbPayload, 
        updated_at: new Date().toISOString() 
      });
    } catch (err) {}
  }

  async getProfile(): Promise<Profile | null> {
    const { data: { user } } = await supabase.auth.getUser();
    if (!user) return null;
    try {
        const { data, error } = await supabase
          .from('profiles')
          .select('*')
          .eq('id', user.id)
          .single();

        if (error || !data) return { id: user.id, fullName: 'Leitor', readingGoal: 12 };
        return mapDbToProfile(data);
    } catch (err) {
        return { id: user.id, fullName: 'Leitor', readingGoal: 12 };
    }
  }

  private handleSupabaseError(error: any) {
    if (error.code === '42P01') {
      this.isSchemaBroken = true;
      this.onSchemaErrorCallback?.('table');
    } else if (error.code === '42501') {
      this.onSchemaErrorCallback?.('permission');
    } else if (error.code === '42703') {
       const columnName = error.message.match(/"(.*?)"/)?.[1] || 'desconhecida';
       this.onSchemaErrorCallback?.('column', columnName);
    }
  }
}

export const dbService = new DatabaseService();

import { useState, useMemo, useCallback, useEffect, useRef } from 'react';
import type { Book, ReadingStats, NewBook, DateFilter, MonthlyStat, TypeStat } from '../types';
import { BookStatus, BookType } from '../types';
import { dbService } from '../services/database';
import { generateBookCover } from '../services/geminiService';
import { supabase } from '../services/supabase';

const MONTHS = ['Janeiro', 'Fevereiro', 'Março', 'Abril', 'Maio', 'Junho', 'Julho', 'Agosto', 'Setembro', 'Outubro', 'Novembro', 'Dezembro'];

export const useBookData = () => {
  const [books, setBooks] = useState<Book[]>([]);
  const [isLoading, setIsLoading] = useState(true);
  const [isLocalMode, setIsLocalMode] = useState(false);
  const [schemaError, setSchemaError] = useState<{type: 'table' | 'column' | 'permission', detail?: string} | null>(null);
  const [dateFilter, setDateFilter] = useState<DateFilter>('allTime');
  const [selectedYear, setSelectedYear] = useState<number>(new Date().getFullYear());
  const [customRange, setCustomRange] = useState({ 
    start: new Date(new Date().getFullYear(), 0, 1).toISOString().split('T')[0],
    end: new Date().toISOString().split('T')[0]
  });

  const autoGenRunning = useRef(false);

  const loadData = useCallback(async () => {
    setIsLoading(true);
    try {
      dbService.setSchemaErrorCallback((type, detail) => {
          setSchemaError({ type, detail });
          setIsLocalMode(true);
      });

      const storedBooks = await dbService.getAllBooks();
      setBooks(storedBooks);
    } catch (error: any) {
      console.error('Erro crítico ao carregar dados:', error.message);
      setIsLocalMode(true);
    } finally {
      setIsLoading(false);
    }
  }, []);

  useEffect(() => {
    loadData();
  }, [loadData]);

  const addBook = useCallback(async (newBook: NewBook) => {
    const { data: { user } } = await supabase.auth.getUser();
    if (!user) throw new Error("Necessário login.");

    const book: Book = {
      ...newBook,
      id: crypto.randomUUID(),
      user_id: user.id,
      dateAdded: new Date().toISOString().split('T')[0],
    };

    // Atualiza o estado local primeiro (UI instantânea)
    setBooks(prev => [book, ...prev]);

    try {
        // Tenta salvar no banco
        await dbService.saveBook(book);
    } catch (err) {
        console.error("Erro ao persistir novo livro:", err);
    }
  }, []);

  const updateBook = useCallback(async (updatedBook: Book) => {
    // Atualiza o estado local primeiro (UI instantânea)
    setBooks(prev => prev.map(b => b.id === updatedBook.id ? updatedBook : b));

    try {
        // Tenta salvar no banco
        await dbService.saveBook(updatedBook);
    } catch (err) {
        console.error("Erro ao persistir atualização:", err);
    }
  }, []);

  const deleteBook = useCallback(async (id: string) => {
    setBooks(prev => prev.filter(b => b.id !== id));
    await dbService.deleteBook(id);
  }, []);

  useEffect(() => {
    if (isLoading || books.length === 0 || autoGenRunning.current) return;

    const generateCovers = async () => {
      const { data: { user } } = await supabase.auth.getUser();
      if (!user) return;

      autoGenRunning.current = true;
      const booksWithoutCover = books.filter(b => 
        !b.coverImageUrl || 
        b.coverImageUrl.includes('picsum.photos')
      );

      if (booksWithoutCover.length > 0) {
        // Processa um por um para não sobrecarregar
        for (const book of booksWithoutCover) {
          try {
            const newCoverUrl = await generateBookCover(book.title, book.genre, book.type);
            // Se gerou uma capa real (não placeholder)
            if (newCoverUrl && !newCoverUrl.includes('picsum.photos')) {
              await updateBook({ ...book, coverImageUrl: newCoverUrl });
            }
          } catch (err) {
            console.error(`Erro ao gerar capa para ${book.title}:`, err);
            // Se falhou por cota ou erro de IA, não tentamos novamente nesta sessão
          }
        }
      }
      autoGenRunning.current = false;
    };

    generateCovers();
  }, [isLoading, books.length, updateBook]);

  const availableYears = useMemo(() => {
    const years = new Set<number>();
    years.add(new Date().getFullYear());
    books.forEach(book => {
      if (book.dateFinished) years.add(new Date(book.dateFinished).getFullYear());
      if (book.dateAdded) years.add(new Date(book.dateAdded).getFullYear());
    });
    return Array.from(years).sort((a, b) => b - a);
  }, [books]);

  const filteredBooks = useMemo(() => {
    return books.filter(book => {
      if (book.status !== BookStatus.Read) return true;
      if (!book.dateFinished) return true;

      const finishDate = new Date(book.dateFinished);
      if (dateFilter === 'thisYear') {
        return finishDate.getFullYear() === new Date().getFullYear();
      }
      if (dateFilter === 'specificYear') {
        return finishDate.getFullYear() === selectedYear;
      }
      if (dateFilter === 'custom') {
        const start = new Date(customRange.start);
        const end = new Date(customRange.end);
        return finishDate >= start && finishDate <= end;
      }
      return true;
    });
  }, [books, dateFilter, selectedYear, customRange]);

  const stats: ReadingStats = useMemo(() => {
    const readBooks = filteredBooks.filter(b => b.status === BookStatus.Read);

    const yearly = {
      booksRead: readBooks.length,
      pagesRead: readBooks.reduce((acc, b) => acc + (b.pages || 0), 0),
      avgRating: readBooks.length > 0 
        ? readBooks.reduce((acc, b) => acc + (b.rating || 0), 0) / (readBooks.filter(b => b.rating).length || 1)
        : 0
    };

    const monthly: MonthlyStat[] = MONTHS.map((month, index) => {
      const monthBooks = readBooks.filter(b => {
        if (!b.dateFinished) return false;
        return new Date(b.dateFinished).getMonth() === index;
      });
      return {
        month,
        booksRead: monthBooks.length,
        pagesRead: monthBooks.reduce((acc, b) => acc + (b.pages || 0), 0),
        avgRating: monthBooks.length > 0 
          ? monthBooks.reduce((acc, b) => acc + (b.rating || 0), 0) / (monthBooks.filter(b => b.rating).length || 1)
          : 0
      };
    });

    const byType: TypeStat[] = [BookType.Book, BookType.HQ].map(type => {
      const typeBooks = readBooks.filter(b => b.type === type);
      return {
        type,
        count: typeBooks.length,
        pages: typeBooks.reduce((acc, b) => acc + (b.pages || 0), 0),
        avgRating: typeBooks.length > 0 
          ? typeBooks.reduce((acc, b) => acc + (b.rating || 0), 0) / (typeBooks.filter(b => b.rating).length || 1)
          : 0
      };
    });

    return {
      tbrCount: books.filter(b => b.status === BookStatus.TBR).length,
      wishlistCount: books.filter(b => b.status === BookStatus.Wishlist).length,
      yearly,
      monthly,
      byType
    };
  }, [books, filteredBooks]);

  const currentlyReading = useMemo(() => {
    return books.find(b => b.status === BookStatus.Reading) || null;
  }, [books]);

  return {
    books,
    stats,
    currentlyReading,
    addBook,
    updateBook,
    deleteBook,
    dateFilter,
    setDateFilter,
    selectedYear,
    setSelectedYear,
    availableYears,
    customRange,
    setCustomRange,
    isLocalMode,
    schemaError,
    isLoading
  };
};

