export default function App() {
  const [session, setSession] = useState<any>(null);
  const [isAuthLoading, setIsAuthLoading] = useState(true);
  const [userProfile, setUserProfile] = useState<Profile | null>(null);
  const [hasApiKey, setHasApiKey] = useState<boolean>(true);

  // Verifica se a chave de API está configurada no deploy externo
  useEffect(() => {
    const checkApiKey = async () => {
      if (window.aistudio) {
        const selected = await window.aistudio.hasSelectedApiKey();
        setHasApiKey(selected);
        // Se não houver chave e o usuário estiver logado, solicita a chave
        if (!selected && session) {
          await window.aistudio.openSelectKey();
          setHasApiKey(true); // Assume sucesso após abrir conforme diretrizes
        }
      }
    };
    if (session) checkApiKey();
  }, [session]);

  useEffect(() => {
    supabase.auth.getSession().then(({ data: { session } }) => {
      setSession(session);
      setIsAuthLoading(false);
    });

    const { data: { subscription } } = supabase.auth.onAuthStateChange((_event, session) => {
      setSession(session);
    });

    return () => subscription.unsubscribe();
  }, []);

  const { 
    books, 
    stats, 
    currentlyReading, 
    addBook, 
    updateBook, 
    deleteBook, 
    dateFilter, 
    setDateFilter,
    selectedYear,
    setSelectedYear,
    availableYears,
    customRange,
    setCustomRange,
    isLocalMode,
    schemaError,
    isLoading
  } = useBookData();

  const [theme, setTheme] = useState<'light' | 'dark'>(() => {
    return (localStorage.getItem('theme') as 'light' | 'dark') || 'light';
  });

  const [readingGoal, setReadingGoal] = useState(() => {
    const saved = localStorage.getItem('biblio_tech_goal');
    return saved ? parseInt(saved, 10) : 12;
  });

  useEffect(() => {
    if (session) {
      dbService.getProfile().then(profile => {
        if (profile) {
          setUserProfile(profile);
          if (profile.readingGoal) {
            setReadingGoal(profile.readingGoal);
            localStorage.setItem('biblio_tech_goal', profile.readingGoal.toString());
          }
        }
      });
    }
  }, [session]);

  const handleSetReadingGoal = (val: number) => {
    setReadingGoal(val);
    localStorage.setItem('biblio_tech_goal', val.toString());
    dbService.updateReadingGoal(val);
  };

  const handleUpdateProfile = async (updates: Partial<Profile>) => {
