import React, { useState, useMemo, useEffect } from 'react';
import { useBookData } from './hooks/useBookData';
import { Header } from './components/Header';
import { Dashboard } from './components/Dashboard';
import { AddBookModal } from './components/AddBookModal';
import { SettingsModal } from './components/SettingsModal';
import { PlusIcon } from './components/Icons';
import type { Book, NewBook, Profile } from './types';
import { BookList } from './components/BookList';
import { ConfirmationModal } from './components/ConfirmationModal';
import { BookStatus } from './types';
import { Wishlist } from './components/Wishlist';
import { BottomNav } from './components/BottomNav';
import { Auth } from './components/Auth';
import { supabase } from './services/supabase';
import { dbService } from './services/database';

export default function App() {
  const [session, setSession] = useState<any>(null);
  const [isAuthLoading, setIsAuthLoading] = useState(true);
  const [userProfile, setUserProfile] = useState<Profile | null>(null);
  const [hasApiKey, setHasApiKey] = useState<boolean>(true);

  useEffect(() => {
    supabase.auth.getSession().then(({ data: { session } }) => {
      setSession(session);
      setIsAuthLoading(false);
    });
    const { data: { subscription } } = supabase.auth.onAuthStateChange((_event, session) => {
      setSession(session);
    });
    return () => subscription.unsubscribe();
  }, []);

  useEffect(() => {
    if (session) {
      dbService.getProfile().then(profile => {
        if (profile) {
          setUserProfile(profile);
          // Injeta a chave do usuário globalmente para os serviços
          if (profile.geminiApiKey) {
            (window as any).__BIBLIOTECH_USER_KEY = profile.geminiApiKey;
            setHasApiKey(true);
          } else {
             checkPlatformApiKey();
          }
        }
      });
    }
  }, [session]);

  const checkPlatformApiKey = async () => {
    if (window.aistudio) {
        const selected = await window.aistudio.hasSelectedApiKey();
        setHasApiKey(selected);
    } else {
        // Fallback para process.env.API_KEY
        const envKey = process.env.API_KEY;
        setHasApiKey(!!(envKey && envKey !== 'undefined'));
    }
  };

  const { 
    books, stats, currentlyReading, addBook, updateBook, deleteBook, 
    dateFilter, setDateFilter, selectedYear, setSelectedYear, availableYears,
    customRange, setCustomRange, isLocalMode, schemaError, isLoading
  } = useBookData();

  const [theme, setTheme] = useState<'light' | 'dark'>(() => (localStorage.getItem('theme') as 'light' | 'dark') || 'light');
  const [readingGoal, setReadingGoal] = useState(() => parseInt(localStorage.getItem('biblio_tech_goal') || '12', 10));

  const handleSetReadingGoal = (val: number) => {
    setReadingGoal(val);
    localStorage.setItem('biblio_tech_goal', val.toString());
    dbService.updateReadingGoal(val);
  };

  const handleUpdateProfile = async (updates: Partial<Profile>) => {
    if (userProfile) {
        const newProfile = { ...userProfile, ...updates };
        setUserProfile(newProfile);
        await dbService.updateProfile(updates);
        if (updates.geminiApiKey) setHasApiKey(true);
    }
  };

  const [isModalOpen, setIsModalOpen] = useState(false);
  const [isSettingsOpen, setIsSettingsOpen] = useState(false);
  const [view, setView] = useState<'dashboard' | 'list' | 'wishlist'>('dashboard');
  const [editingBook, setEditingBook] = useState<Book | null>(null);
  const [deletingBook, setDeletingBook] = useState<Book | null>(null);
  const [defaultStatusForModal, setDefaultStatusForModal] = useState<BookStatus | undefined>();
  const [toastMessage, setToastMessage] = useState<string | null>(null);

  useEffect(() => {
    theme === 'dark' ? document.documentElement.classList.add('dark') : document.documentElement.classList.remove('dark');
    localStorage.setItem('theme', theme);
  }, [theme]);

  const showToast = (message: string) => {
    setToastMessage(message);
    setTimeout(() => setToastMessage(null), 3500);
  };

  const handleAddBook = async (newBook: NewBook) => {
    await addBook(newBook);
    setIsModalOpen(false);
    showToast(`"${newBook.title}" salvo!`);
  };

  const handleUpdateBook = async (updatedBook: Book) => {
    await updateBook(updatedBook);
    setIsModalOpen(false);
    showToast(`"${updatedBook.title}" atualizado.`);
  };

  const openAddModal = (status?: BookStatus) => {
    setEditingBook(null);
    setDefaultStatusForModal(status);
    setIsModalOpen(true);
  };

  if (isAuthLoading) return <div className="min-h-screen bg-background flex items-center justify-center"><div className="w-10 h-10 border-4 border-primary border-t-transparent rounded-full animate-spin"></div></div>;
  if (!session) return <Auth />;
  if (isLoading) return <div className="min-h-screen bg-background flex flex-col items-center justify-center p-4"><div className="w-12 h-12 border-4 border-primary border-t-transparent rounded-full animate-spin mb-4"></div><p className="text-[10px] font-black uppercase tracking-widest text-slate-400">Sincronizando...</p></div>;

  return (
    <div className="min-h-screen bg-background dark:bg-slate-950 text-text-main dark:text-slate-200 pb-24 relative transition-colors duration-300">
      <Header 
        profile={userProfile} onLogoClick={() => setView('dashboard')} onSettingsClick={() => setIsSettingsOpen(true)}
        theme={theme} toggleTheme={() => setTheme(t => t === 'light' ? 'dark' : 'light')} 
        isConnected={!isLocalMode} hasApiKey={hasApiKey}
      />

      {!hasApiKey && (
        <div className="bg-red-500 text-white px-6 py-2 text-center text-[10px] font-black uppercase tracking-widest animate-pulse cursor-pointer" onClick={() => setIsSettingsOpen(true)}>
          IA Indisponível: Clique aqui para configurar sua Chave de API nas Preferências.
        </div>
      )}

      <main className="p-4 md:p-8">
        {view === 'dashboard' && <Dashboard stats={stats} currentlyReading={currentlyReading} updateBook={handleUpdateBook} dateFilter={dateFilter} setDateFilter={setDateFilter} selectedYear={selectedYear} setSelectedYear={setSelectedYear} availableYears={availableYears} books={books} customRange={customRange} setCustomRange={setCustomRange} readingGoal={readingGoal} onSetReadingGoal={handleSetReadingGoal} />}
        {view === 'list' && <BookList books={books.filter(b => b.status !== BookStatus.Wishlist)} onEdit={(b) => { setEditingBook(b); setIsModalOpen(true); }} onDelete={setDeletingBook} onUpdateBook={handleUpdateBook} />}
        {view === 'wishlist' && <Wishlist books={books.filter(b => b.status === BookStatus.Wishlist)} onEdit={(b) => { setEditingBook(b); setIsModalOpen(true); }} onDelete={setDeletingBook} onMoveToShelf={(b) => handleUpdateBook({ ...b, status: BookStatus.TBR })} onAddWishlistItem={() => openAddModal(BookStatus.Wishlist)} />}
      </main>

      <div className="fixed bottom-24 right-6 flex flex-col gap-3">
        <button onClick={() => openAddModal()} className="bg-primary text-background p-4 rounded-full shadow-2xl hover:bg-blue-700 transition-all z-40 active:scale-95"><PlusIcon className="h-6 w-6" /></button>
      </div>

      <BottomNav view={view} setView={setView} />
      {toastMessage && <div className="fixed bottom-32 left-1/2 -translate-x-1/2 z-[60] animate-in fade-in slide-in-from-bottom-4 duration-500"><div className="bg-slate-900 text-white px-6 py-3.5 rounded-2xl shadow-2xl border border-white/10 flex items-center gap-3"><p className="text-[11px] font-black uppercase tracking-widest">{toastMessage}</p></div></div>}
      {isModalOpen && <AddBookModal onClose={() => setIsModalOpen(false)} onAddBook={handleAddBook} onUpdateBook={handleUpdateBook} bookToEdit={editingBook} defaultStatus={defaultStatusForModal} existingBooks={books} />}
      {isSettingsOpen && <SettingsModal onClose={() => setIsSettingsOpen(false)} readingGoal={readingGoal} onSetReadingGoal={handleSetReadingGoal} profile={userProfile} onUpdateProfile={handleUpdateProfile} />}
      {deletingBook && <ConfirmationModal isOpen={!!deletingBook} onClose={() => setDeletingBook(null)} onConfirm={async () => { await deleteBook(deletingBook.id); setDeletingBook(null); showToast(`Removido.`); }} title="Excluir" message={`Apagar "${deletingBook.title}"?`} />}
    </div>
  );
}

import { useState, useMemo, useCallback, useEffect, useRef } from 'react';
import type { Book, ReadingStats, NewBook, DateFilter, MonthlyStat, TypeStat } from '../types';
import { BookStatus, BookType } from '../types';
import { dbService } from '../services/database';
import { generateBookCover } from '../services/geminiService';
import { supabase } from '../services/supabase';

const MONTHS = ['Janeiro', 'Fevereiro', 'Março', 'Abril', 'Maio', 'Junho', 'Julho', 'Agosto', 'Setembro', 'Outubro', 'Novembro', 'Dezembro'];

export const useBookData = () => {
  const [books, setBooks] = useState<Book[]>([]);
  const [isLoading, setIsLoading] = useState(true);
  const [isLocalMode, setIsLocalMode] = useState(false);
  const [schemaError, setSchemaError] = useState<{type: 'table' | 'column' | 'permission', detail?: string} | null>(null);
  const [dateFilter, setDateFilter] = useState<DateFilter>('allTime');
  const [selectedYear, setSelectedYear] = useState<number>(new Date().getFullYear());
  const [customRange, setCustomRange] = useState({ 
    start: new Date(new Date().getFullYear(), 0, 1).toISOString().split('T')[0],
    end: new Date().toISOString().split('T')[0]
  });

  const autoGenRunning = useRef(false);

  const loadData = useCallback(async () => {
    setIsLoading(true);
    setSchemaError(null);
    try {
      dbService.setSchemaErrorCallback((type, detail) => {
          setSchemaError({ type, detail });
          setIsLocalMode(true);
      });

      const storedBooks = await dbService.getAllBooks();
      setBooks(storedBooks);
    } catch (error: any) {
      console.error('Erro crítico ao carregar dados:', error.message);
      setIsLocalMode(true);
    } finally {
      setIsLoading(false);
    }
  }, []);

  useEffect(() => {
    loadData();
  }, [loadData]);

  const addBook = useCallback(async (newBook: NewBook) => {
    const { data: { user } } = await supabase.auth.getUser();
    if (!user) throw new Error("Necessário login.");

    const book: Book = {
      ...newBook,
      id: crypto.randomUUID(),
      user_id: user.id,
      dateAdded: new Date().toISOString().split('T')[0],
    };

    setBooks(prev => [book, ...prev]);

    try {
        await dbService.saveBook(book);
    } catch (err) {
        console.error("Erro ao persistir novo livro:", err);
    }
  }, []);

  const updateBook = useCallback(async (updatedBook: Book) => {
    setBooks(prev => prev.map(b => b.id === updatedBook.id ? updatedBook : b));

    try {
        await dbService.saveBook(updatedBook);
    } catch (err) {
        console.error("Erro ao persistir atualização:", err);
    }
  }, []);

  const deleteBook = useCallback(async (id: string) => {
    setBooks(prev => prev.filter(b => b.id !== id));
    await dbService.deleteBook(id);
  }, []);

  useEffect(() => {
    if (isLoading || books.length === 0 || autoGenRunning.current) return;

    const generateCovers = async () => {
      const { data: { user } } = await supabase.auth.getUser();
      if (!user) return;

      autoGenRunning.current = true;
      const booksWithoutCover = books.filter(b => 
        !b.coverImageUrl || 
        b.coverImageUrl.includes('picsum.photos')
      );

      if (booksWithoutCover.length > 0) {
        for (const book of booksWithoutCover) {
          try {
            const newCoverUrl = await generateBookCover(book.title, book.genre, book.type);
            if (newCoverUrl && !newCoverUrl.includes('picsum.photos')) {
              await updateBook({ ...book, coverImageUrl: newCoverUrl });
            }
          } catch (err) {
            console.error(`Erro ao gerar capa para ${book.title}:`, err);
            break; // Interrompe se houver erro de API (limite atingido)
          }
        }
      }
      autoGenRunning.current = false;
    };

    const timer = setTimeout(generateCovers, 3000); // Debounce para não travar a carga inicial
    return () => clearTimeout(timer);
  }, [isLoading, books.length, updateBook]);

  const availableYears = useMemo(() => {
    const years = new Set<number>();
    years.add(new Date().getFullYear());
    books.forEach(book => {
      if (book.dateFinished) years.add(new Date(book.dateFinished).getFullYear());
      else if (book.dateAdded) years.add(new Date(book.dateAdded).getFullYear());
    });
    return Array.from(years).sort((a, b) => b - a);
  }, [books]);

  // Filtro de livros para as estatísticas
  const filteredBooks = useMemo(() => {
    return books.filter(book => {
      if (book.status !== BookStatus.Read) return true;
      if (!book.dateFinished) return true;

      const finishDate = new Date(book.dateFinished);
      if (dateFilter === 'thisYear') {
        return finishDate.getFullYear() === new Date().getFullYear();
      }
      if (dateFilter === 'specificYear') {
        return finishDate.getFullYear() === selectedYear;
      }
      if (dateFilter === 'custom') {
        const start = new Date(customRange.start);
        const end = new Date(customRange.end);
        return finishDate >= start && finishDate <= end;
      }
      return true;
    });
  }, [books, dateFilter, selectedYear, customRange]);

  // OTIMIZAÇÃO: Cálculo em Passo Único (Single Pass Calculation)
  const stats: ReadingStats = useMemo(() => {
    let tbrCount = 0;
    let wishlistCount = 0;

    const yearly = { booksRead: 0, pagesRead: 0, totalRating: 0, ratingCount: 0 };

    // Inicializa estruturas de dados para mensal e tipo
    const monthlyDataMap = MONTHS.map(month => ({ month, booksRead: 0, pagesRead: 0, totalRating: 0, ratingCount: 0 }));
    const byTypeMap: Record<string, { type: BookType, count: number, pages: number, totalRating: 0, ratingCount: 0 }> = {
      [BookType.Book]: { type: BookType.Book, count: 0, pages: 0, totalRating: 0, ratingCount: 0 },
      [BookType.HQ]: { type: BookType.HQ, count: 0, pages: 0, totalRating: 0, ratingCount: 0 }
    };

    // Itera por todos os livros uma única vez
    books.forEach(book => {
      if (book.status === BookStatus.TBR) tbrCount++;
      if (book.status === BookStatus.Wishlist) wishlistCount++;
    });

    // Itera pelos livros filtrados para estatísticas lidas
    filteredBooks.forEach(book => {
      if (book.status === BookStatus.Read) {
        yearly.booksRead++;
        yearly.pagesRead += (book.pages || 0);
        if (book.rating) {
          yearly.totalRating += book.rating;
          yearly.ratingCount++;
        }

        // Estatística Mensal
        if (book.dateFinished) {
          const monthIndex = new Date(book.dateFinished).getMonth();
          const mData = monthlyDataMap[monthIndex];
          if (mData) {
            mData.booksRead++;
            mData.pagesRead += (book.pages || 0);
            if (book.rating) {
              mData.totalRating += book.rating;
              mData.ratingCount++;
            }
          }
        }

        // Estatística por Tipo
        const tData = byTypeMap[book.type];
        if (tData) {
          tData.count++;
          tData.pages += (book.pages || 0);
          if (book.rating) {
            tData.totalRating += book.rating;
            tData.ratingCount++;
          }
        }
      }
    });

    // Formata o resultado final
    return {
      tbrCount,
      wishlistCount,
      yearly: {
        booksRead: yearly.booksRead,
        pagesRead: yearly.pagesRead,
        avgRating: yearly.ratingCount > 0 ? yearly.totalRating / yearly.ratingCount : 0
      },
      monthly: monthlyDataMap.map(m => ({
        month: m.month,
        booksRead: m.booksRead,
        pagesRead: m.pagesRead,
        avgRating: m.ratingCount > 0 ? m.totalRating / m.ratingCount : 0
      })),
      byType: Object.values(byTypeMap).map(t => ({
        type: t.type,
        count: t.count,
        pages: t.pages,
        avgRating: t.ratingCount > 0 ? t.totalRating / t.ratingCount : 0
      }))
    };
  }, [books, filteredBooks]);

  const currentlyReading = useMemo(() => {
    return books.find(b => b.status === BookStatus.Reading) || null;
  }, [books]);

  return {
    books,
    stats,
    currentlyReading,
    addBook,
    updateBook,
    deleteBook,
    dateFilter,
    setDateFilter,
    selectedYear,
    setSelectedYear,
    availableYears,
    customRange,
    setCustomRange,
    isLocalMode,
    schemaError,
    isLoading
  };
};

import React, { useState, useCallback, useEffect } from 'react';
import type { NewBook, Book, StatusConfigs } from '../types';
import { BookStatus, BookType, GENRES, STATUS_CONFIGS } from '../types';
import { XMarkIcon, BookOpenIcon, StarIcon, StarIconFilled, PlusIcon } from './Icons';
import { generateBookSummary, generateBookCover } from '../services/geminiService';

interface AddBookModalProps {
  onClose: () => void;
  onAddBook: (book: NewBook) => Promise<void>;
  onUpdateBook: (book: Book) => Promise<void>;
  bookToEdit?: Book | null;
  defaultStatus?: BookStatus;
  existingBooks: Book[];
  statusConfigs?: StatusConfigs;
}

interface FormErrors {
  title?: string;
  authors?: string;
  genre?: string;
}

export const AddBookModal: React.FC<AddBookModalProps> = ({ 
  onClose, 
  onAddBook, 
  onUpdateBook, 
  bookToEdit, 
  defaultStatus, 
  existingBooks, 
  statusConfigs = STATUS_CONFIGS 
}) => {
  const isEditMode = !!bookToEdit;

  const [title, setTitle] = useState(bookToEdit?.title || '');
  const [authors, setAuthors] = useState<string[]>(
    bookToEdit?.author ? bookToEdit.author.split(',').map(a => a.trim()).filter(a => a !== '') : []
  );
  const [authorInput, setAuthorInput] = useState('');
  const [pages, setPages] = useState(bookToEdit?.pages || 0);
  const [selectedGenres, setSelectedGenres] = useState<string[]>(
    bookToEdit?.genre ? bookToEdit.genre.split(',').map(g => g.trim()).filter(g => g !== '') : []
  );
  const [type, setType] = useState<BookType>(bookToEdit?.type || BookType.Book);
  const [status, setStatus] = useState<BookStatus>(bookToEdit?.status || defaultStatus || BookStatus.TBR);
  const [rating, setRating] = useState<number>(bookToEdit?.rating || 0);
  const [hoverRating, setHoverRating] = useState<number>(0);
  const [summary, setSummary] = useState(bookToEdit?.summary || '');
  const [notes, setNotes] = useState(bookToEdit?.notes || '');
  const [estimatedPrice, setEstimatedPrice] = useState(bookToEdit?.estimatedPrice?.toString() || '');
  const [buyLink, setBuyLink] = useState(bookToEdit?.buyLink || '');
  const [coverImageUrl, setCoverImageUrl] = useState<string | undefined>(bookToEdit?.coverImageUrl);
  const [isGeneratingCover, setIsGeneratingCover] = useState(false);
  const [isGeneratingSummary, setIsGeneratingSummary] = useState(false);
  const [isSubmitting, setIsSubmitting] = useState(false);
  const [dateAdded] = useState(bookToEdit?.dateAdded || new Date().toISOString().split('T')[0]);

  const [dateFinished, setDateFinished] = useState(bookToEdit?.dateFinished || new Date().toISOString().split('T')[0]);
  const [daysToFinish, setDaysToFinish] = useState(bookToEdit?.daysToFinish?.toString() || '');
  const [timesRead, setTimesRead] = useState(bookToEdit?.timesRead || (bookToEdit?.status === BookStatus.Read ? 1 : 0));

  const [errors, setErrors] = useState<FormErrors>({});
  const [isShaking, setIsShaking] = useState(false);

  useEffect(() => {
    if (status === BookStatus.Read && !daysToFinish && bookToEdit?.dateStarted && dateFinished) {
        const start = new Date(bookToEdit.dateStarted);
        const end = new Date(dateFinished);
        const diffTime = end.getTime() - start.getTime();
        const diffDays = Math.ceil(diffTime / (1000 * 60 * 60 * 24));
        if (diffDays >= 0) setDaysToFinish(diffDays.toString());
    }
    if (status === BookStatus.Read && timesRead === 0) setTimesRead(1);
  }, [status, dateFinished]);

  const addAuthor = () => {
    const val = authorInput.trim();
    if (val && !authors.includes(val)) {
      setAuthors([...authors, val]);
      setAuthorInput('');
      if (errors.authors) setErrors(prev => ({ ...prev, authors: undefined }));
    }
  };

  const removeAuthor = (name: string) => {
    setAuthors(authors.filter(a => a !== name));
  };

  const handleTitleChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    setTitle(e.target.value);
    if (errors.title) setErrors(prev => ({ ...prev, title: undefined }));
  };

  const toggleGenre = (genreName: string) => {
    setSelectedGenres(prev => {
      const isSelected = prev.includes(genreName);
      const newList = isSelected ? prev.filter(g => g !== genreName) : [...prev, genreName];
      if (newList.length > 0 && errors.genre) setErrors(prevErr => ({ ...prevErr, genre: undefined }));
      return newList;
    });
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    if (isSubmitting) return;

    // Se houver algo no input de autor não adicionado, tenta adicionar agora
    let finalAuthors = [...authors];
    if (authorInput.trim() && !finalAuthors.includes(authorInput.trim())) {
        finalAuthors.push(authorInput.trim());
    }

    const newErrors: FormErrors = {};
    if (!title.trim()) newErrors.title = "O título é obrigatório";
    if (finalAuthors.length === 0) newErrors.authors = "Adicione ao menos um autor";
    if (selectedGenres.length === 0) newErrors.genre = "Selecione ao menos um gênero";

    if (Object.keys(newErrors).length > 0) {
      setErrors(newErrors);
      setIsShaking(true);
      setTimeout(() => setIsShaking(false), 500);
      return;
    }

    setIsSubmitting(true);
    try {
        const bookData = { 
            title: title.trim(), 
            author: finalAuthors.join(', '), 
            pages, 
            genre: selectedGenres.join(', '), 
            type, 
            status, 
            summary, 
            notes,
            rating: status === BookStatus.Read ? (rating || undefined) : undefined,
            estimatedPrice: estimatedPrice ? parseFloat(estimatedPrice) : undefined,
            buyLink: buyLink.trim() || undefined,
            coverImageUrl, 
            dateAdded,
            currentPage: status === BookStatus.Read ? pages : bookToEdit?.currentPage,
            dateStarted: bookToEdit?.dateStarted,
            dateFinished: status === BookStatus.Read ? dateFinished : undefined,
            daysToFinish: status === BookStatus.Read && daysToFinish ? parseInt(daysToFinish, 10) : null,
            timesRead: status === BookStatus.Read ? Number(timesRead) : 0
        };
        if (isEditMode) {
            await onUpdateBook({ ...bookToEdit, ...bookData });
        } else {
            await onAddBook(bookData);
        }
    } finally {
        setIsSubmitting(false);
    }
  };

  const handleGenerateCover = useCallback(async () => {
    if (!title || selectedGenres.length === 0) return;
    setIsGeneratingCover(true);
    const result = await generateBookCover(title, selectedGenres[0], type);
    setCoverImageUrl(result);
    setIsGeneratingCover(false);
  }, [title, selectedGenres, type]);

  const handleGenerateSummary = useCallback(async () => {
    if (!title || authors.length === 0) return;
    setIsGeneratingSummary(true);
    try {
      const result = await generateBookSummary(title, authors.join(', '));
      if (result) setSummary(result);
    } catch (err) {
      console.error("Erro ao gerar resumo:", err);
    } finally {
      setIsGeneratingSummary(false);
    }
  }, [title, authors]);

  const labelClass = (isRequired: boolean) => 
    `block text-[10px] font-black uppercase tracking-[0.15em] mb-1.5 ml-1 flex items-center gap-1 ${isRequired ? 'text-slate-500 dark:text-slate-400' : 'text-slate-400 dark:text-slate-500'}`;

  return (
    <div className="fixed inset-0 bg-slate-900/60 backdrop-blur-sm flex items-center justify-center z-50 p-4">
      <div 
        className={`bg-white dark:bg-slate-900 rounded-[2.5rem] shadow-2xl w-full max-w-2xl max-h-[90vh] overflow-hidden flex flex-col border border-white/20 dark:border-slate-800 transition-transform duration-500 ${isShaking ? 'animate-shake' : ''}`}
        style={{ animation: isShaking ? 'shake 0.4s cubic-bezier(.36,.07,.19,.97) both' : 'none' }}
      >
        <div className="p-7 border-b border-slate-100 dark:border-slate-800 flex justify-between items-center bg-slate-50/50 dark:bg-slate-800/30">
            <h2 className="text-2xl font-black font-serif text-slate-900 dark:text-slate-50 tracking-tight">{isEditMode ? 'Editar Registro' : 'Novo Registro'}</h2>
            <button onClick={onClose} disabled={isSubmitting} className="p-2.5 rounded-full hover:bg-slate-200 dark:hover:bg-slate-700 text-slate-400 transition-all hover:rotate-90 disabled:opacity-30">
                <XMarkIcon className="h-5 w-5" />
            </button>
        </div>

        <form onSubmit={handleSubmit} className="p-8 space-y-8 overflow-y-auto custom-scrollbar">
            <div className={`grid grid-cols-1 md:grid-cols-2 gap-8 ${isSubmitting ? 'opacity-50 pointer-events-none' : ''}`}>
                <div className="md:col-span-2">
                    <label className={labelClass(true)}>
                      Título <span className="text-red-500">*</span>
                    </label>
                    <input 
                      type="text" 
                      value={title} 
                      onChange={handleTitleChange} 
                      placeholder="Ex: Cem Anos de Solidão"
                      className={`w-full bg-slate-50 dark:bg-slate-800 border rounded-2xl px-5 py-3.5 outline-none transition-all focus:ring-4 focus:ring-primary/5 ${errors.title ? 'border-red-400 bg-red-50/30 dark:bg-red-950/20' : 'border-slate-200 dark:border-slate-700 focus:border-primary font-bold'}`} 
                    />
                    {errors.title && <p className="text-[10px] text-red-500 font-bold mt-2 uppercase tracking-wide ml-1">{errors.title}</p>}
                </div>

                <div className="md:col-span-2">
                    <label className={labelClass(true)}>
                      Autor(es) <span className="text-red-500">*</span>
                    </label>
                    <div className="flex gap-2 mb-3">
                        <input 
                          type="text" 
                          value={authorInput} 
                          onChange={(e) => setAuthorInput(e.target.value)} 
                          onKeyDown={(e) => { if (e.key === 'Enter') { e.preventDefault(); addAuthor(); } }}
                          placeholder="Adicione um autor..."
                          className={`flex-1 bg-slate-50 dark:bg-slate-800 border rounded-2xl px-5 py-3.5 outline-none transition-all focus:ring-4 focus:ring-primary/5 ${errors.authors ? 'border-red-400' : 'border-slate-200 dark:border-slate-700 focus:border-primary font-bold'}`} 
                        />
                        <button 
                          type="button" 
                          onClick={addAuthor}
                          className="px-5 rounded-2xl bg-slate-100 dark:bg-slate-800 border border-slate-200 dark:border-slate-700 text-slate-500 hover:bg-primary hover:text-white hover:border-primary transition-all active:scale-95"
                        >
                          <PlusIcon className="h-5 w-5" />
                        </button>
                    </div>

                    <div className="flex flex-wrap gap-2 min-h-[40px]">
                        {authors.length > 0 ? (
                            authors.map(a => (
                                <span key={a} className="bg-slate-50 dark:bg-slate-800 border border-slate-200 dark:border-slate-700 text-slate-600 dark:text-slate-300 text-[10px] font-black uppercase tracking-widest px-4 py-2 rounded-xl flex items-center gap-2 shadow-sm animate-in fade-in zoom-in duration-300">
                                    {a}
                                    <button type="button" onClick={() => removeAuthor(a)} className="hover:text-red-500 transition-colors p-0.5">
                                        <XMarkIcon className="h-3.5 w-3.5" />
                                    </button>
                                </span>
                            ))
                        ) : (
                            <span className="text-slate-400 dark:text-slate-500 text-[10px] font-bold uppercase tracking-widest ml-1 mt-1 italic">Nenhum autor adicionado</span>
                        )}
                    </div>
                    {errors.authors && <p className="text-[10px] text-red-500 font-bold mt-2 uppercase tracking-wide ml-1">{errors.authors}</p>}
                </div>

                <div>
                    <label className={labelClass(false)}>Status</label>
                    <select value={status} onChange={(e) => setStatus(e.target.value as BookStatus)} className="w-full bg-slate-50 dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-2xl px-5 py-3.5 outline-none focus:ring-4 focus:ring-primary/5 focus:border-primary cursor-pointer font-bold text-slate-700 dark:text-slate-300">
                        <option value={BookStatus.TBR}>{statusConfigs[BookStatus.TBR].label}</option>
                        <option value={BookStatus.Reading}>{statusConfigs[BookStatus.Reading].label}</option>
                        <option value={BookStatus.Read}>{statusConfigs[BookStatus.Read].label}</option>
                        <option value={BookStatus.Wishlist}>{statusConfigs[BookStatus.Wishlist].label}</option>
                    </select>
                </div>

                {status === BookStatus.Read && (
                  <div className="md:col-span-2 grid grid-cols-1 md:grid-cols-3 gap-8 animate-in slide-in-from-top-4 duration-300">
                    <div>
                      <label className={labelClass(false)}>Data de Conclusão</label>
                      <input 
                        type="date" 
                        value={dateFinished} 
                        onChange={(e) => setDateFinished(e.target.value)} 
                        className="w-full bg-slate-50 dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-2xl px-5 py-3.5 outline-none focus:border-primary font-bold text-slate-700 dark:text-slate-300" 
                      />
                    </div>
                    <div>
                      <label className={labelClass(false)}>Dias Gastos</label>
                      <input 
                        type="number" 
                        min="0"
                        placeholder="Ex: 15"
                        value={daysToFinish} 
                        onChange={(e) => setDaysToFinish(e.target.value)} 
                        className="w-full bg-slate-50 dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-2xl px-5 py-3.5 outline-none focus:border-primary font-bold text-slate-700 dark:text-slate-300" 
                      />
                    </div>
                    <div>
                      <label className={labelClass(false)}>Vezes Lido</label>
                      <input 
                        type="number" 
                        min="1"
                        placeholder="Ex: 1"
                        value={timesRead} 
                        onChange={(e) => setTimesRead(Number(e.target.value))} 
                        className="w-full bg-slate-50 dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-2xl px-5 py-3.5 outline-none focus:border-primary font-bold text-slate-700 dark:text-slate-300" 
                      />
                    </div>
                  </div>
                )}

                <div className="md:col-span-2">
                    <label className={labelClass(true)}>Gêneros <span className="text-red-500">*</span></label>
                    <div className={`p-5 bg-slate-50/50 dark:bg-slate-800/20 border rounded-[2rem] transition-all ${errors.genre ? 'border-red-400 ring-4 ring-red-500/5 bg-red-50/10' : 'border-slate-200 dark:border-slate-700'}`}>
                        <div className="flex flex-wrap gap-2.5 mb-5 min-h-[38px]">
                            {selectedGenres.length > 0 ? (
                                selectedGenres.map(g => (
                                    <span key={g} className="bg-primary text-white text-[10px] font-black uppercase tracking-widest px-4 py-2 rounded-xl flex items-center gap-2 shadow-md animate-in fade-in zoom-in duration-300">
                                        {g}
                                        <button type="button" onClick={() => toggleGenre(g)} className="hover:text-blue-200 transition-colors p-0.5">
                                            <XMarkIcon className="h-3.5 w-3.5" />
                                        </button>
                                    </span>
                                ))
                            ) : (
                                <span className="text-slate-400 dark:text-slate-500 text-xs italic ml-1 mt-2">Escolha as categorias da obra...</span>
                            )}
                        </div>
                        <div className="flex flex-wrap gap-2 pt-5 border-t border-slate-200/60 dark:border-slate-700/60 max-h-48 overflow-y-auto pr-2 custom-scrollbar">
                            {GENRES.map(g => {
                                const isSelected = selectedGenres.includes(g);
                                return (
                                    <button
                                        key={g}
                                        type="button"
                                        onClick={() => toggleGenre(g)}
                                        className={`px-4 py-2 rounded-xl text-[10px] font-black uppercase tracking-[0.1em] transition-all ${
                                            isSelected 
                                                ? 'bg-primary text-white border border-primary scale-95 shadow-sm' 
                                                : 'bg-white dark:bg-slate-900 text-slate-500 dark:text-slate-400 border border-slate-200 dark:border-slate-700 hover:border-primary/40 hover:bg-slate-50 dark:hover:bg-slate-800'
                                        }`}
                                    >
                                        {g}
                                    </button>
                                );
                            })}
                        </div>
                    </div>
                    {errors.genre && <p className="text-[10px] text-red-500 font-bold mt-3 uppercase tracking-wide ml-1">{errors.genre}</p>}
                </div>

                <div>
                    <label className={labelClass(false)}>Total de Páginas</label>
                    <input type="number" min="0" value={pages} onChange={(e) => setPages(Number(e.target.value))} className="w-full bg-slate-50 dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-2xl px-5 py-3.5 outline-none focus:border-primary font-bold text-slate-700 dark:text-slate-300" />
                </div>
                <div>
                    <label className={labelClass(false)}>Tipo de Mídia</label>
                    <select value={type} onChange={(e) => setType(e.target.value as BookType)} className="w-full bg-slate-50 dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-2xl px-5 py-3.5 outline-none focus:border-primary font-bold text-slate-700 dark:text-slate-300">
                        <option value={BookType.Book}>Livro</option>
                        <option value={BookType.HQ}>HQ</option>
                    </select>
                </div>

                <div className="md:col-span-2">
                    <label className={labelClass(false)}>Avaliação / Nota</label>
                    <div className="flex items-center gap-1.5 p-4 bg-slate-50 dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-2xl">
                        {[...Array(10)].map((_, i) => {
                            const val = i + 1;
                            const isActive = val <= (hoverRating || rating);
                            return (
                                <button
                                    key={i}
                                    type="button"
                                    onClick={() => setRating(val)}
                                    onMouseEnter={() => setHoverRating(val)}
                                    onMouseLeave={() => setHoverRating(0)}
                                    className="p-0.5 transition-transform hover:scale-110"
                                >
                                    {isActive ? (
                                        <StarIconFilled className="h-6 w-6 text-amber-400" />
                                    ) : (
                                        <StarIcon className="h-6 w-6 text-slate-300 dark:text-slate-600" />
                                    )}
                                </button>
                            );
                        })}
                        <span className="ml-4 text-sm font-black text-amber-500 min-w-[2ch]">
                            {rating || '-'}
                        </span>
                    </div>
                </div>

                <div>
                    <label className={labelClass(false)}>Valor Estimado (R$)</label>
                    <input 
                      type="number" 
                      step="0.01" 
                      value={estimatedPrice} 
                      onChange={(e) => setEstimatedPrice(e.target.value)} 
                      placeholder="0,00"
                      className="w-full bg-slate-50 dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-2xl px-5 py-3.5 outline-none focus:border-primary font-bold text-slate-700 dark:text-slate-300" 
                    />
                </div>
                <div>
                    <label className={labelClass(false)}>Link de Compra</label>
                    <input 
                      type="text" 
                      value={buyLink} 
                      onChange={(e) => setBuyLink(e.target.value)} 
                      placeholder="https://..."
                      className="w-full bg-slate-50 dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-2xl px-5 py-3.5 outline-none focus:border-primary font-bold text-slate-700 dark:text-slate-300" 
                    />
                </div>
            </div>

            <div className="p-7 bg-blue-50/40 dark:bg-blue-900/10 rounded-[2.5rem] border border-blue-100 dark:border-blue-800/50 flex flex-col sm:flex-row items-center gap-8 shadow-inner">
                <div className="relative group flex-shrink-0">
                    {coverImageUrl ? (
                        <img src={coverImageUrl} alt="Capa" className="w-24 h-36 object-cover rounded-xl shadow-xl transition-transform group-hover:scale-110 duration-500"/>
                    ) : (
                        <div className="w-24 h-36 bg-slate-200 dark:bg-slate-800 rounded-xl flex items-center justify-center border-2 border-dashed border-slate-300 dark:border-slate-700">
                            <BookOpenIcon className="h-8 w-8 text-slate-400 dark:text-slate-600" />
                        </div>
                    )}
                </div>
                <div className="text-center sm:text-left flex-1">
                    <h4 className="text-sm font-black text-slate-800 dark:text-slate-200 mb-2 uppercase tracking-wide">✦ Inteligência BiblioTech</h4>
                    <p className="text-[11px] text-slate-500 dark:text-slate-400 mb-5 leading-relaxed font-medium uppercase tracking-tight">Deixe a IA criar um resumo inicial envolvente ou uma arte de capa personalizada para sua estante.</p>
                    <div className="flex flex-wrap gap-3 justify-center sm:justify-start">
                        <button 
                            type="button" 
                            onClick={handleGenerateSummary} 
                            disabled={isGeneratingSummary || isSubmitting || !title || authors.length === 0} 
                            className="px-6 py-3 text-[10px] font-black uppercase tracking-widest rounded-xl bg-primary text-white hover:bg-slate-900 dark:hover:bg-slate-100 dark:hover:text-slate-900 transition-all shadow-md active:scale-95 disabled:opacity-50 flex items-center gap-2"
                        >
                            {isGeneratingSummary ? 'Processando...' : '✦ Gerar Resumo com IA'}
                        </button>
                        <button 
                            type="button" 
                            onClick={handleGenerateCover} 
                            disabled={isGeneratingCover || isSubmitting || !title || selectedGenres.length === 0} 
                            className="px-6 py-3 text-[10px] font-black uppercase tracking-widest rounded-xl bg-white dark:bg-slate-800 text-primary border border-blue-200 dark:border-blue-800/50 hover:bg-primary hover:text-white transition-all shadow-md active:scale-95 disabled:opacity-50 flex items-center gap-2"
                        >
                            {isGeneratingCover ? 'Criando Arte...' : 'Gerar Arte de Capa'}
                        </button>
                    </div>
                </div>
            </div>

            <div className="space-y-3">
                <label className={labelClass(false)}>Resumo & Sinopse</label>
                <textarea 
                  value={summary} 
                  onChange={(e) => setSummary(e.target.value)} 
                  rows={4} 
                  className="w-full bg-slate-50 dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-[1.5rem] px-5 py-4 outline-none focus:border-primary focus:ring-4 focus:ring-primary/5 text-sm leading-relaxed text-slate-600 dark:text-slate-300 font-medium" 
                  placeholder="Como você descreveria esta jornada?..."
                ></textarea>
            </div>

            <div className="space-y-3">
                <label className={labelClass(false)}>Notas Pessoais</label>
                <textarea 
                    value={notes} 
                    onChange={(e) => setNotes(e.target.value)} 
                    rows={4} 
