import type { Book, Profile } from '../types';
import { supabase } from './supabase';

const TABLE_NAME = 'books';
const BASE_LOCAL_STORAGE_KEY = 'biblio_tech_cache_';

const mapBookToDb = (book: any) => {
    const dateAddedValue = book.dateAdded || new Date().toISOString().split('T')[0];
    return {
        id: book.id,
        user_id: book.user_id,
        title: book.title || 'Sem Título',
        author: book.author || 'Autor Desconhecido',
        pages: parseInt(String(book.pages || 0), 10),
        genre: book.genre || '',
        type: book.type || 'Livro',
        status: book.status || 'Não lido',
        rating: (book.rating !== undefined && book.rating !== null && book.rating !== 0) ? parseFloat(String(book.rating)) : null,
        cover_image_url: book.coverImageUrl || null,
        summary: book.summary || null,
        notes: book.notes || null,
        estimated_price: (book.estimatedPrice !== undefined && book.estimatedPrice !== null) ? parseFloat(String(book.estimatedPrice)) : null,
        buy_link: book.buy_link || book.buyLink || null,
        current_page: parseInt(String(book.currentPage || 0), 10),
        date_added: dateAddedValue,
        date_started: book.dateStarted || null,
        date_finished: book.dateFinished || null,
        days_to_finish: (book.daysToFinish !== undefined && book.daysToFinish !== null) ? parseInt(String(book.daysToFinish), 10) : null,
        times_read: (book.times_read !== undefined && book.times_read !== null) ? parseInt(String(book.times_read), 10) : (book.timesRead || 1)
    };
};

const mapDbToBook = (db: any): Book => ({
    id: db.id,
    user_id: db.user_id,
    title: db.title,
    author: db.author,
    pages: db.pages || 0,
    genre: db.genre || '',
    type: db.type,
    status: db.status,
    rating: db.rating ? parseFloat(String(db.rating)) : undefined,
    coverImageUrl: db.cover_image_url,
    summary: db.summary,
    notes: db.notes,
    estimatedPrice: db.estimated_price ? parseFloat(String(db.estimated_price)) : undefined,
    buyLink: db.buy_link,
    currentPage: db.current_page || 0,
    dateAdded: db.date_added,
    dateStarted: db.date_started,
    dateFinished: db.date_finished,
    daysToFinish: db.days_to_finish,
    timesRead: db.times_read || 1
});

const mapDbToProfile = (db: any): Profile => ({
    id: db.id,
    fullName: db.full_name,
    avatarUrl: db.avatar_url,
    readingGoal: db.reading_goal || 12,
    geminiApiKey: db.gemini_api_key || ''
});

export class DatabaseService {
  private isSchemaBroken = false;
  private onSchemaErrorCallback?: (type: 'table' | 'column' | 'permission', detail?: string) => void;

  setSchemaErrorCallback(cb: (type: 'table' | 'column' | 'permission', detail?: string) => void) {
    this.onSchemaErrorCallback = cb;
  }

  private async getCacheKey(): Promise<string | null> {
    const { data: { user } } = await supabase.auth.getUser();
    return user ? `${BASE_LOCAL_STORAGE_KEY}${user.id}` : null;
  }

  private async getLocalBooks(): Promise<Book[]> {
    const key = await this.getCacheKey();
    if (!key) return [];
    try {
      const data = localStorage.getItem(key);
      return data ? JSON.parse(data) : [];
    } catch (e) {
      return [];
    }
  }

  private async saveLocalBooks(books: Book[]): Promise<void> {
    const key = await this.getCacheKey();
    if (!key) return;

    try {
      const data = JSON.stringify(books);
      localStorage.setItem(key, data);
    } catch (e: any) {
      if (e.name === 'QuotaExceededError' || e.code === 22 || e.name === 'NS_ERROR_DOM_QUOTA_REACHED') {
        const leanBooks = books.map(book => ({
          ...book,
          coverImageUrl: (book.coverImageUrl?.startsWith('data:')) ? null : book.coverImageUrl
        }));
        try {
          localStorage.setItem(key, JSON.stringify(leanBooks));
        } catch (innerError) {
          localStorage.removeItem(key);
        }
      }
    }
  }

  async getAllBooks(): Promise<Book[]> {
    try {
      const { data, error } = await supabase
        .from(TABLE_NAME)
        .select('*')
        .order('date_added', { ascending: false });

      if (error) {
        this.handleSupabaseError(error);
        return await this.getLocalBooks();
      }

      this.isSchemaBroken = false;
      const books = (data || []).map(mapDbToBook);
      await this.saveLocalBooks(books);
      return books;
    } catch (err) {
      return await this.getLocalBooks();
    }
  }

  /**
   * Busca estatísticas rápidas via agregação no banco para otimizar o carregamento inicial.
   */
  async getQuickStatsSummary() {
    if (this.isSchemaBroken) return null;

    try {
      const { data: { user } } = await supabase.auth.getUser();
      if (!user) return null;

      // Executa múltiplas contagens em paralelo no banco
      const [read, tbr, wishlist] = await Promise.all([
        supabase.from(TABLE_NAME).select('*', { count: 'exact', head: true }).eq('status', 'Lido').eq('user_id', user.id),
        supabase.from(TABLE_NAME).select('*', { count: 'exact', head: true }).eq('status', 'Não lido').eq('user_id', user.id),
        supabase.from(TABLE_NAME).select('*', { count: 'exact', head: true }).eq('status', 'Lista de Desejos').eq('user_id', user.id)
      ]);

      return {
        readCount: read.count || 0,
        tbrCount: tbr.count || 0,
        wishlistCount: wishlist.count || 0
      };
    } catch (err) {
      return null;
    }
  }

  async saveBook(book: Partial<Book>): Promise<void> {
    const { data: { user } } = await supabase.auth.getUser();
    if (!user) throw new Error("Acesso negado.");

    const dbPayload = mapBookToDb(book);
    dbPayload.user_id = user.id;

    const books = await this.getLocalBooks();
    const index = books.findIndex(b => b.id === book.id);
    const updatedBookState = mapDbToBook(dbPayload);

    if (index >= 0) books[index] = updatedBookState;
    else books.unshift(updatedBookState);

    await this.saveLocalBooks(books);

    if (this.isSchemaBroken) return;
    try {
      await supabase.from(TABLE_NAME).upsert(dbPayload);
    } catch (err) {}
  }

  async deleteBook(id: string): Promise<void> {
    const books = (await this.getLocalBooks()).filter(b => b.id !== id);
    await this.saveLocalBooks(books);
    if (this.isSchemaBroken) return;
    try {
      await supabase.from(TABLE_NAME).delete().eq('id', id);
    } catch (err) {}
  }

  async updateReadingGoal(goal: number): Promise<void> {
    const { data: { user } } = await supabase.auth.getUser();
    if (!user) return;
    try {
      await supabase.from('profiles').upsert({ id: user.id, reading_goal: goal, updated_at: new Date().toISOString() });
    } catch (err) {}
  }

  async updateProfile(profile: Partial<Profile>): Promise<void> {
    const { data: { user } } = await supabase.auth.getUser();
    if (!user) return;
    try {
      const dbPayload: any = { id: user.id, updated_at: new Date().toISOString() };
      if (profile.fullName !== undefined) dbPayload.full_name = profile.fullName;
      if (profile.avatarUrl !== undefined) dbPayload.avatar_url = profile.avatarUrl;
      if (profile.geminiApiKey !== undefined) dbPayload.gemini_api_key = profile.geminiApiKey;

      await supabase.from('profiles').upsert(dbPayload);
    } catch (err) {}
  }

  async getProfile(): Promise<Profile | null> {
    const { data: { user } } = await supabase.auth.getUser();
    if (!user) return null;
    try {
        const { data } = await supabase.from('profiles').select('*').eq('id', user.id).single();
        if (!data) return { id: user.id, fullName: 'Leitor', readingGoal: 12 };
        return mapDbToProfile(data);
    } catch (err) {
        return { id: user.id, fullName: 'Leitor', readingGoal: 12 };
    }
  }

  private handleSupabaseError(error: any) {
    if (error.code === '42P01') this.isSchemaBroken = true;
  }
}

export const dbService = new DatabaseService();

import { useState, useMemo, useCallback, useEffect, useRef } from 'react';
import type { Book, ReadingStats, NewBook, DateFilter, MonthlyStat, TypeStat } from '../types';
import { BookStatus, BookType } from '../types';
import { dbService } from '../services/database';
import { generateBookCover } from '../services/geminiService';
import { supabase } from '../services/supabase';

const MONTHS = ['Janeiro', 'Fevereiro', 'Março', 'Abril', 'Maio', 'Junho', 'Julho', 'Agosto', 'Setembro', 'Outubro', 'Novembro', 'Dezembro'];

export const useBookData = () => {
  const [books, setBooks] = useState<Book[]>([]);
  const [isLoading, setIsLoading] = useState(true);
  const [isLocalMode, setIsLocalMode] = useState(false);
  const [schemaError, setSchemaError] = useState<{type: 'table' | 'column' | 'permission', detail?: string} | null>(null);
  const [dateFilter, setDateFilter] = useState<DateFilter>('allTime');
  const [selectedYear, setSelectedYear] = useState<number>(new Date().getFullYear());
  const [customRange, setCustomRange] = useState({ 
    start: new Date(new Date().getFullYear(), 0, 1).toISOString().split('T')[0],
    end: new Date().toISOString().split('T')[0]
  });

  // Estado para estatísticas rápidas vindo direto do banco (agregados)
  const [quickSummary, setQuickSummary] = useState<{readCount: number, tbrCount: number, wishlistCount: number} | null>(null);

  const autoGenRunning = useRef(false);

  const loadData = useCallback(async () => {
    setIsLoading(true);
    setSchemaError(null);
    try {
      dbService.setSchemaErrorCallback((type, detail) => {
          setSchemaError({ type, detail });
          setIsLocalMode(true);
      });

      // OTIMIZAÇÃO: Busca paralela de agregados (rápido) e lista completa (pesado)
      const [storedBooks, quickStats] = await Promise.all([
        dbService.getAllBooks(),
        dbService.getQuickStatsSummary()
      ]);

      if (quickStats) setQuickSummary(quickStats);
      setBooks(storedBooks);
    } catch (error: any) {
      console.error('Erro crítico ao carregar dados:', error.message);
      setIsLocalMode(true);
    } finally {
      setIsLoading(false);
    }
  }, []);

  useEffect(() => {
    loadData();
  }, [loadData]);

  const addBook = useCallback(async (newBook: NewBook) => {
    const { data: { user } } = await supabase.auth.getUser();
    if (!user) throw new Error("Necessário login.");

    const book: Book = {
      ...newBook,
      id: crypto.randomUUID(),
      user_id: user.id,
      dateAdded: new Date().toISOString().split('T')[0],
    };

    setBooks(prev => [book, ...prev]);

    try {
        await dbService.saveBook(book);
    } catch (err) {
        console.error("Erro ao persistir novo livro:", err);
    }
  }, []);

  const updateBook = useCallback(async (updatedBook: Book) => {
    setBooks(prev => prev.map(b => b.id === updatedBook.id ? updatedBook : b));

    try {
        await dbService.saveBook(updatedBook);
    } catch (err) {
        console.error("Erro ao persistir atualização:", err);
    }
  }, []);

  const deleteBook = useCallback(async (id: string) => {
    setBooks(prev => prev.filter(b => b.id !== id));
    await dbService.deleteBook(id);
  }, []);

  useEffect(() => {
    if (isLoading || books.length === 0 || autoGenRunning.current) return;

    const generateCovers = async () => {
      const { data: { user } } = await supabase.auth.getUser();
      if (!user) return;

      autoGenRunning.current = true;
      const booksWithoutCover = books.filter(b => 
        !b.coverImageUrl || 
        b.coverImageUrl.includes('picsum.photos')
      );

      if (booksWithoutCover.length > 0) {
        for (const book of booksWithoutCover) {
          try {
            const newCoverUrl = await generateBookCover(book.title, book.genre, book.type);
            if (newCoverUrl && !newCoverUrl.includes('picsum.photos')) {
              await updateBook({ ...book, coverImageUrl: newCoverUrl });
            }
          } catch (err) {
            console.error(`Erro ao gerar capa para ${book.title}:`, err);
            break; // Interrompe se houver erro de API (limite atingido)
          }
        }
      }
      autoGenRunning.current = false;
    };

    const timer = setTimeout(generateCovers, 3000); // Debounce para não travar a carga inicial
    return () => clearTimeout(timer);
  }, [isLoading, books.length, updateBook]);

  const availableYears = useMemo(() => {
    const years = new Set<number>();
    years.add(new Date().getFullYear());
    books.forEach(book => {
      if (book.dateFinished) years.add(new Date(book.dateFinished).getFullYear());
      else if (book.dateAdded) years.add(new Date(book.dateAdded).getFullYear());
    });
    return Array.from(years).sort((a, b) => b - a);
  }, [books]);

  const filteredBooks = useMemo(() => {
    return books.filter(book => {
      if (book.status !== BookStatus.Read) return true;
      if (!book.dateFinished) return true;

      const finishDate = new Date(book.dateFinished);
      if (dateFilter === 'thisYear') {
        return finishDate.getFullYear() === new Date().getFullYear();
      }
      if (dateFilter === 'specificYear') {
        return finishDate.getFullYear() === selectedYear;
      }
      if (dateFilter === 'custom') {
        const start = new Date(customRange.start);
        const end = new Date(customRange.end);
        return finishDate >= start && finishDate <= end;
      }
      return true;
    });
  }, [books, dateFilter, selectedYear, customRange]);

  const stats: ReadingStats = useMemo(() => {
    // Inicialização - Usa o sumário rápido se os livros ainda não carregaram
    let tbrCount = quickSummary?.tbrCount || 0;
    let wishlistCount = quickSummary?.wishlistCount || 0;

    // Se temos os livros carregados localmente, recalculamos para maior precisão
    if (books.length > 0) {
      tbrCount = 0;
      wishlistCount = 0;
      books.forEach(book => {
        if (book.status === BookStatus.TBR) tbrCount++;
        if (book.status === BookStatus.Wishlist) wishlistCount++;
      });
    }

    const yearly = { booksRead: 0, pagesRead: 0, totalRating: 0, ratingCount: 0 };
    const monthlyDataMap = MONTHS.map(month => ({ month, booksRead: 0, pagesRead: 0, totalRating: 0, ratingCount: 0 }));
    const byTypeMap: Record<string, { type: BookType, count: number, pages: number, totalRating: 0, ratingCount: 0 }> = {
      [BookType.Book]: { type: BookType.Book, count: 0, pages: 0, totalRating: 0, ratingCount: 0 },
      [BookType.HQ]: { type: BookType.HQ, count: 0, pages: 0, totalRating: 0, ratingCount: 0 }
    };

    filteredBooks.forEach(book => {
      if (book.status === BookStatus.Read) {
        yearly.booksRead++;
        yearly.pagesRead += (book.pages || 0);
        if (book.rating) {
          yearly.totalRating += book.rating;
          yearly.ratingCount++;
        }

        if (book.dateFinished) {
          const monthIndex = new Date(book.dateFinished).getMonth();
          const mData = monthlyDataMap[monthIndex];
          if (mData) {
            mData.booksRead++;
            mData.pagesRead += (book.pages || 0);
            if (book.rating) {
              mData.totalRating += book.rating;
              mData.ratingCount++;
            }
          }
        }

        const tData = byTypeMap[book.type];
        if (tData) {
          tData.count++;
          tData.pages += (book.pages || 0);
          if (book.rating) {
            tData.totalRating += book.rating;
            tData.ratingCount++;
          }
        }
      }
    });

    return {
      tbrCount,
      wishlistCount,
      yearly: {
        booksRead: books.length === 0 && quickSummary ? quickSummary.readCount : yearly.booksRead,
        pagesRead: yearly.pagesRead,
        avgRating: yearly.ratingCount > 0 ? yearly.totalRating / yearly.ratingCount : 0
      },
      monthly: monthlyDataMap.map(m => ({
        month: m.month,
        booksRead: m.booksRead,
        pagesRead: m.pagesRead,
        avgRating: m.ratingCount > 0 ? m.totalRating / m.ratingCount : 0
      })),
      byType: Object.values(byTypeMap).map(t => ({
        type: t.type,
        count: t.count,
        pages: t.pages,
        avgRating: t.ratingCount > 0 ? t.totalRating / t.ratingCount : 0
      }))
    };
  }, [books, filteredBooks, quickSummary]);

  const currentlyReading = useMemo(() => {
    return books.find(b => b.status === BookStatus.Reading) || null;
  }, [books]);

  return {
    books,
    stats,
    currentlyReading,
    addBook,
    updateBook,
    deleteBook,
    dateFilter,
    setDateFilter,
    selectedYear,
    setSelectedYear,
    availableYears,
    customRange,
    setCustomRange,
    isLocalMode,
    schemaError,
    isLoading
  };
};

import React from 'react';
import { 
  ComposedChart, 
  Bar, 
  XAxis, 
  YAxis, 
  CartesianGrid, 
  Tooltip, 
  Legend, 
  ResponsiveContainer,
  Area,
  ResponsiveContainer as ReContainer
} from 'recharts';
