                    <div className="w-2.5 h-2.5 rounded-full bg-indigo-400 dark:bg-indigo-600"></div>
                    <span className="text-[10px] font-bold text-slate-500 dark:text-slate-400 uppercase tracking-widest">Páginas</span>
