import React from 'react';
import { 
  ComposedChart, 
  Bar, 
  XAxis, 
  YAxis, 
  CartesianGrid, 
  Tooltip, 
  Legend, 
  ResponsiveContainer,
  Area,
} from 'recharts';
import type { MonthlyStat } from '../types';

interface MonthlyChartProps {
