            tickLine={false} 
            tick={{ fill: '#94a3b8', fontSize: 10, fontWeight: 800, textTransform: 'uppercase' }}
            dy={15}
          />

          <YAxis 
            yAxisId="left" 
            orientation="left" 
            axisLine={false} 
            tickLine={false}
            tick={{ fill: '#94a3b8', fontSize: 10, fontWeight: 700 }}
          />

          <YAxis yAxisId="right" orientation="right" hide={true} />

          <Tooltip 
            content={<CustomTooltip />} 
