          <Area
            yAxisId="right"
            type="monotone"
            dataKey="Páginas"
            fill="url(#colorPaginas)"
            stroke="#6366f1"
            strokeWidth={3}
            strokeOpacity={0.8}
            dot={{ r: 0 }}
