import { GoogleGenAI, GenerateContentResponse, Type } from "@google/genai";
import { Recommendation } from "../types";

const stringifyError = (err: any): string => {
  if (!err) return "Erro desconhecido";
  if (typeof err === 'string') return err;
  if (err.message) return err.message;
  try {
    return JSON.stringify(err);
  } catch {
    return String(err);
  }
};

/**
 * Executes a Gemini task using the environment's API key.
 * If a 403 Permission Denied error occurs (common with Pro models or restricted keys),
 * it triggers the AI Studio key selection dialog.
 */
const callGenAI = async (task: (ai: GoogleGenAI) => Promise<any>, modelName?: string) => {
  const isProImageModel = modelName === 'gemini-3-pro-image-preview';

  // For Pro Image models, ensure a key has been selected via the platform dialog
  if (isProImageModel && window.aistudio) {
    const hasKey = await window.aistudio.hasSelectedApiKey();
    if (!hasKey) {
      console.warn("Pro Image model requires manual key selection. Opening dialog...");
      await window.aistudio.openSelectKey();
    }
  }

  // Exclusively use process.env.API_KEY as per guidelines
  const apiKey = process.env.API_KEY;

  if (!apiKey || apiKey === 'undefined' || apiKey === '') {
    if (window.aistudio) {
      await window.aistudio.openSelectKey();
    }
    throw new Error("API_KEY_MISSING");
  }

  try {
    // Always create a new instance to ensure the most up-to-date key is used
    const ai = new GoogleGenAI({ apiKey });
    return await task(ai);
  } catch (error: any) {
    const errorMsg = stringifyError(error);
    console.error(`Gemini API Error [${modelName || 'unknown'}]:`, errorMsg);

    // Handle 403 PERMISSION_DENIED (and 404 for deleted keys/projects)
    if (
      errorMsg.includes("PERMISSION_DENIED") ||
      errorMsg.includes("403") ||
      errorMsg.includes("Requested entity was not found") ||
      errorMsg.includes("404")
    ) {
      if (window.aistudio) {
        console.warn("Permission denied for Gemini model. Prompting for a paid/valid API key...");
        await window.aistudio.openSelectKey();
      }
    }
    throw error;
  }
};

export const generateBookSummary = async (title: string, author: string): Promise<string> => {
  const model = 'gemini-3-flash-preview';
