import type { Book, Profile } from '../types';
import { supabase } from './supabase';

const TABLE_NAME = 'books';
const BASE_LOCAL_STORAGE_KEY = 'biblio_tech_cache_';

const mapBookToDb = (book: any) => {
    const dateAddedValue = book.dateAdded || new Date().toISOString().split('T')[0];
    return {
        id: book.id,
        user_id: book.user_id,
        title: book.title || 'Sem Título',
        author: book.author || 'Autor Desconhecido',
        pages: parseInt(String(book.pages || 0), 10),
        genre: book.genre || '',
        type: book.type || 'Livro',
        status: book.status || 'Não lido',
        rating: (book.rating !== undefined && book.rating !== null && book.rating !== 0) ? parseFloat(String(book.rating)) : null,
        cover_image_url: book.coverImageUrl || null,
        summary: book.summary || null,
        notes: book.notes || null,
        estimated_price: (book.estimatedPrice !== undefined && book.estimatedPrice !== null) ? parseFloat(String(book.estimatedPrice)) : null,
        buy_link: book.buyLink || null,
        current_page: parseInt(String(book.currentPage || 0), 10),
        date_added: dateAddedValue,
        date_started: book.dateStarted || null,
        date_finished: book.dateFinished || null,
        days_to_finish: (book.daysToFinish !== undefined && book.daysToFinish !== null) ? parseInt(String(book.daysToFinish), 10) : null,
        times_read: (book.timesRead !== undefined && book.timesRead !== null) ? parseInt(String(book.timesRead), 10) : 0,
        was_wishlist: book.wasWishlist || false
    };
};

const mapDbToBook = (db: any): Book => ({
    id: db.id,
    user_id: db.user_id,
    title: db.title,
    author: db.author,
    pages: db.pages || 0,
    genre: db.genre || '',
    type: db.type,
    status: db.status,
    rating: db.rating ? parseFloat(String(db.rating)) : undefined,
    coverImageUrl: db.cover_image_url,
    summary: db.summary,
    notes: db.notes,
    estimatedPrice: db.estimated_price ? parseFloat(String(db.estimated_price)) : undefined,
    buyLink: db.buy_link,
    currentPage: db.current_page || 0,
    dateAdded: db.date_added,
    dateStarted: db.date_started,
    dateFinished: db.date_finished,
    daysToFinish: db.days_to_finish,
    timesRead: db.times_read || 0,
    wasWishlist: db.was_wishlist || false
});

const mapDbToProfile = (db: any): Profile => ({
    id: db.id,
    fullName: db.full_name,
    avatarUrl: db.avatar_url,
    readingGoal: db.reading_goal || 12
});

export class DatabaseService {
  private isSchemaBroken = false;
  private brokenDetail = '';
  private onSchemaErrorCallback?: (type: 'table' | 'column' | 'permission', detail?: string) => void;

  setSchemaErrorCallback(cb: (type: 'table' | 'column' | 'permission', detail?: string) => void) {
    this.onSchemaErrorCallback = cb;
  }

  private async getCacheKey(): Promise<string | null> {
    const { data: { user } } = await supabase.auth.getUser();
    return user ? `${BASE_LOCAL_STORAGE_KEY}${user.id}` : null;
  }

  private async getLocalBooks(): Promise<Book[]> {
    const key = await this.getCacheKey();
    if (!key) return [];
    try {
      const data = localStorage.getItem(key);
      return data ? JSON.parse(data) : [];
    } catch (e) {
      return [];
    }
  }

  private async saveLocalBooks(books: Book[]): Promise<void> {
    const key = await this.getCacheKey();
    if (!key) return;
    try {
      localStorage.setItem(key, JSON.stringify(books));
    } catch (e: any) {
      console.warn("Local Storage falhou, dados mantidos apenas em memória.");
    }
  }

  async getAllBooks(): Promise<Book[]> {
    try {
      const { data, error } = await supabase
        .from(TABLE_NAME)
        .select('*')
        .order('date_added', { ascending: false });

      if (error) {
        console.error(`Erro ao buscar livros no Supabase [${error.code}]: ${error.message}`);
        this.handleSupabaseError(error);
        return await this.getLocalBooks();
      }

      this.isSchemaBroken = false;
      const books = (data || []).map(mapDbToBook);
      await this.saveLocalBooks(books);
      return books;
    } catch (err: any) {
      console.error("Erro inesperado em getAllBooks:", err.message || err);
      return await this.getLocalBooks();
    }
  }

  async getQuickStatsSummary() {
    if (this.isSchemaBroken) return null;

    try {
      const { data: { user } } = await supabase.auth.getUser();
      if (!user) return null;

      const [read, tbr, wishlist] = await Promise.all([
        supabase.from(TABLE_NAME).select('*', { count: 'exact', head: true }).eq('status', 'Lido').eq('user_id', user.id),
        supabase.from(TABLE_NAME).select('*', { count: 'exact', head: true }).eq('status', 'Não lido').eq('user_id', user.id),
        supabase.from(TABLE_NAME).select('*', { count: 'exact', head: true }).eq('status', 'Lista de Desejos').eq('user_id', user.id)
      ]);

      return {
        readCount: read.count || 0,
        tbrCount: tbr.count || 0,
        wishlistCount: wishlist.count || 0
      };
    } catch (err) {
      return null;
    }
  }

  async saveBook(book: Partial<Book>): Promise<void> {
    const { data: { user } } = await supabase.auth.getUser();
    if (!user) {
        throw new Error("Usuário não identificado. Faça login novamente.");
    }

    const dbPayload = mapBookToDb(book);
    dbPayload.user_id = user.id;

    // Sincroniza Localmente Primeiro
    const books = await this.getLocalBooks();
    const index = books.findIndex(b => b.id === (book.id || dbPayload.id));
    const updatedBookState = mapDbToBook(dbPayload);

    if (index >= 0) books[index] = updatedBookState;
    else books.unshift(updatedBookState);
    await this.saveLocalBooks(books);

    if (this.isSchemaBroken) {
        throw new Error(`O banco de dados está desatualizado: ${this.brokenDetail}. Por favor, execute o script SQL.`);
    }

    // Persiste no Supabase
    const { error } = await supabase.from(TABLE_NAME).upsert(dbPayload);
    if (error) {
        console.error(`Supabase Upsert Error [${error.code}]: ${error.message}`);
        this.handleSupabaseError(error);
        throw new Error(`Erro ao salvar na nuvem: ${error.message}`);
    }
  }

  async deleteBook(id: string): Promise<void> {
    const books = (await this.getLocalBooks()).filter(b => b.id !== id);
    await this.saveLocalBooks(books);

    if (this.isSchemaBroken) return;
    const { error } = await supabase.from(TABLE_NAME).delete().eq('id', id);
    if (error) {
        console.error(`Erro ao deletar livro no Supabase [${error.code}]: ${error.message}`);
    }
  }

  async updateReadingGoal(goal: number): Promise<void> {
    const { data: { user } } = await supabase.auth.getUser();
    if (!user) throw new Error("Usuário não identificado.");
    const { error } = await supabase.from('profiles').upsert({ 
        id: user.id, 
        reading_goal: goal, 
        updated_at: new Date().toISOString() 
    });
    if (error) {
        console.error("Erro ao salvar meta:", error.message);
        throw error;
    }
  }

  async updateProfile(profile: Partial<Profile>): Promise<void> {
    const { data: { user } } = await supabase.auth.getUser();
    if (!user) throw new Error("Usuário não identificado.");
    const dbPayload: any = { id: user.id, updated_at: new Date().toISOString() };
    if (profile.fullName !== undefined) dbPayload.full_name = profile.fullName;
    if (profile.avatarUrl !== undefined) dbPayload.avatar_url = profile.avatarUrl;

    const { error } = await supabase.from('profiles').upsert(dbPayload);
    if (error) {
        console.error("Erro ao atualizar perfil:", error.message);
        throw error;
    }
  }

  async getProfile(): Promise<Profile | null> {
    const { data: { user } } = await supabase.auth.getUser();
    if (!user) return null;
    try {
        const { data, error } = await supabase.from('profiles').select('*').eq('id', user.id).single();
        if (error || !data) return { id: user.id, fullName: 'Leitor', readingGoal: 12 };
        return mapDbToProfile(data);
    } catch (err) {
        return { id: user.id, fullName: 'Leitor', readingGoal: 12 };
    }
  }

  private handleSupabaseError(error: any) {
    if (error.code === '42P01' || error.code === 'PGRST204' || error.code === 'PGRST107') {
        this.isSchemaBroken = true;
        this.brokenDetail = error.message;
        const msg = error.code === 'PGRST204' 
            ? 'Colunas faltando (was_wishlist/times_read/current_page). Execute o script de migração.' 
            : 'Tabela ou Schema desatualizado. Verifique o SQL Editor.';
        if (this.onSchemaErrorCallback) this.onSchemaErrorCallback('table', msg);
    }
  }
}

export const dbService = new DatabaseService();

import React, { useState, useEffect, useMemo } from 'react';
import type { Book } from '../types';
import { BookStatus } from '../types';
import { StarIcon, StarIconFilled } from './Icons';

interface CurrentlyReadingProps {
  book: Book;
  updateBook: (book: Book) => Promise<void>;
}

const StarRatingDisplay: React.FC<{ rating: number }> = ({ rating }) => {
  return (
    <div className="flex items-center gap-0.5">
      {[...Array(10)].map((_, index) => {
        const starIndex = index + 1;
        const diff = rating - index;
        const isFull = diff >= 1;
        const isPartial = diff > 0 && diff < 1;
        const fillPercentage = isPartial ? diff * 100 : (isFull ? 100 : 0);

        return (
          <div key={index} className="relative h-6 w-6">
            <StarIcon className="absolute inset-0 h-6 w-6 text-slate-200 dark:text-slate-700" />
            <div 
              className="absolute inset-0 overflow-hidden" 
              style={{ width: `${fillPercentage}%` }}
            >
              <StarIconFilled className="h-6 w-6 text-amber-400" />
            </div>
          </div>
        );
      })}
    </div>
  );
};

const calculateDaysReading = (startDate?: string) => {
    if (!startDate) return 0;
    const start = new Date(startDate);
    const today = new Date();
    today.setHours(0,0,0,0);
    start.setHours(0,0,0,0);
    const diffTime = today.getTime() - start.getTime();
    const diffDays = Math.ceil(diffTime / (1000 * 60 * 60 * 24));
    return diffDays >= 0 ? diffDays : 0;
}

export const CurrentlyReading: React.FC<CurrentlyReadingProps> = ({ book, updateBook }) => {
    const [currentPage, setCurrentPage] = useState(book.currentPage || 0);
    const [dateStarted, setDateStarted] = useState(book.dateStarted || new Date().toISOString().split('T')[0]);
    const [isFinishing, setIsFinishing] = useState(false);
    const [selectedRating, setSelectedRating] = useState<number>(book.rating || 0);
    const [isSaving, setIsSaving] = useState(false);

    const daysReading = useMemo(() => calculateDaysReading(dateStarted), [dateStarted]);
    const progressPercentage = book.pages > 0 ? (currentPage / book.pages) * 100 : 0;
    const pagesRemaining = book.pages - currentPage;

    const pagesPerDay = useMemo(() => {
        const days = daysReading || 1;
        return Math.round((currentPage / days) * 10) / 10;
    }, [currentPage, daysReading]);

    const estDaysToFinish = useMemo(() => {
        if (pagesPerDay <= 0) return null;
        return Math.ceil(pagesRemaining / pagesPerDay);
    }, [pagesRemaining, pagesPerDay]);

    useEffect(() => {
        setCurrentPage(book.currentPage || 0);
        setDateStarted(book.dateStarted || new Date().toISOString().split('T')[0]);
        setIsFinishing(false);
        setSelectedRating(0);
        setIsSaving(false);
    }, [book.id]);

    const handleProgressChange = (e: React.ChangeEvent<HTMLInputElement>) => {
        const value = parseInt(e.target.value, 10);
        if (!isNaN(value) && value >= 0 && value <= book.pages) {
            setCurrentPage(value);
        } else if (e.target.value === '') {
            setCurrentPage(0);
        }
    };

    const handleUpdateClick = async () => {
        setIsSaving(true);
        try {
            await updateBook({ ...book, currentPage, dateStarted });
        } finally {
            setIsSaving(false);
        }
    };

    const handleConfirmFinish = async () => {
        setIsSaving(true);
        try {
            const updatedBook: Book = { 
                ...book, 
                currentPage: book.pages, 
                status: BookStatus.Read,
                rating: selectedRating,
                dateFinished: new Date().toISOString().split('T')[0],
                daysToFinish: daysReading,
                timesRead: (book.timesRead || 0) + 1
            };
            await updateBook(updatedBook);
        } finally {
            setIsSaving(false);
        }
    };

    const genresList = book.genre ? book.genre.split(',').map(g => g.trim()).filter(g => g !== '') : [];
    const authorsList = book.author ? book.author.split(',').map(a => a.trim()).filter(a => a !== '') : [];

  return (
    <div className="bg-white dark:bg-slate-900 p-8 rounded-[2.5rem] shadow-soft border border-slate-100 dark:border-slate-800 h-full flex flex-col relative overflow-hidden group animate-in zoom-in-95 duration-500">
      <div className="absolute -top-24 -right-24 w-64 h-64 bg-primary/5 dark:bg-primary/10 rounded-full blur-3xl pointer-events-none"></div>

      <div className="flex justify-between items-center mb-8 relative z-10">
        <div className="flex gap-2">
            <span className="bg-primary text-white text-[10px] font-black uppercase tracking-[0.15em] px-4 py-1.5 rounded-full shadow-lg shadow-primary/20">
              Lendo agora
            </span>
            {daysReading > 0 && (
              <span className="bg-slate-100 dark:bg-slate-800 text-slate-500 dark:text-slate-400 text-[10px] font-bold uppercase tracking-widest px-4 py-1.5 rounded-full border border-slate-200 dark:border-slate-700">
                 Jornada de {daysReading} {daysReading === 1 ? 'dia' : 'dias'}
              </span>
            )}
        </div>
      </div>

      <div className="flex flex-col lg:flex-row gap-10 items-center lg:items-start relative z-10">
        <div className="relative group/cover flex-shrink-0">
            <img
              src={book.coverImageUrl}
              alt={book.title}
              className="w-48 h-72 object-cover rounded-2xl shadow-xl transition-all duration-700 group-hover/cover:scale-[1.02] relative z-10"
            />
        </div>

        <div className="flex-1 w-full text-center lg:text-left">
          {!isFinishing ? (
            <>
              <div className="mb-6">
                <h3 className="text-3xl font-black text-slate-900 dark:text-slate-50 mb-2 leading-tight font-serif italic">{book.title}</h3>
                <div className="flex flex-wrap justify-center lg:justify-start items-center gap-2">
                  {authorsList.map((author, idx) => (
                    <React.Fragment key={author}>
                      <p className="text-xl text-slate-400 dark:text-slate-500 font-medium">{author}</p>
                      {idx < authorsList.length - 1 && (
                        <span className="text-slate-300 dark:text-slate-700 text-lg">•</span>
                      )}
                    </React.Fragment>
                  ))}
                </div>
              </div>

              <div className="flex flex-wrap justify-center lg:justify-start gap-2 mb-8">
                  {genresList.map(g => (
                    <span key={g} className="bg-slate-50 dark:bg-slate-800 text-slate-500 dark:text-slate-400 px-4 py-1.5 rounded-xl border border-slate-100 dark:border-slate-700 text-[10px] font-black uppercase tracking-widest">
                        {g}
                    </span>
                  ))}
                  <span className="bg-blue-50 dark:bg-blue-900/20 text-primary px-4 py-1.5 rounded-xl border border-blue-100 dark:border-blue-800/50 text-[10px] font-black uppercase tracking-widest">
                    {book.pages} páginas totais
                  </span>
              </div>

              <div className="mb-10">
                <div className="flex justify-between items-end mb-3">
                    <div className="flex items-baseline gap-2">
                        <span className="text-4xl font-black text-slate-900 dark:text-slate-50 tracking-tighter">{progressPercentage.toFixed(0)}%</span>
                        <span className="text-xs font-bold text-slate-400 dark:text-slate-500 uppercase tracking-widest">Completo</span>
                    </div>
                </div>

                <div className="w-full bg-slate-100 dark:bg-slate-800 rounded-2xl h-4 mb-4 overflow-hidden p-1 border border-slate-200/50 dark:border-slate-700">
                  <div 
                      className="bg-gradient-to-r from-primary to-blue-400 h-full rounded-xl transition-all duration-1000 ease-out" 
                      style={{ width: `${progressPercentage}%` }}
                  ></div>
                </div>

                <div className="grid grid-cols-2 sm:grid-cols-3 gap-4">
                    <div className="bg-slate-50/80 dark:bg-slate-800/80 p-3 rounded-2xl border border-slate-100 dark:border-slate-700">
                        <p className="text-[9px] font-black text-slate-400 dark:text-slate-500 uppercase tracking-widest mb-1">Ritmo Médio</p>
                        <p className="text-sm font-bold text-slate-700 dark:text-slate-300">{pagesPerDay} <span className="text-[10px] text-slate-400 dark:text-slate-500">pág/dia</span></p>
                    </div>
                    <div className="bg-slate-50/80 dark:bg-slate-800/80 p-3 rounded-2xl border border-slate-100 dark:border-slate-700">
                        <p className="text-[9px] font-black text-slate-400 dark:text-slate-500 uppercase tracking-widest mb-1">Previsão</p>
                        <p className="text-sm font-bold text-slate-700 dark:text-slate-300">{estDaysToFinish ? `+${estDaysToFinish} dias` : '--'}</p>
                    </div>
                    <div className="hidden sm:block bg-slate-50/80 dark:bg-slate-800/80 p-3 rounded-2xl border border-slate-100 dark:border-slate-700">
                        <p className="text-[9px] font-black text-slate-400 dark:text-slate-500 uppercase tracking-widest mb-1">Página Atual</p>
                        <p className="text-sm font-bold text-slate-700 dark:text-slate-300">{currentPage} <span className="text-[10px] text-slate-400 dark:text-slate-500">de {book.pages}</span></p>
                    </div>
                </div>
              </div>

              <div className="flex flex-col sm:flex-row gap-4">
                <div className="flex flex-1 gap-2">
                    <input 
                        type="number"
                        value={currentPage}
                        disabled={isSaving}
                        onChange={handleProgressChange}
                        className="w-24 bg-white dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-2xl px-4 py-3 text-slate-900 dark:text-slate-100 font-black focus:border-primary transition-all outline-none text-center disabled:opacity-50"
                        aria-label="Página atual"
                    />
                    <button
                        onClick={handleUpdateClick}
                        disabled={isSaving}
                        className="flex-1 px-4 py-3 text-[10px] font-black rounded-2xl bg-slate-900 dark:bg-slate-100 text-white dark:text-slate-900 hover:bg-primary dark:hover:bg-primary dark:hover:text-white shadow-xl transition-all active:scale-95 uppercase tracking-widest disabled:opacity-50 flex items-center justify-center gap-2"
                    >
                        {isSaving ? (
                            <svg className="animate-spin h-4 w-4 text-current" xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24"><circle className="opacity-25" cx="12" cy="12" r="10" stroke="currentColor" strokeWidth="4"></circle><path className="opacity-75" fill="currentColor" d="M4 12a8 8 0 018-8V0C5.373 0 0 5.373 0 12h4zm2 5.291A7.962 7.962 0 014 12H0c0 3.042 1.135 5.824 3 7.938l3-2.647z"></path></svg>
                        ) : 'Salvar Progresso'}
                    </button>
                </div>
                <button
                    onClick={() => setIsFinishing(true)}
                    disabled={isSaving}
                    className="px-8 py-3 text-[10px] font-black rounded-2xl bg-emerald-500 text-white hover:bg-emerald-600 shadow-xl shadow-emerald-200 dark:shadow-emerald-900/20 transition-all active:scale-95 uppercase tracking-widest disabled:opacity-50"
                >
                    Concluir Leitura
                </button>
              </div>
            </>
          ) : (
            <div className="animate-in slide-in-from-right-8 duration-500">
                <h3 className="text-2xl font-black text-slate-900 dark:text-slate-50 mb-2 leading-tight font-serif italic">Parabéns pela conclusão!</h3>
                <p className="text-slate-500 dark:text-slate-400 mb-6 font-medium italic">Como você avalia sua experiência com "{book.title}"?</p>

                <div className="bg-slate-50 dark:bg-slate-800/50 p-6 rounded-[2rem] border border-slate-100 dark:border-slate-700 mb-8">
                    <div className="flex items-center justify-between mb-4">
                        <span className="text-[10px] font-black text-slate-400 uppercase tracking-widest">Sua Nota:</span>
                        <div className="flex items-center gap-2">
                             <input 
                                type="number" 
                                step="0.1" 
                                min="0" 
                                max="10" 
                                value={selectedRating} 
                                disabled={isSaving}
                                onChange={(e) => setSelectedRating(parseFloat(e.target.value) || 0)}
                                className="w-16 bg-white dark:bg-slate-900 border border-slate-200 dark:border-slate-700 rounded-lg px-2 py-1 text-center font-black text-amber-500 disabled:opacity-50"
                            />
                            <StarIconFilled className="h-5 w-5 text-amber-500" />
                        </div>
                    </div>

                    <input 
                        type="range" 
                        min="0" 
                        max="10" 
                        step="0.1" 
                        value={selectedRating} 
                        disabled={isSaving}
                        onChange={(e) => setSelectedRating(parseFloat(e.target.value))}
                        className="w-full h-2 bg-slate-200 dark:bg-slate-700 rounded-lg appearance-none cursor-pointer accent-amber-500 mb-6 disabled:opacity-50"
                    />

                    <div className="flex justify-center">
                        <StarRatingDisplay rating={selectedRating} />
                    </div>
                </div>

                <div className="flex gap-4">
                    <button
                        onClick={handleConfirmFinish}
                        disabled={selectedRating === 0 || isSaving}
                        className="flex-1 px-8 py-4 text-[11px] font-black rounded-2xl bg-emerald-500 text-white hover:bg-emerald-600 shadow-xl shadow-emerald-200 dark:shadow-emerald-900/20 transition-all active:scale-95 uppercase tracking-widest disabled:opacity-50 disabled:grayscale flex items-center justify-center gap-3"
                    >
                        {isSaving && (
                            <svg className="animate-spin h-4 w-4 text-white" xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24"><circle className="opacity-25" cx="12" cy="12" r="10" stroke="currentColor" strokeWidth="4"></circle><path className="opacity-75" fill="currentColor" d="M4 12a8 8 0 018-8V0C5.373 0 0 5.373 0 12h4zm2 5.291A7.962 7.962 0 014 12H0c0 3.042 1.135 5.824 3 7.938l3-2.647z"></path></svg>
                        )}
                        {isSaving ? 'Finalizando...' : 'Confirmar e Finalizar'}
                    </button>
                    <button
                        onClick={() => setIsFinishing(false)}
                        disabled={isSaving}
                        className="px-8 py-4 text-[11px] font-black rounded-2xl bg-slate-100 dark:bg-slate-800 text-slate-500 dark:text-slate-400 hover:bg-slate-200 transition-all uppercase tracking-widest disabled:opacity-50"
                    >
                        Voltar
                    </button>
                </div>
            </div>
          )}
        </div>
      </div>
    </div>
  );
};

import React, { useState, useMemo, useEffect } from 'react';
import { useBookData } from './hooks/useBookData';
import { Header } from './components/Header';
import { Dashboard } from './components/Dashboard';
import { AddBookModal } from './components/AddBookModal';
import { SettingsModal } from './components/SettingsModal';
import { PlusIcon, XMarkIcon } from './components/Icons';
import type { Book, NewBook, Profile } from './types';
import { BookList } from './components/BookList';
import { ConfirmationModal } from './components/ConfirmationModal';
import { BookStatus } from './types';
import { Wishlist } from './components/Wishlist';
import { BottomNav } from './components/BottomNav';
import { Auth } from './components/Auth';
import { StatsView } from './components/StatsView';
import { supabase } from './services/supabase';
import { dbService } from './services/database';

export default function App() {
  const [session, setSession] = useState<any>(null);
  const [isAuthLoading, setIsAuthLoading] = useState(true);
  const [userProfile, setUserProfile] = useState<Profile | null>(null);
  const [hasApiKey, setHasApiKey] = useState<boolean>(true);

  useEffect(() => {
    supabase.auth.getSession().then(({ data: { session } }) => {
      setSession(session);
      setIsAuthLoading(false);
    });
    const { data: { subscription } } = supabase.auth.onAuthStateChange((_event, session) => {
      setSession(session);
    });
    return () => subscription.unsubscribe();
  }, []);

  useEffect(() => {
    if (session) {
      dbService.getProfile().then(profile => {
        if (profile) {
          setUserProfile(profile);
          if (profile.readingGoal) setReadingGoal(profile.readingGoal);
          checkPlatformApiKey();
        }
      });
    }
  }, [session]);

  const checkPlatformApiKey = async () => {
    if (window.aistudio) {
        const selected = await window.aistudio.hasSelectedApiKey();
        setHasApiKey(selected);
    } else {
        const envKey = process.env.API_KEY;
        setHasApiKey(!!(envKey && envKey !== 'undefined' && envKey !== ''));
    }
  };

  const { 
    books, stats, currentlyReading, addBook, updateBook, deleteBook, 
    dateFilter, setDateFilter, selectedYear, setSelectedYear, availableYears,
    customRange, setCustomRange, isLocalMode, schemaError, isLoading
  } = useBookData();

  const [theme, setTheme] = useState<'light' | 'dark'>(() => (localStorage.getItem('theme') as 'light' | 'dark') || 'light');
  const [readingGoal, setReadingGoal] = useState(() => parseInt(localStorage.getItem('biblio_tech_goal') || '12', 10));

  const handleSetReadingGoal = async (val: number) => {
    try {
        setReadingGoal(val);
        localStorage.setItem('biblio_tech_goal', val.toString());
        await dbService.updateReadingGoal(val);
        showToast("Meta de leitura atualizada.");
    } catch (err: any) {
        showToast(`Erro ao salvar meta: ${err.message}`);
    }
  };

  const handleUpdateProfile = async (updates: Partial<Profile>) => {
    if (userProfile) {
        try {
            const newProfile = { ...userProfile, ...updates };
            setUserProfile(newProfile);
            await dbService.updateProfile(updates);
            checkPlatformApiKey();
            showToast("Perfil atualizado.");
        } catch (err: any) {
            showToast(`Erro ao atualizar perfil: ${err.message}`);
        }
    }
  };

  const [isModalOpen, setIsModalOpen] = useState(false);
  const [isSettingsOpen, setIsSettingsOpen] = useState(false);
  const [view, setView] = useState<'dashboard' | 'list' | 'wishlist' | 'stats'>('dashboard');
  const [editingBook, setEditingBook] = useState<Book | null>(null);
  const [deletingBook, setDeletingBook] = useState<Book | null>(null);
  const [defaultStatusForModal, setDefaultStatusForModal] = useState<BookStatus | undefined>();
  const [toastMessage, setToastMessage] = useState<string | null>(null);

  useEffect(() => {
    theme === 'dark' ? document.documentElement.classList.add('dark') : document.documentElement.classList.remove('dark');
    localStorage.setItem('theme', theme);
  }, [theme]);

  const showToast = (message: string) => {
    setToastMessage(message);
    setTimeout(() => setToastMessage(null), 3500);
  };

  const handleAddBook = async (newBook: NewBook) => {
    try {
        await addBook(newBook);
        setIsModalOpen(false);
        showToast(`"${newBook.title}" salvo!`);
    } catch (err: any) {
        showToast(`Erro ao salvar: ${err.message}`);
    }
  };

  const handleUpdateBook = async (updatedBook: Book) => {
    try {
        await updateBook(updatedBook);
        setIsModalOpen(false);
        showToast(`"${updatedBook.title}" atualizado.`);
    } catch (err: any) {
        showToast(`Erro ao atualizar: ${err.message}`);
    }
  };

  const openAddModal = (status?: BookStatus) => {
    setEditingBook(null);
    setDefaultStatusForModal(status);
    setIsModalOpen(true);
  };

  if (isAuthLoading) return <div className="min-h-screen bg-background flex items-center justify-center"><div className="w-10 h-10 border-4 border-primary border-t-transparent rounded-full animate-spin"></div></div>;
  if (!session) return <Auth />;
  if (isLoading) return <div className="min-h-screen bg-background flex flex-col items-center justify-center p-4"><div className="w-12 h-12 border-4 border-primary border-t-transparent rounded-full animate-spin mb-4"></div><p className="text-[10px] font-black uppercase tracking-widest text-slate-400">Sincronizando...</p></div>;

  return (
    <div className="min-h-screen bg-background dark:bg-slate-950 text-text-main dark:text-slate-200 pb-24 relative transition-colors duration-300">
      <Header 
        profile={userProfile} onLogoClick={() => setView('dashboard')} onSettingsClick={() => setIsSettingsOpen(true)}
        theme={theme} toggleTheme={() => setTheme(t => t === 'light' ? 'dark' : 'light')} 
        isConnected={!isLocalMode} hasApiKey={hasApiKey}
      />

      {/* Alerta de Erro de Banco de Dados */}
      {schemaError && (
        <div className="bg-red-600 text-white px-6 py-3 text-center text-[10px] font-black uppercase tracking-widest flex items-center justify-center gap-4 animate-in slide-in-from-top duration-500">
          <div className="flex-1">
             ⚠️ Erro de Sincronização: {schemaError.detail || "O banco de dados está desatualizado."} 
             <span className="block mt-1 font-bold opacity-80">Rode o script SQL do arquivo instrucoes_sql.txt no painel do Supabase!</span>
          </div>
        </div>
      )}

      {!hasApiKey && !schemaError && (
        <div className="bg-red-500 text-white px-6 py-2 text-center text-[10px] font-black uppercase tracking-widest animate-pulse cursor-pointer" onClick={() => setIsSettingsOpen(true)}>
          IA Indisponível: Clique aqui para configurar sua Chave de API nas Preferências.
        </div>
      )}

      <main className="p-4 md:p-8">
        {view === 'dashboard' && <Dashboard stats={stats} currentlyReading={currentlyReading} updateBook={handleUpdateBook} dateFilter={dateFilter} setDateFilter={setDateFilter} selectedYear={selectedYear} setSelectedYear={setSelectedYear} availableYears={availableYears} books={books} customRange={customRange} setCustomRange={setCustomRange} readingGoal={readingGoal} onSetReadingGoal={handleSetReadingGoal} />}
        {view === 'list' && <BookList books={books.filter(b => b.status !== BookStatus.Wishlist)} onEdit={(b) => { setEditingBook(b); setIsModalOpen(true); }} onDelete={setDeletingBook} onUpdateBook={handleUpdateBook} />}
        {view === 'wishlist' && <Wishlist books={books.filter(b => b.status === BookStatus.Wishlist)} onEdit={(b) => { setEditingBook(b); setIsModalOpen(true); }} onDelete={setDeletingBook} onMoveToShelf={(b) => handleUpdateBook({ ...b, status: BookStatus.TBR, wasWishlist: true })} onAddWishlistItem={() => openAddModal(BookStatus.Wishlist)} />}
        {view === 'stats' && <StatsView books={books} availableYears={availableYears} />}
      </main>

      <div className="fixed bottom-24 right-6 flex flex-col gap-3">
        <button onClick={() => openAddModal()} className="bg-primary text-background p-4 rounded-full shadow-2xl hover:bg-blue-700 transition-all z-40 active:scale-95"><PlusIcon className="h-6 w-6" /></button>
      </div>

      <BottomNav view={view} setView={setView} />
      {toastMessage && <div className="fixed bottom-32 left-1/2 -translate-x-1/2 z-[60] animate-in fade-in slide-in-from-bottom-4 duration-500"><div className="bg-slate-900 text-white px-6 py-3.5 rounded-2xl shadow-2xl border border-white/10 flex items-center gap-3"><p className="text-[11px] font-black uppercase tracking-widest">{toastMessage}</p></div></div>}
      {isModalOpen && <AddBookModal onClose={() => setIsModalOpen(false)} onAddBook={handleAddBook} onUpdateBook={handleUpdateBook} bookToEdit={editingBook} defaultStatus={defaultStatusForModal} existingBooks={books} />}
      {isSettingsOpen && <SettingsModal onClose={() => setIsSettingsOpen(false)} readingGoal={readingGoal} onSetReadingGoal={handleSetReadingGoal} profile={userProfile} onUpdateProfile={handleUpdateProfile} />}
      {deletingBook && <ConfirmationModal isOpen={!!deletingBook} onClose={() => setDeletingBook(null)} onConfirm={async () => { await deleteBook(deletingBook.id); setDeletingBook(null); showToast(`Removido.`); }} title="Excluir" message={`Apagar "${deletingBook.title}"?`} />}
    </div>
  );
}

-- ======================================================
-- SCRIPT DE ESTRUTURA COMPLETA: BIBLIOTECH (v13)
-- EXECUTE ESTE SCRIPT NO "SQL EDITOR" DO SEU SUPABASE
-- ======================================================

-- 1. TABELA DE PERFIS (PROFILES)
CREATE TABLE IF NOT EXISTS public.profiles (
  id UUID PRIMARY KEY REFERENCES auth.users ON DELETE CASCADE,
  full_name TEXT,
  avatar_url TEXT,
  reading_goal INTEGER DEFAULT 12,
  updated_at TIMESTAMP WITH TIME ZONE DEFAULT timezone('utc'::text, now())
);

-- 2. TABELA DE LIVROS (BOOKS)
CREATE TABLE IF NOT EXISTS public.books (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  user_id UUID REFERENCES auth.users ON DELETE CASCADE NOT NULL,
  title TEXT NOT NULL,
  author TEXT NOT NULL,
  pages INTEGER DEFAULT 0,
  genre TEXT,
  type TEXT DEFAULT 'Livro',
  status TEXT DEFAULT 'Não lido',
  rating DECIMAL(3,1),
  cover_image_url TEXT,
  summary TEXT,
  notes TEXT,
  estimated_price DECIMAL(10,2),
  buy_link TEXT,
  current_page INTEGER DEFAULT 0,
  date_added DATE DEFAULT CURRENT_DATE NOT NULL,
  date_started DATE,
  date_finished DATE,
  days_to_finish INTEGER,
  times_read INTEGER DEFAULT 1,
  was_wishlist BOOLEAN DEFAULT FALSE
);

-- 3. MIGRAÇÕES CRÍTICAS (Correção do erro 22P02 - Integer vs Decimal)
DO $$ 
BEGIN 
  -- Converte rating para DECIMAL se ainda for INTEGER
  IF EXISTS (
    SELECT 1 FROM information_schema.columns 
    WHERE table_name='books' AND column_name='rating' AND data_type='integer'
  ) THEN
    ALTER TABLE public.books ALTER COLUMN rating TYPE DECIMAL(3,1) USING rating::DECIMAL(3,1);
  END IF;

  -- Garante que current_page existe
  IF NOT EXISTS (SELECT 1 FROM information_schema.columns WHERE table_name='books' AND column_name='current_page') THEN
    ALTER TABLE public.books ADD COLUMN current_page INTEGER DEFAULT 0;
  END IF;

  -- Garante que was_wishlist existe
  IF NOT EXISTS (SELECT 1 FROM information_schema.columns WHERE table_name='books' AND column_name='was_wishlist') THEN
    ALTER TABLE public.books ADD COLUMN was_wishlist BOOLEAN DEFAULT FALSE;
  END IF;

  -- Garante que times_read existe
  IF NOT EXISTS (SELECT 1 FROM information_schema.columns WHERE table_name='books' AND column_name='times_read') THEN
    ALTER TABLE public.books ADD COLUMN times_read INTEGER DEFAULT 1;
  END IF;
END $$;

-- 4. GATILHO PARA CRIAÇÃO AUTOMÁTICA DE PERFIL
CREATE OR REPLACE FUNCTION public.handle_new_user() 
RETURNS TRIGGER AS $$
BEGIN
  INSERT INTO public.profiles (id, full_name, avatar_url)
  VALUES (new.id, new.raw_user_meta_data->>'full_name', new.raw_user_meta_data->>'avatar_url')
  ON CONFLICT (id) DO NOTHING;
  RETURN new;
END;
$$ LANGUAGE plpgsql SECURITY DEFINER;

DROP TRIGGER IF EXISTS on_auth_user_created ON auth.users;
CREATE TRIGGER on_auth_user_created
  AFTER INSERT ON auth.users
  FOR EACH ROW EXECUTE PROCEDURE public.handle_new_user();

