                      placeholder="0,00"
                      className="w-full bg-slate-50 dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-2xl px-5 py-3.5 outline-none focus:border-primary font-bold text-slate-700 dark:text-slate-300" 
                    />
                </div>
                <div>
                    <label className={labelClass(false)}>Link de Compra</label>
                    <input 
                      type="text" 
                      value={buyLink} 
                      onChange={(e) => setBuyLink(e.target.value)} 
                      placeholder="https://..."
                      className="w-full bg-slate-50 dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-2xl px-5 py-3.5 outline-none focus:border-primary font-bold text-slate-700 dark:text-slate-300" 
                    />
                </div>
            </div>

            <div className="p-7 bg-blue-50/40 dark:bg-blue-900/10 rounded-[2.5rem] border border-blue-100 dark:border-blue-800/50 flex flex-col sm:flex-row items-center gap-8 shadow-inner">
                <div className="relative group flex-shrink-0">
                    {coverImageUrl ? (
                        <img 
                          src={coverImageUrl} 
                          alt="Capa" 
                          onError={(e) => {
                            (e.target as HTMLImageElement).src = `https://picsum.photos/seed/${encodeURIComponent(title || 'default')}/400/600`;
                          }}
                          className="w-24 h-36 object-cover rounded-xl shadow-xl transition-transform group-hover:scale-110 duration-500"
                        />
                    ) : (
                        <div className="w-24 h-36 bg-slate-200 dark:bg-slate-800 rounded-xl flex items-center justify-center border-2 border-dashed border-slate-300 dark:border-slate-700">
                            <BookOpenIcon className="h-8 w-8 text-slate-400 dark:text-slate-600" />
                        </div>
                    )}
                </div>
                <div className="text-center sm:text-left flex-1">
                    <h4 className="text-sm font-black text-slate-800 dark:text-slate-200 mb-2 uppercase tracking-wide">✦ Inteligência BiblioTech</h4>
                    <p className="text-[11px] text-slate-500 dark:text-slate-400 mb-5 leading-relaxed font-medium uppercase tracking-tight">Deixe a IA pesquisar referências reais e criar uma arte de capa única para sua estante.</p>
                    <div className="flex flex-wrap gap-3 justify-center sm:justify-start">
                        <button 
                            type="button" 
                            onClick={handleGenerateSummary} 
                            disabled={isGeneratingSummary || isSubmitting || !title || authors.length === 0} 
                            className="px-6 py-3 text-[10px] font-black uppercase tracking-widest rounded-xl bg-primary text-white hover:bg-slate-900 dark:hover:bg-slate-100 dark:hover:text-slate-900 transition-all shadow-md active:scale-95 disabled:opacity-50 flex items-center gap-2"
                        >
                            {isGeneratingSummary ? 'Processando...' : '✦ Gerar Resumo com IA'}
                        </button>
                        <button 
                            type="button" 
                            onClick={handleGenerateCover} 
                            disabled={isGeneratingCover || isSubmitting || !title || selectedGenres.length === 0} 
                            className="px-6 py-3 text-[10px] font-black uppercase tracking-widest rounded-xl bg-white dark:bg-slate-800 text-primary border border-blue-200 dark:border-blue-800/50 hover:bg-primary hover:text-white transition-all shadow-md active:scale-95 disabled:opacity-50 flex items-center gap-2"
                        >
                            {isGeneratingCover ? 'Pesquisando e Criando...' : 'Pesquisar e Gerar Capa'}
                        </button>
                    </div>
                </div>
            </div>

            <div className="space-y-3">
                <label className={labelClass(false)}>Resumo & Sinopse</label>
                <textarea 
                  value={summary} 
                  onChange={(e) => setSummary(e.target.value)} 
                  rows={4} 
                  className="w-full bg-slate-50 dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-[1.5rem] px-5 py-4 outline-none focus:border-primary focus:ring-4 focus:ring-primary/5 text-sm leading-relaxed text-slate-600 dark:text-slate-300 font-medium" 
                  placeholder="Como você descreveria esta jornada?..."
                ></textarea>
            </div>

            <div className="space-y-3">
                <label className={labelClass(false)}>Notas Pessoais</label>
                <textarea 
                    value={notes} 
                    onChange={(e) => setNotes(e.target.value)} 
                    rows={4} 
                    className="w-full bg-slate-50 dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-[1.5rem] px-5 py-4 outline-none focus:border-primary focus:ring-4 focus:ring-primary/5 text-sm leading-relaxed text-slate-600 dark:text-slate-300 font-medium" 
                    placeholder="Anotações sobre a leitura, personagens favoritos, citações..."
                ></textarea>
            </div>

            <div className="flex justify-end gap-4 pt-8 border-t border-slate-100 dark:border-slate-800 mt-6">
                <button 
                  type="button" 
                  onClick={onClose} 
                  disabled={isSubmitting}
                  className="px-8 py-3.5 rounded-2xl text-slate-500 dark:text-slate-400 font-black text-[11px] uppercase tracking-widest hover:bg-slate-100 dark:hover:bg-slate-800 transition-all disabled:opacity-30"
                >
                  Cancelar
                </button>
                <button 
                  type="submit" 
                  disabled={isSubmitting}
                  className="px-10 py-3.5 rounded-2xl bg-slate-900 dark:bg-slate-100 text-white dark:text-slate-900 font-black text-[11px] uppercase tracking-widest hover:bg-primary dark:hover:bg-primary dark:hover:text-white shadow-2xl transition-all active:scale-95 shadow-primary/20 disabled:bg-slate-400 flex items-center gap-3"
                >
                  {isSubmitting && (
                    <svg className="animate-spin h-4 w-4 text-white dark:text-slate-900" xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24">
                        <circle className="opacity-25" cx="12" cy="12" r="10" stroke="currentColor" strokeWidth="4"></circle>
                        <path className="opacity-75" fill="currentColor" d="M4 12a8 8 0 018-8V0C5.373 0 0 5.373 0 12h4zm2 5.291A7.962 7.962 0 014 12H0c0 3.042 1.135 5.824 3 7.938l3-2.647z"></path>
                    </svg>
                  )}
                  {isSubmitting ? 'Salvando...' : (isEditMode ? 'Salvar Alterações' : 'Salvar no Banco')}
                </button>
            </div>
        </form>
      </div>
    </div>
  );
};

// Fix: Added useMemo to the React imports
import React, { useState, useCallback, useEffect, useRef, useMemo } from 'react';
import type { NewBook, Book, StatusConfigs } from '../types';
import { BookStatus, BookType, GENRES, STATUS_CONFIGS } from '../types';
import { XMarkIcon, BookOpenIcon, StarIcon, StarIconFilled, PlusIcon } from './Icons';
import { generateBookSummary, generateBookCover } from '../services/geminiService';

interface AddBookModalProps {
  onClose: () => void;
  onAddBook: (book: NewBook) => Promise<void>;
  onUpdateBook: (book: Book) => Promise<void>;
  bookToEdit?: Book | null;
  defaultStatus?: BookStatus;
  existingBooks: Book[];
  statusConfigs?: StatusConfigs;
}

interface FormErrors {
  title?: string;
  authors?: string;
  genre?: string;
}

export const AddBookModal: React.FC<AddBookModalProps> = ({ 
  onClose, 
  onAddBook, 
  onUpdateBook, 
  bookToEdit, 
  defaultStatus, 
  existingBooks, 
  statusConfigs = STATUS_CONFIGS 
}) => {
  const isEditMode = !!bookToEdit;

  const [title, setTitle] = useState(bookToEdit?.title || '');
  const [authors, setAuthors] = useState<string[]>(
    bookToEdit?.author ? bookToEdit.author.split(',').map(a => a.trim()).filter(a => a !== '') : []
  );
  const [authorInput, setAuthorInput] = useState('');
  const [pages, setPages] = useState(bookToEdit?.pages || 0);
  const [selectedGenres, setSelectedGenres] = useState<string[]>(
    bookToEdit?.genre ? bookToEdit.genre.split(',').map(g => g.trim()).filter(g => g !== '') : []
  );
  const [type, setType] = useState<BookType>(bookToEdit?.type || BookType.Book);
  const [status, setStatus] = useState<BookStatus>(bookToEdit?.status || defaultStatus || BookStatus.TBR);
  const [rating, setRating] = useState<number>(bookToEdit?.rating || 0);
  const [hoverRating, setHoverRating] = useState<number>(0);
  const [summary, setSummary] = useState(bookToEdit?.summary || '');
  const [notes, setNotes] = useState(bookToEdit?.notes || '');
  const [estimatedPrice, setEstimatedPrice] = useState(bookToEdit?.estimatedPrice?.toString() || '');
  const [buyLink, setBuyLink] = useState(bookToEdit?.buyLink || '');
  const [coverImageUrl, setCoverImageUrl] = useState<string>(bookToEdit?.coverImageUrl || '');
  const [isGeneratingCover, setIsGeneratingCover] = useState(false);
  const [isGeneratingSummary, setIsGeneratingSummary] = useState(false);
  const [isSubmitting, setIsSubmitting] = useState(false);

  const [dateAdded, setDateAdded] = useState(bookToEdit?.dateAdded || new Date().toISOString().split('T')[0]);

  const [dateFinished, setDateFinished] = useState(bookToEdit?.dateFinished || new Date().toISOString().split('T')[0]);
  const [daysToFinish, setDaysToFinish] = useState(bookToEdit?.daysToFinish?.toString() || '');
  const [timesRead, setTimesRead] = useState(bookToEdit?.timesRead || (bookToEdit?.status === BookStatus.Read ? 1 : 0));

  const [errors, setErrors] = useState<FormErrors>({});
  const [isShaking, setIsShaking] = useState(false);

  // Estados para Auto-complete
  const [titleSuggestions, setTitleSuggestions] = useState<string[]>([]);
  const [authorSuggestions, setAuthorSuggestions] = useState<string[]>([]);
  const [activeSuggestionIndex, setActiveSuggestionIndex] = useState(0);
  const [showTitleSug, setShowTitleSug] = useState(false);
  const [showAuthorSug, setShowAuthorSug] = useState(false);

  const titleRef = useRef<HTMLDivElement>(null);
  const authorRef = useRef<HTMLDivElement>(null);

  // Listas únicas de referência
  // Fix: useMemo is now available through the updated import
  const uniqueTitles = useMemo(() => Array.from(new Set(existingBooks.map(b => b.title))), [existingBooks]);
  const uniqueAuthors = useMemo(() => {
    const all = existingBooks.flatMap(b => b.author.split(',').map(a => a.trim()));
    return Array.from(new Set(all));
  }, [existingBooks]);

  useEffect(() => {
    const handleClickOutside = (event: MouseEvent) => {
      if (titleRef.current && !titleRef.current.contains(event.target as Node)) setShowTitleSug(false);
      if (authorRef.current && !authorRef.current.contains(event.target as Node)) setShowAuthorSug(false);
    };
    document.addEventListener('mousedown', handleClickOutside);
    return () => document.removeEventListener('mousedown', handleClickOutside);
  }, []);

  useEffect(() => {
    if (status === BookStatus.Read && !daysToFinish && bookToEdit?.dateStarted && dateFinished) {
        const start = new Date(bookToEdit.dateStarted);
        const end = new Date(dateFinished);
        const diffTime = end.getTime() - start.getTime();
        const diffDays = Math.ceil(diffTime / (1000 * 60 * 60 * 24));
        if (diffDays >= 0) setDaysToFinish(diffDays.toString());
    }
    if (status === BookStatus.Read && timesRead === 0) setTimesRead(1);
  }, [status, dateFinished]);

  const addAuthor = (name?: string) => {
    const val = name || authorInput.trim();
    if (val && !authors.includes(val)) {
      setAuthors([...authors, val]);
      setAuthorInput('');
      setShowAuthorSug(false);
      if (errors.authors) setErrors(prev => ({ ...prev, authors: undefined }));
    }
  };

  const removeAuthor = (name: string) => {
    setAuthors(authors.filter(a => a !== name));
  };

  const handleTitleChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const value = e.target.value;
    setTitle(value);
    if (errors.title) setErrors(prev => ({ ...prev, title: undefined }));

    if (value.trim().length > 0) {
      const filtered = uniqueTitles.filter(t => t.toLowerCase().includes(value.toLowerCase()) && t.toLowerCase() !== value.toLowerCase()).slice(0, 5);
      setTitleSuggestions(filtered);
      setShowTitleSug(filtered.length > 0);
      setActiveSuggestionIndex(0);
    } else {
      setShowTitleSug(false);
    }
  };

  const handleAuthorInputChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const value = e.target.value;
    setAuthorInput(value);

    if (value.trim().length > 0) {
      const filtered = uniqueAuthors.filter(a => a.toLowerCase().includes(value.toLowerCase()) && !authors.includes(a)).slice(0, 5);
      setAuthorSuggestions(filtered);
      setShowAuthorSug(filtered.length > 0);
      setActiveSuggestionIndex(0);
    } else {
      setShowAuthorSug(false);
    }
  };

  const handleKeyDown = (e: React.KeyboardEvent, type: 'title' | 'author') => {
    const suggestions = type === 'title' ? titleSuggestions : authorSuggestions;
    const show = type === 'title' ? showTitleSug : showAuthorSug;

    if (show && suggestions.length > 0) {
      if (e.key === 'ArrowDown') {
        e.preventDefault();
        setActiveSuggestionIndex(prev => (prev < suggestions.length - 1 ? prev + 1 : prev));
      } else if (e.key === 'ArrowUp') {
        e.preventDefault();
        setActiveSuggestionIndex(prev => (prev > 0 ? prev - 1 : 0));
      } else if (e.key === 'Enter') {
        e.preventDefault();
        const selected = suggestions[activeSuggestionIndex];
        if (type === 'title') {
          setTitle(selected);
          setShowTitleSug(false);
        } else {
          addAuthor(selected);
        }
      } else if (e.key === 'Escape') {
        type === 'title' ? setShowTitleSug(false) : setShowAuthorSug(false);
      }
    }
  };

  // Fix: Implemented toggleGenre function which was missing
  const toggleGenre = (genre: string) => {
    setSelectedGenres(prev => 
      prev.includes(genre) 
        ? prev.filter(g => g !== genre) 
        : [...prev, genre]
    );
    if (errors.genre) setErrors(prev => ({ ...prev, genre: undefined }));
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    if (isSubmitting) return;

    let finalAuthors = [...authors];
    if (authorInput.trim() && !finalAuthors.includes(authorInput.trim())) {
        finalAuthors.push(authorInput.trim());
    }

    const newErrors: FormErrors = {};
    if (!title.trim()) newErrors.title = "O título é obrigatório";
    if (finalAuthors.length === 0) newErrors.authors = "Adicione ao menos um autor";
    if (selectedGenres.length === 0) newErrors.genre = "Selecione ao menos um gênero";

    if (Object.keys(newErrors).length > 0) {
      setErrors(newErrors);
      setIsShaking(true);
      setTimeout(() => setIsShaking(false), 500);
      return;
    }

    setIsSubmitting(true);
    try {
        const bookData = { 
            title: title.trim(), 
            author: finalAuthors.join(', '), 
            pages, 
            genre: selectedGenres.join(', '), 
            type, 
            status, 
            summary, 
            notes,
            rating: status === BookStatus.Read ? (rating || undefined) : undefined,
            estimatedPrice: estimatedPrice ? parseFloat(estimatedPrice) : undefined,
            buyLink: buyLink.trim() || undefined,
            coverImageUrl: coverImageUrl.trim() || undefined, 
            dateAdded,
            currentPage: status === BookStatus.Read ? pages : bookToEdit?.currentPage,
            dateStarted: bookToEdit?.dateStarted,
            dateFinished: status === BookStatus.Read ? dateFinished : undefined,
            daysToFinish: status === BookStatus.Read && daysToFinish ? parseInt(daysToFinish, 10) : null,
            timesRead: status === BookStatus.Read ? Number(timesRead) : 0
        };
        if (isEditMode) {
            await onUpdateBook({ ...bookToEdit, ...bookData });
        } else {
            await onAddBook(bookData);
        }
    } finally {
        setIsSubmitting(false);
    }
  };

  const handleGenerateCover = useCallback(async () => {
    if (!title || selectedGenres.length === 0) return;
    setIsGeneratingCover(true);
    try {
      const result = await generateBookCover(title, selectedGenres[0], type, authors.join(', '));
      if (result) setCoverImageUrl(result);
    } finally {
      setIsGeneratingCover(false);
    }
  }, [title, selectedGenres, type, authors]);

  const handleGenerateSummary = useCallback(async () => {
    if (!title || authors.length === 0) return;
    setIsGeneratingSummary(true);
    try {
      const result = await generateBookSummary(title, authors.join(', '));
      if (result) setSummary(result);
    } catch (err) {
      console.error("Erro ao gerar resumo:", err);
    } finally {
      setIsGeneratingSummary(false);
    }
  }, [title, authors]);

  const labelClass = (isRequired: boolean) => 
    `block text-[10px] font-black uppercase tracking-[0.15em] mb-1.5 ml-1 flex items-center gap-1 ${isRequired ? 'text-slate-500 dark:text-slate-400' : 'text-slate-400 dark:text-slate-500'}`;

  const SuggestionDropdown = ({ suggestions, show, onSelect }: { suggestions: string[], show: boolean, onSelect: (val: string) => void }) => {
    if (!show || suggestions.length === 0) return null;
    return (
      <div className="absolute left-0 right-0 top-full mt-2 z-[60] bg-white/95 dark:bg-slate-900/95 backdrop-blur-md border border-slate-200 dark:border-slate-700 rounded-2xl shadow-2xl overflow-hidden animate-in fade-in slide-in-from-top-2 duration-200">
        {suggestions.map((suggestion, index) => (
          <button
            key={index}
            type="button"
            onMouseEnter={() => setActiveSuggestionIndex(index)}
            onClick={() => onSelect(suggestion)}
            className={`w-full text-left px-5 py-3 text-xs font-bold transition-colors ${activeSuggestionIndex === index ? 'bg-primary text-white' : 'text-slate-700 dark:text-slate-300 hover:bg-slate-50 dark:hover:bg-slate-800'}`}
          >
            {suggestion}
          </button>
        ))}
      </div>
    );
  };

  return (
    <div className="fixed inset-0 bg-slate-900/60 backdrop-blur-sm flex items-center justify-center z-50 p-4">
      <div 
        className={`bg-white dark:bg-slate-900 rounded-[2.5rem] shadow-2xl w-full max-w-2xl max-h-[90vh] overflow-hidden flex flex-col border border-white/20 dark:border-slate-800 transition-transform duration-500 ${isShaking ? 'animate-shake' : ''}`}
        style={{ animation: isShaking ? 'shake 0.4s cubic-bezier(.36,.07,.19,.97) both' : 'none' }}
      >
        <div className="p-7 border-b border-slate-100 dark:border-slate-800 flex justify-between items-center bg-slate-50/50 dark:bg-slate-800/30">
            <h2 className="text-2xl font-black font-serif text-slate-900 dark:text-slate-50 tracking-tight">{isEditMode ? 'Editar Registro' : 'Novo Registro'}</h2>
            <button onClick={onClose} disabled={isSubmitting} className="p-2.5 rounded-full hover:bg-slate-200 dark:hover:bg-slate-700 text-slate-400 transition-all hover:rotate-90 disabled:opacity-30">
                <XMarkIcon className="h-5 w-5" />
            </button>
        </div>

        <form onSubmit={handleSubmit} className="p-8 space-y-8 overflow-y-auto custom-scrollbar">
            <div className={`grid grid-cols-1 md:grid-cols-2 gap-8 ${isSubmitting ? 'opacity-50 pointer-events-none' : ''}`}>
                <div className="md:col-span-2 relative" ref={titleRef}>
                    <label className={labelClass(true)}>
                      Título <span className="text-red-500">*</span>
                    </label>
                    <input 
                      type="text" 
                      value={title} 
                      onChange={handleTitleChange}
                      onKeyDown={(e) => handleKeyDown(e, 'title')}
                      placeholder="Ex: Cem Anos de Solidão"
                      className={`w-full bg-slate-50 dark:bg-slate-800 border rounded-2xl px-5 py-3.5 outline-none transition-all focus:ring-4 focus:ring-primary/5 ${errors.title ? 'border-red-400 bg-red-50/30 dark:bg-red-950/20' : 'border-slate-200 dark:border-slate-700 focus:border-primary font-bold'}`} 
                    />
                    <SuggestionDropdown 
                      suggestions={titleSuggestions} 
                      show={showTitleSug} 
                      onSelect={(val) => { setTitle(val); setShowTitleSug(false); }} 
                    />
                    {errors.title && <p className="text-[10px] text-red-500 font-bold mt-2 uppercase tracking-wide ml-1">{errors.title}</p>}
                </div>

                <div className="md:col-span-2">
                    <label className={labelClass(true)}>
                      Autor(es) <span className="text-red-500">*</span>
                    </label>
                    <div className="flex gap-2 mb-3 relative" ref={authorRef}>
                        <div className="flex-1 relative">
                          <input 
                            type="text" 
                            value={authorInput} 
                            onChange={handleAuthorInputChange}
                            onKeyDown={(e) => handleKeyDown(e, 'author')}
                            onFocus={() => authorInput.trim() && setAuthorSuggestions(uniqueAuthors.filter(a => a.toLowerCase().includes(authorInput.toLowerCase()) && !authors.includes(a)).slice(0,5))}
                            placeholder="Adicione um autor..."
                            className={`w-full bg-slate-50 dark:bg-slate-800 border rounded-2xl px-5 py-3.5 outline-none transition-all focus:ring-4 focus:ring-primary/5 ${errors.authors ? 'border-red-400' : 'border-slate-200 dark:border-slate-700 focus:border-primary font-bold'}`} 
                          />
                          <SuggestionDropdown 
                            suggestions={authorSuggestions} 
                            show={showAuthorSug} 
                            onSelect={(val) => addAuthor(val)} 
                          />
                        </div>
                        <button 
                          type="button" 
                          onClick={() => addAuthor()}
                          className="px-5 rounded-2xl bg-slate-100 dark:bg-slate-800 border border-slate-200 dark:border-slate-700 text-slate-500 hover:bg-primary hover:text-white hover:border-primary transition-all active:scale-95 flex-shrink-0"
                        >
                          <PlusIcon className="h-5 w-5" />
                        </button>
                    </div>

                    <div className="flex flex-wrap gap-2 min-h-[40px]">
                        {authors.length > 0 ? (
                            authors.map(a => (
                                <span key={a} className="bg-slate-50 dark:bg-slate-800 border border-slate-200 dark:border-slate-700 text-slate-600 dark:text-slate-300 text-[10px] font-black uppercase tracking-widest px-4 py-2 rounded-xl flex items-center gap-2 shadow-sm animate-in fade-in zoom-in duration-300">
                                    {a}
                                    <button type="button" onClick={() => removeAuthor(a)} className="hover:text-red-500 transition-colors p-0.5">
                                        <XMarkIcon className="h-3.5 w-3.5" />
                                    </button>
                                </span>
                            ))
                        ) : (
                            <span className="text-slate-400 dark:text-slate-500 text-[10px] font-bold uppercase tracking-widest ml-1 mt-1 italic">Nenhum autor adicionado</span>
                        )}
                    </div>
                    {errors.authors && <p className="text-[10px] text-red-500 font-bold mt-2 uppercase tracking-wide ml-1">{errors.authors}</p>}
                </div>

                <div>
                    <label className={labelClass(false)}>Status</label>
                    <select value={status} onChange={(e) => setStatus(e.target.value as BookStatus)} className="w-full bg-slate-50 dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-2xl px-5 py-3.5 outline-none focus:ring-4 focus:ring-primary/5 focus:border-primary cursor-pointer font-bold text-slate-700 dark:text-slate-300">
                        <option value={BookStatus.TBR}>{statusConfigs[BookStatus.TBR].label}</option>
                        <option value={BookStatus.Reading}>{statusConfigs[BookStatus.Reading].label}</option>
                        <option value={BookStatus.Read}>{statusConfigs[BookStatus.Read].label}</option>
                        <option value={BookStatus.Wishlist}>{statusConfigs[BookStatus.Wishlist].label}</option>
                    </select>
                </div>

                <div>
                    <label className={labelClass(false)}>Total de Páginas</label>
                    <input type="number" min="0" value={pages} onChange={(e) => setPages(Number(e.target.value))} className="w-full bg-slate-50 dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-2xl px-5 py-3.5 outline-none focus:border-primary font-bold text-slate-700 dark:text-slate-300" />
                </div>

                <div>
                    <label className={labelClass(false)}>Data de Adição</label>
                    <input 
                      type="date" 
                      value={dateAdded} 
                      onChange={(e) => setDateAdded(e.target.value)} 
                      className="w-full bg-slate-50 dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-2xl px-5 py-3.5 outline-none focus:border-primary font-bold text-slate-700 dark:text-slate-300" 
                    />
                </div>

                <div>
                    <label className={labelClass(false)}>Tipo de Mídia</label>
                    <select value={type} onChange={(e) => setType(e.target.value as BookType)} className="w-full bg-slate-50 dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-2xl px-5 py-3.5 outline-none focus:border-primary font-bold text-slate-700 dark:text-slate-300">
                        <option value={BookType.Book}>Livro</option>
                        <option value={BookType.HQ}>HQ</option>
                    </select>
                </div>

                {status === BookStatus.Read && (
                  <div className="md:col-span-2 grid grid-cols-1 md:grid-cols-3 gap-8 animate-in slide-in-from-top-4 duration-300">
                    <div>
                      <label className={labelClass(false)}>Data de Conclusão</label>
                      <input 
                        type="date" 
                        value={dateFinished} 
                        onChange={(e) => setDateFinished(e.target.value)} 
                        className="w-full bg-slate-50 dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-2xl px-5 py-3.5 outline-none focus:border-primary font-bold text-slate-700 dark:text-slate-300" 
                      />
                    </div>
                    <div>
                      <label className={labelClass(false)}>Dias Gastos</label>
                      <input 
                        type="number" 
                        min="0"
                        placeholder="Ex: 15"
                        value={daysToFinish} 
                        onChange={(e) => setDaysToFinish(e.target.value)} 
                        className="w-full bg-slate-50 dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-2xl px-5 py-3.5 outline-none focus:border-primary font-bold text-slate-700 dark:text-slate-300" 
                      />
                    </div>
                    <div>
                      <label className={labelClass(false)}>Vezes Lido</label>
                      <input 
                        type="number" 
                        min="1"
                        placeholder="Ex: 1"
                        value={timesRead} 
                        onChange={(e) => setTimesRead(Number(e.target.value))} 
                        className="w-full bg-slate-50 dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-2xl px-5 py-3.5 outline-none focus:border-primary font-bold text-slate-700 dark:text-slate-300" 
                      />
                    </div>
                  </div>
                )}

                <div className="md:col-span-2">
                    <label className={labelClass(true)}>Gêneros <span className="text-red-500">*</span></label>
                    <div className={`p-5 bg-slate-50/50 dark:bg-slate-800/20 border rounded-[2.5rem] transition-all ${errors.genre ? 'border-red-400 ring-4 ring-red-500/5 bg-red-50/10' : 'border-slate-200 dark:border-slate-700'}`}>
                        <div className="flex flex-wrap gap-2.5 mb-5 min-h-[38px]">
                            {selectedGenres.length > 0 ? (
                                selectedGenres.map(g => (
                                    <span key={g} className="bg-primary text-white text-[10px] font-black uppercase tracking-widest px-4 py-2 rounded-xl flex items-center gap-2 shadow-md animate-in fade-in zoom-in duration-300">
                                        {g}
                                        <button type="button" onClick={() => toggleGenre(g)} className="hover:text-blue-200 transition-colors p-0.5">
                                            <XMarkIcon className="h-3.5 w-3.5" />
                                        </button>
                                    </span>
                                ))
                            ) : (
                                <span className="text-slate-400 dark:text-slate-500 text-xs italic ml-1 mt-2">Escolha as categorias da obra...</span>
                            )}
                        </div>
                        <div className="flex flex-wrap gap-2 pt-5 border-t border-slate-200/60 dark:border-slate-700/60 max-h-48 overflow-y-auto pr-2 custom-scrollbar">
                            {GENRES.map(g => {
                                const isSelected = selectedGenres.includes(g);
                                return (
                                    <button
                                        key={g}
                                        type="button"
                                        onClick={() => toggleGenre(g)}
                                        className={`px-4 py-2 rounded-xl text-[10px] font-black uppercase tracking-[0.1em] transition-all ${
                                            isSelected 
                                                ? 'bg-primary text-white border border-primary scale-95 shadow-sm' 
                                                : 'bg-white dark:bg-slate-900 text-slate-500 dark:text-slate-400 border border-slate-200 dark:border-slate-700 hover:border-primary/40 hover:bg-slate-50 dark:hover:bg-slate-800'
                                        }`}
                                    >
                                        {g}
                                    </button>
                                );
                            })}
                        </div>
                    </div>
                    {errors.genre && <p className="text-[10px] text-red-500 font-bold mt-3 uppercase tracking-wide ml-1">{errors.genre}</p>}
                </div>

                <div className="md:col-span-2">
                    <label className={labelClass(false)}>Avaliação / Nota (0 a 10)</label>
                    <div className="flex flex-col gap-4 p-5 bg-slate-50 dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-2xl">
                        <div className="flex items-center gap-4">
                            <input 
                                type="range" 
                                min="0" 
                                max="10" 
                                step="0.1" 
                                value={rating} 
                                onChange={(e) => setRating(parseFloat(e.target.value))}
                                className="flex-1 h-2 bg-slate-200 dark:bg-slate-700 rounded-lg appearance-none cursor-pointer accent-amber-500"
                            />
                            <div className="flex items-center gap-2">
                                <input 
                                    type="number" 
                                    min="0" 
                                    max="10" 
                                    step="0.1" 
                                    value={rating} 
                                    onChange={(e) => setRating(parseFloat(e.target.value) || 0)}
                                    className="w-20 bg-white dark:bg-slate-900 border border-slate-200 dark:border-slate-700 rounded-xl px-2 py-1.5 text-center font-black text-amber-500 outline-none focus:border-amber-500"
                                />
                                <StarIconFilled className="h-5 w-5 text-amber-500" />
                            </div>
                        </div>
                        <div className="flex justify-between px-1">
                            {[0, 2, 4, 6, 8, 10].map(v => (
                                <button 
                                    key={v} 
                                    type="button" 
                                    onClick={() => setRating(v)}
                                    className="text-[9px] font-black text-slate-400 hover:text-primary transition-colors"
                                >
                                    {v}
                                </button>
                            ))}
                        </div>
                    </div>
                </div>

                <div className="md:col-span-2 space-y-4">
                    <label className={labelClass(false)}>URL da Capa (Manual)</label>
                    <input 
                      type="text" 
                      value={coverImageUrl} 
                      onChange={(e) => setCoverImageUrl(e.target.value)} 
                      placeholder="Cole o link da imagem (ex: https://site.com/imagem.jpg)"
                      className="w-full bg-slate-50 dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-2xl px-5 py-3.5 outline-none focus:border-primary font-medium text-slate-700 dark:text-slate-300 text-xs transition-all" 
                    />
                    <p className="text-[9px] text-slate-400 italic px-1">Insira um link direto para a imagem. O preview será atualizado abaixo.</p>
                </div>

                <div>
                    <label className={labelClass(false)}>Valor Estimado (R$)</label>
                    <input 
                      type="number" 
                      step="0.01" 
                      value={estimatedPrice} 
                      onChange={(e) => setEstimatedPrice(e.target.value)} 
                      placeholder="0,00"
                      className="w-full bg-slate-50 dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-2xl px-5 py-3.5 outline-none focus:border-primary font-bold text-slate-700 dark:text-slate-300" 
                    />
                </div>
                <div>
                    <label className={labelClass(false)}>Link de Compra</label>
                    <input 
                      type="text" 
                      value={buyLink} 
                      onChange={(e) => setBuyLink(e.target.value)} 
                      placeholder="https://..."
                      className="w-full bg-slate-50 dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-2xl px-5 py-3.5 outline-none focus:border-primary font-bold text-slate-700 dark:text-slate-300" 
                    />
                </div>
            </div>

            <div className="p-7 bg-blue-50/40 dark:bg-blue-900/10 rounded-[2.5rem] border border-blue-100 dark:border-blue-800/50 flex flex-col sm:flex-row items-center gap-8 shadow-inner">
                <div className="relative group flex-shrink-0">
                    {coverImageUrl ? (
                        <img 
                          src={coverImageUrl} 
                          alt="Capa" 
                          onError={(e) => {
                            (e.target as HTMLImageElement).src = `https://picsum.photos/seed/${encodeURIComponent(title || 'default')}/400/600`;
                          }}
                          className="w-24 h-36 object-cover rounded-xl shadow-xl transition-transform group-hover:scale-110 duration-500"
                        />
                    ) : (
                        <div className="w-24 h-36 bg-slate-200 dark:bg-slate-800 rounded-xl flex items-center justify-center border-2 border-dashed border-slate-300 dark:border-slate-700">
                            <BookOpenIcon className="h-8 w-8 text-slate-400 dark:text-slate-600" />
                        </div>
                    )}
                </div>
                <div className="text-center sm:text-left flex-1">
                    <h4 className="text-sm font-black text-slate-800 dark:text-slate-200 mb-2 uppercase tracking-wide">✦ Inteligência BiblioTech</h4>
                    <p className="text-[11px] text-slate-500 dark:text-slate-400 mb-5 leading-relaxed font-medium uppercase tracking-tight">Deixe a IA pesquisar referências reais e criar uma arte de capa única para sua estante.</p>
                    <div className="flex flex-wrap gap-3 justify-center sm:justify-start">
                        <button 
                            type="button" 
                            onClick={handleGenerateSummary} 
                            disabled={isGeneratingSummary || isSubmitting || !title || authors.length === 0} 
                            className="px-6 py-3 text-[10px] font-black uppercase tracking-widest rounded-xl bg-primary text-white hover:bg-slate-900 dark:hover:bg-slate-100 dark:hover:text-slate-900 transition-all shadow-md active:scale-95 disabled:opacity-50 flex items-center gap-2"
                        >
                            {isGeneratingSummary ? 'Processando...' : '✦ Gerar Resumo com IA'}
                        </button>
                        <button 
                            type="button" 
                            onClick={handleGenerateCover} 
                            disabled={isGeneratingCover || isSubmitting || !title || selectedGenres.length === 0} 
                            className="px-6 py-3 text-[10px] font-black uppercase tracking-widest rounded-xl bg-white dark:bg-slate-800 text-primary border border-blue-200 dark:border-blue-800/50 hover:bg-primary hover:text-white transition-all shadow-md active:scale-95 disabled:opacity-50 flex items-center gap-2"
                        >
                            {isGeneratingCover ? 'Pesquisando e Criando...' : 'Pesquisar e Gerar Capa'}
                        </button>
                    </div>
                </div>
            </div>

            <div className="space-y-3">
                <label className={labelClass(false)}>Resumo & Sinopse</label>
                <textarea 
                  value={summary} 
                  onChange={(e) => setSummary(e.target.value)} 
                  rows={4} 
                  className="w-full bg-slate-50 dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-[1.5rem] px-5 py-4 outline-none focus:border-primary focus:ring-4 focus:ring-primary/5 text-sm leading-relaxed text-slate-600 dark:text-slate-300 font-medium" 
                  placeholder="Como você descreveria esta jornada?..."
                ></textarea>
            </div>

            <div className="space-y-3">
                <label className={labelClass(false)}>Notas Pessoais</label>
                <textarea 
                    value={notes} 
                    onChange={(e) => setNotes(e.target.value)} 
                    rows={4} 
                    className="w-full bg-slate-50 dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-[1.5rem] px-5 py-4 outline-none focus:border-primary focus:ring-4 focus:ring-primary/5 text-sm leading-relaxed text-slate-600 dark:text-slate-300 font-medium" 
                    placeholder="Anotações sobre a leitura, personagens favoritos, citações..."
                ></textarea>
            </div>

            <div className="flex justify-end gap-4 pt-8 border-t border-slate-100 dark:border-slate-800 mt-6">
                <button 
                  type="button" 
                  onClick={onClose} 
                  disabled={isSubmitting}
                  className="px-8 py-3.5 rounded-2xl text-slate-500 dark:text-slate-400 font-black text-[11px] uppercase tracking-widest hover:bg-slate-100 dark:hover:bg-slate-800 transition-all disabled:opacity-30"
                >
                  Cancelar
                </button>
                <button 
                  type="submit" 
                  disabled={isSubmitting}
                  className="px-10 py-3.5 rounded-2xl bg-slate-900 dark:bg-slate-100 text-white dark:text-slate-900 font-black text-[11px] uppercase tracking-widest hover:bg-primary dark:hover:bg-primary dark:hover:text-white shadow-2xl transition-all active:scale-95 shadow-primary/20 disabled:bg-slate-400 flex items-center gap-3"
                >
                  {isSubmitting && (
                    <svg className="animate-spin h-4 w-4 text-white dark:text-slate-900" xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24">
                        <circle className="opacity-25" cx="12" cy="12" r="10" stroke="currentColor" strokeWidth="4"></circle>
                        <path className="opacity-75" fill="currentColor" d="M4 12a8 8 0 018-8V0C5.373 0 0 5.373 0 12h4zm2 5.291A7.962 7.962 0 014 12H0c0 3.042 1.135 5.824 3 7.938l3-2.647z"></path>
                    </svg>
                  )}
                  {isSubmitting ? 'Salvando...' : (isEditMode ? 'Salvar Alterações' : 'Salvar no Banco')}
                </button>
            </div>
        </form>
      </div>
    </div>
  );
};

// Fix: Added useMemo to the React imports
import React, { useState, useCallback, useEffect, useRef, useMemo } from 'react';
import type { NewBook, Book, StatusConfigs } from '../types';
import { BookStatus, BookType, GENRES, STATUS_CONFIGS } from '../types';
import { XMarkIcon, BookOpenIcon, StarIcon, StarIconFilled, PlusIcon } from './Icons';
import { generateBookSummary, generateBookCover } from '../services/geminiService';

interface AddBookModalProps {
  onClose: () => void;
  onAddBook: (book: NewBook) => Promise<void>;
  onUpdateBook: (book: Book) => Promise<void>;
  bookToEdit?: Book | null;
  defaultStatus?: BookStatus;
  existingBooks: Book[];
  statusConfigs?: StatusConfigs;
}

interface FormErrors {
  title?: string;
  authors?: string;
  genre?: string;
}

export const AddBookModal: React.FC<AddBookModalProps> = ({ 
  onClose, 
  onAddBook, 
  onUpdateBook, 
  bookToEdit, 
  defaultStatus, 
  existingBooks, 
  statusConfigs = STATUS_CONFIGS 
}) => {
  const isEditMode = !!bookToEdit;

  const [title, setTitle] = useState(bookToEdit?.title || '');
  const [authors, setAuthors] = useState<string[]>(
    bookToEdit?.author ? bookToEdit.author.split(',').map(a => a.trim()).filter(a => a !== '') : []
  );
  const [authorInput, setAuthorInput] = useState('');
  const [pages, setPages] = useState(bookToEdit?.pages || 0);
  const [selectedGenres, setSelectedGenres] = useState<string[]>(
    bookToEdit?.genre ? bookToEdit.genre.split(',').map(g => g.trim()).filter(g => g !== '') : []
  );
  const [type, setType] = useState<BookType>(bookToEdit?.type || BookType.Book);
  const [status, setStatus] = useState<BookStatus>(bookToEdit?.status || defaultStatus || BookStatus.TBR);
  const [rating, setRating] = useState<number>(bookToEdit?.rating || 0);
  const [hoverRating, setHoverRating] = useState<number>(0);
  const [summary, setSummary] = useState(bookToEdit?.summary || '');
  const [notes, setNotes] = useState(bookToEdit?.notes || '');
  const [estimatedPrice, setEstimatedPrice] = useState(bookToEdit?.estimatedPrice?.toString() || '');
  const [buyLink, setBuyLink] = useState(bookToEdit?.buyLink || '');
  const [coverImageUrl, setCoverImageUrl] = useState<string>(bookToEdit?.coverImageUrl || '');
  const [isGeneratingCover, setIsGeneratingCover] = useState(false);
  const [isGeneratingSummary, setIsGeneratingSummary] = useState(false);
  const [isSubmitting, setIsSubmitting] = useState(false);

  const [dateAdded, setDateAdded] = useState(bookToEdit?.dateAdded || new Date().toISOString().split('T')[0]);

  const [dateFinished, setDateFinished] = useState(bookToEdit?.dateFinished || new Date().toISOString().split('T')[0]);
  const [daysToFinish, setDaysToFinish] = useState(bookToEdit?.daysToFinish?.toString() || '');
  const [timesRead, setTimesRead] = useState(bookToEdit?.timesRead || (bookToEdit?.status === BookStatus.Read ? 1 : 0));

  const [errors, setErrors] = useState<FormErrors>({});
  const [isShaking, setIsShaking] = useState(false);

  // Estados para Auto-complete
  const [titleSuggestions, setTitleSuggestions] = useState<string[]>([]);
  const [authorSuggestions, setAuthorSuggestions] = useState<string[]>([]);
  const [activeSuggestionIndex, setActiveSuggestionIndex] = useState(0);
  const [showTitleSug, setShowTitleSug] = useState(false);
  const [showAuthorSug, setShowAuthorSug] = useState(false);

  const titleRef = useRef<HTMLDivElement>(null);
  const authorRef = useRef<HTMLDivElement>(null);

  // Listas únicas de referência
  const uniqueTitles = useMemo(() => Array.from(new Set(existingBooks.map(b => b.title))), [existingBooks]);
  const uniqueAuthors = useMemo(() => {
    const all = existingBooks.flatMap(b => b.author.split(',').map(a => a.trim()));
    return Array.from(new Set(all));
  }, [existingBooks]);

  useEffect(() => {
    const handleClickOutside = (event: MouseEvent) => {
      if (titleRef.current && !titleRef.current.contains(event.target as Node)) setShowTitleSug(false);
      if (authorRef.current && !authorRef.current.contains(event.target as Node)) setShowAuthorSug(false);
    };
    document.addEventListener('mousedown', handleClickOutside);
    return () => document.removeEventListener('mousedown', handleClickOutside);
  }, []);

  useEffect(() => {
    if (status === BookStatus.Read && !daysToFinish && bookToEdit?.dateStarted && dateFinished) {
        const start = new Date(bookToEdit.dateStarted);
        const end = new Date(dateFinished);
        const diffTime = end.getTime() - start.getTime();
        const diffDays = Math.ceil(diffTime / (1000 * 60 * 60 * 24));
        if (diffDays >= 0) setDaysToFinish(diffDays.toString());
    }
    if (status === BookStatus.Read && timesRead === 0) setTimesRead(1);
  }, [status, dateFinished]);

  const addAuthor = (name?: string) => {
    const val = name || authorInput.trim();
    if (val && !authors.includes(val)) {
      setAuthors([...authors, val]);
      setAuthorInput('');
      setShowAuthorSug(false);
      if (errors.authors) setErrors(prev => ({ ...prev, authors: undefined }));
    }
  };

  const removeAuthor = (name: string) => {
    setAuthors(authors.filter(a => a !== name));
  };

  const handleTitleChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const value = e.target.value;
    setTitle(value);
    if (errors.title) setErrors(prev => ({ ...prev, title: undefined }));

    if (value.trim().length > 0) {
      const filtered = uniqueTitles.filter(t => t.toLowerCase().includes(value.toLowerCase()) && t.toLowerCase() !== value.toLowerCase()).slice(0, 5);
      setTitleSuggestions(filtered);
      setShowTitleSug(filtered.length > 0);
      setActiveSuggestionIndex(0);
    } else {
      setShowTitleSug(false);
    }
  };

  const handleAuthorInputChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const value = e.target.value;
    setAuthorInput(value);

    if (value.trim().length > 0) {
      const filtered = uniqueAuthors.filter(a => a.toLowerCase().includes(value.toLowerCase()) && !authors.includes(a)).slice(0, 5);
      setAuthorSuggestions(filtered);
      setShowAuthorSug(filtered.length > 0);
      setActiveSuggestionIndex(0);
    } else {
      setShowAuthorSug(false);
    }
  };

  const handleKeyDown = (e: React.KeyboardEvent, type: 'title' | 'author') => {
    const suggestions = type === 'title' ? titleSuggestions : authorSuggestions;
    const show = type === 'title' ? showTitleSug : showAuthorSug;

    if (show && suggestions.length > 0) {
      if (e.key === 'ArrowDown') {
        e.preventDefault();
        setActiveSuggestionIndex(prev => (prev < suggestions.length - 1 ? prev + 1 : prev));
      } else if (e.key === 'ArrowUp') {
        e.preventDefault();
        setActiveSuggestionIndex(prev => (prev > 0 ? prev - 1 : 0));
      } else if (e.key === 'Enter') {
        e.preventDefault();
        const selected = suggestions[activeSuggestionIndex];
        if (type === 'title') {
          setTitle(selected);
          setShowTitleSug(false);
        } else {
          addAuthor(selected);
        }
      } else if (e.key === 'Escape') {
        type === 'title' ? setShowTitleSug(false) : setShowAuthorSug(false);
      }
    }
  };

  const toggleGenre = (genre: string) => {
    setSelectedGenres(prev => 
      prev.includes(genre) 
        ? prev.filter(g => g !== genre) 
        : [...prev, genre]
    );
    if (errors.genre) setErrors(prev => ({ ...prev, genre: undefined }));
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    if (isSubmitting) return;

    let finalAuthors = [...authors];
    if (authorInput.trim() && !finalAuthors.includes(authorInput.trim())) {
        finalAuthors.push(authorInput.trim());
    }

    const newErrors: FormErrors = {};
    const trimmedTitle = title.trim();

    // Validação de Título Vazio
    if (!trimmedTitle) {
      newErrors.title = "O título é obrigatório";
    } else {
      // Validação de Título Duplicado
      const isDuplicate = existingBooks.some(b => 
        b.title.toLowerCase() === trimmedTitle.toLowerCase() && 
        (!isEditMode || b.id !== bookToEdit?.id)
      );

      if (isDuplicate) {
        newErrors.title = "Já existe um livro com este título cadastrado na sua biblioteca";
      }
    }

    if (finalAuthors.length === 0) newErrors.authors = "Adicione ao menos um autor";
    if (selectedGenres.length === 0) newErrors.genre = "Selecione ao menos um gênero";

    if (Object.keys(newErrors).length > 0) {
      setErrors(newErrors);
      setIsShaking(true);
      setTimeout(() => setIsShaking(false), 500);
      return;
    }

    setIsSubmitting(true);
    try {
        const bookData = { 
            title: trimmedTitle, 
            author: finalAuthors.join(', '), 
            pages, 
            genre: selectedGenres.join(', '), 
            type, 
            status, 
            summary, 
            notes,
            rating: status === BookStatus.Read ? (rating || undefined) : undefined,
            estimatedPrice: estimatedPrice ? parseFloat(estimatedPrice) : undefined,
            buyLink: buyLink.trim() || undefined,
            coverImageUrl: coverImageUrl.trim() || undefined, 
            dateAdded,
            currentPage: status === BookStatus.Read ? pages : bookToEdit?.currentPage,
            dateStarted: bookToEdit?.dateStarted,
            dateFinished: status === BookStatus.Read ? dateFinished : undefined,
            daysToFinish: status === BookStatus.Read && daysToFinish ? parseInt(daysToFinish, 10) : null,
            timesRead: status === BookStatus.Read ? Number(timesRead) : 0
        };
        if (isEditMode) {
            await onUpdateBook({ ...bookToEdit, ...bookData });
        } else {
            await onAddBook(bookData);
        }
    } finally {
        setIsSubmitting(false);
    }
  };

  const handleGenerateCover = useCallback(async () => {
    if (!title || selectedGenres.length === 0) return;
    setIsGeneratingCover(true);
    try {
      const result = await generateBookCover(title, selectedGenres[0], type, authors.join(', '));
      if (result) setCoverImageUrl(result);
    } finally {
      setIsGeneratingCover(false);
    }
  }, [title, selectedGenres, type, authors]);

  const handleGenerateSummary = useCallback(async () => {
    if (!title || authors.length === 0) return;
    setIsGeneratingSummary(true);
    try {
      const result = await generateBookSummary(title, authors.join(', '));
      if (result) setSummary(result);
    } catch (err) {
      console.error("Erro ao gerar resumo:", err);
    } finally {
      setIsGeneratingSummary(false);
    }
  }, [title, authors]);

  const labelClass = (isRequired: boolean) => 
    `block text-[10px] font-black uppercase tracking-[0.15em] mb-1.5 ml-1 flex items-center gap-1 ${isRequired ? 'text-slate-500 dark:text-slate-400' : 'text-slate-400 dark:text-slate-500'}`;

  const SuggestionDropdown = ({ suggestions, show, onSelect }: { suggestions: string[], show: boolean, onSelect: (val: string) => void }) => {
    if (!show || suggestions.length === 0) return null;
    return (
      <div className="absolute left-0 right-0 top-full mt-2 z-[60] bg-white/95 dark:bg-slate-900/95 backdrop-blur-md border border-slate-200 dark:border-slate-700 rounded-2xl shadow-2xl overflow-hidden animate-in fade-in slide-in-from-top-2 duration-200">
        {suggestions.map((suggestion, index) => (
          <button
            key={index}
            type="button"
            onMouseEnter={() => setActiveSuggestionIndex(index)}
            onClick={() => onSelect(suggestion)}
            className={`w-full text-left px-5 py-3 text-xs font-bold transition-colors ${activeSuggestionIndex === index ? 'bg-primary text-white' : 'text-slate-700 dark:text-slate-300 hover:bg-slate-50 dark:hover:bg-slate-800'}`}
          >
            {suggestion}
          </button>
        ))}
      </div>
    );
  };

  return (
    <div className="fixed inset-0 bg-slate-900/60 backdrop-blur-sm flex items-center justify-center z-50 p-4">
      <div 
        className={`bg-white dark:bg-slate-900 rounded-[2.5rem] shadow-2xl w-full max-w-2xl max-h-[90vh] overflow-hidden flex flex-col border border-white/20 dark:border-slate-800 transition-transform duration-500 ${isShaking ? 'animate-shake' : ''}`}
        style={{ animation: isShaking ? 'shake 0.4s cubic-bezier(.36,.07,.19,.97) both' : 'none' }}
      >
        <div className="p-7 border-b border-slate-100 dark:border-slate-800 flex justify-between items-center bg-slate-50/50 dark:bg-slate-800/30">
            <h2 className="text-2xl font-black font-serif text-slate-900 dark:text-slate-50 tracking-tight">{isEditMode ? 'Editar Registro' : 'Novo Registro'}</h2>
            <button onClick={onClose} disabled={isSubmitting} className="p-2.5 rounded-full hover:bg-slate-200 dark:hover:bg-slate-700 text-slate-400 transition-all hover:rotate-90 disabled:opacity-30">
                <XMarkIcon className="h-5 w-5" />
            </button>
        </div>

        <form onSubmit={handleSubmit} className="p-8 space-y-8 overflow-y-auto custom-scrollbar">
            <div className={`grid grid-cols-1 md:grid-cols-2 gap-8 ${isSubmitting ? 'opacity-50 pointer-events-none' : ''}`}>
                <div className="md:col-span-2 relative" ref={titleRef}>
                    <label className={labelClass(true)}>
                      Título <span className="text-red-500">*</span>
                    </label>
                    <input 
                      type="text" 
                      value={title} 
                      onChange={handleTitleChange}
                      onKeyDown={(e) => handleKeyDown(e, 'title')}
                      placeholder="Ex: Cem Anos de Solidão"
                      className={`w-full bg-slate-50 dark:bg-slate-800 border rounded-2xl px-5 py-3.5 outline-none transition-all focus:ring-4 focus:ring-primary/5 ${errors.title ? 'border-red-400 bg-red-50/30 dark:bg-red-950/20' : 'border-slate-200 dark:border-slate-700 focus:border-primary font-bold'}`} 
                    />
                    <SuggestionDropdown 
                      suggestions={titleSuggestions} 
                      show={showTitleSug} 
                      onSelect={(val) => { setTitle(val); setShowTitleSug(false); }} 
                    />
                    {errors.title && <p className="text-[10px] text-red-500 font-bold mt-2 uppercase tracking-wide ml-1">{errors.title}</p>}
                </div>

                <div className="md:col-span-2">
                    <label className={labelClass(true)}>
                      Autor(es) <span className="text-red-500">*</span>
                    </label>
                    <div className="flex gap-2 mb-3 relative" ref={authorRef}>
                        <div className="flex-1 relative">
                          <input 
                            type="text" 
                            value={authorInput} 
                            onChange={handleAuthorInputChange}
                            onKeyDown={(e) => handleKeyDown(e, 'author')}
                            onFocus={() => authorInput.trim() && setAuthorSuggestions(uniqueAuthors.filter(a => a.toLowerCase().includes(authorInput.toLowerCase()) && !authors.includes(a)).slice(0,5))}
                            placeholder="Adicione um autor..."
                            className={`w-full bg-slate-50 dark:bg-slate-800 border rounded-2xl px-5 py-3.5 outline-none transition-all focus:ring-4 focus:ring-primary/5 ${errors.authors ? 'border-red-400' : 'border-slate-200 dark:border-slate-700 focus:border-primary font-bold'}`} 
                          />
                          <SuggestionDropdown 
                            suggestions={authorSuggestions} 
                            show={showAuthorSug} 
                            onSelect={(val) => addAuthor(val)} 
                          />
                        </div>
                        <button 
                          type="button" 
                          onClick={() => addAuthor()}
                          className="px-5 rounded-2xl bg-slate-100 dark:bg-slate-800 border border-slate-200 dark:border-slate-700 text-slate-500 hover:bg-primary hover:text-white hover:border-primary transition-all active:scale-95 flex-shrink-0"
                        >
                          <PlusIcon className="h-5 w-5" />
                        </button>
                    </div>

                    <div className="flex flex-wrap gap-2 min-h-[40px]">
                        {authors.length > 0 ? (
                            authors.map(a => (
                                <span key={a} className="bg-slate-50 dark:bg-slate-800 border border-slate-200 dark:border-slate-700 text-slate-600 dark:text-slate-300 text-[10px] font-black uppercase tracking-widest px-4 py-2 rounded-xl flex items-center gap-2 shadow-sm animate-in fade-in zoom-in duration-300">
                                    {a}
                                    <button type="button" onClick={() => removeAuthor(a)} className="hover:text-red-500 transition-colors p-0.5">
                                        <XMarkIcon className="h-3.5 w-3.5" />
                                    </button>
                                </span>
                            ))
                        ) : (
                            <span className="text-slate-400 dark:text-slate-500 text-[10px] font-bold uppercase tracking-widest ml-1 mt-1 italic">Nenhum autor adicionado</span>
                        )}
                    </div>
                    {errors.authors && <p className="text-[10px] text-red-500 font-bold mt-2 uppercase tracking-wide ml-1">{errors.authors}</p>}
                </div>

                <div>
                    <label className={labelClass(false)}>Status</label>
                    <select value={status} onChange={(e) => setStatus(e.target.value as BookStatus)} className="w-full bg-slate-50 dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-2xl px-5 py-3.5 outline-none focus:ring-4 focus:ring-primary/5 focus:border-primary cursor-pointer font-bold text-slate-700 dark:text-slate-300">
                        <option value={BookStatus.TBR}>{statusConfigs[BookStatus.TBR].label}</option>
                        <option value={BookStatus.Reading}>{statusConfigs[BookStatus.Reading].label}</option>
                        <option value={BookStatus.Read}>{statusConfigs[BookStatus.Read].label}</option>
                        <option value={BookStatus.Wishlist}>{statusConfigs[BookStatus.Wishlist].label}</option>
                    </select>
                </div>

                <div>
                    <label className={labelClass(false)}>Total de Páginas</label>
                    <input type="number" min="0" value={pages} onChange={(e) => setPages(Number(e.target.value))} className="w-full bg-slate-50 dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-2xl px-5 py-3.5 outline-none focus:border-primary font-bold text-slate-700 dark:text-slate-300" />
                </div>

                <div>
                    <label className={labelClass(false)}>Data de Adição</label>
                    <input 
                      type="date" 
                      value={dateAdded} 
                      onChange={(e) => setDateAdded(e.target.value)} 
                      className="w-full bg-slate-50 dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-2xl px-5 py-3.5 outline-none focus:border-primary font-bold text-slate-700 dark:text-slate-300" 
                    />
                </div>

                <div>
                    <label className={labelClass(false)}>Tipo de Mídia</label>
                    <select value={type} onChange={(e) => setType(e.target.value as BookType)} className="w-full bg-slate-50 dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-2xl px-5 py-3.5 outline-none focus:border-primary font-bold text-slate-700 dark:text-slate-300">
                        <option value={BookType.Book}>Livro</option>
                        <option value={BookType.HQ}>HQ</option>
                    </select>
                </div>

                {status === BookStatus.Read && (
                  <div className="md:col-span-2 grid grid-cols-1 md:grid-cols-3 gap-8 animate-in slide-in-from-top-4 duration-300">
                    <div>
                      <label className={labelClass(false)}>Data de Conclusão</label>
                      <input 
                        type="date" 
                        value={dateFinished} 
                        onChange={(e) => setDateFinished(e.target.value)} 
                        className="w-full bg-slate-50 dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-2xl px-5 py-3.5 outline-none focus:border-primary font-bold text-slate-700 dark:text-slate-300" 
                      />
                    </div>
                    <div>
                      <label className={labelClass(false)}>Dias Gastos</label>
                      <input 
                        type="number" 
                        min="0"
                        placeholder="Ex: 15"
                        value={daysToFinish} 
                        onChange={(e) => setDaysToFinish(e.target.value)} 
                        className="w-full bg-slate-50 dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-2xl px-5 py-3.5 outline-none focus:border-primary font-bold text-slate-700 dark:text-slate-300" 
                      />
                    </div>
                    <div>
                      <label className={labelClass(false)}>Vezes Lido</label>
                      <input 
                        type="number" 
                        min="1"
                        placeholder="Ex: 1"
                        value={timesRead} 
                        onChange={(e) => setTimesRead(Number(e.target.value))} 
                        className="w-full bg-slate-50 dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-2xl px-5 py-3.5 outline-none focus:border-primary font-bold text-slate-700 dark:text-slate-300" 
                      />
                    </div>
                  </div>
                )}

                <div className="md:col-span-2">
                    <label className={labelClass(true)}>Gêneros <span className="text-red-500">*</span></label>
                    <div className={`p-5 bg-slate-50/50 dark:bg-slate-800/20 border rounded-[2.5rem] transition-all ${errors.genre ? 'border-red-400 ring-4 ring-red-500/5 bg-red-50/10' : 'border-slate-200 dark:border-slate-700'}`}>
                        <div className="flex flex-wrap gap-2.5 mb-5 min-h-[38px]">
                            {selectedGenres.length > 0 ? (
                                selectedGenres.map(g => (
                                    <span key={g} className="bg-primary text-white text-[10px] font-black uppercase tracking-widest px-4 py-2 rounded-xl flex items-center gap-2 shadow-md animate-in fade-in zoom-in duration-300">
                                        {g}
                                        <button type="button" onClick={() => toggleGenre(g)} className="hover:text-blue-200 transition-colors p-0.5">
                                            <XMarkIcon className="h-3.5 w-3.5" />
                                        </button>
                                    </span>
                                ))
                            ) : (
                                <span className="text-slate-400 dark:text-slate-500 text-xs italic ml-1 mt-2">Escolha as categorias da obra...</span>
                            )}
                        </div>
                        <div className="flex flex-wrap gap-2 pt-5 border-t border-slate-200/60 dark:border-slate-700/60 max-h-48 overflow-y-auto pr-2 custom-scrollbar">
                            {GENRES.map(g => {
                                const isSelected = selectedGenres.includes(g);
                                return (
                                    <button
                                        key={g}
                                        type="button"
                                        onClick={() => toggleGenre(g)}
                                        className={`px-4 py-2 rounded-xl text-[10px] font-black uppercase tracking-[0.1em] transition-all ${
                                            isSelected 
                                                ? 'bg-primary text-white border border-primary scale-95 shadow-sm' 
                                                : 'bg-white dark:bg-slate-900 text-slate-500 dark:text-slate-400 border border-slate-200 dark:border-slate-700 hover:border-primary/40 hover:bg-slate-50 dark:hover:bg-slate-800'
                                        }`}
                                    >
                                        {g}
                                    </button>
                                );
                            })}
                        </div>
                    </div>
                    {errors.genre && <p className="text-[10px] text-red-500 font-bold mt-3 uppercase tracking-wide ml-1">{errors.genre}</p>}
                </div>

                <div className="md:col-span-2">
                    <label className={labelClass(false)}>Avaliação / Nota (0 a 10)</label>
                    <div className="flex flex-col gap-4 p-5 bg-slate-50 dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-2xl">
                        <div className="flex items-center gap-4">
                            <input 
                                type="range" 
                                min="0" 
                                max="10" 
                                step="0.1" 
                                value={rating} 
                                onChange={(e) => setRating(parseFloat(e.target.value))}
                                className="flex-1 h-2 bg-slate-200 dark:bg-slate-700 rounded-lg appearance-none cursor-pointer accent-amber-500"
                            />
                            <div className="flex items-center gap-2">
                                <input 
                                    type="number" 
                                    min="0" 
                                    max="10" 
                                    step="0.1" 
                                    value={rating} 
                                    onChange={(e) => setRating(parseFloat(e.target.value) || 0)}
                                    className="w-20 bg-white dark:bg-slate-900 border border-slate-200 dark:border-slate-700 rounded-xl px-2 py-1.5 text-center font-black text-amber-500 outline-none focus:border-amber-500"
                                />
                                <StarIconFilled className="h-5 w-5 text-amber-500" />
                            </div>
                        </div>
                        <div className="flex justify-between px-1">
                            {[0, 2, 4, 6, 8, 10].map(v => (
                                <button 
                                    key={v} 
                                    type="button" 
                                    onClick={() => setRating(v)}
                                    className="text-[9px] font-black text-slate-400 hover:text-primary transition-colors"
                                >
                                    {v}
                                </button>
                            ))}
                        </div>
                    </div>
                </div>

                <div className="md:col-span-2 space-y-4">
                    <label className={labelClass(false)}>URL da Capa (Manual)</label>
                    <input 
                      type="text" 
                      value={coverImageUrl} 
                      onChange={(e) => setCoverImageUrl(e.target.value)} 
                      placeholder="Cole o link da imagem (ex: https://site.com/imagem.jpg)"
                      className="w-full bg-slate-50 dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-2xl px-5 py-3.5 outline-none focus:border-primary font-medium text-slate-700 dark:text-slate-300 text-xs transition-all" 
                    />
                    <p className="text-[9px] text-slate-400 italic px-1">Insira um link direto para a imagem. O preview será atualizado abaixo.</p>
                </div>

                <div>
                    <label className={labelClass(false)}>Valor Estimado (R$)</label>
                    <input 
                      type="number" 
                      step="0.01" 
                      value={estimatedPrice} 
                      onChange={(e) => setEstimatedPrice(e.target.value)} 
                      placeholder="0,00"
                      className="w-full bg-slate-50 dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-2xl px-5 py-3.5 outline-none focus:border-primary font-bold text-slate-700 dark:text-slate-300" 
                    />
                </div>
                <div>
                    <label className={labelClass(false)}>Link de Compra</label>
                    <input 
                      type="text" 
                      value={buyLink} 
                      onChange={(e) => setBuyLink(e.target.value)} 
                      placeholder="https://..."
                      className="w-full bg-slate-50 dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-2xl px-5 py-3.5 outline-none focus:border-primary font-bold text-slate-700 dark:text-slate-300" 
                    />
                </div>
            </div>

            <div className="p-7 bg-blue-50/40 dark:bg-blue-900/10 rounded-[2.5rem] border border-blue-100 dark:border-blue-800/50 flex flex-col sm:flex-row items-center gap-8 shadow-inner">
                <div className="relative group flex-shrink-0">
                    {coverImageUrl ? (
                        <img 
                          src={coverImageUrl} 
                          alt="Capa" 
                          onError={(e) => {
                            (e.target as HTMLImageElement).src = `https://picsum.photos/seed/${encodeURIComponent(title || 'default')}/400/600`;
                          }}
                          className="w-24 h-36 object-cover rounded-xl shadow-xl transition-transform group-hover:scale-110 duration-500"
                        />
                    ) : (
                        <div className="w-24 h-36 bg-slate-200 dark:bg-slate-800 rounded-xl flex items-center justify-center border-2 border-dashed border-slate-300 dark:border-slate-700">
                            <BookOpenIcon className="h-8 w-8 text-slate-400 dark:text-slate-600" />
                        </div>
                    )}
                </div>
                <div className="text-center sm:text-left flex-1">
                    <h4 className="text-sm font-black text-slate-800 dark:text-slate-200 mb-2 uppercase tracking-wide">✦ Inteligência BiblioTech</h4>
                    <p className="text-[11px] text-slate-500 dark:text-slate-400 mb-5 leading-relaxed font-medium uppercase tracking-tight">Deixe a IA pesquisar referências reais e criar uma arte de capa única para sua estante.</p>
                    <div className="flex flex-wrap gap-3 justify-center sm:justify-start">
                        <button 
                            type="button" 
                            onClick={handleGenerateSummary} 
                            disabled={isGeneratingSummary || isSubmitting || !title || authors.length === 0} 
                            className="px-6 py-3 text-[10px] font-black uppercase tracking-widest rounded-xl bg-primary text-white hover:bg-slate-900 dark:hover:bg-slate-100 dark:hover:text-slate-900 transition-all shadow-md active:scale-95 disabled:opacity-50 flex items-center gap-2"
                        >
                            {isGeneratingSummary ? 'Processando...' : '✦ Gerar Resumo com IA'}
                        </button>
                        <button 
                            type="button" 
                            onClick={handleGenerateCover} 
                            disabled={isGeneratingCover || isSubmitting || !title || selectedGenres.length === 0} 
                            className="px-6 py-3 text-[10px] font-black uppercase tracking-widest rounded-xl bg-white dark:bg-slate-800 text-primary border border-blue-200 dark:border-blue-800/50 hover:bg-primary hover:text-white transition-all shadow-md active:scale-95 disabled:opacity-50 flex items-center gap-2"
                        >
                            {isGeneratingCover ? 'Pesquisando e Criando...' : 'Pesquisar e Gerar Capa'}
                        </button>
                    </div>
                </div>
            </div>

            <div className="space-y-3">
                <label className={labelClass(false)}>Resumo & Sinopse</label>
                <textarea 
                  value={summary} 
                  onChange={(e) => setSummary(e.target.value)} 
                  rows={4} 
                  className="w-full bg-slate-50 dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-[1.5rem] px-5 py-4 outline-none focus:border-primary focus:ring-4 focus:ring-primary/5 text-sm leading-relaxed text-slate-600 dark:text-slate-300 font-medium" 
                  placeholder="Como você descreveria esta jornada?..."
                ></textarea>
            </div>

            <div className="space-y-3">
                <label className={labelClass(false)}>Notas Pessoais</label>
                <textarea 
                    value={notes} 
                    onChange={(e) => setNotes(e.target.value)} 
                    rows={4} 
                    className="w-full bg-slate-50 dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-[1.5rem] px-5 py-4 outline-none focus:border-primary focus:ring-4 focus:ring-primary/5 text-sm leading-relaxed text-slate-600 dark:text-slate-300 font-medium" 
                    placeholder="Anotações sobre a leitura, personagens favoritos, citações..."
                ></textarea>
            </div>

            <div className="flex justify-end gap-4 pt-8 border-t border-slate-100 dark:border-slate-800 mt-6">
                <button 
                  type="button" 
                  onClick={onClose} 
                  disabled={isSubmitting}
                  className="px-8 py-3.5 rounded-2xl text-slate-500 dark:text-slate-400 font-black text-[11px] uppercase tracking-widest hover:bg-slate-100 dark:hover:bg-slate-800 transition-all disabled:opacity-30"
                >
                  Cancelar
                </button>
                <button 
                  type="submit" 
                  disabled={isSubmitting}
                  className="px-10 py-3.5 rounded-2xl bg-slate-900 dark:bg-slate-100 text-white dark:text-slate-900 font-black text-[11px] uppercase tracking-widest hover:bg-primary dark:hover:bg-primary dark:hover:text-white shadow-2xl transition-all active:scale-95 shadow-primary/20 disabled:bg-slate-400 flex items-center gap-3"
                >
                  {isSubmitting && (
                    <svg className="animate-spin h-4 w-4 text-white dark:text-slate-900" xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24">
                        <circle className="opacity-25" cx="12" cy="12" r="10" stroke="currentColor" strokeWidth="4"></circle>
                        <path className="opacity-75" fill="currentColor" d="M4 12a8 8 0 018-8V0C5.373 0 0 5.373 0 12h4zm2 5.291A7.962 7.962 0 014 12H0c0 3.042 1.135 5.824 3 7.938l3-2.647z"></path>
                    </svg>
                  )}
                  {isSubmitting ? 'Salvando...' : (isEditMode ? 'Salvar Alterações' : 'Salvar no Banco')}
                </button>
            </div>
        </form>
      </div>
    </div>
  );
};

import React, { useState, useCallback, useEffect, useRef, useMemo } from 'react';
import type { NewBook, Book, StatusConfigs } from '../types';
import { BookStatus, BookType, GENRES, STATUS_CONFIGS } from '../types';
import { XMarkIcon, BookOpenIcon, StarIcon, StarIconFilled, PlusIcon } from './Icons';
import { generateBookSummary, generateBookCover } from '../services/geminiService';

interface AddBookModalProps {
  onClose: () => void;
  onAddBook: (book: NewBook) => Promise<void>;
  onUpdateBook: (book: Book) => Promise<void>;
  bookToEdit?: Book | null;
  defaultStatus?: BookStatus;
  existingBooks: Book[];
  statusConfigs?: StatusConfigs;
}

interface FormErrors {
  title?: string;
  authors?: string;
  genre?: string;
}

export const AddBookModal: React.FC<AddBookModalProps> = ({ 
  onClose, 
  onAddBook, 
  onUpdateBook, 
  bookToEdit, 
  defaultStatus, 
  existingBooks, 
  statusConfigs = STATUS_CONFIGS 
}) => {
  const isEditMode = !!bookToEdit;

  const [title, setTitle] = useState(bookToEdit?.title || '');
  const [authors, setAuthors] = useState<string[]>(
    bookToEdit?.author ? bookToEdit.author.split(',').map(a => a.trim()).filter(a => a !== '') : []
  );
  const [authorInput, setAuthorInput] = useState('');
  const [pages, setPages] = useState(bookToEdit?.pages || 0);
  const [selectedGenres, setSelectedGenres] = useState<string[]>(
    bookToEdit?.genre ? bookToEdit.genre.split(',').map(g => g.trim()).filter(g => g !== '') : []
  );
  const [type, setType] = useState<BookType>(bookToEdit?.type || BookType.Book);
  const [status, setStatus] = useState<BookStatus>(bookToEdit?.status || defaultStatus || BookStatus.TBR);
  const [rating, setRating] = useState<number>(bookToEdit?.rating || 0);
  const [hoverRating, setHoverRating] = useState<number>(0);
  const [summary, setSummary] = useState(bookToEdit?.summary || '');
  const [notes, setNotes] = useState(bookToEdit?.notes || '');
  const [estimatedPrice, setEstimatedPrice] = useState(bookToEdit?.estimatedPrice?.toString() || '');
  const [buyLink, setBuyLink] = useState(bookToEdit?.buyLink || '');
  const [coverImageUrl, setCoverImageUrl] = useState<string>(bookToEdit?.coverImageUrl || '');
  const [isGeneratingCover, setIsGeneratingCover] = useState(false);
  const [isGeneratingSummary, setIsGeneratingSummary] = useState(false);
  const [isSubmitting, setIsSubmitting] = useState(false);

  const [dateAdded, setDateAdded] = useState(bookToEdit?.dateAdded || new Date().toISOString().split('T')[0]);

  const [dateFinished, setDateFinished] = useState(bookToEdit?.dateFinished || new Date().toISOString().split('T')[0]);
  const [daysToFinish, setDaysToFinish] = useState(bookToEdit?.daysToFinish?.toString() || '');
  const [timesRead, setTimesRead] = useState(bookToEdit?.timesRead || (bookToEdit?.status === BookStatus.Read ? 1 : 0));

  const [errors, setErrors] = useState<FormErrors>({});
  const [isShaking, setIsShaking] = useState(false);

  // Estados para Auto-complete
  const [titleSuggestions, setTitleSuggestions] = useState<string[]>([]);
  const [authorSuggestions, setAuthorSuggestions] = useState<string[]>([]);
  const [activeSuggestionIndex, setActiveSuggestionIndex] = useState(0);
  const [showTitleSug, setShowTitleSug] = useState(false);
  const [showAuthorSug, setShowAuthorSug] = useState(false);

  const titleRef = useRef<HTMLDivElement>(null);
  const authorRef = useRef<HTMLDivElement>(null);

  // Listas únicas de referência para sugestões
  const uniqueTitles = useMemo(() => Array.from(new Set(existingBooks.map(b => b.title))), [existingBooks]);
  const uniqueAuthors = useMemo(() => {
    const all = existingBooks.flatMap(b => b.author.split(',').map(a => a.trim()));
    return Array.from(new Set(all));
  }, [existingBooks]);

  useEffect(() => {
    const handleClickOutside = (event: MouseEvent) => {
      if (titleRef.current && !titleRef.current.contains(event.target as Node)) setShowTitleSug(false);
      if (authorRef.current && !authorRef.current.contains(event.target as Node)) setShowAuthorSug(false);
    };
    document.addEventListener('mousedown', handleClickOutside);
    return () => document.removeEventListener('mousedown', handleClickOutside);
  }, []);

  useEffect(() => {
    if (status === BookStatus.Read && !daysToFinish && bookToEdit?.dateStarted && dateFinished) {
        const start = new Date(bookToEdit.dateStarted);
        const end = new Date(dateFinished);
        const diffTime = end.getTime() - start.getTime();
        const diffDays = Math.ceil(diffTime / (1000 * 60 * 60 * 24));
        if (diffDays >= 0) setDaysToFinish(diffDays.toString());
    }
    if (status === BookStatus.Read && timesRead === 0) setTimesRead(1);
  }, [status, dateFinished]);

  const addAuthor = (name?: string) => {
    const val = name || authorInput.trim();
    if (val && !authors.includes(val)) {
      setAuthors([...authors, val]);
      setAuthorInput('');
      setShowAuthorSug(false);
      if (errors.authors) setErrors(prev => ({ ...prev, authors: undefined }));
    }
  };

  const removeAuthor = (name: string) => {
    setAuthors(authors.filter(a => a !== name));
  };

  const handleTitleChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const value = e.target.value;
    setTitle(value);
    if (errors.title) setErrors(prev => ({ ...prev, title: undefined }));

    if (value.trim().length > 0) {
      const filtered = uniqueTitles.filter(t => t.toLowerCase().includes(value.toLowerCase()) && t.toLowerCase() !== value.toLowerCase()).slice(0, 5);
      setTitleSuggestions(filtered);
      setShowTitleSug(filtered.length > 0);
      setActiveSuggestionIndex(0);
    } else {
      setShowTitleSug(false);
    }
  };

  const handleAuthorInputChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const value = e.target.value;
    setAuthorInput(value);

    if (value.trim().length > 0) {
      const filtered = uniqueAuthors.filter(a => a.toLowerCase().includes(value.toLowerCase()) && !authors.includes(a)).slice(0, 5);
      setAuthorSuggestions(filtered);
      setShowAuthorSug(filtered.length > 0);
      setActiveSuggestionIndex(0);
    } else {
      setShowAuthorSug(false);
    }
  };

  const handleKeyDown = (e: React.KeyboardEvent, type: 'title' | 'author') => {
    const suggestions = type === 'title' ? titleSuggestions : authorSuggestions;
    const show = type === 'title' ? showTitleSug : showAuthorSug;

    if (show && suggestions.length > 0) {
      if (e.key === 'ArrowDown') {
        e.preventDefault();
        setActiveSuggestionIndex(prev => (prev < suggestions.length - 1 ? prev + 1 : prev));
      } else if (e.key === 'ArrowUp') {
        e.preventDefault();
        setActiveSuggestionIndex(prev => (prev > 0 ? prev - 1 : 0));
      } else if (e.key === 'Enter') {
        e.preventDefault();
        const selected = suggestions[activeSuggestionIndex];
        if (type === 'title') {
          setTitle(selected);
          setShowTitleSug(false);
        } else {
          addAuthor(selected);
        }
      } else if (e.key === 'Escape') {
        type === 'title' ? setShowTitleSug(false) : setShowAuthorSug(false);
      }
    }
  };

  const toggleGenre = (genre: string) => {
    setSelectedGenres(prev => 
      prev.includes(genre) 
        ? prev.filter(g => g !== genre) 
        : [...prev, genre]
    );
    if (errors.genre) setErrors(prev => ({ ...prev, genre: undefined }));
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    if (isSubmitting) return;

    let finalAuthors = [...authors];
    if (authorInput.trim() && !finalAuthors.includes(authorInput.trim())) {
        finalAuthors.push(authorInput.trim());
    }

    const newErrors: FormErrors = {};
    const trimmedTitle = title.trim();

    // 1. Validação de Campo Obrigatório
    if (!trimmedTitle) {
      newErrors.title = "O título é obrigatório";
    } else {
      // 2. Validação de Duplicidade (Impedir dois livros com mesmo nome)
      const isDuplicate = existingBooks.some(b => 
        b.title.trim().toLowerCase() === trimmedTitle.toLowerCase() && 
        (!isEditMode || b.id !== bookToEdit?.id)
      );

      if (isDuplicate) {
        newErrors.title = "Já existe um livro com este título na sua biblioteca";
      }
    }

    if (finalAuthors.length === 0) newErrors.authors = "Adicione ao menos um autor";
    if (selectedGenres.length === 0) newErrors.genre = "Selecione ao menos um gênero";

    if (Object.keys(newErrors).length > 0) {
      setErrors(newErrors);
      setIsShaking(true);
      setTimeout(() => setIsShaking(false), 500);
      return;
    }

    setIsSubmitting(true);
    try {
        const bookData = { 
            title: trimmedTitle, 
            author: finalAuthors.join(', '), 
            pages, 
            genre: selectedGenres.join(', '), 
            type, 
            status, 
            summary, 
            notes,
            rating: status === BookStatus.Read ? (rating || undefined) : undefined,
            estimatedPrice: estimatedPrice ? parseFloat(estimatedPrice) : undefined,
            buyLink: buyLink.trim() || undefined,
            coverImageUrl: coverImageUrl.trim() || undefined, 
            dateAdded,
            currentPage: status === BookStatus.Read ? pages : (bookToEdit?.currentPage || 0),
            dateStarted: bookToEdit?.dateStarted,
            dateFinished: status === BookStatus.Read ? dateFinished : undefined,
            daysToFinish: status === BookStatus.Read && daysToFinish ? parseInt(daysToFinish, 10) : null,
            timesRead: status === BookStatus.Read ? Number(timesRead) : 0
        };
        if (isEditMode) {
            await onUpdateBook({ ...bookToEdit, ...bookData });
        } else {
            await onAddBook(bookData);
        }
    } finally {
        setIsSubmitting(false);
    }
  };

  const handleGenerateCover = useCallback(async () => {
    if (!title || selectedGenres.length === 0) return;
    setIsGeneratingCover(true);
    try {
      const result = await generateBookCover(title, selectedGenres[0], type, authors.join(', '));
      if (result) setCoverImageUrl(result);
    } finally {
      setIsGeneratingCover(false);
    }
  }, [title, selectedGenres, type, authors]);

  const handleGenerateSummary = useCallback(async () => {
    if (!title || authors.length === 0) return;
    setIsGeneratingSummary(true);
    try {
      const result = await generateBookSummary(title, authors.join(', '));
      if (result) setSummary(result);
    } catch (err) {
      console.error("Erro ao gerar resumo:", err);
    } finally {
      setIsGeneratingSummary(false);
    }
  }, [title, authors]);

  const labelClass = (isRequired: boolean) => 
    `block text-[10px] font-black uppercase tracking-[0.15em] mb-1.5 ml-1 flex items-center gap-1 ${isRequired ? 'text-slate-500 dark:text-slate-400' : 'text-slate-400 dark:text-slate-500'}`;

  const SuggestionDropdown = ({ suggestions, show, onSelect }: { suggestions: string[], show: boolean, onSelect: (val: string) => void }) => {
    if (!show || suggestions.length === 0) return null;
    return (
      <div className="absolute left-0 right-0 top-full mt-2 z-[60] bg-white/95 dark:bg-slate-900/95 backdrop-blur-md border border-slate-200 dark:border-slate-700 rounded-2xl shadow-2xl overflow-hidden animate-in fade-in slide-in-from-top-2 duration-200">
        {suggestions.map((suggestion, index) => (
          <button
            key={index}
            type="button"
            onMouseEnter={() => setActiveSuggestionIndex(index)}
            onClick={() => onSelect(suggestion)}
            className={`w-full text-left px-5 py-3 text-xs font-bold transition-colors ${activeSuggestionIndex === index ? 'bg-primary text-white' : 'text-slate-700 dark:text-slate-300 hover:bg-slate-50 dark:hover:bg-slate-800'}`}
          >
            {suggestion}
          </button>
        ))}
      </div>
    );
  };

  return (
    <div className="fixed inset-0 bg-slate-900/60 backdrop-blur-sm flex items-center justify-center z-50 p-4">
      <div 
        className={`bg-white dark:bg-slate-900 rounded-[2.5rem] shadow-2xl w-full max-w-2xl max-h-[90vh] overflow-hidden flex flex-col border border-white/20 dark:border-slate-800 transition-transform duration-500 ${isShaking ? 'animate-shake' : ''}`}
        style={{ animation: isShaking ? 'shake 0.4s cubic-bezier(.36,.07,.19,.97) both' : 'none' }}
      >
        <div className="p-7 border-b border-slate-100 dark:border-slate-800 flex justify-between items-center bg-slate-50/50 dark:bg-slate-800/30">
            <h2 className="text-2xl font-black font-serif text-slate-900 dark:text-slate-50 tracking-tight">{isEditMode ? 'Editar Registro' : 'Novo Registro'}</h2>
            <button onClick={onClose} disabled={isSubmitting} className="p-2.5 rounded-full hover:bg-slate-200 dark:hover:bg-slate-700 text-slate-400 transition-all hover:rotate-90 disabled:opacity-30">
                <XMarkIcon className="h-5 w-5" />
            </button>
        </div>

        <form onSubmit={handleSubmit} className="p-8 space-y-8 overflow-y-auto custom-scrollbar">
            <div className={`grid grid-cols-1 md:grid-cols-2 gap-8 ${isSubmitting ? 'opacity-50 pointer-events-none' : ''}`}>
                <div className="md:col-span-2 relative" ref={titleRef}>
                    <label className={labelClass(true)}>
                      Título <span className="text-red-500">*</span>
                    </label>
                    <input 
                      type="text" 
                      value={title} 
                      onChange={handleTitleChange}
