import React, { useState, useEffect } from 'react';
import { supabase } from '../services/supabase';
import { Logo } from './Logo';
import { XMarkIcon } from './Icons';

export const Auth: React.FC = () => {
  const [loading, setLoading] = useState(false);
  const [email, setEmail] = useState('');
  const [password, setPassword] = useState('');
  const [showPassword, setShowPassword] = useState(false);
  const [fullName, setFullName] = useState('');
  const [mode, setMode] = useState<'login' | 'signup'>('login');
  const [errorMsg, setErrorMsg] = useState<string | null>(null);
  const [needsEmailConfirmation, setNeedsEmailConfirmation] = useState(false);
  const [showHelp, setShowHelp] = useState(false);
  const [highlightSignup, setHighlightSignup] = useState(false);

  const currentKey = (supabase as any).supabaseKey || '';
  const isStripeKey = currentKey.startsWith('sb_');

  // Limpa erros e estados de destaque ao trocar de modo
  useEffect(() => {
    setErrorMsg(null);
    setHighlightSignup(false);
  }, [mode]);

  const handleAuth = async (e: React.FormEvent) => {
    e.preventDefault();
    setLoading(true);
    setErrorMsg(null);
    setHighlightSignup(false);

    if (isStripeKey) {
        setErrorMsg("Erro de Configuração: Chave do Stripe detectada. Use a chave 'anon public' do Supabase.");
        setLoading(false);
        return;
    }

    try {
      if (mode === 'login') {
        const { error, data } = await supabase.auth.signInWithPassword({ email, password });
        if (error) {
          console.error("Supabase Login Error:", error.message);

          // Tratamento amigável para erro de credenciais (usuário não existe ou senha errada)
          if (error.message.toLowerCase().includes('invalid login credentials')) {
             setHighlightSignup(true);
             setErrorMsg('E-mail ou senha incorretos. Se este é seu primeiro acesso, clique em CADASTRAR acima!');
             return;
          }

          if (error.message.toLowerCase().includes('email not confirmed')) {
             setErrorMsg('E-mail não confirmado. Verifique sua caixa de entrada (e spam) para ativar sua conta.');
             return;
          }

          setErrorMsg(error.message);
        }
      } else {
        if (password.length < 6) {
          setErrorMsg('A senha precisa ter no mínimo 6 caracteres.');
          return;
        }
        if (fullName.trim().length < 3) {
          setErrorMsg('Informe seu nome completo.');
          return;
        }

        const { error, data } = await supabase.auth.signUp({ 
          email, 
          password,
          options: { data: { full_name: fullName.trim() } }
        });

        if (error) {
            if (error.message.toLowerCase().includes('user already registered')) {
                setMode('login');
                setErrorMsg('E-mail já cadastrado. Tente entrar com sua senha!');
            } else {
                setErrorMsg(error.message);
            }
            return;
        }

        if (data.user && !data.session) {
           setNeedsEmailConfirmation(true);
        }
      }
    } catch (error: any) {
      setErrorMsg("Ocorreu um erro inesperado. Tente novamente.");
    } finally {
      setLoading(false);
    }
  };

  const handleForgotPassword = async () => {
    if (!email) {
        setErrorMsg("Digite seu e-mail para recuperar a senha.");
        return;
    }
    setLoading(true);
    try {
        const { error } = await supabase.auth.resetPasswordForEmail(email);
        if (error) throw error;
        setErrorMsg("Link de recuperação enviado com sucesso!");
    } catch (error: any) {
        setErrorMsg(error.message);
    } finally {
        setLoading(false);
    }
  };

  if (needsEmailConfirmation) {
    return (
      <div className="min-h-screen bg-background dark:bg-slate-950 flex flex-col items-center justify-center p-6">
        <div className="w-full max-w-md bg-white dark:bg-slate-900 rounded-[2.5rem] shadow-2xl border border-emerald-100 dark:border-emerald-900/30 p-10 text-center animate-in zoom-in duration-500">
          <div className="bg-emerald-500 w-16 h-16 rounded-full flex items-center justify-center mx-auto mb-6 shadow-lg">
            <svg xmlns="http://www.w3.org/2000/svg" className="h-8 w-8 text-white" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={3} d="M5 13l4 4L19 7" />
            </svg>
          </div>
          <h2 className="text-2xl font-black text-slate-900 dark:text-slate-50 mb-4 font-serif italic">Ative sua conta!</h2>
          <p className="text-slate-500 dark:text-slate-400 text-sm leading-relaxed mb-8">
            Enviamos um e-mail para <b>{email}</b>. Clique no link de confirmação para liberar seu acesso.
          </p>
          <button 
            onClick={() => setNeedsEmailConfirmation(false)}
            className="w-full py-4 bg-slate-100 dark:bg-slate-800 rounded-2xl text-[10px] font-black uppercase tracking-widest text-slate-600 dark:text-slate-400 hover:bg-slate-200 transition-all shadow-md"
          >
            Voltar para Login
          </button>
        </div>
      </div>
    );
  }

  return (
    <div className="min-h-screen bg-background dark:bg-slate-950 flex flex-col items-center justify-center p-6 font-sans">
      <div className="w-full max-w-md bg-white dark:bg-slate-900 rounded-[2.5rem] shadow-2xl border border-slate-100 dark:border-slate-800 p-10 transition-all relative overflow-hidden">

        <div className="flex flex-col items-center mb-10 pt-4">
            <Logo size="lg" className="mb-6" showText={true} />

            <div className="flex w-full bg-slate-50 dark:bg-slate-800/50 p-1 rounded-2xl border border-slate-100 dark:border-slate-700">
                <button 
                    onClick={() => setMode('login')}
                    className={`flex-1 py-3 text-[10px] font-black uppercase tracking-widest rounded-xl transition-all ${mode === 'login' ? 'bg-white dark:bg-slate-700 text-primary shadow-md' : 'text-slate-400 hover:text-slate-600'}`}
                >
                    Entrar
                </button>
                <button 
                    onClick={() => setMode('signup')}
                    className={`flex-1 py-3 text-[10px] font-black uppercase tracking-widest rounded-xl transition-all ${mode === 'signup' ? 'bg-white dark:bg-slate-700 text-primary shadow-md' : 'text-slate-400 hover:text-slate-600'} ${highlightSignup ? 'animate-pulse ring-4 ring-primary/30 border-primary bg-primary/5 text-primary' : ''}`}
                >
                    Cadastrar
                </button>
            </div>
        </div>

        <form onSubmit={handleAuth} className="space-y-6">
          {mode === 'signup' && (
            <div className="animate-in slide-in-from-top-2 duration-300">
              <label className="block text-[10px] font-black uppercase tracking-widest text-slate-400 mb-2 ml-1">Nome Completo</label>
              <input
                type="text"
                placeholder="Ex: João Silva"
                value={fullName}
                onChange={(e) => setFullName(e.target.value)}
                className="w-full bg-slate-50 dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-2xl px-5 py-3.5 outline-none focus:border-primary font-medium dark:text-white transition-all shadow-sm"
                required={mode === 'signup'}
              />
            </div>
          )}

          <div>
            <label className="block text-[10px] font-black uppercase tracking-widest text-slate-400 mb-2 ml-1">E-mail</label>
            <input
              type="email"
              placeholder="exemplo@email.com"
              value={email}
              onChange={(e) => setEmail(e.target.value)}
              className="w-full bg-slate-50 dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-2xl px-5 py-3.5 outline-none focus:border-primary font-medium dark:text-white transition-all shadow-sm"
              required
            />
          </div>

          <div>
            <div className="flex justify-between items-center mb-2 ml-1">
                <label className="block text-[10px] font-black uppercase tracking-widest text-slate-400">Senha</label>
                <button type="button" onClick={() => setShowPassword(!showPassword)} className="text-[9px] font-bold text-primary uppercase hover:underline">
                    {showPassword ? 'Ocultar' : 'Mostrar'}
                </button>
            </div>
            <input
              type={showPassword ? 'text' : 'password'}
              placeholder="••••••••"
              value={password}
              onChange={(e) => setPassword(e.target.value)}
              className="w-full bg-slate-50 dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-2xl px-5 py-3.5 outline-none focus:border-primary font-medium dark:text-white transition-all shadow-sm"
              required
            />
          </div>

          {errorMsg && (
            <div className={`p-4 rounded-2xl border animate-shake space-y-3 ${errorMsg.includes('sucesso') ? 'bg-emerald-50 dark:bg-emerald-900/20 text-emerald-600 border-emerald-100' : 'bg-red-50 dark:bg-red-900/20 text-red-500 border-red-100 dark:border-red-900/30'}`}>
              <p className="text-[10px] font-bold uppercase leading-relaxed text-center">{errorMsg}</p>
              {highlightSignup && mode === 'login' && (
                  <button 
                    type="button"
                    onClick={() => setMode('signup')}
                    className="w-full bg-blue-600 text-white py-3 rounded-xl text-[9px] tracking-widest shadow-md hover:bg-blue-700 transition-all font-black uppercase"
                  >
                    Clique aqui para criar sua conta
                  </button>
              )}
            </div>
          )}

          <button
            type="submit"
            disabled={loading}
            className="w-full bg-primary text-white font-black text-[11px] uppercase tracking-widest py-4 rounded-2xl shadow-xl hover:bg-slate-900 dark:hover:bg-white dark:hover:text-slate-900 transition-all active:scale-95 disabled:opacity-50"
          >
            {loading ? 'Processando...' : mode === 'login' ? 'Entrar no BiblioTech' : 'Criar minha conta'}
          </button>

          {mode === 'login' && (
              <button 
                type="button" 
                onClick={handleForgotPassword}
                className="w-full text-center text-[9px] font-black text-slate-400 uppercase tracking-widest hover:text-primary transition-colors"
              >
                Esqueci minha senha
              </button>
          )}
        </form>

        <div className="mt-8 pt-6 border-t border-slate-50 dark:border-slate-800 text-center">
            <button 
                onClick={() => setShowHelp(true)}
                className="text-[9px] font-black text-slate-400 uppercase tracking-widest hover:text-primary transition-colors"
            >
                Ajuda com Acesso
            </button>
        </div>
      </div>

      {showHelp && (
        <div className="fixed inset-0 bg-slate-900/80 backdrop-blur-md flex items-center justify-center z-[100] p-6">
            <div className="bg-white dark:bg-slate-900 rounded-[2.5rem] p-8 max-w-lg w-full shadow-2xl border border-white/20 relative animate-in zoom-in duration-300">
                <button onClick={() => setShowHelp(false)} className="absolute top-6 right-6 p-2 rounded-full hover:bg-slate-100 dark:hover:bg-slate-800 transition-all"><XMarkIcon className="h-5 w-5"/></button>
                <h3 className="text-2xl font-black font-serif italic mb-6">Problemas de Acesso?</h3>
                <div className="space-y-4">
                    <p className="text-sm text-slate-600 dark:text-slate-400">• Se você recebe "Invalid login credentials", verifique se já criou sua conta na aba <b>CADASTRAR</b>.</p>
                    <p className="text-sm text-slate-600 dark:text-slate-400">• O cadastro no Supabase exige que o e-mail seja real, pois o link de ativação é enviado para você.</p>
                    <p className="text-sm text-slate-600 dark:text-slate-400">• Verifique se não há espaços extras no início ou fim do seu e-mail.</p>
                </div>
                <button 
                    onClick={() => setShowHelp(false)}
                    className="w-full bg-primary text-white font-black text-[11px] uppercase tracking-widest py-4 rounded-2xl mt-8 shadow-xl active:scale-95"
                >
                    Entendido!
                </button>
            </div>
        </div>
      )}
    </div>
  );
};

import type { Book, Profile } from '../types';
import { supabase } from './supabase';
import { BookStatus } from '../types';

const TABLE_NAME = 'books';
const BASE_LOCAL_STORAGE_KEY = 'biblio_tech_cache_';

const mapBookToDb = (book: any) => {
    const dateAddedValue = book.dateAdded || new Date().toISOString().split('T')[0];
    return {
        id: book.id,
        user_id: book.user_id,
        title: book.title || 'Sem Título',
        author: book.author || 'Autor Desconhecido',
        pages: Math.floor(parseInt(String(book.pages || 0), 10)),
        genre: book.genre || '',
        type: book.type || 'Livro',
        status: book.status || 'Não lido',
        rating: (book.rating !== undefined && book.rating !== null && book.rating !== 0) ? parseFloat(String(book.rating)) : null,
        cover_image_url: book.coverImageUrl || null,
        summary: book.summary || null,
        notes: book.notes || null,
        estimated_price: (book.estimatedPrice !== undefined && book.estimatedPrice !== null) ? parseFloat(String(book.estimatedPrice)) : null,
        price_paid: (book.pricePaid !== undefined && book.pricePaid !== null) ? parseFloat(String(book.pricePaid)) : null,
        buy_link: book.buyLink || null,
        current_page: Math.floor(parseInt(String(book.currentPage || 0), 10)),
        date_added: dateAddedValue,
        date_started: book.dateStarted || null,
        date_finished: book.dateFinished || null,
        days_to_finish: (book.daysToFinish !== undefined && book.daysToFinish !== null) ? Math.floor(parseInt(String(book.daysToFinish), 10)) : null,
        times_read: (book.timesRead !== undefined && book.timesRead !== null) ? Math.floor(parseInt(String(book.timesRead), 10)) : 0,
        was_wishlist: book.wasWishlist === true
    };
};

const mapDbToBook = (db: any): Book => ({
    id: db.id,
    user_id: db.user_id,
    title: db.title,
    author: db.author,
    pages: db.pages || 0,
    genre: db.genre || '',
    type: db.type,
    status: db.status as BookStatus,
    rating: db.rating ? parseFloat(String(db.rating)) : undefined,
    coverImageUrl: db.cover_image_url,
    summary: db.summary,
    notes: db.notes,
    estimatedPrice: db.estimated_price ? parseFloat(String(db.estimated_price)) : undefined,
    pricePaid: db.price_paid ? parseFloat(String(db.price_paid)) : undefined,
    buyLink: db.buy_link,
    currentPage: db.current_page || 0,
    dateAdded: db.date_added,
    dateStarted: db.date_started,
    dateFinished: db.date_finished,
    daysToFinish: db.days_to_finish,
    timesRead: db.times_read || 0,
    wasWishlist: db.was_wishlist === true
});

const mapDbToProfile = (db: any): Profile => ({
    id: db.id,
    fullName: db.full_name,
    avatarUrl: db.avatar_url,
    readingGoal: db.reading_goal || 12
});

export class DatabaseService {
  private isSchemaBroken = false;
  private brokenDetail = '';
  private onSchemaErrorCallback?: (type: 'table' | 'column' | 'permission', detail?: string) => void;

  setSchemaErrorCallback(cb: (type: 'table' | 'column' | 'permission', detail?: string) => void) {
    this.onSchemaErrorCallback = cb;
  }

  private async getCacheKey(): Promise<string | null> {
    const { data: { user } } = await supabase.auth.getUser();
    return user ? `${BASE_LOCAL_STORAGE_KEY}${user.id}` : null;
  }

  private async getLocalBooks(): Promise<Book[]> {
    const key = await this.getCacheKey();
    if (!key) return [];
    try {
      const data = localStorage.getItem(key);
      return data ? JSON.parse(data) : [];
    } catch (e) {
      return [];
    }
  }

  private async saveLocalBooks(books: Book[]): Promise<void> {
    const key = await this.getCacheKey();
    if (!key) return;
    try {
      localStorage.setItem(key, JSON.stringify(books));
    } catch (e: any) {
      console.warn("Local Storage falhou, dados mantidos apenas em memória.");
    }
  }

  async getAllBooks(): Promise<Book[]> {
    try {
      const { data, error } = await supabase
        .from(TABLE_NAME)
        .select('*')
        .order('date_added', { ascending: false });

      if (error) {
        console.error(`Erro ao buscar livros no Supabase [${error.code}]: ${error.message}`);
        this.handleSupabaseError(error);
        return await this.getLocalBooks();
      }

      this.isSchemaBroken = false;
      const books = (data || []).map(mapDbToBook);
      await this.saveLocalBooks(books);
      return books;
    } catch (err: any) {
      console.error("Erro inesperado em getAllBooks:", err.message || err);
      return await this.getLocalBooks();
    }
  }

  async getQuickStatsSummary() {
    if (this.isSchemaBroken) return null;

    try {
      const { data: { user } } = await supabase.auth.getUser();
      if (!user) return null;

      const [read, tbr, wishlist, dropped] = await Promise.all([
        supabase.from(TABLE_NAME).select('*', { count: 'exact', head: true }).eq('status', 'Lido').eq('user_id', user.id),
        supabase.from(TABLE_NAME).select('*', { count: 'exact', head: true }).eq('status', 'Não lido').eq('user_id', user.id),
        supabase.from(TABLE_NAME).select('*', { count: 'exact', head: true }).eq('status', 'Lista de Desejos').eq('user_id', user.id),
        supabase.from(TABLE_NAME).select('*', { count: 'exact', head: true }).eq('status', 'Abandonado').eq('user_id', user.id)
      ]);

      return {
        readCount: read.count || 0,
        tbrCount: tbr.count || 0,
        wishlistCount: wishlist.count || 0,
        droppedCount: dropped.count || 0
      };
    } catch (err) {
      return null;
    }
  }

  async saveBook(book: Partial<Book>): Promise<void> {
    const { data: { user } } = await supabase.auth.getUser();
    if (!user) {
        throw new Error("Usuário não identificado. Faça login novamente.");
    }

    const dbPayload = mapBookToDb(book);
    dbPayload.user_id = user.id;

    const books = await this.getLocalBooks();
    const index = books.findIndex(b => b.id === (book.id || dbPayload.id));
    const updatedBookState = mapDbToBook(dbPayload);

    if (index >= 0) books[index] = updatedBookState;
    else books.unshift(updatedBookState);
    await this.saveLocalBooks(books);

    if (this.isSchemaBroken) {
        throw new Error(`O banco de dados está desatualizado. Por favor, execute o script SQL.`);
    }

    const { error } = await supabase.from(TABLE_NAME).upsert(dbPayload);
    if (error) {
        console.error(`Supabase Upsert Error [${error.code}]: ${error.message}`);
        this.handleSupabaseError(error);
        throw new Error(`Erro ao salvar na nuvem: ${error.message}`);
    }
  }

  async deleteBook(id: string): Promise<void> {
    const books = (await this.getLocalBooks()).filter(b => b.id !== id);
    await this.saveLocalBooks(books);

    if (this.isSchemaBroken) return;
    const { error } = await supabase.from(TABLE_NAME).delete().eq('id', id);
    if (error) {
        console.error(`Erro ao deletar livro no Supabase [${error.code}]: ${error.message}`);
    }
  }

  async updateReadingGoal(goal: number): Promise<void> {
    const { data: { user } } = await supabase.auth.getUser();
    if (!user) throw new Error("Usuário não identificado.");
    const cleanGoal = Math.round(goal);
    const { error } = await supabase.from('profiles').upsert({ 
        id: user.id, 
        reading_goal: cleanGoal, 
        updated_at: new Date().toISOString() 
    });
    if (error) {
        console.error("Erro ao salvar meta:", error.message);
        throw error;
    }
  }

  async updateProfile(profile: Partial<Profile>): Promise<void> {
    const { data: { user } } = await supabase.auth.getUser();
    if (!user) throw new Error("Usuário não identificado.");
    const dbPayload: any = { id: user.id, updated_at: new Date().toISOString() };
    if (profile.fullName !== undefined) dbPayload.full_name = profile.fullName;
    if (profile.avatarUrl !== undefined) dbPayload.avatar_url = profile.avatarUrl;

    const { error } = await supabase.from('profiles').upsert(dbPayload);
    if (error) {
        console.error("Erro ao atualizar perfil:", error.message);
        throw error;
    }
  }

  async getProfile(): Promise<Profile | null> {
    const { data: { user } } = await supabase.auth.getUser();
    if (!user) return null;
    try {
        const { data, error } = await supabase.from('profiles').select('*').eq('id', user.id).single();
        if (error || !data) return { id: user.id, fullName: 'Leitor', readingGoal: 12 };
        return mapDbToProfile(data);
    } catch (err) {
        return { id: user.id, fullName: 'Leitor', readingGoal: 12 };
    }
  }

  private handleSupabaseError(error: any) {
    if (error.code === '42P01' || error.code === 'PGRST204' || error.code === 'PGRST107' || error.code === '22P02') {
        this.isSchemaBroken = true;
        this.brokenDetail = error.message;
        const msg = error.code === '22P02' 
            ? 'Erro de tipo de dados. Rode o script de migração SQL v14.' 
            : 'Tabela ou Schema desatualizado. Verifique o SQL Editor no painel do Supabase.';
        if (this.onSchemaErrorCallback) this.onSchemaErrorCallback('table', msg);
    }
  }
}

export const dbService = new DatabaseService();

import React, { useState, useMemo, useEffect } from 'react';
import { useBookData } from './hooks/useBookData';
import { Header } from './components/Header';
import { Dashboard } from './components/Dashboard';
import { AddBookModal } from './components/AddBookModal';
import { SettingsModal } from './components/SettingsModal';
import { PlusIcon, XMarkIcon } from './components/Icons';
import type { Book, NewBook, Profile } from './types';
import { BookList } from './components/BookList';
import { ConfirmationModal } from './components/ConfirmationModal';
import { BookStatus } from './types';
import { Wishlist } from './components/Wishlist';
import { BottomNav } from './components/BottomNav';
import { Auth } from './components/Auth';
import { StatsView } from './components/StatsView';
import { PricePaidModal } from './components/PricePaidModal'; // Novo Import
import { supabase } from './services/supabase';
import { dbService } from './services/database';

export default function App() {
  const [session, setSession] = useState<any>(null);
  const [isAuthLoading, setIsAuthLoading] = useState(true);
  const [userProfile, setUserProfile] = useState<Profile | null>(null);
  const [hasApiKey, setHasApiKey] = useState<boolean>(true);

  useEffect(() => {
    supabase.auth.getSession().then(({ data: { session } }) => {
      setSession(session);
      setIsAuthLoading(false);
    });
    const { data: { subscription } } = supabase.auth.onAuthStateChange((_event, session) => {
      setSession(session);
    });
    return () => subscription.unsubscribe();
  }, []);

  useEffect(() => {
    if (session) {
      dbService.getProfile().then(profile => {
        if (profile) {
          setUserProfile(profile);
          if (profile.readingGoal) setReadingGoal(profile.readingGoal);
          checkPlatformApiKey();
        }
      });
    }
  }, [session]);

  const checkPlatformApiKey = async () => {
    if (window.aistudio) {
        const selected = await window.aistudio.hasSelectedApiKey();
        setHasApiKey(selected);
    } else {
        const envKey = process.env.API_KEY;
        setHasApiKey(!!(envKey && envKey !== 'undefined' && envKey !== ''));
    }
  };

  const { 
    books, stats, currentlyReading, addBook, updateBook, deleteBook, 
    dateFilter, setDateFilter, selectedYear, setSelectedYear, availableYears,
    customRange, setCustomRange, isLocalMode, schemaError, isLoading
  } = useBookData();

  const [theme, setTheme] = useState<'light' | 'dark'>(() => (localStorage.getItem('theme') as 'light' | 'dark') || 'light');
  const [readingGoal, setReadingGoal] = useState(() => parseInt(localStorage.getItem('biblio_tech_goal') || '12', 10));

  const handleSetReadingGoal = async (val: number) => {
    try {
        setReadingGoal(val);
        localStorage.setItem('biblio_tech_goal', val.toString());
        await dbService.updateReadingGoal(val);
        showToast("Meta de leitura atualizada.");
    } catch (err: any) {
        showToast(`Erro ao salvar meta: ${err.message}`);
    }
  };

  const handleUpdateProfile = async (updates: Partial<Profile>) => {
    if (userProfile) {
        try {
            const newProfile = { ...userProfile, ...updates };
            setUserProfile(newProfile);
            await dbService.updateProfile(updates);
            checkPlatformApiKey();
            showToast("Perfil atualizado.");
        } catch (err: any) {
            showToast(`Erro ao atualizar perfil: ${err.message}`);
        }
    }
  };

  const [isModalOpen, setIsModalOpen] = useState(false);
  const [isSettingsOpen, setIsSettingsOpen] = useState(false);
  const [view, setView] = useState<'dashboard' | 'list' | 'wishlist' | 'stats'>('dashboard');
  const [editingBook, setEditingBook] = useState<Book | null>(null);
  const [isDuplicating, setIsDuplicating] = useState(false);
  const [deletingBook, setDeletingBook] = useState<Book | null>(null);
  const [convertingBook, setConvertingBook] = useState<Book | null>(null); // Estado para o modal de preço
  const [defaultStatusForModal, setDefaultStatusForModal] = useState<BookStatus | undefined>();
  const [toastMessage, setToastMessage] = useState<string | null>(null);

  useEffect(() => {
    theme === 'dark' ? document.documentElement.classList.add('dark') : document.documentElement.classList.remove('dark');
    localStorage.setItem('theme', theme);
  }, [theme]);

  const showToast = (message: string) => {
    setToastMessage(message);
    setTimeout(() => setToastMessage(null), 3500);
  };

  const handleAddBook = async (newBook: NewBook) => {
    try {
        await addBook(newBook);
        setIsModalOpen(false);
        showToast(`"${newBook.title}" salvo!`);
    } catch (err: any) {
        showToast(`Erro ao salvar: ${err.message}`);
    }
  };

  const handleUpdateBook = async (updatedBook: Book) => {
    try {
        await updateBook(updatedBook);
        setIsModalOpen(false);
        showToast(`"${updatedBook.title}" atualizado.`);
    } catch (err: any) {
        showToast(`Erro ao atualizar: ${err.message}`);
    }
  };

  const handleFinishConversion = async (price: number) => {
    if (convertingBook) {
      const updated: Book = {
        ...convertingBook,
        status: BookStatus.TBR,
        wasWishlist: true,
        pricePaid: price,
        dateAdded: new Date().toISOString().split('T')[0] // Data da "compra" vira data de adição na estante
      };
      await handleUpdateBook(updated);
      setConvertingBook(null);
      showToast("Movido para sua estante!");
    }
  };

  const openAddModal = (status?: BookStatus) => {
    setEditingBook(null);
    setIsDuplicating(false);
    setDefaultStatusForModal(status);
    setIsModalOpen(true);
  };

  const handleDuplicateRequest = (book: Book) => {
    setEditingBook(book);
    setIsDuplicating(true);
    setIsModalOpen(true);
  };

  if (isAuthLoading) return <div className="min-h-screen bg-background flex items-center justify-center"><div className="w-10 h-10 border-4 border-primary border-t-transparent rounded-full animate-spin"></div></div>;
  if (!session) return <Auth />;
  if (isLoading) return <div className="min-h-screen bg-background flex flex-col items-center justify-center p-4"><div className="w-12 h-12 border-4 border-primary border-t-transparent rounded-full animate-spin mb-4"></div><p className="text-[10px] font-black uppercase tracking-widest text-slate-400">Sincronizando...</p></div>;

  return (
    <div className="min-h-screen bg-background dark:bg-slate-950 text-text-main dark:text-slate-200 pb-24 relative transition-colors duration-300">
      <Header 
        profile={userProfile} onLogoClick={() => setView('dashboard')} onSettingsClick={() => setIsSettingsOpen(true)}
        theme={theme} toggleTheme={() => setTheme(t => t === 'light' ? 'dark' : 'light')} 
        isConnected={!isLocalMode} hasApiKey={hasApiKey}
      />

      {schemaError && (
        <div className="bg-red-600 text-white px-6 py-3 text-center text-[10px] font-black uppercase tracking-widest flex items-center justify-center gap-4 animate-in slide-in-from-top duration-500">
          <div className="flex-1">
             ⚠️ Erro de Sincronização: {schemaError.detail || "O banco de dados está desatualizado."} 
             <span className="block mt-1 font-bold opacity-80">Rode o script SQL do arquivo instrucoes_sql.txt no painel do Supabase!</span>
          </div>
        </div>
      )}

      {!hasApiKey && !schemaError && (
        <div className="bg-red-500 text-white px-6 py-2 text-center text-[10px] font-black uppercase tracking-widest animate-pulse cursor-pointer" onClick={() => setIsSettingsOpen(true)}>
          IA Indisponível: Clique aqui para configurar sua Chave de API nas Preferências.
        </div>
      )}

      <main className="p-4 md:p-8">
        {view === 'dashboard' && <Dashboard stats={stats} currentlyReading={currentlyReading} updateBook={handleUpdateBook} dateFilter={dateFilter} setDateFilter={setDateFilter} selectedYear={selectedYear} setSelectedYear={setSelectedYear} availableYears={availableYears} books={books} customRange={customRange} setCustomRange={setCustomRange} readingGoal={readingGoal} onSetReadingGoal={handleSetReadingGoal} />}
        {view === 'list' && <BookList books={books.filter(b => b.status !== BookStatus.Wishlist)} onEdit={(b) => { setEditingBook(b); setIsDuplicating(false); setIsModalOpen(true); }} onDelete={setDeletingBook} onDuplicate={handleDuplicateRequest} onUpdateBook={handleUpdateBook} />}
        {view === 'wishlist' && <Wishlist books={books.filter(b => b.status === BookStatus.Wishlist)} onEdit={(b) => { setEditingBook(b); setIsDuplicating(false); setIsModalOpen(true); }} onDelete={setDeletingBook} onDuplicate={handleDuplicateRequest} onMoveToShelf={(b) => setConvertingBook(b)} onAddWishlistItem={() => openAddModal(BookStatus.Wishlist)} />}
        {view === 'stats' && <StatsView books={books} availableYears={availableYears} />}
      </main>

      <div className="fixed bottom-24 right-6 flex flex-col gap-3">
        <button onClick={() => openAddModal()} className="bg-primary text-background p-4 rounded-full shadow-2xl hover:bg-blue-700 transition-all z-40 active:scale-95"><PlusIcon className="h-6 w-6" /></button>
      </div>

      <BottomNav view={view} setView={setView} />
      {toastMessage && <div className="fixed bottom-32 left-1/2 -translate-x-1/2 z-[60] animate-in fade-in slide-in-from-bottom-4 duration-500"><div className="bg-slate-900 text-white px-6 py-3.5 rounded-2xl shadow-2xl border border-white/10 flex items-center gap-3"><p className="text-[11px] font-black uppercase tracking-widest">{toastMessage}</p></div></div>}

      {isModalOpen && <AddBookModal onClose={() => setIsModalOpen(false)} onAddBook={handleAddBook} onUpdateBook={handleUpdateBook} bookToEdit={editingBook} isDuplicating={isDuplicating} defaultStatus={defaultStatusForModal} existingBooks={books} />}

      {convertingBook && <PricePaidModal book={convertingBook} onClose={() => setConvertingBook(null)} onConfirm={handleFinishConversion} />}

      {isSettingsOpen && <SettingsModal onClose={() => setIsSettingsOpen(false)} readingGoal={readingGoal} onSetReadingGoal={handleSetReadingGoal} profile={userProfile} onUpdateProfile={handleUpdateProfile} />}

      {deletingBook && <ConfirmationModal isOpen={!!deletingBook} onClose={() => setDeletingBook(null)} onConfirm={async () => { await deleteBook(deletingBook.id); setDeletingBook(null); showToast(`Removido.`); }} title="Excluir" message={`Apagar "${deletingBook.title}"?`} />}
    </div>
  );
}

import React, { useState, useCallback, useEffect, useRef, useMemo } from 'react';
import type { NewBook, Book, StatusConfigs } from '../types';
import { BookStatus, BookType, GENRES, STATUS_CONFIGS } from '../types';
import { XMarkIcon, BookOpenIcon, StarIcon, StarIconFilled, PlusIcon, TagIcon } from './Icons';
import { generateBookSummary, generateBookCover } from '../services/geminiService';

interface AddBookModalProps {
  onClose: () => void;
  onAddBook: (book: NewBook) => Promise<void>;
  onUpdateBook: (book: Book) => Promise<void>;
  bookToEdit?: Book | null;
  isDuplicating?: boolean;
  defaultStatus?: BookStatus;
  existingBooks: Book[];
  statusConfigs?: StatusConfigs;
}

interface FormErrors {
  title?: string;
  authors?: string;
  genre?: string;
}

export const AddBookModal: React.FC<AddBookModalProps> = ({ 
  onClose, 
  onAddBook, 
  onUpdateBook, 
  bookToEdit, 
  isDuplicating = false,
  defaultStatus, 
  existingBooks, 
  statusConfigs = STATUS_CONFIGS 
}) => {
  const isEditMode = !!bookToEdit && !isDuplicating;

  const [title, setTitle] = useState(bookToEdit?.title || '');
  const [authors, setAuthors] = useState<string[]>(
    bookToEdit?.author ? bookToEdit.author.split(',').map(a => a.trim()).filter(a => a !== '') : []
  );
  const [authorInput, setAuthorInput] = useState('');
  const [pages, setPages] = useState(bookToEdit?.pages || 0);
  const [currentPage, setCurrentPage] = useState(isDuplicating ? 0 : (bookToEdit?.currentPage || 0));
  const [selectedGenres, setSelectedGenres] = useState<string[]>(
    bookToEdit?.genre ? bookToEdit.genre.split(',').map(g => g.trim()).filter(g => g !== '') : []
  );
  const [type, setType] = useState<BookType>(bookToEdit?.type || BookType.Book);
  const [status, setStatus] = useState<BookStatus>(bookToEdit?.status || defaultStatus || BookStatus.TBR);
  const [rating, setRating] = useState<number>(isDuplicating ? 0 : (bookToEdit?.rating || 0));
  const [summary, setSummary] = useState(bookToEdit?.summary || '');
  const [notes, setNotes] = useState(isDuplicating ? '' : (bookToEdit?.notes || ''));
  const [estimatedPrice, setEstimatedPrice] = useState(bookToEdit?.estimatedPrice?.toString() || '');
  const [pricePaid, setPricePaid] = useState(isDuplicating ? '' : (bookToEdit?.pricePaid?.toString() || ''));
  const [buyLink, setBuyLink] = useState(bookToEdit?.buyLink || '');
  const [coverImageUrl, setCoverImageUrl] = useState<string>(bookToEdit?.coverImageUrl || '');
  const [isGeneratingCover, setIsGeneratingCover] = useState(false);
  const [isGeneratingSummary, setIsGeneratingSummary] = useState(false);
  const [isSubmitting, setIsSubmitting] = useState(false);

  const [dateAdded, setDateAdded] = useState(isDuplicating ? new Date().toISOString().split('T')[0] : (bookToEdit?.dateAdded || new Date().toISOString().split('T')[0]));
  const [dateFinished, setDateFinished] = useState(isDuplicating ? new Date().toISOString().split('T')[0] : (bookToEdit?.dateFinished || new Date().toISOString().split('T')[0]));
  const [daysToFinish, setDaysToFinish] = useState(isDuplicating ? '' : (bookToEdit?.daysToFinish?.toString() || ''));
  const [timesRead, setTimesRead] = useState(isDuplicating ? 0 : (bookToEdit?.timesRead || (bookToEdit?.status === BookStatus.Read ? 1 : 0)));

  const [errors, setErrors] = useState<FormErrors>({});
  const [isShaking, setIsShaking] = useState(false);

  const [titleSuggestions, setTitleSuggestions] = useState<string[]>([]);
  const [authorSuggestions, setAuthorSuggestions] = useState<string[]>([]);
  const [activeSuggestionIndex, setActiveSuggestionIndex] = useState(0);
  const [showTitleSug, setShowTitleSug] = useState(false);
  const [showAuthorSug, setShowAuthorSug] = useState(false);

  const titleRef = useRef<HTMLDivElement>(null);
  const authorRef = useRef<HTMLDivElement>(null);

  const uniqueTitles = useMemo(() => Array.from(new Set(existingBooks.map(b => b.title))), [existingBooks]);
  const uniqueAuthors = useMemo(() => {
    const all = existingBooks.flatMap(b => b.author.split(',').map(a => a.trim()));
    return Array.from(new Set(all));
  }, [existingBooks]);

  useEffect(() => {
    const handleClickOutside = (event: MouseEvent) => {
      if (titleRef.current && !titleRef.current.contains(event.target as Node)) setShowTitleSug(false);
      if (authorRef.current && !authorRef.current.contains(event.target as Node)) setShowAuthorSug(false);
    };
    document.addEventListener('mousedown', handleClickOutside);
    return () => document.removeEventListener('mousedown', handleClickOutside);
  }, []);

  const addAuthor = (name?: string) => {
    const val = name || authorInput.trim();
    if (val && !authors.includes(val)) {
      setAuthors([...authors, val]);
      setAuthorInput('');
      setShowAuthorSug(false);
      if (errors.authors) setErrors(prev => ({ ...prev, authors: undefined }));
    }
  };

  const removeAuthor = (name: string) => {
    setAuthors(authors.filter(a => a !== name));
  };

  const handleTitleChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const value = e.target.value;
    setTitle(value);
    if (errors.title) setErrors(prev => ({ ...prev, title: undefined }));
    if (value.trim().length > 0) {
      const filtered = uniqueTitles.filter(t => t.toLowerCase().includes(value.toLowerCase()) && t.toLowerCase() !== value.toLowerCase()).slice(0, 5);
      setTitleSuggestions(filtered);
      setShowTitleSug(filtered.length > 0);
      setActiveSuggestionIndex(0);
    } else {
      setShowTitleSug(false);
    }
  };

  const handleAuthorInputChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const value = e.target.value;
    setAuthorInput(value);
    if (value.trim().length > 0) {
      const filtered = uniqueAuthors.filter(a => a.toLowerCase().includes(value.toLowerCase()) && !authors.includes(a)).slice(0, 5);
      setAuthorSuggestions(filtered);
      setShowAuthorSug(filtered.length > 0);
      setActiveSuggestionIndex(0);
    } else {
      setShowAuthorSug(false);
    }
  };

  const handleKeyDown = (e: React.KeyboardEvent, type: 'title' | 'author') => {
    const suggestions = type === 'title' ? titleSuggestions : authorSuggestions;
    const show = type === 'title' ? showTitleSug : showAuthorSug;
    if (show && suggestions.length > 0) {
      if (e.key === 'ArrowDown') {
        e.preventDefault();
        setActiveSuggestionIndex(prev => (prev < suggestions.length - 1 ? prev + 1 : prev));
      } else if (e.key === 'ArrowUp') {
        e.preventDefault();
        setActiveSuggestionIndex(prev => (prev > 0 ? prev - 1 : 0));
      } else if (e.key === 'Enter') {
        e.preventDefault();
        const selected = suggestions[activeSuggestionIndex];
        if (type === 'title') {
          setTitle(selected);
          setShowTitleSug(false);
        } else {
          addAuthor(selected);
        }
      } else if (e.key === 'Escape') {
        type === 'title' ? setShowTitleSug(false) : setShowAuthorSug(false);
      }
    }
  };

  const toggleGenre = (genre: string) => {
    setSelectedGenres(prev => 
      prev.includes(genre) 
        ? prev.filter(g => g !== genre) 
        : [...prev, genre]
    );
    if (errors.genre) setErrors(prev => ({ ...prev, genre: undefined }));
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    if (isSubmitting) return;

    let finalAuthors = [...authors];
    if (authorInput.trim() && !finalAuthors.includes(authorInput.trim())) {
        finalAuthors.push(authorInput.trim());
    }

    const newErrors: FormErrors = {};
    const trimmedTitle = title.trim();

    if (!trimmedTitle) {
      newErrors.title = "O título é obrigatório";
    } else {
      // No modo duplicação, permitimos o mesmo título se o usuário desejar
      const isDuplicate = existingBooks.some(b => 
        b.title.trim().toLowerCase() === trimmedTitle.toLowerCase() && 
        (!isEditMode || b.id !== bookToEdit?.id)
      );
      if (isDuplicate && isEditMode) {
        newErrors.title = "Já existe um livro com este título na sua biblioteca";
      }
    }

    if (finalAuthors.length === 0) newErrors.authors = "Adicione ao menos um autor";
    if (selectedGenres.length === 0) newErrors.genre = "Selecione ao menos um gênero";

    if (Object.keys(newErrors).length > 0) {
      setErrors(newErrors);
      setIsShaking(true);
      setTimeout(() => setIsShaking(false), 500);
      return;
    }

    setIsSubmitting(true);
    try {
        const bookData = { 
            title: trimmedTitle, 
            author: finalAuthors.join(', '), 
            pages, 
            genre: selectedGenres.join(', '), 
            type, 
            status, 
            summary, 
            notes,
            rating: (status === BookStatus.Read || rating > 0) ? (rating || undefined) : undefined,
            estimatedPrice: estimatedPrice ? parseFloat(estimatedPrice.replace(',', '.')) : undefined,
            pricePaid: pricePaid ? parseFloat(pricePaid.replace(',', '.')) : (isDuplicating ? undefined : bookToEdit?.pricePaid),
            buyLink: buyLink.trim() || undefined,
            coverImageUrl: coverImageUrl.trim() || undefined, 
            dateAdded,
            currentPage: status === BookStatus.Read ? pages : (status === BookStatus.TBR || status === BookStatus.Wishlist ? 0 : currentPage),
            dateStarted: isDuplicating ? undefined : bookToEdit?.dateStarted,
            dateFinished: status === BookStatus.Read ? dateFinished : undefined,
            daysToFinish: status === BookStatus.Read && daysToFinish ? parseInt(daysToFinish, 10) : null,
            timesRead: status === BookStatus.Read ? Number(timesRead) : (isDuplicating ? 0 : (bookToEdit?.timesRead || 0)),
            wasWishlist: isDuplicating ? (status === BookStatus.Wishlist) : (bookToEdit?.wasWishlist || (status === BookStatus.Wishlist))
        };
        if (isEditMode) {
            await onUpdateBook({ ...bookToEdit, ...bookData });
        } else {
            await onAddBook(bookData);
        }
    } finally {
        setIsSubmitting(false);
    }
  };

  const handleGenerateCover = useCallback(async () => {
    if (!title || selectedGenres.length === 0) return;
    setIsGeneratingCover(true);
    try {
      const result = await generateBookCover(title, selectedGenres[0], type, authors.join(', '));
      if (result) setCoverImageUrl(result);
    } finally {
      setIsGeneratingCover(false);
    }
  }, [title, selectedGenres, type, authors]);

  const handleGenerateSummary = useCallback(async () => {
    if (!title || authors.length === 0) return;
    setIsGeneratingSummary(true);
    try {
      const result = await generateBookSummary(title, authors.join(', '));
      if (result) setSummary(result);
    } catch (err) {
      console.error("Erro ao gerar resumo:", err);
    } finally {
      setIsGeneratingSummary(false);
    }
  }, [title, authors]);

  const labelClass = (isRequired: boolean) => 
    `block text-[10px] font-black uppercase tracking-[0.15em] mb-1.5 ml-1 flex items-center gap-1 ${isRequired ? 'text-slate-500 dark:text-slate-400' : 'text-slate-400 dark:text-slate-500'}`;

  const SuggestionDropdown = ({ suggestions, show, onSelect }: { suggestions: string[], show: boolean, onSelect: (val: string) => void }) => {
    if (!show || suggestions.length === 0) return null;
    return (
      <div className="absolute left-0 right-0 top-full mt-2 z-[60] bg-white/95 dark:bg-slate-900/95 backdrop-blur-md border border-slate-200 dark:border-slate-700 rounded-2xl shadow-2xl overflow-hidden animate-in fade-in slide-in-from-top-2 duration-200">
        {suggestions.map((suggestion, index) => (
          <button
            key={index}
            type="button"
            onMouseEnter={() => setActiveSuggestionIndex(index)}
            onClick={() => onSelect(suggestion)}
            className={`w-full text-left px-5 py-3 text-xs font-bold transition-colors ${activeSuggestionIndex === index ? 'bg-primary text-white' : 'text-slate-700 dark:text-slate-300 hover:bg-slate-50 dark:hover:bg-slate-800'}`}
          >
            {suggestion}
          </button>
        ))}
      </div>
    );
  };

  const modalTitle = isEditMode ? 'Editar Registro' : (isDuplicating ? 'Duplicar Registro' : 'Novo Registro');

  return (
    <div className="fixed inset-0 bg-slate-900/60 backdrop-blur-sm flex items-center justify-center z-50 p-4">
      <div 
        className={`bg-white dark:bg-slate-900 rounded-[2.5rem] shadow-2xl w-full max-w-2xl max-h-[90vh] overflow-hidden flex flex-col border border-white/20 dark:border-slate-800 transition-transform duration-500 ${isShaking ? 'animate-shake' : ''}`}
        style={{ animation: isShaking ? 'shake 0.4s cubic-bezier(.36,.07,.19,.97) both' : 'none' }}
      >
        <div className="p-7 border-b border-slate-100 dark:border-slate-800 flex justify-between items-center bg-slate-50/50 dark:bg-slate-800/30">
            <h2 className="text-2xl font-black font-serif text-slate-900 dark:text-slate-50 tracking-tight">{modalTitle}</h2>
            <button onClick={onClose} disabled={isSubmitting} className="p-2.5 rounded-full hover:bg-slate-200 dark:hover:bg-slate-700 text-slate-400 transition-all hover:rotate-90 disabled:opacity-30">
                <XMarkIcon className="h-5 w-5" />
            </button>
        </div>

        <form onSubmit={handleSubmit} className="p-8 space-y-8 overflow-y-auto custom-scrollbar">
            {isDuplicating && (
              <div className="bg-primary/10 border border-primary/20 p-4 rounded-2xl animate-in slide-in-from-top-2 duration-500">
                <p className="text-[10px] font-black text-primary uppercase tracking-[0.1em] text-center">✦ Você está criando uma nova entrada baseada em "{bookToEdit?.title}".</p>
              </div>
            )}

            <div className={`grid grid-cols-1 md:grid-cols-2 gap-8 ${isSubmitting ? 'opacity-50 pointer-events-none' : ''}`}>
                <div className="md:col-span-2 relative" ref={titleRef}>
                    <label className={labelClass(true)}>
                      Título <span className="text-red-500">*</span>
                    </label>
                    <input 
                      type="text" 
                      value={title} 
                      onChange={handleTitleChange}
                      onKeyDown={(e) => handleKeyDown(e, 'title')}
