/**
 * Utilitário para otimização de imagens no lado do cliente.
 * Reduz dimensões e aplica compressão para diminuir o peso no banco de dados.
 */
export const optimizeBase64Image = (base64Data: string, maxWidth: number = 400, quality: number = 0.7): Promise<string> => {
  return new Promise((resolve) => {
    const img = new Image();
    img.src = base64Data;
    img.onload = () => {
      const canvas = document.createElement('canvas');
      let width = img.width;
      let height = img.height;

      // Mantém a proporção redimensionando para o maxWidth
      if (width > maxWidth) {
        height = Math.round((height * maxWidth) / width);
        width = maxWidth;
      }

      canvas.width = width;
      canvas.height = height;

      const ctx = canvas.getContext('2d');
      if (!ctx) {
        resolve(base64Data); // Fallback para original se canvas falhar
        return;
      }

      // Aplica suavização na imagem
      ctx.imageSmoothingEnabled = true;
      ctx.imageSmoothingQuality = 'high';

      ctx.drawImage(img, 0, 0, width, height);

      // Exporta como WebP (mais leve) ou JPEG se WebP não suportado
      const optimized = canvas.toDataURL('image/webp', quality);

      // Se por algum motivo a "otimização" ficou maior que a original, usa a original
      if (optimized.length > base64Data.length) {
        resolve(base64Data);
      } else {
        resolve(optimized);
      }
    };
    img.onerror = () => resolve(base64Data);
  });
};

import { GoogleGenAI, GenerateContentResponse, Type } from "@google/genai";
import { Recommendation } from "../types";
import { optimizeBase64Image } from "./imageOptimizer";

const stringifyError = (err: any): string => {
  if (!err) return "Erro desconhecido";
  if (typeof err === 'string') return err;
  if (err.message) return err.message;
  try {
    const parsed = JSON.stringify(err);
    if (parsed === '{}') return err.toString();
    return parsed;
  } catch {
    return String(err);
  }
};

const callGenAI = async (task: (ai: GoogleGenAI) => Promise<any>, modelName?: string) => {
  const isProModel = modelName === 'gemini-3-pro-image-preview' || modelName?.includes('pro');

  if (isProModel && window.aistudio) {
    const hasKey = await window.aistudio.hasSelectedApiKey();
    if (!hasKey) {
      await window.aistudio.openSelectKey();
    }
  }

  const apiKey = process.env.API_KEY;

  if (!apiKey || apiKey === 'undefined' || apiKey === '') {
    if (window.aistudio) {
      await window.aistudio.openSelectKey();
    }
    throw new Error("API_KEY_MISSING");
  }

  try {
    const ai = new GoogleGenAI({ apiKey });
    return await task(ai);
  } catch (error: any) {
    const errorMsg = stringifyError(error);
    console.error(`Gemini API Error [${modelName || 'unknown'}]:`, errorMsg);

    if (
      errorMsg.includes("PERMISSION_DENIED") ||
      errorMsg.includes("403") ||
      errorMsg.includes("The caller does not have permission") ||
      errorMsg.includes("Requested entity was not found") ||
      errorMsg.includes("404")
    ) {
      if (window.aistudio) {
        await window.aistudio.openSelectKey();
      }
    }
    throw error;
  }
};

export const generateBookSummary = async (title: string, author: string): Promise<string> => {
  const model = 'gemini-3-flash-preview';
  try {
    return await callGenAI(async (ai) => {
      const prompt = `Escreva um resumo curto (um parágrafo) e envolvente em Português para o livro "${title}" de ${author}. Não dê spoilers.`;
      const response: GenerateContentResponse = await ai.models.generateContent({
        model,
        contents: prompt,
      });
      return response.text || "Não foi possível gerar um resumo.";
    }, model);
  } catch (error: any) {
    return `A IA não conseguiu processar o resumo no momento. Verifique sua chave de API.`;
  }
};

export const generateBookCover = async (title: string, genre: string, type: string, author?: string): Promise<string> => {
  const model = 'gemini-3-pro-image-preview';

  try {
    const base64Image = await callGenAI(async (ai) => {
      const prompt = `Pesquise a capa original do livro "${title}" ${author ? `de ${author}` : ''}. 
      Baseado nos resultados da pesquisa, gere uma nova capa que seja uma reprodução fiel, artística e profissional da identidade visual original da obra. 
      Gênero: ${genre}. 
      Estilo: Alta resolução, cinematográfico. 
      Evite textos ilegíveis; foque na simbologia e paleta de cores icônica da capa real.`;

      const response: GenerateContentResponse = await ai.models.generateContent({
        model,
        contents: { parts: [{ text: prompt }] },
        config: {
          imageConfig: {
            aspectRatio: "3:4"
          },
          tools: [{ googleSearch: {} }]
        },
      });

      if (response.candidates?.[0]?.content?.parts) {
        for (const part of response.candidates[0].content.parts) {
          if (part.inlineData) {
            return `data:image/png;base64,${part.inlineData.data}`;
          }
        }
      }

      return `https://picsum.photos/seed/${encodeURIComponent(title)}/400/600`;
    }, model);

    // OTIMIZAÇÃO: Reduz o tamanho da imagem antes de retornar para ser salva no banco
    if (base64Image.startsWith('data:image')) {
      return await optimizeBase64Image(base64Image, 400, 0.75);
    }

    return base64Image;
  } catch (error: any) {
    console.error("Erro na geração de capa:", stringifyError(error));
    return `https://picsum.photos/seed/${encodeURIComponent(title)}/400/600`;
  }
};

export const getAIRecommendations = async (readBooks: { title: string, genre: string }[]): Promise<Recommendation[]> => {
  if (readBooks.length === 0) return [];
  const model = 'gemini-3-flash-preview';
  try {
    return await callGenAI(async (ai) => {
      const booksDescription = readBooks.map(b => `${b.title} (${b.genre})`).join(', ');
      const prompt = `Com base em: ${booksDescription}. Recomende 3 livros novos em Português com links de busca na Amazon Brasil.`;
      const response: GenerateContentResponse = await ai.models.generateContent({
        model,
        contents: prompt,
        config: {
          responseMimeType: "application/json",
          responseSchema: {
            type: Type.ARRAY,
            items: {
              type: Type.OBJECT,
              properties: {
                title: { type: Type.STRING },
                author: { type: Type.STRING },
                reason: { type: Type.STRING },
                genre: { type: Type.STRING },
                buyLink: { type: Type.STRING },
              },
              required: ["title", "author", "reason", "genre", "buyLink"]
            }
          }
        }
      });
      return JSON.parse(response.text || '[]');
    }, model);
  } catch (error: any) {
    return [];
  }
};

