    setHighlightSignup(false);
  }, [mode]);

  const handleAuth = async (e: React.FormEvent) => {
    e.preventDefault();
    setLoading(true);
    setErrorMsg(null);
    setHighlightSignup(false);

    if (isStripeKey) {
        setErrorMsg("Erro de Configuração: Chave do Stripe detectada. Use a chave 'anon public' do Supabase.");
        setLoading(false);
        return;
    }

    try {
      if (mode === 'login') {
        const { error, data } = await supabase.auth.signInWithPassword({ email, password });
        if (error) {
          handleAuthError(error);
          return;
        }
      } else {
        if (password.length < 6) {
          setErrorMsg('A senha precisa ter no mínimo 6 caracteres.');
          setLoading(false);
          return;
        }
        if (fullName.trim().length < 3) {
          setErrorMsg('Informe seu nome completo.');
          setLoading(false);
          return;
        }

        const { error, data } = await supabase.auth.signUp({ 
          email, 
          password,
          options: { data: { full_name: fullName.trim() } }
        });

        if (error) {
            handleAuthError(error);
            return;
        }

        if (data.user && !data.session) {
           setNeedsEmailConfirmation(true);
        }
      }
    } catch (error: any) {
      if (error.message === 'Failed to fetch' || error instanceof TypeError) {
        setErrorMsg("❌ Falha de Conexão: Não foi possível alcançar o servidor. Verifique se o projeto Supabase está ATIVO ou se há internet.");
      } else {
        setErrorMsg("Ocorreu um erro inesperado. Tente novamente.");
      }
    } finally {
      setLoading(false);
    }
  };

  const handleAuthError = (error: any) => {
    const msg = error.message.toLowerCase();

    if (msg.includes('failed to fetch') || msg.includes('network error')) {
        setErrorMsg("❌ Erro de Rede: Servidor inacessível. O projeto Supabase pode estar pausado.");
    } else if (msg.includes('invalid login credentials')) {
        setHighlightSignup(true);
        setErrorMsg('E-mail ou senha incorretos. Se este é seu primeiro acesso, clique em CADASTRAR acima!');
    } else if (msg.includes('email not confirmed')) {
        setErrorMsg('E-mail não confirmado. Verifique sua caixa de entrada para ativar sua conta.');
    } else if (msg.includes('user already registered')) {
        setMode('login');
        setErrorMsg('E-mail já cadastrado. Tente entrar com sua senha!');
    } else {
        setErrorMsg(error.message);
    }
  };

  const handleForgotPassword = async () => {
    if (!email) {
        setErrorMsg("Digite seu e-mail para recuperar a senha.");
        return;
    }
    setLoading(true);
    try {
        const { error } = await supabase.auth.resetPasswordForEmail(email);
        if (error) throw error;
        setErrorMsg("Link de recuperação enviado com sucesso!");
    } catch (error: any) {
        handleAuthError(error);
    } finally {
        setLoading(false);
    }
  };

  if (needsEmailConfirmation) {
    return (
      <div className="min-h-screen bg-background dark:bg-slate-950 flex flex-col items-center justify-center p-6">
        <div className="w-full max-w-md bg-white dark:bg-slate-900 rounded-[2.5rem] shadow-2xl border border-emerald-100 dark:border-emerald-900/30 p-10 text-center animate-in zoom-in duration-500">
          <div className="bg-emerald-500 w-16 h-16 rounded-full flex items-center justify-center mx-auto mb-6 shadow-lg">
            <svg xmlns="http://www.w3.org/2000/svg" className="h-8 w-8 text-white" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={3} d="M5 13l4 4L19 7" />
            </svg>
          </div>
          <h2 className="text-2xl font-black text-slate-900 dark:text-slate-50 mb-4 font-serif italic">Ative sua conta!</h2>
          <p className="text-slate-500 dark:text-slate-400 text-sm leading-relaxed mb-8">
            Enviamos um e-mail para <b>{email}</b>. Clique no link de confirmação para liberar seu acesso.
          </p>
          <button 
            onClick={() => setNeedsEmailConfirmation(false)}
            className="w-full py-4 bg-slate-100 dark:bg-slate-800 rounded-2xl text-[10px] font-black uppercase tracking-widest text-slate-600 dark:text-slate-400 hover:bg-slate-200 transition-all shadow-md"
          >
            Voltar para Login
          </button>
        </div>
      </div>
    );
  }

  return (
    <div className="min-h-screen bg-background dark:bg-slate-950 flex flex-col items-center justify-center p-6 font-sans">
      <div className="w-full max-w-md bg-white dark:bg-slate-900 rounded-[2.5rem] shadow-2xl border border-slate-100 dark:border-slate-800 p-10 transition-all relative overflow-hidden">

        <div className="flex flex-col items-center mb-10 pt-4">
            <Logo size="lg" className="mb-6" showText={true} />

            <div className="flex w-full bg-slate-50 dark:bg-slate-800/50 p-1 rounded-2xl border border-slate-100 dark:border-slate-700">
                <button 
                    onClick={() => setMode('login')}
                    className={`flex-1 py-3 text-[10px] font-black uppercase tracking-widest rounded-xl transition-all ${mode === 'login' ? 'bg-white dark:bg-slate-700 text-primary shadow-md' : 'text-slate-400 hover:text-slate-600'}`}
                >
                    Entrar
                </button>
                <button 
                    onClick={() => setMode('signup')}
                    className={`flex-1 py-3 text-[10px] font-black uppercase tracking-widest rounded-xl transition-all ${mode === 'signup' ? 'bg-white dark:bg-slate-700 text-primary shadow-md' : 'text-slate-400 hover:text-slate-600'} ${highlightSignup ? 'animate-pulse ring-4 ring-primary/30 border-primary bg-primary/5 text-primary' : ''}`}
                >
                    Cadastrar
                </button>
            </div>
        </div>

        <form onSubmit={handleAuth} className="space-y-6">
          {mode === 'signup' && (
            <div className="animate-in slide-in-from-top-2 duration-300">
              <label className="block text-[10px] font-black uppercase tracking-widest text-slate-400 mb-2 ml-1">Nome Completo</label>
              <input
                type="text"
                placeholder="Ex: João Silva"
                value={fullName}
                onChange={(e) => setFullName(e.target.value)}
                className="w-full bg-slate-50 dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-2xl px-5 py-3.5 outline-none focus:border-primary font-medium dark:text-white transition-all shadow-sm"
                required={mode === 'signup'}
              />
            </div>
          )}

          <div>
            <label className="block text-[10px] font-black uppercase tracking-widest text-slate-400 mb-2 ml-1">E-mail</label>
            <input
              type="email"
              placeholder="exemplo@email.com"
              value={email}
              onChange={(e) => setEmail(e.target.value)}
              className="w-full bg-slate-50 dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-2xl px-5 py-3.5 outline-none focus:border-primary font-medium dark:text-white transition-all shadow-sm"
              required
            />
          </div>

          <div>
            <div className="flex justify-between items-center mb-2 ml-1">
                <label className="block text-[10px] font-black uppercase tracking-widest text-slate-400">Senha</label>
                <button type="button" onClick={() => setShowPassword(!showPassword)} className="text-[9px] font-bold text-primary uppercase hover:underline">
                    {showPassword ? 'Ocultar' : 'Mostrar'}
                </button>
            </div>
            <input
              type={showPassword ? 'text' : 'password'}
              placeholder="••••••••"
              value={password}
              onChange={(e) => setPassword(e.target.value)}
              className="w-full bg-slate-50 dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-2xl px-5 py-3.5 outline-none focus:border-primary font-medium dark:text-white transition-all shadow-sm"
              required
            />
          </div>

          {errorMsg && (
            <div className={`p-4 rounded-2xl border animate-shake space-y-3 ${errorMsg.includes('sucesso') ? 'bg-emerald-50 dark:bg-emerald-900/20 text-emerald-600 border-emerald-100' : 'bg-red-50 dark:bg-red-900/20 text-red-500 border-red-100 dark:border-red-900/30'}`}>
              <p className="text-[10px] font-bold uppercase leading-relaxed text-center">{errorMsg}</p>
              {highlightSignup && mode === 'login' && (
                  <button 
                    type="button"
                    onClick={() => setMode('signup')}
                    className="w-full bg-blue-600 text-white py-3 rounded-xl text-[9px] tracking-widest shadow-md hover:bg-blue-700 transition-all font-black uppercase"
                  >
                    Clique aqui para criar sua conta
                  </button>
              )}
            </div>
          )}

          <button
            type="submit"
            disabled={loading}
            className="w-full bg-primary text-white font-black text-[11px] uppercase tracking-widest py-4 rounded-2xl shadow-xl hover:bg-slate-900 dark:hover:bg-white dark:hover:text-slate-900 transition-all active:scale-95 disabled:opacity-50"
          >
            {loading ? 'Processando...' : mode === 'login' ? 'Entrar no BiblioTech' : 'Criar minha conta'}
          </button>

          {mode === 'login' && (
              <button 
                type="button" 
                onClick={handleForgotPassword}
                className="w-full text-center text-[9px] font-black text-slate-400 uppercase tracking-widest hover:text-primary transition-colors"
              >
                Esqueci minha senha
              </button>
          )}
        </form>

        <div className="mt-8 pt-6 border-t border-slate-50 dark:border-slate-800 text-center">
            <button 
                onClick={() => setShowHelp(true)}
                className="text-[9px] font-black text-slate-400 uppercase tracking-widest hover:text-primary transition-colors"
            >
                Ajuda com Acesso
            </button>
        </div>
      </div>

      {showHelp && (
        <div className="fixed inset-0 bg-slate-900/80 backdrop-blur-md flex items-center justify-center z-[100] p-6">
            <div className="bg-white dark:bg-slate-900 rounded-[2.5rem] p-8 max-w-lg w-full shadow-2xl border border-white/20 relative animate-in zoom-in duration-300">
                <button onClick={() => setShowHelp(false)} className="absolute top-6 right-6 p-2 rounded-full hover:bg-slate-100 dark:hover:bg-slate-800 transition-all"><XMarkIcon className="h-5 w-5"/></button>
                <h3 className="text-2xl font-black font-serif italic mb-6">Problemas de Acesso?</h3>
                <div className="space-y-4">
                    <p className="text-sm text-slate-600 dark:text-slate-400">• Se você recebe "Invalid login credentials", verifique se já criou sua conta na aba <b>CADASTRAR</b>.</p>
                    <p className="text-sm text-slate-600 dark:text-slate-400">• O erro "Failed to fetch" ocorre se o projeto Supabase estiver pausado ou sem internet.</p>
                    <p className="text-sm text-slate-600 dark:text-slate-400">• Cadastro no Supabase exige e-mail real para ativação.</p>
                </div>
                <button 
                    onClick={() => setShowHelp(false)}
                    className="w-full bg-primary text-white font-black text-[11px] uppercase tracking-widest py-4 rounded-2xl mt-8 shadow-xl active:scale-95"
                >
                    Entendido!
                </button>
            </div>
        </div>
      )}
    </div>
  );
};

import React, { useState, useMemo, useEffect } from 'react';
import { useBookData } from './hooks/useBookData';
import { Header } from './components/Header';
import { Dashboard } from './components/Dashboard';
import { AddBookModal } from './components/AddBookModal';
import { SettingsModal } from './components/SettingsModal';
import { PlusIcon, XMarkIcon } from './components/Icons';
import type { Book, NewBook, Profile } from './types';
import { BookList } from './components/BookList';
import { ConfirmationModal } from './components/ConfirmationModal';
import { BookStatus } from './types';
import { Wishlist } from './components/Wishlist';
import { BottomNav } from './components/BottomNav';
import { Auth } from './components/Auth';
import { StatsView } from './components/StatsView';
import { PricePaidModal } from './components/PricePaidModal'; 
import { supabase } from './services/supabase';
import { dbService } from './services/database';

export default function App() {
  const [session, setSession] = useState<any>(null);
  const [isAuthLoading, setIsAuthLoading] = useState(true);
  const [userProfile, setUserProfile] = useState<Profile | null>(null);
  const [hasApiKey, setHasApiKey] = useState<boolean>(true);

  useEffect(() => {
    // Busca sessão inicial tratando possíveis erros de fetch
    supabase.auth.getSession()
      .then(({ data: { session } }) => {
        setSession(session);
      })
      .catch((err) => {
        console.warn("⚠️ Não foi possível sincronizar sessão inicial (Offline/Fetch Error).");
      })
      .finally(() => {
        setIsAuthLoading(false);
      });

    const { data: { subscription } } = supabase.auth.onAuthStateChange((_event, session) => {
      setSession(session);
    });
    return () => subscription.unsubscribe();
  }, []);

  useEffect(() => {
    if (session) {
      dbService.getProfile().then(profile => {
        if (profile) {
          setUserProfile(profile);
          if (profile.readingGoal) setReadingGoal(profile.readingGoal);
          checkPlatformApiKey();
        }
      });
    }
  }, [session]);

  const checkPlatformApiKey = async () => {
    if (window.aistudio) {
        const selected = await window.aistudio.hasSelectedApiKey();
        setHasApiKey(selected);
    } else {
        const envKey = process.env.API_KEY;
        setHasApiKey(!!(envKey && envKey !== 'undefined' && envKey !== ''));
    }
  };

  const { 
    books, stats, currentlyReading, addBook, updateBook, deleteBook, 
    dateFilter, setDateFilter, selectedYear, setSelectedYear, availableYears,
    customRange, setCustomRange, isLocalMode, schemaError, isLoading
  } = useBookData();

  const [theme, setTheme] = useState<'light' | 'dark'>(() => (localStorage.getItem('theme') as 'light' | 'dark') || 'light');
  const [readingGoal, setReadingGoal] = useState(() => parseInt(localStorage.getItem('biblio_tech_goal') || '12', 10));

  const handleSetReadingGoal = async (val: number) => {
    try {
        setReadingGoal(val);
        localStorage.setItem('biblio_tech_goal', val.toString());
        await dbService.updateReadingGoal(val);
        showToast("Meta de leitura atualizada.");
    } catch (err: any) {
        showToast(`Erro ao salvar meta: ${err.message}`);
    }
  };

  const handleUpdateProfile = async (updates: Partial<Profile>) => {
    if (userProfile) {
        try {
            const newProfile = { ...userProfile, ...updates };
            setUserProfile(newProfile);
            await dbService.updateProfile(updates);
            checkPlatformApiKey();
            showToast("Perfil atualizado.");
        } catch (err: any) {
            showToast(`Erro ao atualizar perfil: ${err.message}`);
        }
    }
  };

  const [isModalOpen, setIsModalOpen] = useState(false);
  const [isSettingsOpen, setIsSettingsOpen] = useState(false);
  const [view, setView] = useState<'dashboard' | 'list' | 'wishlist' | 'stats'>('dashboard');
  const [editingBook, setEditingBook] = useState<Book | null>(null);
  const [isDuplicating, setIsDuplicating] = useState(false);
  const [deletingBook, setDeletingBook] = useState<Book | null>(null);
  const [convertingBook, setConvertingBook] = useState<Book | null>(null); 
  const [defaultStatusForModal, setDefaultStatusForModal] = useState<BookStatus | undefined>();
  const [toastMessage, setToastMessage] = useState<string | null>(null);

  useEffect(() => {
    theme === 'dark' ? document.documentElement.classList.add('dark') : document.documentElement.classList.remove('dark');
    localStorage.setItem('theme', theme);
  }, [theme]);

  const showToast = (message: string) => {
    setToastMessage(message);
    setTimeout(() => setToastMessage(null), 3500);
  };

  const handleAddBook = async (newBook: NewBook) => {
    try {
        await addBook(newBook);
        setIsModalOpen(false);
        showToast(`"${newBook.title}" salvo!`);
    } catch (err: any) {
        showToast(`Erro ao salvar: ${err.message}`);
    }
  };

  const handleUpdateBook = async (updatedBook: Book) => {
    try {
        await updateBook(updatedBook);
        setIsModalOpen(false);
        showToast(`"${updatedBook.title}" atualizado.`);
    } catch (err: any) {
        showToast(`Erro ao atualizar: ${err.message}`);
    }
  };

  const handleFinishConversion = async (price: number) => {
    if (convertingBook) {
      const updated: Book = {
        ...convertingBook,
        status: BookStatus.TBR,
        wasWishlist: true,
        pricePaid: price,
        dateAdded: new Date().toISOString().split('T')[0] 
      };
      await handleUpdateBook(updated);
      setConvertingBook(null);
      showToast("Movido para sua estante!");
    }
  };

  const openAddModal = (status?: BookStatus) => {
    setEditingBook(null);
    setIsDuplicating(false);
    setDefaultStatusForModal(status);
    setIsModalOpen(true);
  };

  const handleDuplicateRequest = (book: Book) => {
    setEditingBook(book);
    setIsDuplicating(true);
    setIsModalOpen(true);
  };

  if (isAuthLoading) return <div className="min-h-screen bg-background flex items-center justify-center"><div className="w-10 h-10 border-4 border-primary border-t-transparent rounded-full animate-spin"></div></div>;
  if (!session) return <Auth />;

  // No carregamento inicial, se houver cache, o isLoading já é setado para false pelo hook
  if (isLoading) return <div className="min-h-screen bg-background flex flex-col items-center justify-center p-4"><div className="w-12 h-12 border-4 border-primary border-t-transparent rounded-full animate-spin mb-4"></div><p className="text-[10px] font-black uppercase tracking-widest text-slate-400">Sincronizando...</p></div>;

  return (
    <div className="min-h-screen bg-background dark:bg-slate-950 text-text-main dark:text-slate-200 pb-24 relative transition-colors duration-300">
      <Header 
        profile={userProfile} onLogoClick={() => setView('dashboard')} onSettingsClick={() => setIsSettingsOpen(true)}
        theme={theme} toggleTheme={() => setTheme(t => t === 'light' ? 'dark' : 'light')} 
        isConnected={!isLocalMode} hasApiKey={hasApiKey}
      />

      {schemaError && (
        <div className="bg-red-600 text-white px-6 py-3 text-center text-[10px] font-black uppercase tracking-widest flex items-center justify-center gap-4 animate-in slide-in-from-top duration-500">
          <div className="flex-1">
             ⚠️ Erro de Sincronização: {schemaError.detail || "O banco de dados está desatualizado."} 
             <span className="block mt-1 font-bold opacity-80">Rode o script SQL do arquivo instrucoes_sql.txt no painel do Supabase!</span>
          </div>
        </div>
      )}

      {!hasApiKey && !schemaError && (
        <div className="bg-red-500 text-white px-6 py-2 text-center text-[10px] font-black uppercase tracking-widest animate-pulse cursor-pointer" onClick={() => setIsSettingsOpen(true)}>
          IA Indisponível: Clique aqui para configurar sua Chave de API nas Preferências.
        </div>
      )}

      <main className="p-4 md:p-8">
        {view === 'dashboard' && <Dashboard stats={stats} currentlyReading={currentlyReading} updateBook={handleUpdateBook} dateFilter={dateFilter} setDateFilter={setDateFilter} selectedYear={selectedYear} setSelectedYear={setSelectedYear} availableYears={availableYears} books={books} customRange={customRange} setCustomRange={setCustomRange} readingGoal={readingGoal} onSetReadingGoal={handleSetReadingGoal} />}
        {view === 'list' && <BookList books={books.filter(b => b.status !== BookStatus.Wishlist)} onEdit={(b) => { setEditingBook(b); setIsDuplicating(false); setIsModalOpen(true); }} onDelete={setDeletingBook} onDuplicate={handleDuplicateRequest} onUpdateBook={handleUpdateBook} />}
        {view === 'wishlist' && <Wishlist books={books.filter(b => b.status === BookStatus.Wishlist)} onEdit={(b) => { setEditingBook(b); setIsDuplicating(false); setIsModalOpen(true); }} onDelete={setDeletingBook} onDuplicate={handleDuplicateRequest} onMoveToShelf={(b) => setConvertingBook(b)} onAddWishlistItem={() => openAddModal(BookStatus.Wishlist)} />}
        {view === 'stats' && <StatsView books={books} availableYears={availableYears} />}
      </main>

      <div className="fixed bottom-24 right-6 flex flex-col gap-3">
        <button onClick={() => openAddModal()} className="bg-primary text-background p-4 rounded-full shadow-2xl hover:bg-blue-700 transition-all z-40 active:scale-95"><PlusIcon className="h-6 w-6" /></button>
      </div>

      <BottomNav view={view} setView={setView} />
      {toastMessage && <div className="fixed bottom-32 left-1/2 -translate-x-1/2 z-[60] animate-in fade-in slide-in-from-bottom-4 duration-500"><div className="bg-slate-900 text-white px-6 py-3.5 rounded-2xl shadow-2xl border border-white/10 flex items-center gap-3"><p className="text-[11px] font-black uppercase tracking-widest">{toastMessage}</p></div></div>}

      {isModalOpen && <AddBookModal onClose={() => setIsModalOpen(false)} onAddBook={handleAddBook} onUpdateBook={handleUpdateBook} bookToEdit={editingBook} isDuplicating={isDuplicating} defaultStatus={defaultStatusForModal} existingBooks={books} />}

      {convertingBook && <PricePaidModal book={convertingBook} onClose={() => setConvertingBook(null)} onConfirm={handleFinishConversion} />}

      {isSettingsOpen && <SettingsModal onClose={() => setIsSettingsOpen(false)} readingGoal={readingGoal} onSetReadingGoal={handleSetReadingGoal} profile={userProfile} onUpdateProfile={handleUpdateProfile} />}

      {deletingBook && <ConfirmationModal isOpen={!!deletingBook} onClose={() => setDeletingBook(null)} onConfirm={async () => { await deleteBook(deletingBook.id); setDeletingBook(null); showToast(`Removido.`); }} title="Excluir" message={`Apagar "${deletingBook.title}"?`} />}
    </div>
  );
}

import type { Book, Profile } from '../types';
import { supabase } from './supabase';
import { BookStatus } from '../types';

const TABLE_NAME = 'books';
const BASE_LOCAL_STORAGE_KEY = 'biblio_tech_cache_';
const FETCH_TIMEOUT_MS = 6000; // Timeout mais curto para evitar travamentos longos

const mapBookToDb = (book: any) => {
    const dateAddedValue = book.dateAdded || new Date().toISOString().split('T')[0];
    return {
        id: book.id,
        user_id: book.user_id,
        title: book.title || 'Sem Título',
        author: book.author || 'Autor Desconhecido',
        pages: Math.floor(parseInt(String(book.pages || 0), 10)),
        genre: book.genre || '',
        type: book.type || 'Livro',
        status: book.status || 'Não lido',
        rating: (book.rating !== undefined && book.rating !== null && book.rating !== 0) ? parseFloat(String(book.rating)) : null,
        cover_image_url: book.cover_image_url || book.coverImageUrl || null,
        summary: book.summary || null,
        notes: book.notes || null,
        estimated_price: (book.estimatedPrice !== undefined && book.estimatedPrice !== null) ? parseFloat(String(book.estimatedPrice)) : null,
        price_paid: (book.pricePaid !== undefined && book.pricePaid !== null) ? parseFloat(String(book.pricePaid)) : null,
        buy_link: book.buyLink || null,
        current_page: Math.floor(parseInt(String(book.currentPage || 0), 10)),
        date_added: dateAddedValue,
        date_started: book.dateStarted || null,
        date_finished: book.dateFinished || null,
        days_to_finish: (book.daysToFinish !== undefined && book.daysToFinish !== null) ? Math.floor(parseInt(String(book.daysToFinish), 10)) : null,
        times_read: (book.timesRead !== undefined && book.timesRead !== null) ? Math.floor(parseInt(String(book.timesRead), 10)) : 0,
        was_wishlist: book.wasWishlist === true
    };
};

const mapDbToBook = (db: any): Book => ({
    id: db.id,
    user_id: db.user_id,
    title: db.title,
    author: db.author,
    pages: db.pages || 0,
    genre: db.genre || '',
    type: db.type,
    status: db.status as BookStatus,
    rating: db.rating ? parseFloat(String(db.rating)) : undefined,
    coverImageUrl: db.cover_image_url,
    summary: db.summary,
    notes: db.notes,
    estimatedPrice: db.estimated_price ? parseFloat(String(db.estimated_price)) : undefined,
    pricePaid: db.price_paid ? parseFloat(String(db.price_paid)) : undefined,
    buyLink: db.buy_link,
    currentPage: db.current_page || 0,
    dateAdded: db.date_added,
    dateStarted: db.date_started,
    dateFinished: db.date_finished,
    daysToFinish: db.days_to_finish,
    timesRead: db.times_read || 0,
    wasWishlist: db.was_wishlist === true
});

const withTimeoutAndRetry = <T>(
    promiseFn: () => Promise<any>, 
    ms: number, 
    retries: number = 0 // Reduzido retries para evitar loops infinitos em conexões lentas
): Promise<T> => {
  return new Promise((resolve, reject) => {
    let attempt = 0;
    const execute = async () => {
      attempt++;
      let timeoutId: any;
      const timeoutPromise = new Promise((_, rej) => {
        timeoutId = setTimeout(() => rej(new Error("TIMEOUT_EXCEEDED")), ms);
      });
      try {
        const result = await Promise.race([promiseFn(), timeoutPromise]);
        clearTimeout(timeoutId);
        resolve(result as T);
      } catch (err: any) {
        clearTimeout(timeoutId);
        if (attempt <= retries) {
          setTimeout(execute, 1000); 
        } else {
          reject(err);
        }
      }
    };
    execute();
  });
};

export class DatabaseService {
  private isSchemaBroken = false;
  private cachedUser: any = null;
  private onSchemaErrorCallback?: (type: 'table' | 'column' | 'permission', detail?: string) => void;

  setSchemaErrorCallback(cb: (type: 'table' | 'column' | 'permission', detail?: string) => void) {
    this.onSchemaErrorCallback = cb;
  }

  /**
   * OTIMIZAÇÃO: Cache de usuário para evitar múltiplas chamadas 'auth.getUser' (rede)
   */
  private async getSafeUser() {
    if (this.cachedUser) return this.cachedUser;

    try {
        // getSession é muito mais rápido porque lê do localStorage
        const { data: { session } } = await supabase.auth.getSession();
        if (session?.user) {
            this.cachedUser = session.user;
            return session.user;
        }

        // Se não houver sessão, tentamos getUser uma única vez
        const { data: { user } } = await supabase.auth.getUser();
        this.cachedUser = user;
        return user;
    } catch (e) {
        return null;
    }
  }

  private async getCacheKey(): Promise<string | null> {
    const user = await this.getSafeUser();
    return user ? `${BASE_LOCAL_STORAGE_KEY}${user.id}` : null;
  }

  async getLocalBooks(): Promise<Book[]> {
    const key = await this.getCacheKey();
    if (!key) return [];
    try {
      const data = localStorage.getItem(key);
      return data ? JSON.parse(data) : [];
    } catch (e) {
      return [];
    }
  }

  async getLocalStats() {
    const key = await this.getCacheKey();
    if (!key) return null;
    try {
      const data = localStorage.getItem(`${key}_stats`);
      return data ? JSON.parse(data) : null;
    } catch (e) {
      return null;
    }
  }

  private async saveLocalBooks(books: Book[]): Promise<void> {
    const key = await this.getCacheKey();
    if (!key) return;
    try {
      localStorage.setItem(key, JSON.stringify(books));
    } catch (e: any) {}
  }

  private async saveLocalStats(stats: any) {
    const key = await this.getCacheKey();
    if (!key) return;
    try {
      localStorage.setItem(`${key}_stats`, JSON.stringify(stats));
    } catch (e) {}
  }

  async getAllBooks(): Promise<Book[]> {
    try {
      const user = await this.getSafeUser();
      if (!user) return await this.getLocalBooks();

      // OTIMIZAÇÃO: Selecionamos apenas os campos necessários, limitando a 100 itens iniciais
      const fetchFn = () => supabase
        .from(TABLE_NAME)
        .select(`
          id, user_id, title, author, pages, genre, type, status, rating, 
          cover_image_url, summary, notes, estimated_price, price_paid, 
          buy_link, current_page, date_added, date_started, date_finished, 
          days_to_finish, times_read, was_wishlist
        `)
        .order('date_added', { ascending: false })
        .limit(200);

      const { data, error } = await withTimeoutAndRetry<any>(fetchFn, FETCH_TIMEOUT_MS);

      if (error) {
        this.handleSupabaseError(error);
        return await this.getLocalBooks();
      }

      const books = (data || []).map(mapDbToBook);
      await this.saveLocalBooks(books);
      return books;
    } catch (err: any) {
      return await this.getLocalBooks();
    }
  }

  async getQuickStatsSummary() {
    try {
      const user = await this.getSafeUser();
      if (!user) return await this.getLocalStats();

      const fetchFn = () => supabase
        .from(TABLE_NAME)
        .select('status')
        .eq('user_id', user.id);

      const { data, error } = await withTimeoutAndRetry<any>(fetchFn, 4000);

      if (error) throw error;

      const counts = (data || []).reduce((acc: any, curr: any) => {
        acc[curr.status] = (acc[curr.status] || 0) + 1;
        return acc;
      }, {});

      const stats = {
        readCount: counts['Lido'] || 0,
        tbrCount: counts['Não lido'] || 0,
        wishlistCount: counts['Lista de Desejos'] || 0,
        droppedCount: counts['Abandonado'] || 0
      };

      await this.saveLocalStats(stats);
      return stats;
    } catch (err: any) {
      return await this.getLocalStats();
    }
  }

  async saveBook(book: Partial<Book>): Promise<void> {
    const user = await this.getSafeUser();
    if (!user) return;

    const dbPayload = mapBookToDb(book);
    dbPayload.user_id = user.id;

    // Atualiza cache local primeiro para UI imediata
    const books = await this.getLocalBooks();
    const index = books.findIndex(b => b.id === (book.id || dbPayload.id));
    const updatedBookState = mapDbToBook(dbPayload);

    if (index >= 0) books[index] = updatedBookState;
    else books.unshift(updatedBookState);
    await this.saveLocalBooks(books);

    // Salva no background sem 'await' para não travar a UI
    supabase.from(TABLE_NAME).upsert(dbPayload).then(({ error }) => {
        if (error) this.handleSupabaseError(error);
    }).catch(() => {});
  }

  async deleteBook(id: string): Promise<void> {
    const books = (await this.getLocalBooks()).filter(b => b.id !== id);
    await this.saveLocalBooks(books);

    supabase.from(TABLE_NAME).delete().eq('id', id).catch(() => {});
  }

  async updateReadingGoal(goal: number): Promise<void> {
    const user = await this.getSafeUser();
    if (!user) return;
    supabase.from('profiles').upsert({ id: user.id, reading_goal: Math.round(goal), updated_at: new Date().toISOString() }).catch(() => {});
  }

  async updateProfile(profile: Partial<Profile>): Promise<void> {
    const user = await this.getSafeUser();
    if (!user) return;
    const dbPayload: any = { id: user.id, updated_at: new Date().toISOString() };
    if (profile.fullName !== undefined) dbPayload.full_name = profile.fullName;
    if (profile.avatarUrl !== undefined) dbPayload.avatar_url = profile.avatarUrl;
    supabase.from('profiles').upsert(dbPayload).catch(() => {});
  }

  async getProfile(): Promise<Profile | null> {
    const user = await this.getSafeUser();
    if (!user) return null;
    try {
        const { data, error } = await supabase.from('profiles').select('id, full_name, avatar_url, reading_goal').eq('id', user.id).single();
        if (error || !data) return { id: user.id, fullName: 'Leitor', readingGoal: 12 };
        return {
            id: data.id,
            fullName: data.full_name,
            avatarUrl: data.avatar_url,
            readingGoal: data.reading_goal
        };
    } catch (err) {
        return { id: user.id, fullName: 'Leitor', readingGoal: 12 };
    }
  }

  private handleSupabaseError(error: any) {
    const code = error.code || (error.message === 'TIMEOUT_EXCEEDED' ? '57014' : '');
    if (code === '42P01' || code === 'PGRST204' || code === 'PGRST107' || code === '22P02') {
        this.isSchemaBroken = true;
        let msg = 'Estrutura do banco desatualizada.';
        if (this.onSchemaErrorCallback) this.onSchemaErrorCallback('table', msg);
    }
  }
}

export const dbService = new DatabaseService();

/**
 * Utilitário para otimização de imagens no lado do cliente.
 * Reduz dimensões e aplica compressão para diminuir o peso no banco de dados.
 */
export const optimizeBase64Image = (base64Data: string, maxWidth: number = 320, quality: number = 0.6): Promise<string> => {
  return new Promise((resolve) => {
    const img = new Image();
    img.src = base64Data;
    img.onload = () => {
      const canvas = document.createElement('canvas');
      let width = img.width;
      let height = img.height;

      // Mantém a proporção redimensionando para o maxWidth (reduzido para economizar espaço)
      if (width > maxWidth) {
        height = Math.round((height * maxWidth) / width);
        width = maxWidth;
      }

      canvas.width = width;
      canvas.height = height;

      const ctx = canvas.getContext('2d');
      if (!ctx) {
        resolve(base64Data);
        return;
      }

      ctx.imageSmoothingEnabled = true;
      ctx.imageSmoothingQuality = 'medium'; // Balanceado entre qualidade e peso

      ctx.drawImage(img, 0, 0, width, height);

      // WebP com qualidade reduzida (0.6) é ideal para Base64 no Supabase
      const optimized = canvas.toDataURL('image/webp', quality);

      if (optimized.length > base64Data.length) {
        resolve(base64Data);
      } else {
        resolve(optimized);
      }
    };
    img.onerror = () => resolve(base64Data);
  });
};

import { useState, useMemo, useCallback, useEffect, useRef } from 'react';
import type { Book, ReadingStats, NewBook, DateFilter } from '../types';
import { BookStatus, BookType } from '../types';
import { dbService } from '../services/database';
import { supabase } from '../services/supabase';

const MONTHS = ['Janeiro', 'Fevereiro', 'Março', 'Abril', 'Maio', 'Junho', 'Julho', 'Agosto', 'Setembro', 'Outubro', 'Novembro', 'Dezembro'];

export const useBookData = () => {
  const [books, setBooks] = useState<Book[]>([]);
  const [isLoading, setIsLoading] = useState(true);
  const [isLocalMode, setIsLocalMode] = useState(false);
  const [schemaError, setSchemaError] = useState<{type: 'table' | 'column' | 'permission', detail?: string} | null>(null);
  const [dateFilter, setDateFilter] = useState<DateFilter>('allTime');
  const [selectedYear, setSelectedYear] = useState<number>(new Date().getFullYear());
  const [customRange, setCustomRange] = useState({ 
    start: new Date(new Date().getFullYear(), 0, 1).toISOString().split('T')[0],
    end: new Date().toISOString().split('T')[0]
  });

  const [quickSummary, setQuickSummary] = useState<{readCount: number, tbrCount: number, wishlistCount: number} | null>(null);
  const isSincronizing = useRef(false);

  // ESTRATÉGIA: Carregamento do Cache (Instantâneo)
  const loadCache = useCallback(async () => {
    const cachedBooks = await dbService.getLocalBooks();
    const cachedStats = await dbService.getLocalStats();

    if (cachedBooks.length > 0) setBooks(cachedBooks);
    if (cachedStats) setQuickSummary(cachedStats);

    // Se temos cache, liberamos a UI imediatamente
    if (cachedBooks.length > 0 || cachedStats) {
        setIsLoading(false);
    }
  }, []);

  // ESTRATÉGIA: Sincronização com Nuvem (Background)
  const syncWithCloud = useCallback(async () => {
    if (isSincronizing.current) return;
    isSincronizing.current = true;

    dbService.setSchemaErrorCallback((type, detail) => {
        setSchemaError({ type, detail });
        setIsLocalMode(true);
    });

    try {
      const [booksResult, statsResult] = await Promise.allSettled([
        dbService.getAllBooks(),
        dbService.getQuickStatsSummary()
      ]);

      if (booksResult.status === 'fulfilled') {
        setBooks(booksResult.value);
      }
      if (statsResult.status === 'fulfilled' && statsResult.value) {
        setQuickSummary(statsResult.value);
      }
    } catch (e) {
      console.warn("Erro silencioso na sincronização.");
    } finally {
      setIsLoading(false);
      isSincronizing.current = false;
    }
  }, []);

  useEffect(() => {
    loadCache().then(() => syncWithCloud());

    const { data: { subscription } } = supabase.auth.onAuthStateChange((event) => {
      if (event === 'SIGNED_IN') {
        syncWithCloud();
      }
    });
    return () => subscription.unsubscribe();
  }, [loadCache, syncWithCloud]);

  const addBook = useCallback(async (newBook: NewBook) => {
    const { data: { session } } = await supabase.auth.getSession();
    const user = session?.user;
    if (!user) throw new Error("Necessário login.");

    const book: Book = {
      ...newBook,
      id: crypto.randomUUID(),
      user_id: user.id,
      dateAdded: newBook.dateAdded || new Date().toISOString().split('T')[0],
    };

    setBooks(prev => [book, ...prev]);
    await dbService.saveBook(book);
  }, []);

  const updateBook = useCallback(async (updatedBook: Book) => {
    setBooks(prev => prev.map(b => b.id === updatedBook.id ? updatedBook : b));
    await dbService.saveBook(updatedBook);
  }, []);

  const deleteBook = useCallback(async (id: string) => {
    setBooks(prev => prev.filter(b => b.id !== id));
    await dbService.deleteBook(id);
  }, []);

  const availableYears = useMemo(() => {
    const years = new Set<number>();
    years.add(new Date().getFullYear());
    books.forEach(book => {
      if (book.dateFinished) years.add(new Date(book.dateFinished).getFullYear());
      else if (book.dateAdded) years.add(new Date(book.dateAdded).getFullYear());
    });
    return Array.from(years).sort((a, b) => b - a);
  }, [books]);

  const filteredBooks = useMemo(() => {
    return books.filter(book => {
      if (book.status !== BookStatus.Read) return true;
      if (!book.dateFinished) return true;
      const finishDate = new Date(book.dateFinished);
      if (dateFilter === 'thisYear') return finishDate.getFullYear() === new Date().getFullYear();
      if (dateFilter === 'specificYear') return finishDate.getFullYear() === selectedYear;
      if (dateFilter === 'custom') {
        const start = new Date(customRange.start);
        const end = new Date(customRange.end);
        return finishDate >= start && finishDate <= end;
      }
      return true;
    });
  }, [books, dateFilter, selectedYear, customRange]);

  const stats: ReadingStats = useMemo(() => {
    let tbrCount = quickSummary?.tbrCount || 0;
    let wishlistCount = quickSummary?.wishlistCount || 0;
    if (books.length > 0) {
      tbrCount = 0; wishlistCount = 0;
      books.forEach(book => {
        if (book.status === BookStatus.TBR) tbrCount++;
        if (book.status === BookStatus.Wishlist) wishlistCount++;
      });
    }
    const yearly = { booksRead: 0, pagesRead: 0, totalRating: 0, ratingCount: 0 };
    const monthlyDataMap = MONTHS.map(month => ({ month, booksRead: 0, pagesRead: 0, totalRating: 0, ratingCount: 0 }));
    const byTypeMap: Record<string, any> = {
      [BookType.Book]: { type: BookType.Book, count: 0, pages: 0, totalRating: 0, ratingCount: 0 },
      [BookType.HQ]: { type: BookType.HQ, count: 0, pages: 0, totalRating: 0, ratingCount: 0 }
    };
    filteredBooks.forEach(book => {
      if (book.status === BookStatus.Read) {
        yearly.booksRead++;
        yearly.pagesRead += (book.pages || 0);
        if (book.rating) { yearly.totalRating += book.rating; yearly.ratingCount++; }
        if (book.dateFinished) {
          const monthIndex = new Date(book.dateFinished).getMonth();
          const mData = monthlyDataMap[monthIndex];
          if (mData) {
            mData.booksRead++;
            mData.pagesRead += (book.pages || 0);
            if (book.rating) { mData.totalRating += book.rating; mData.ratingCount++; }
          }
        }
        const tData = byTypeMap[book.type];
        if (tData) {
          tData.count++;
          tData.pages += (book.pages || 0);
          if (book.rating) { tData.totalRating += book.rating; tData.ratingCount++; }
        }
      }
    });
    return {
      tbrCount, wishlistCount,
      yearly: {
        booksRead: books.length === 0 && quickSummary ? quickSummary.readCount : yearly.booksRead,
        pagesRead: yearly.pagesRead,
        avgRating: yearly.ratingCount > 0 ? yearly.totalRating / yearly.ratingCount : 0
      },
      monthly: monthlyDataMap.map(m => ({
        month: m.month, booksRead: m.booksRead, pagesRead: m.pagesRead,
        avgRating: m.ratingCount > 0 ? m.totalRating / m.ratingCount : 0
      })),
      byType: Object.values(byTypeMap).map(t => ({
        type: t.type, count: t.count, pages: t.pages,
        avgRating: t.ratingCount > 0 ? t.totalRating / t.ratingCount : 0
      }))
    };
  }, [books, filteredBooks, quickSummary]);

  const currentlyReading = useMemo(() => books.find(b => b.status === BookStatus.Reading) || null, [books]);

  return {
    books, stats, currentlyReading, addBook, updateBook, deleteBook, 
    dateFilter, setDateFilter, selectedYear, setSelectedYear, availableYears,
    customRange, setCustomRange, isLocalMode, schemaError, isLoading
  };
};

/**
 * Utilitário para otimização extrema de imagens no lado do cliente.
 * Reduz dimensões e aplica compressão pesada para garantir fluidez em conexões lentas.
 */
export const optimizeBase64Image = (base64Data: string, maxWidth: number = 240, quality: number = 0.5): Promise<string> => {
  return new Promise((resolve) => {
    // Se não for uma imagem base64 ou for muito pequena, ignora
    if (!base64Data || !base64Data.startsWith('data:image')) {
      resolve(base64Data);
      return;
    }

    const img = new Image();
    img.src = base64Data;
    img.onload = () => {
      const canvas = document.createElement('canvas');
      let width = img.width;
      let height = img.height;

      // Redimensionamento agressivo para miniaturas
      if (width > maxWidth) {
        height = Math.round((height * maxWidth) / width);
        width = maxWidth;
      }

      canvas.width = width;
      canvas.height = height;

      const ctx = canvas.getContext('2d');
      if (!ctx) {
        resolve(base64Data);
        return;
      }

      // Desabilita suavização de alta qualidade para ganhar performance no processamento
      ctx.imageSmoothingEnabled = true;
      ctx.imageSmoothingQuality = 'low'; 

      ctx.drawImage(img, 0, 0, width, height);

      // WebP com compressão de 50% (ideal para economia de KB em strings JSON)
      const optimized = canvas.toDataURL('image/webp', quality);

      // Retorna a menor versão
      resolve(optimized.length < base64Data.length ? optimized : base64Data);
    };
    img.onerror = () => resolve(base64Data);
  });
};

import { GoogleGenAI, GenerateContentResponse, Type } from "@google/genai";
import { Recommendation } from "../types";
import { optimizeBase64Image } from "./imageOptimizer";

const stringifyError = (err: any): string => {
  if (!err) return "Erro desconhecido";
  if (typeof err === 'string') return err;
  if (err.message) return err.message;
  try {
    const parsed = JSON.stringify(err);
    if (parsed === '{}') return err.toString();
    return parsed;
  } catch {
    return String(err);
  }
};

const callGenAI = async (task: (ai: GoogleGenAI) => Promise<any>, modelName?: string) => {
  const isProModel = modelName === 'gemini-3-pro-image-preview' || modelName?.includes('pro');

  if (isProModel && window.aistudio) {
    const hasKey = await window.aistudio.hasSelectedApiKey();
    if (!hasKey) {
      await window.aistudio.openSelectKey();
    }
  }

  const apiKey = process.env.API_KEY;

  if (!apiKey || apiKey === 'undefined' || apiKey === '') {
    if (window.aistudio) {
      await window.aistudio.openSelectKey();
    }
    throw new Error("API_KEY_MISSING");
  }

  try {
    const ai = new GoogleGenAI({ apiKey });
    return await task(ai);
  } catch (error: any) {
    const errorMsg = stringifyError(error);
    console.error(`Gemini API Error [${modelName || 'unknown'}]:`, errorMsg);

    if (
      errorMsg.includes("PERMISSION_DENIED") ||
      errorMsg.includes("403") ||
      errorMsg.includes("The caller does not have permission") ||
      errorMsg.includes("Requested entity was not found") ||
      errorMsg.includes("404")
    ) {
      if (window.aistudio) {
        await window.aistudio.openSelectKey();
      }
    }
    throw error;
  }
};

export const generateBookSummary = async (title: string, author: string): Promise<string> => {
  const model = 'gemini-3-flash-preview';
  try {
    return await callGenAI(async (ai) => {
      const prompt = `Escreva um resumo curto (um parágrafo) e envolvente em Português para o livro "${title}" de ${author}. Não dê spoilers.`;
      const response: GenerateContentResponse = await ai.models.generateContent({
        model,
        contents: prompt,
      });
      return response.text || "Não foi possível gerar um resumo.";
    }, model);
  } catch (error: any) {
    return `A IA não conseguiu processar o resumo no momento. Verifique sua chave de API.`;
  }
};

export const generateBookCover = async (title: string, genre: string, type: string, author?: string): Promise<string> => {
  const model = 'gemini-3-pro-image-preview';

  try {
    const base64Image = await callGenAI(async (ai) => {
      const prompt = `Pesquise a capa original do livro "${title}" ${author ? `de ${author}` : ''}. 
      Baseado nos resultados da pesquisa, gere uma nova capa artística e minimalista. 
      Gênero: ${genre}. 
      Estilo: Profissional, simbólico. Evite textos pequenos.`;

      const response: GenerateContentResponse = await ai.models.generateContent({
        model,
        contents: { parts: [{ text: prompt }] },
        config: {
          imageConfig: {
            aspectRatio: "3:4"
          },
          tools: [{ googleSearch: {} }]
        },
      });

      if (response.candidates?.[0]?.content?.parts) {
        for (const part of response.candidates[0].content.parts) {
          if (part.inlineData) {
            return `data:image/png;base64,${part.inlineData.data}`;
          }
        }
      }

      return `https://picsum.photos/seed/${encodeURIComponent(title)}/240/360`;
    }, model);

    // OTIMIZAÇÃO EXTREMA: 240px largura, 0.5 qualidade
    if (base64Image && base64Image.startsWith('data:image')) {
      return await optimizeBase64Image(base64Image, 240, 0.5);
    }

    return base64Image;
  } catch (error: any) {
    console.error("Erro na geração de capa:", stringifyError(error));
    return `https://picsum.photos/seed/${encodeURIComponent(title)}/240/360`;
  }
};

export const getAIRecommendations = async (readBooks: { title: string, genre: string }[]): Promise<Recommendation[]> => {
  if (readBooks.length === 0) return [];
  const model = 'gemini-3-flash-preview';
  try {
    return await callGenAI(async (ai) => {
      const booksDescription = readBooks.map(b => `${b.title} (${b.genre})`).join(', ');
      const prompt = `Com base em: ${booksDescription}. Recomende 3 livros novos em Português com links de busca na Amazon Brasil.`;
      const response: GenerateContentResponse = await ai.models.generateContent({
        model,
        contents: prompt,
        config: {
          responseMimeType: "application/json",
          responseSchema: {
            type: Type.ARRAY,
            items: {
              type: Type.OBJECT,
              properties: {
                title: { type: Type.STRING },
                author: { type: Type.STRING },
                reason: { type: Type.STRING },
                genre: { type: Type.STRING },
                buyLink: { type: Type.STRING },
              },
              required: ["title", "author", "reason", "genre", "buyLink"]
            }
          }
        }
      });
      return JSON.parse(response.text || '[]');
    }, model);
  } catch (error: any) {
    return [];
  }
};

import type { Book, Profile } from '../types';
import { supabase } from './supabase';
import { BookStatus } from '../types';

const TABLE_NAME = 'books';
const BASE_LOCAL_STORAGE_KEY = 'biblio_tech_cache_';
const FETCH_TIMEOUT_MS = 4000; // Timeout agressivo: falha rápido para usar cache local

const mapBookToDb = (book: any) => {
    const dateAddedValue = book.dateAdded || new Date().toISOString().split('T')[0];
    return {
        id: book.id,
        user_id: book.user_id,
        title: book.title || 'Sem Título',
        author: book.author || 'Autor Desconhecido',
        pages: Math.floor(parseInt(String(book.pages || 0), 10)),
        genre: book.genre || '',
        type: book.type || 'Livro',
        status: book.status || 'Não lido',
        rating: (book.rating !== undefined && book.rating !== null && book.rating !== 0) ? parseFloat(String(book.rating)) : null,
        cover_image_url: book.cover_image_url || book.coverImageUrl || null,
        summary: book.summary || null,
        notes: book.notes || null,
        estimated_price: (book.estimatedPrice !== undefined && book.estimatedPrice !== null) ? parseFloat(String(book.estimatedPrice)) : null,
        price_paid: (book.pricePaid !== undefined && book.pricePaid !== null) ? parseFloat(String(book.pricePaid)) : null,
        buy_link: book.buyLink || null,
        current_page: Math.floor(parseInt(String(book.currentPage || 0), 10)),
        date_added: dateAddedValue,
        date_started: book.dateStarted || null,
        date_finished: book.dateFinished || null,
        days_to_finish: (book.daysToFinish !== undefined && book.daysToFinish !== null) ? Math.floor(parseInt(String(book.daysToFinish), 10)) : null,
        times_read: (book.timesRead !== undefined && book.timesRead !== null) ? Math.floor(parseInt(String(book.timesRead), 10)) : 0,
        was_wishlist: book.wasWishlist === true
    };
};

const mapDbToBook = (db: any): Book => ({
    id: db.id,
    user_id: db.user_id,
    title: db.title,
    author: db.author,
    pages: db.pages || 0,
    genre: db.genre || '',
    type: db.type,
    status: db.status as BookStatus,
    rating: db.rating ? parseFloat(String(db.rating)) : undefined,
    coverImageUrl: db.cover_image_url,
    summary: db.summary,
    notes: db.notes,
    estimatedPrice: db.estimated_price ? parseFloat(String(db.estimated_price)) : undefined,
    pricePaid: db.price_paid ? parseFloat(String(db.price_paid)) : undefined,
    buyLink: db.buy_link,
    currentPage: db.current_page || 0,
    dateAdded: db.date_added,
    dateStarted: db.date_started,
    dateFinished: db.date_finished,
    daysToFinish: db.days_to_finish,
    timesRead: db.times_read || 0,
    wasWishlist: db.was_wishlist === true
});

const withTimeoutAndRetry = <T>(
    promiseFn: () => Promise<any>, 
    ms: number
): Promise<T> => {
  return new Promise((resolve, reject) => {
    const timeoutId = setTimeout(() => reject(new Error("TIMEOUT")), ms);
    promiseFn()
      .then(res => {
        clearTimeout(timeoutId);
        resolve(res);
      })
      .catch(err => {
        clearTimeout(timeoutId);
        reject(err);
      });
  });
};

export class DatabaseService {
  private cachedUser: any = null;
  private onSchemaErrorCallback?: (type: 'table' | 'column' | 'permission', detail?: string) => void;

  setSchemaErrorCallback(cb: (type: 'table' | 'column' | 'permission', detail?: string) => void) {
    this.onSchemaErrorCallback = cb;
  }

  private async getSafeUser() {
    if (this.cachedUser) return this.cachedUser;
    try {
        const { data: { session } } = await supabase.auth.getSession();
        if (session?.user) {
            this.cachedUser = session.user;
            return session.user;
        }
        return null;
    } catch (e) {
        return null;
    }
  }

  async getAllBooks(): Promise<Book[]> {
    try {
      const user = await this.getSafeUser();
      if (!user) return await this.getLocalBooks();

      const fetchFn = () => supabase
        .from(TABLE_NAME)
        .select(`
          id, title, author, pages, genre, type, status, rating, 
          cover_image_url, current_page, date_added, date_started, 
          date_finished, days_to_finish, times_read, was_wishlist
        `)
        .order('date_added', { ascending: false })
        .limit(100); // Limite menor para acelerar resposta inicial

      const { data, error } = await withTimeoutAndRetry<any>(fetchFn, FETCH_TIMEOUT_MS);

      if (error) throw error;

      const books = (data || []).map(mapDbToBook);
      await this.saveLocalBooks(books);
      return books;
    } catch (err) {
      return await this.getLocalBooks();
    }
  }

  async getLocalBooks(): Promise<Book[]> {
    const user = await this.getSafeUser();
    if (!user) return [];
    try {
      const data = localStorage.getItem(`${BASE_LOCAL_STORAGE_KEY}${user.id}`);
      return data ? JSON.parse(data) : [];
    } catch (e) { return []; }
  }

  private async saveLocalBooks(books: Book[]): Promise<void> {
    const user = await this.getSafeUser();
    if (!user) return;
    try {
      localStorage.setItem(`${BASE_LOCAL_STORAGE_KEY}${user.id}`, JSON.stringify(books));
    } catch (e) {}
  }

  async saveBook(book: Partial<Book>): Promise<void> {
    const user = await this.getSafeUser();
    if (!user) return;

    const dbPayload = mapBookToDb(book);
    dbPayload.user_id = user.id;

    const books = await this.getLocalBooks();
    const index = books.findIndex(b => b.id === (book.id || dbPayload.id));
    const updatedBookState = mapDbToBook(dbPayload);

    if (index >= 0) books[index] = updatedBookState;
    else books.unshift(updatedBookState);
    await this.saveLocalBooks(books);

    // Salva na nuvem em segundo plano
    supabase.from(TABLE_NAME).upsert(dbPayload).catch(() => {});
  }

  async deleteBook(id: string): Promise<void> {
    const user = await this.getSafeUser();
    if (!user) return;
    const books = (await this.getLocalBooks()).filter(b => b.id !== id);
    await this.saveLocalBooks(books);
    supabase.from(TABLE_NAME).delete().eq('id', id).catch(() => {});
  }

  async getProfile(): Promise<Profile | null> {
    const user = await this.getSafeUser();
    if (!user) return null;
    try {
        const { data, error } = await supabase.from('profiles').select('id, full_name, avatar_url, reading_goal').eq('id', user.id).single();
        if (error || !data) return { id: user.id, fullName: 'Leitor', readingGoal: 12 };
        return {
            id: data.id,
            fullName: data.full_name,
            avatarUrl: data.avatar_url,
            readingGoal: data.reading_goal
        };
    } catch (err) { return { id: user.id, fullName: 'Leitor', readingGoal: 12 }; }
  }

  async updateReadingGoal(goal: number): Promise<void> {
    const user = await this.getSafeUser();
    if (!user) return;
    supabase.from('profiles').upsert({ id: user.id, reading_goal: Math.round(goal), updated_at: new Date().toISOString() }).catch(() => {});
  }

  async updateProfile(profile: Partial<Profile>): Promise<void> {
    const user = await this.getSafeUser();
    if (!user) return;
    const dbPayload: any = { id: user.id, updated_at: new Date().toISOString() };
    if (profile.fullName !== undefined) dbPayload.full_name = profile.fullName;
    supabase.from('profiles').upsert(dbPayload).catch(() => {});
  }

  async getQuickStatsSummary() {
    const user = await this.getSafeUser();
    if (!user) return null;
    try {
      const { data, error } = await withTimeoutAndRetry<any>(() => supabase.from(TABLE_NAME).select('status').eq('user_id', user.id), 3000);
      if (error) return null;
      const counts = (data || []).reduce((acc: any, curr: any) => {
        acc[curr.status] = (acc[curr.status] || 0) + 1;
        return acc;
      }, {});
      return {
        readCount: counts['Lido'] || 0,
        tbrCount: counts['Não lido'] || 0,
        wishlistCount: counts['Lista de Desejos'] || 0,
        droppedCount: counts['Abandonado'] || 0
      };
    } catch (e) { return null; }
  }

  async getLocalStats() {
    const user = await this.getSafeUser();
    if (!user) return null;
    try {
      const data = localStorage.getItem(`${BASE_LOCAL_STORAGE_KEY}${user.id}_stats`);
      return data ? JSON.parse(data) : null;
    } catch (e) { return null; }
  }
}

