const TABLE_NAME = 'books';
const BASE_LOCAL_STORAGE_KEY = 'biblio_tech_cache_';
const FETCH_TIMEOUT_MS = 12000;

const withRetry = async <T>(
  promiseFn: () => Promise<any>,
  maxRetries: number = 2,
  delay: number = 1000
): Promise<T> => {
  let lastError: any;

  for (let attempt = 0; attempt <= maxRetries; attempt++) {
    try {
      const result = await Promise.race([
        promiseFn(),
        new Promise((_, reject) => 
          setTimeout(() => reject(new Error("TIMEOUT")), FETCH_TIMEOUT_MS)
        )
      ]);

      if (result && (result as any).error) throw (result as any).error;
      const data = (result && (result as any).data !== undefined) ? (result as any).data : result;
      return data as T;
    } catch (err: any) {
      lastError = err;
      const errorMsg = err.message?.toLowerCase() || '';

      const isRetryable = 
        errorMsg.includes('fetch') || 
        errorMsg.includes('network') || 
        errorMsg.includes('timeout') ||
        errorMsg.includes('abort') ||
        err instanceof TypeError;

      if (isRetryable && attempt < maxRetries) {
        const backoff = delay * (attempt + 1);
        console.warn(`[Supabase] Tentativa ${attempt + 1} falhou: ${errorMsg}. Tentando novamente em ${backoff}ms...`);
        await new Promise(resolve => setTimeout(resolve, backoff));
        continue;
      }
      break;
    }
  }
  throw lastError;
};

const mapBookToDb = (book: any) => {
    const dateAddedValue = book.dateAdded || new Date().toISOString().split('T')[0];
    return {
        id: book.id,
        user_id: book.user_id,
        title: book.title || 'Sem Título',
        author: book.author || 'Autor Desconhecido',
        pages: Math.floor(parseInt(String(book.pages || 0), 10)),
        genre: book.genre || '',
        type: book.type || 'Livro',
        status: book.status || 'Não lido',
        rating: (book.rating !== undefined && book.rating !== null && book.rating !== 0) ? parseFloat(String(book.rating)) : null,
        summary: book.summary || null,
        notes: book.notes || null,
        estimated_price: (book.estimatedPrice !== undefined && book.estimatedPrice !== null) ? parseFloat(String(book.estimatedPrice)) : null,
        price_paid: (book.pricePaid !== undefined && book.pricePaid !== null) ? parseFloat(String(book.pricePaid)) : null,
        buy_link: book.buyLink || null,
        current_page: Math.floor(parseInt(String(book.currentPage || 0), 10)),
        date_added: dateAddedValue,
        date_started: book.dateStarted || null,
        date_finished: book.dateFinished || null,
        days_to_finish: (book.daysToFinish !== undefined && book.daysToFinish !== null) ? Math.floor(parseInt(String(book.daysToFinish), 10)) : null,
        times_read: (book.timesRead !== undefined && book.timesRead !== null) ? Math.floor(parseInt(String(book.timesRead), 10)) : 0,
        was_wishlist: book.wasWishlist === true
    };
};

const mapDbToBook = (db: any): Book => ({
    id: db.id,
    user_id: db.user_id,
    title: db.title,
    author: db.author,
    pages: db.pages || 0,
    genre: db.genre || '',
    type: db.type,
    status: db.status as BookStatus,
    rating: db.rating ? parseFloat(String(db.rating)) : undefined,
    summary: db.summary,
    notes: db.notes,
    estimatedPrice: db.estimated_price ? parseFloat(String(db.estimated_price)) : undefined,
    pricePaid: db.price_paid ? parseFloat(String(db.price_paid)) : undefined,
    buyLink: db.buy_link,
    currentPage: db.current_page || 0,
    dateAdded: db.date_added,
    dateStarted: db.date_started,
    dateFinished: db.date_finished,
    daysToFinish: db.days_to_finish,
    timesRead: db.times_read || 0,
    wasWishlist: db.was_wishlist === true
});

export class DatabaseService {
  private cachedUser: any = null;
  private onSchemaErrorCallback?: (type: 'table' | 'column' | 'permission', detail?: string) => void;

  setSchemaErrorCallback(cb: (type: 'table' | 'column' | 'permission', detail?: string) => void) {
    this.onSchemaErrorCallback = cb;
  }

  private async getSafeUser() {
    if (this.cachedUser) return this.cachedUser;
    try {
        const { data: { session } } = await supabase.auth.getSession();
        if (session?.user) {
            this.cachedUser = session.user;
            return session.user;
        }
        return null;
    } catch (e) {
        return null;
    }
  }

  async getAllBooks(): Promise<Book[]> {
    try {
      const user = await this.getSafeUser();
      if (!user) return await this.getLocalBooks();

      const data = await withRetry<any[]>(() => supabase
        .from(TABLE_NAME)
        .select(`
          id, title, author, pages, genre, type, status, rating, 
          current_page, date_added, date_started, 
          date_finished, days_to_finish, times_read, was_wishlist,
          summary, notes, estimated_price, price_paid, buy_link, user_id
        `)
        .eq('user_id', user.id)
        .order('date_added', { ascending: false })
      );

      const books = (data || []).map(mapDbToBook);
      await this.saveLocalBooks(books);
      return books;
    } catch (err: any) {
      console.error("Erro na nuvem, carregando local:", err.message || err);
      return await this.getLocalBooks();
    }
  }

  // Removido migrateImagesToStorage pois não usamos mais imagens

  async getLocalBooks(): Promise<Book[]> {
    const user = await this.getSafeUser();
    if (!user) return [];
    try {
      const data = localStorage.getItem(`${BASE_LOCAL_STORAGE_KEY}${user.id}`);
      return data ? JSON.parse(data) : [];
    } catch (e) { return []; }
  }

  private async saveLocalBooks(books: Book[]): Promise<void> {
    const user = await this.getSafeUser();
    if (!user) return;
    try {
      localStorage.setItem(`${BASE_LOCAL_STORAGE_KEY}${user.id}`, JSON.stringify(books));
    } catch (e) {}
  }

  async saveBook(book: Partial<Book>): Promise<void> {
    const user = await this.getSafeUser();
    if (!user) return;

    const bookId = book.id || crypto.randomUUID();
    const updatedBookForDb = { ...book, id: bookId, user_id: user.id };
    const dbPayload = mapBookToDb(updatedBookForDb);

    const books = await this.getLocalBooks();
    const index = books.findIndex(b => b.id === bookId);
    const updatedBookState = mapDbToBook(dbPayload);

    if (index >= 0) books[index] = updatedBookState;
    else books.unshift(updatedBookState);
    await this.saveLocalBooks(books);

    withRetry(() => supabase.from(TABLE_NAME).upsert(dbPayload)).catch(() => {});
  }

  async deleteBook(id: string): Promise<void> {
    const user = await this.getSafeUser();
    if (!user) return;

    const books = (await this.getLocalBooks()).filter(b => b.id !== id);
    await this.saveLocalBooks(books);

    supabase.from(TABLE_NAME).delete().eq('id', id).catch(() => {});
  }

  async getProfile(): Promise<Profile | null> {
    const user = await this.getSafeUser();
    if (!user) return null;
    try {
        const data = await withRetry<any>(() => 
          supabase.from('profiles').select('id, full_name, avatar_url, reading_goal').eq('id', user.id).single()
        );
        return {
            id: data.id,
            fullName: data.full_name,
            avatarUrl: data.avatar_url,
            readingGoal: data.reading_goal
        };
    } catch (err) { return { id: user.id, fullName: 'Leitor', readingGoal: 12 }; }
  }

  async updateReadingGoal(goal: number): Promise<void> {
    const user = await this.getSafeUser();
    if (!user) return;
    withRetry(() => supabase.from('profiles').upsert({ id: user.id, reading_goal: Math.round(goal), updated_at: new Date().toISOString() })).catch(() => {});
  }

  async updateProfile(profile: Partial<Profile>): Promise<void> {
    const user = await this.getSafeUser();
    if (!user) return;
    const dbPayload: any = { id: user.id, updated_at: new Date().toISOString() };
    if (profile.fullName !== undefined) dbPayload.full_name = profile.fullName;
    withRetry(() => supabase.from('profiles').upsert(dbPayload)).catch(() => {});
  }

  async getQuickStatsSummary() {
    const user = await this.getSafeUser();
    if (!user) return null;
    try {
      const data = await withRetry<any[]>(() => 
        supabase.from(TABLE_NAME).select('status').eq('user_id', user.id)
      );
      const counts = (data || []).reduce((acc: any, curr: any) => {
        acc[curr.status] = (acc[curr.status] || 0) + 1;
        return acc;
      }, {});
      return {
        readCount: counts['Lido'] || 0,
        tbrCount: counts['Não lido'] || 0,
        wishlistCount: counts['Lista de Desejos'] || 0,
        droppedCount: counts['Abandonado'] || 0
      };
    } catch (e) { return null; }
  }

  async getLocalStats() {
    const user = await this.getSafeUser();
    if (!user) return null;
    try {
      const data = localStorage.getItem(`${BASE_LOCAL_STORAGE_KEY}${user.id}_stats`);
      return data ? JSON.parse(data) : null;
    } catch (e) { return null; }
  }
}

export const dbService = new DatabaseService();

import { GoogleGenAI, GenerateContentResponse, Type } from "@google/genai";
import { Recommendation } from "../types";

const stringifyError = (err: any): string => {
  if (!err) return "Erro desconhecido";
  if (typeof err === 'string') return err;
  if (err.message) return err.message;
  try {
    const parsed = JSON.stringify(err);
    if (parsed === '{}') return err.toString();
    return parsed;
  } catch {
    return String(err);
  }
};

const callGenAI = async (task: (ai: GoogleGenAI) => Promise<any>, modelName?: string) => {
  const isProModel = modelName === 'gemini-3-pro-image-preview' || modelName?.includes('pro');

  if (isProModel && window.aistudio) {
    const hasKey = await window.aistudio.hasSelectedApiKey();
    if (!hasKey) {
      await window.aistudio.openSelectKey();
    }
  }

  const apiKey = process.env.API_KEY;

  if (!apiKey || apiKey === 'undefined' || apiKey === '') {
    if (window.aistudio) {
      await window.aistudio.openSelectKey();
    }
    throw new Error("API_KEY_MISSING");
  }

  try {
    const ai = new GoogleGenAI({ apiKey });
    return await task(ai);
  } catch (error: any) {
    const errorMsg = stringifyError(error);
    console.error(`Gemini API Error [${modelName || 'unknown'}]:`, errorMsg);

    if (
      errorMsg.includes("PERMISSION_DENIED") ||
      errorMsg.includes("403") ||
      errorMsg.includes("The caller does not have permission") ||
      errorMsg.includes("Requested entity was not found") ||
      errorMsg.includes("404")
    ) {
      if (window.aistudio) {
        await window.aistudio.openSelectKey();
      }
    }
    throw error;
  }
};

export const generateBookSummary = async (title: string, author: string): Promise<string> => {
  const model = 'gemini-3-flash-preview';
  try {
    return await callGenAI(async (ai) => {
      const prompt = `Escreva um resumo curto (um parágrafo) e envolvente em Português para o livro "${title}" de ${author}. Não dê spoilers.`;
      const response: GenerateContentResponse = await ai.models.generateContent({
        model,
        contents: prompt,
      });
      return response.text || "Não foi possível gerar um resumo.";
    }, model);
  } catch (error: any) {
    return `A IA não conseguiu processar o resumo no momento. Verifique sua chave de API.`;
  }
};

export const getAIRecommendations = async (readBooks: { title: string, genre: string }[]): Promise<Recommendation[]> => {
  if (readBooks.length === 0) return [];
  const model = 'gemini-3-flash-preview';
  try {
    return await callGenAI(async (ai) => {
      const booksDescription = readBooks.map(b => `${b.title} (${b.genre})`).join(', ');
      const prompt = `Com base em: ${booksDescription}. Recomende 3 livros novos em Português com links de busca na Amazon Brasil.`;
      const response: GenerateContentResponse = await ai.models.generateContent({
        model,
        contents: prompt,
        config: {
          responseMimeType: "application/json",
          responseSchema: {
            type: Type.ARRAY,
            items: {
              type: Type.OBJECT,
              properties: {
                title: { type: Type.STRING },
                author: { type: Type.STRING },
                reason: { type: Type.STRING },
                genre: { type: Type.STRING },
                buyLink: { type: Type.STRING },
              },
              required: ["title", "author", "reason", "genre", "buyLink"]
            }
          }
        }
      });
      return JSON.parse(response.text || '[]');
    }, model);
  } catch (error: any) {
    return [];
  }
};

import { useState, useMemo, useCallback, useEffect, useRef } from 'react';
import type { Book, ReadingStats, NewBook, DateFilter } from '../types';
import { BookStatus, BookType } from '../types';
import { dbService } from '../services/database';
import { supabase } from '../services/supabase';

const MONTHS = ['Janeiro', 'Fevereiro', 'Março', 'Abril', 'Maio', 'Junho', 'Julho', 'Agosto', 'Setembro', 'Outubro', 'Novembro', 'Dezembro'];

export const useBookData = () => {
  const [books, setBooks] = useState<Book[]>([]);
  const [isLoading, setIsLoading] = useState(true);
  const [isLocalMode, setIsLocalMode] = useState(false);
  const [schemaError, setSchemaError] = useState<{type: 'table' | 'column' | 'permission', detail?: string} | null>(null);
  const [dateFilter, setDateFilter] = useState<DateFilter>('allTime');
  const [selectedYear, setSelectedYear] = useState<number>(new Date().getFullYear());
  const [customRange, setCustomRange] = useState({ 
    start: new Date(new Date().getFullYear(), 0, 1).toISOString().split('T')[0],
    end: new Date().toISOString().split('T')[0]
  });

  const [quickSummary, setQuickSummary] = useState<{readCount: number, tbrCount: number, wishlistCount: number} | null>(null);
  const isSincronizing = useRef(false);

  const loadCache = useCallback(async () => {
    try {
      const cachedBooks = await dbService.getLocalBooks();
      const cachedStats = await dbService.getLocalStats();

      if (cachedBooks.length > 0) setBooks(cachedBooks);
      if (cachedStats) setQuickSummary(cachedStats);
    } finally {
      setIsLoading(false);
    }
  }, []);

  const syncWithCloud = useCallback(async () => {
    if (isSincronizing.current) return;
    isSincronizing.current = true;

    dbService.setSchemaErrorCallback((type, detail) => {
        setSchemaError({ type, detail });
        setIsLocalMode(true);
    });

    try {
      const [booksResult, statsResult] = await Promise.allSettled([
        dbService.getAllBooks(),
        dbService.getQuickStatsSummary()
      ]);

      if (booksResult.status === 'fulfilled') {
        setBooks(booksResult.value);
      }

      if (statsResult.status === 'fulfilled' && statsResult.value) {
        setQuickSummary(statsResult.value);
      }
    } catch (e) {
      console.warn("Sincronização com a nuvem falhou, mantendo dados locais.");
    } finally {
      setIsLoading(false);
      isSincronizing.current = false;
    }
  }, []);

  useEffect(() => {
    loadCache().then(() => syncWithCloud());

    const { data: { subscription } } = supabase.auth.onAuthStateChange((event) => {
      if (event === 'SIGNED_IN') {
        syncWithCloud();
      }
    });
    return () => subscription.unsubscribe();
  }, [loadCache, syncWithCloud]);

  const addBook = useCallback(async (newBook: NewBook) => {
    const { data: { session } } = await supabase.auth.getSession();
    const user = session?.user;
    if (!user) throw new Error("Necessário login.");

    const book: Book = {
      ...newBook,
      id: crypto.randomUUID(),
      user_id: user.id,
      dateAdded: newBook.dateAdded || new Date().toISOString().split('T')[0],
    };

    setBooks(prev => [book, ...prev]);
    await dbService.saveBook(book);
  }, []);

  const updateBook = useCallback(async (updatedBook: Book) => {
    setBooks(prev => prev.map(b => b.id === updatedBook.id ? updatedBook : b));
    await dbService.saveBook(updatedBook);
  }, []);

  const deleteBook = useCallback(async (id: string) => {
    setBooks(prev => prev.filter(b => b.id !== id));
    await dbService.deleteBook(id);
  }, []);

  const availableYears = useMemo(() => {
    const years = new Set<number>();
    years.add(new Date().getFullYear());
    books.forEach(book => {
      if (book.dateFinished) years.add(new Date(book.dateFinished).getFullYear());
      else if (book.dateAdded) years.add(new Date(book.dateAdded).getFullYear());
    });
    return Array.from(years).sort((a, b) => b - a);
  }, [books]);

  const filteredBooks = useMemo(() => {
    return books.filter(book => {
      if (book.status !== BookStatus.Read) return true;
      if (!book.dateFinished) return true;
      const finishDate = new Date(book.dateFinished);
      if (dateFilter === 'thisYear') return finishDate.getFullYear() === new Date().getFullYear();
      if (dateFilter === 'specificYear') return finishDate.getFullYear() === selectedYear;
      if (dateFilter === 'custom') {
        const start = new Date(customRange.start);
        const end = new Date(customRange.end);
        return finishDate >= start && finishDate <= end;
      }
      return true;
    });
  }, [books, dateFilter, selectedYear, customRange]);

  const stats: ReadingStats = useMemo(() => {
    let tbrCount = quickSummary?.tbrCount || 0;
    let wishlistCount = quickSummary?.wishlistCount || 0;
    if (books.length > 0) {
      tbrCount = 0; wishlistCount = 0;
      books.forEach(book => {
        if (book.status === BookStatus.TBR) tbrCount++;
        if (book.status === BookStatus.Wishlist) wishlistCount++;
      });
    }
    const yearly = { booksRead: 0, pagesRead: 0, totalRating: 0, ratingCount: 0 };
    const monthlyDataMap = MONTHS.map(month => ({ month, booksRead: 0, pagesRead: 0, totalRating: 0, ratingCount: 0 }));
    const byTypeMap: Record<string, any> = {
      [BookType.Book]: { type: BookType.Book, count: 0, pages: 0, totalRating: 0, ratingCount: 0 },
      [BookType.HQ]: { type: BookType.HQ, count: 0, pages: 0, totalRating: 0, ratingCount: 0 }
    };
    filteredBooks.forEach(book => {
      if (book.status === BookStatus.Read) {
        yearly.booksRead++;
        yearly.pagesRead += (book.pages || 0);
        if (book.rating) { yearly.totalRating += book.rating; yearly.ratingCount++; }
        if (book.dateFinished) {
          const monthIndex = new Date(book.dateFinished).getMonth();
          const mData = monthlyDataMap[monthIndex];
          if (mData) {
            mData.booksRead++;
            mData.pagesRead += (book.pages || 0);
            if (book.rating) { mData.totalRating += book.rating; mData.ratingCount++; }
          }
        }
        const tData = byTypeMap[book.type];
        if (tData) {
          tData.count++;
          tData.pages += (book.pages || 0);
          if (book.rating) { tData.totalRating += book.rating; tData.ratingCount++; }
        }
      }
    });
    return {
      tbrCount, wishlistCount,
      yearly: {
        booksRead: books.length === 0 && quickSummary ? quickSummary.readCount : yearly.booksRead,
        pagesRead: yearly.pagesRead,
        avgRating: yearly.ratingCount > 0 ? yearly.totalRating / yearly.ratingCount : 0
      },
      monthly: monthlyDataMap.map(m => ({
        month: m.month, booksRead: m.booksRead, pagesRead: m.pagesRead,
        avgRating: m.ratingCount > 0 ? m.totalRating / m.ratingCount : 0
      })),
      byType: Object.values(byTypeMap).map(t => ({
        type: t.type, count: t.count, pages: t.pages,
        avgRating: t.ratingCount > 0 ? t.totalRating / t.ratingCount : 0
      }))
    };
  }, [books, filteredBooks, quickSummary]);

  const currentlyReading = useMemo(() => books.find(b => b.status === BookStatus.Reading) || null, [books]);

  return {
    books, stats, currentlyReading, addBook, updateBook, deleteBook, 
    dateFilter, setDateFilter, selectedYear, setSelectedYear, availableYears,
    customRange, setCustomRange, isLocalMode, schemaError, isLoading
  };
};

import React, { useState, useCallback, useEffect, useRef, useMemo } from 'react';
import type { NewBook, Book, StatusConfigs } from '../types';
import { BookStatus, BookType, GENRES, STATUS_CONFIGS } from '../types';
import { XMarkIcon, BookOpenIcon, StarIcon, StarIconFilled, PlusIcon, TagIcon } from './Icons';
import { generateBookSummary } from '../services/geminiService';

interface AddBookModalProps {
  onClose: () => void;
  onAddBook: (book: NewBook) => Promise<void>;
  onUpdateBook: (book: Book) => Promise<void>;
  bookToEdit?: Book | null;
  isDuplicating?: boolean;
  defaultStatus?: BookStatus;
  existingBooks: Book[];
  statusConfigs?: StatusConfigs;
}

interface FormErrors {
  title?: string;
  authors?: string;
  genre?: string;
}

export const AddBookModal: React.FC<AddBookModalProps> = ({ 
  onClose, 
  onAddBook, 
  onUpdateBook, 
  bookToEdit, 
  isDuplicating = false,
  defaultStatus, 
  existingBooks, 
  statusConfigs = STATUS_CONFIGS 
}) => {
  const isEditMode = !!bookToEdit && !isDuplicating;

  const [title, setTitle] = useState(bookToEdit?.title || '');
  const [authors, setAuthors] = useState<string[]>(
    bookToEdit?.author ? bookToEdit.author.split(',').map(a => a.trim()).filter(a => a !== '') : []
  );
  const [authorInput, setAuthorInput] = useState('');
  const [pages, setPages] = useState(bookToEdit?.pages || 0);
  const [currentPage, setCurrentPage] = useState(isDuplicating ? 0 : (bookToEdit?.currentPage || 0));
  const [selectedGenres, setSelectedGenres] = useState<string[]>(
    bookToEdit?.genre ? bookToEdit.genre.split(',').map(g => g.trim()).filter(g => g !== '') : []
  );
  const [type, setType] = useState<BookType>(bookToEdit?.type || BookType.Book);
  const [status, setStatus] = useState<BookStatus>(bookToEdit?.status || defaultStatus || BookStatus.TBR);
  const [rating, setRating] = useState<number>(isDuplicating ? 0 : (bookToEdit?.rating || 0));
  const [summary, setSummary] = useState(bookToEdit?.summary || '');
  const [notes, setNotes] = useState(isDuplicating ? '' : (bookToEdit?.notes || ''));
  const [estimatedPrice, setEstimatedPrice] = useState(bookToEdit?.estimatedPrice?.toString() || '');
  const [pricePaid, setPricePaid] = useState(isDuplicating ? '' : (bookToEdit?.pricePaid?.toString() || ''));
  const [buyLink, setBuyLink] = useState(bookToEdit?.buyLink || '');
  const [isGeneratingSummary, setIsGeneratingSummary] = useState(false);
  const [isSubmitting, setIsSubmitting] = useState(false);

  const [dateAdded, setDateAdded] = useState(isDuplicating ? new Date().toISOString().split('T')[0] : (bookToEdit?.dateAdded || new Date().toISOString().split('T')[0]));
  const [dateFinished, setDateFinished] = useState(isDuplicating ? new Date().toISOString().split('T')[0] : (bookToEdit?.dateFinished || new Date().toISOString().split('T')[0]));
  const [daysToFinish, setDaysToFinish] = useState(isDuplicating ? '' : (bookToEdit?.daysToFinish?.toString() || ''));
  const [timesRead, setTimesRead] = useState(isDuplicating ? 0 : (bookToEdit?.timesRead || (bookToEdit?.status === BookStatus.Read ? 1 : 0)));

  const [errors, setErrors] = useState<FormErrors>({});
  const [isShaking, setIsShaking] = useState(false);

  const [titleSuggestions, setTitleSuggestions] = useState<string[]>([]);
  const [authorSuggestions, setAuthorSuggestions] = useState<string[]>([]);
  const [activeSuggestionIndex, setActiveSuggestionIndex] = useState(0);
  const [showTitleSug, setShowTitleSug] = useState(false);
  const [showAuthorSug, setShowAuthorSug] = useState(false);

  const titleRef = useRef<HTMLDivElement>(null);
  const authorRef = useRef<HTMLDivElement>(null);

  const uniqueTitles = useMemo(() => Array.from(new Set(existingBooks.map(b => b.title))), [existingBooks]);
  const uniqueAuthors = useMemo(() => {
    const all = existingBooks.flatMap(b => b.author.split(',').map(a => a.trim()));
    return Array.from(new Set(all));
  }, [existingBooks]);

  useEffect(() => {
    const handleClickOutside = (event: MouseEvent) => {
      if (titleRef.current && !titleRef.current.contains(event.target as Node)) setShowTitleSug(false);
      if (authorRef.current && !authorRef.current.contains(event.target as Node)) setShowAuthorSug(false);
    };
    document.addEventListener('mousedown', handleClickOutside);
    return () => document.removeEventListener('mousedown', handleClickOutside);
  }, []);

  const addAuthor = (name?: string) => {
    const val = name || authorInput.trim();
    if (val && !authors.includes(val)) {
      setAuthors([...authors, val]);
      setAuthorInput('');
      setShowAuthorSug(false);
      if (errors.authors) setErrors(prev => ({ ...prev, authors: undefined }));
    }
  };

  const removeAuthor = (name: string) => {
    setAuthors(authors.filter(a => a !== name));
  };

  const handleTitleChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const value = e.target.value;
    setTitle(value);
    if (errors.title) setErrors(prev => ({ ...prev, title: undefined }));
    if (value.trim().length > 0) {
      const filtered = uniqueTitles.filter(t => t.toLowerCase().includes(value.toLowerCase()) && t.toLowerCase() !== value.toLowerCase()).slice(0, 5);
      setTitleSuggestions(filtered);
      setShowTitleSug(filtered.length > 0);
      setActiveSuggestionIndex(0);
    } else {
      setShowTitleSug(false);
    }
  };

  const handleAuthorInputChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const value = e.target.value;
    setAuthorInput(value);
    if (value.trim().length > 0) {
      const filtered = uniqueAuthors.filter(a => a.toLowerCase().includes(value.toLowerCase()) && !authors.includes(a)).slice(0, 5);
      setAuthorSuggestions(filtered);
      setShowAuthorSug(filtered.length > 0);
      setActiveSuggestionIndex(0);
    } else {
      setShowAuthorSug(false);
    }
  };

  const handleKeyDown = (e: React.KeyboardEvent, type: 'title' | 'author') => {
    const suggestions = type === 'title' ? titleSuggestions : authorSuggestions;
    const show = type === 'title' ? showTitleSug : showAuthorSug;
    if (show && suggestions.length > 0) {
      if (e.key === 'ArrowDown') {
        e.preventDefault();
        setActiveSuggestionIndex(prev => (prev < suggestions.length - 1 ? prev + 1 : prev));
      } else if (e.key === 'ArrowUp') {
        e.preventDefault();
        setActiveSuggestionIndex(prev => (prev > 0 ? prev - 1 : 0));
      } else if (e.key === 'Enter') {
        e.preventDefault();
        const selected = suggestions[activeSuggestionIndex];
        if (type === 'title') {
          setTitle(selected);
          setShowTitleSug(false);
        } else {
          addAuthor(selected);
        }
      } else if (e.key === 'Escape') {
        type === 'title' ? setShowTitleSug(false) : setShowAuthorSug(false);
      }
    }
  };

  const toggleGenre = (genre: string) => {
    setSelectedGenres(prev => 
      prev.includes(genre) 
        ? prev.filter(g => g !== genre) 
        : [...prev, genre]
    );
    if (errors.genre) setErrors(prev => ({ ...prev, genre: undefined }));
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    if (isSubmitting) return;

    let finalAuthors = [...authors];
    if (authorInput.trim() && !finalAuthors.includes(authorInput.trim())) {
        finalAuthors.push(authorInput.trim());
    }

    const newErrors: FormErrors = {};
    const trimmedTitle = title.trim();

    if (!trimmedTitle) {
      newErrors.title = "O título é obrigatório";
    }

    if (finalAuthors.length === 0) newErrors.authors = "Adicione ao menos um autor";
    if (selectedGenres.length === 0) newErrors.genre = "Selecione ao menos um gênero";

    if (Object.keys(newErrors).length > 0) {
      setErrors(newErrors);
      setIsShaking(true);
      setTimeout(() => setIsShaking(false), 500);
      return;
    }

    setIsSubmitting(true);
    try {
        const bookData = { 
            title: trimmedTitle, 
            author: finalAuthors.join(', '), 
            pages, 
            genre: selectedGenres.join(', '), 
            type, 
            status, 
            summary, 
            notes,
            rating: (status === BookStatus.Read || rating > 0) ? (rating || undefined) : undefined,
            estimatedPrice: estimatedPrice ? parseFloat(estimatedPrice.replace(',', '.')) : undefined,
            pricePaid: pricePaid ? parseFloat(pricePaid.replace(',', '.')) : (isDuplicating ? undefined : bookToEdit?.pricePaid),
            buyLink: buyLink.trim() || undefined,
            dateAdded,
            currentPage: status === BookStatus.Read ? pages : (status === BookStatus.TBR || status === BookStatus.Wishlist ? 0 : currentPage),
            dateStarted: isDuplicating ? undefined : bookToEdit?.dateStarted,
            dateFinished: status === BookStatus.Read ? dateFinished : undefined,
            daysToFinish: status === BookStatus.Read && daysToFinish ? parseInt(daysToFinish, 10) : null,
            timesRead: status === BookStatus.Read ? Number(timesRead) : (isDuplicating ? 0 : (bookToEdit?.timesRead || 0)),
            wasWishlist: isDuplicating ? (status === BookStatus.Wishlist) : (bookToEdit?.wasWishlist || (status === BookStatus.Wishlist))
        };
        if (isEditMode) {
            await onUpdateBook({ ...bookToEdit, ...bookData });
        } else {
            await onAddBook(bookData);
        }
    } finally {
        setIsSubmitting(false);
    }
  };

  const handleGenerateSummary = useCallback(async () => {
    if (!title || authors.length === 0) return;
    setIsGeneratingSummary(true);
    try {
      const result = await generateBookSummary(title, authors.join(', '));
      if (result) setSummary(result);
    } catch (err) {
      console.error("Erro ao gerar resumo:", err);
    } finally {
      setIsGeneratingSummary(false);
    }
  }, [title, authors]);

  const labelClass = (isRequired: boolean) => 
    `block text-[10px] font-black uppercase tracking-[0.15em] mb-1.5 ml-1 flex items-center gap-1 ${isRequired ? 'text-slate-500 dark:text-slate-400' : 'text-slate-400 dark:text-slate-500'}`;

  const SuggestionDropdown = ({ suggestions, show, onSelect }: { suggestions: string[], show: boolean, onSelect: (val: string) => void }) => {
    if (!show || suggestions.length === 0) return null;
    return (
      <div className="absolute left-0 right-0 top-full mt-2 z-[60] bg-white/95 dark:bg-slate-900/95 backdrop-blur-md border border-slate-200 dark:border-slate-700 rounded-2xl shadow-2xl overflow-hidden animate-in fade-in slide-in-from-top-2 duration-200">
        {suggestions.map((suggestion, index) => (
          <button
            key={index}
            type="button"
            onMouseEnter={() => setActiveSuggestionIndex(index)}
            onClick={() => onSelect(suggestion)}
            className={`w-full text-left px-5 py-3 text-xs font-bold transition-colors ${activeSuggestionIndex === index ? 'bg-primary text-white' : 'text-slate-700 dark:text-slate-300 hover:bg-slate-50 dark:hover:bg-slate-800'}`}
          >
            {suggestion}
          </button>
        ))}
      </div>
    );
  };

  const modalTitle = isEditMode ? 'Editar Registro' : (isDuplicating ? 'Duplicar Registro' : 'Novo Registro');

  return (
    <div className="fixed inset-0 bg-slate-900/60 backdrop-blur-sm flex items-center justify-center z-50 p-4">
      <div 
        className={`bg-white dark:bg-slate-900 rounded-[2.5rem] shadow-2xl w-full max-w-2xl max-h-[90vh] overflow-hidden flex flex-col border border-white/20 dark:border-slate-800 transition-transform duration-500 ${isShaking ? 'animate-shake' : ''}`}
        style={{ animation: isShaking ? 'shake 0.4s cubic-bezier(.36,.07,.19,.97) both' : 'none' }}
      >
        <div className="p-7 border-b border-slate-100 dark:border-slate-800 flex justify-between items-center bg-slate-50/50 dark:bg-slate-800/30">
            <h2 className="text-2xl font-black font-serif text-slate-900 dark:text-slate-50 tracking-tight">{modalTitle}</h2>
            <button onClick={onClose} disabled={isSubmitting} className="p-2.5 rounded-full hover:bg-slate-200 dark:hover:bg-slate-700 text-slate-400 transition-all hover:rotate-90 disabled:opacity-30">
                <XMarkIcon className="h-5 w-5" />
            </button>
        </div>

        <form onSubmit={handleSubmit} className="p-8 space-y-8 overflow-y-auto custom-scrollbar">
            <div className={`grid grid-cols-1 md:grid-cols-2 gap-8 ${isSubmitting ? 'opacity-50 pointer-events-none' : ''}`}>
                <div className="md:col-span-2 relative" ref={titleRef}>
                    <label className={labelClass(true)}>
                      Título <span className="text-red-500">*</span>
                    </label>
                    <input 
                      type="text" 
                      value={title} 
                      onChange={handleTitleChange}
                      onKeyDown={(e) => handleKeyDown(e, 'title')}
                      placeholder="Ex: Cem Anos de Solidão"
                      className={`w-full bg-slate-50 dark:bg-slate-800 border rounded-2xl px-5 py-3.5 outline-none transition-all focus:ring-4 focus:ring-primary/5 ${errors.title ? 'border-red-400 bg-red-50/30 dark:bg-red-950/20' : 'border-slate-200 dark:border-slate-700 focus:border-primary font-bold'}`} 
                    />
                    <SuggestionDropdown 
                      suggestions={titleSuggestions} 
                      show={showTitleSug} 
                      onSelect={(val) => { setTitle(val); setShowTitleSug(false); }} 
                    />
                    {errors.title && <p className="text-[10px] text-red-500 font-bold mt-2 uppercase tracking-wide ml-1 animate-in fade-in slide-in-from-top-1">{errors.title}</p>}
                </div>

                <div className="md:col-span-2">
                    <label className={labelClass(true)}>
                      Autor(es) <span className="text-red-500">*</span>
                    </label>
                    <div className="flex gap-2 mb-3 relative" ref={authorRef}>
                        <div className="flex-1 relative">
                          <input 
                            type="text" 
                            value={authorInput} 
                            onChange={handleAuthorInputChange}
                            onKeyDown={(e) => handleKeyDown(e, 'author')}
                            placeholder="Adicione um autor..."
                            className={`w-full bg-slate-50 dark:bg-slate-800 border rounded-2xl px-5 py-3.5 outline-none transition-all focus:ring-4 focus:ring-primary/5 ${errors.authors ? 'border-red-400' : 'border-slate-200 dark:border-slate-700 focus:border-primary font-bold'}`} 
                          />
                          <SuggestionDropdown 
                            suggestions={authorSuggestions} 
                            show={showAuthorSug} 
                            onSelect={(val) => addAuthor(val)} 
                          />
                        </div>
                        <button 
                          type="button" 
                          onClick={() => addAuthor()}
                          className="px-5 rounded-2xl bg-slate-100 dark:bg-slate-800 border border-slate-200 dark:border-slate-700 text-slate-500 hover:bg-primary hover:text-white hover:border-primary transition-all active:scale-95 flex-shrink-0"
                        >
                          <PlusIcon className="h-5 w-5" />
                        </button>
                    </div>
                    <div className="flex flex-wrap gap-2">
                        {authors.map(a => (
                            <span key={a} className="bg-slate-50 dark:bg-slate-800 border border-slate-200 dark:border-slate-700 text-slate-600 dark:text-slate-300 text-[10px] font-black uppercase tracking-widest px-4 py-2 rounded-xl flex items-center gap-2 shadow-sm">
                                {a}
                                <button type="button" onClick={() => removeAuthor(a)} className="hover:text-red-500 transition-colors p-0.5">
                                    <XMarkIcon className="h-3.5 w-3.5" />
                                </button>
                            </span>
                        ))}
                    </div>
                </div>

                <div>
                    <label className={labelClass(false)}>Status</label>
                    <select value={status} onChange={(e) => setStatus(e.target.value as BookStatus)} className="w-full bg-slate-50 dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-2xl px-5 py-3.5 outline-none focus:ring-4 focus:ring-primary/5 focus:border-primary cursor-pointer font-bold text-slate-700 dark:text-slate-300">
                        <option value={BookStatus.TBR}>{statusConfigs[BookStatus.TBR].label}</option>
                        <option value={BookStatus.Reading}>{statusConfigs[BookStatus.Reading].label}</option>
                        <option value={BookStatus.Read}>{statusConfigs[BookStatus.Read].label}</option>
                        <option value={BookStatus.Wishlist}>{statusConfigs[BookStatus.Wishlist].label}</option>
                        <option value={BookStatus.Dropped}>{statusConfigs[BookStatus.Dropped].label}</option>
                    </select>
                </div>

                <div>
                    <label className={labelClass(false)}>Total de Páginas</label>
                    <input type="number" min="0" value={pages} onChange={(e) => setPages(Number(e.target.value))} className="w-full bg-slate-50 dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-2xl px-5 py-3.5 outline-none focus:border-primary font-bold text-slate-700 dark:text-slate-300" />
                </div>

                {(status === BookStatus.Dropped || status === BookStatus.Reading) && (
                    <div className="animate-in slide-in-from-top-2 duration-300">
                        <label className={labelClass(false)}>Página Atual (Progresso)</label>
                        <input 
                            type="number" 
                            min="0" 
                            max={pages || undefined}
                            value={currentPage} 
                            onChange={(e) => setCurrentPage(Number(e.target.value))} 
                            className="w-full bg-slate-50 dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-2xl px-5 py-3.5 outline-none focus:border-primary font-bold text-slate-700 dark:text-slate-300" 
                        />
                    </div>
                )}

                <div className="md:col-span-2 border-t border-slate-100 dark:border-slate-800 pt-6 mt-2">
                    <div className="flex items-center gap-2 mb-6">
                        <div className="bg-emerald-50 dark:bg-emerald-900/20 p-2 rounded-lg text-emerald-600">
                            <TagIcon className="h-4 w-4" />
                        </div>
                        <h3 className="text-[10px] font-black uppercase tracking-[0.2em] text-slate-400">Informações de Aquisição</h3>
                    </div>
                    <div className="grid grid-cols-1 md:grid-cols-2 gap-8">
                        <div>
                            <label className={labelClass(false)}>Valor Estimado (R$)</label>
                            <input 
                              type="text" 
                              value={estimatedPrice} 
                              onChange={(e) => setEstimatedPrice(e.target.value)} 
                              placeholder="0,00"
                              className="w-full bg-slate-50 dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-2xl px-5 py-3.5 outline-none focus:border-primary font-bold text-slate-700 dark:text-slate-300" 
                            />
                        </div>
                        {(bookToEdit?.wasWishlist || bookToEdit?.pricePaid) && (
                            <div>
                                <label className={labelClass(false)}>Valor Real Pago (R$)</label>
                                <input 
                                  type="text" 
                                  value={pricePaid} 
                                  onChange={(e) => setPricePaid(e.target.value)} 
                                  placeholder="0,00"
                                  className="w-full bg-emerald-50/30 dark:bg-emerald-900/10 border border-emerald-100 dark:border-emerald-800 rounded-2xl px-5 py-3.5 outline-none focus:border-emerald-500 font-bold text-emerald-700 dark:text-emerald-400" 
                                />
                            </div>
                        )}
                    </div>
                </div>

                <div>
                    <label className={labelClass(false)}>Link de Compra</label>
                    <input 
                      type="text" 
                      value={buyLink} 
                      onChange={(e) => setBuyLink(e.target.value)} 
                      placeholder="https://..."
                      className="w-full md:col-span-2 bg-slate-50 dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-2xl px-5 py-3.5 outline-none focus:border-primary font-bold text-slate-700 dark:text-slate-300" 
                    />
                </div>

                <div>
                    <label className={labelClass(false)}>Data de Registro</label>
                    <input 
                      type="date" 
                      value={dateAdded} 
                      onChange={(e) => setDateAdded(e.target.value)} 
                      className="w-full bg-slate-50 dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-2xl px-5 py-3.5 outline-none focus:border-primary font-bold text-slate-700 dark:text-slate-300" 
                    />
                </div>

                <div>
                    <label className={labelClass(false)}>Tipo de Mídia</label>
                    <select value={type} onChange={(e) => setType(e.target.value as BookType)} className="w-full bg-slate-50 dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-2xl px-5 py-3.5 outline-none focus:border-primary font-bold text-slate-700 dark:text-slate-300">
                        <option value={BookType.Book}>Livro</option>
                        <option value={BookType.HQ}>HQ</option>
                    </select>
                </div>

                {status === BookStatus.Read && (
                  <div className="md:col-span-2 grid grid-cols-1 md:grid-cols-3 gap-8">
                    <div>
                      <label className={labelClass(false)}>Data de Conclusão</label>
                      <input 
                        type="date" 
                        value={dateFinished} 
                        onChange={(e) => setDateFinished(e.target.value)} 
                        className="w-full bg-slate-50 dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-2xl px-5 py-3.5 outline-none focus:border-primary font-bold text-slate-700 dark:text-slate-300" 
                      />
                    </div>
                    <div>
                      <label className={labelClass(false)}>Dias Gastos</label>
                      <input 
                        type="number" 
                        value={daysToFinish} 
                        onChange={(e) => setDaysToFinish(e.target.value)} 
                        className="w-full bg-slate-50 dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-2xl px-5 py-3.5 outline-none focus:border-primary font-bold text-slate-700 dark:text-slate-300" 
                      />
                    </div>
                    <div>
                      <label className={labelClass(false)}>Vezes Lido</label>
                      <input 
                        type="number" 
                        min="1"
                        value={timesRead} 
                        onChange={(e) => setTimesRead(Number(e.target.value))} 
                        className="w-full bg-slate-50 dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-2xl px-5 py-3.5 outline-none focus:border-primary font-bold text-slate-700 dark:text-slate-300" 
                      />
                    </div>
                  </div>
                )}

                <div className="md:col-span-2">
                    <label className={labelClass(true)}>Gêneros <span className="text-red-500">*</span></label>
                    <div className={`p-5 bg-slate-50/50 dark:bg-slate-800/20 border rounded-[2.5rem] ${errors.genre ? 'border-red-400' : 'border-slate-200 dark:border-slate-700'}`}>
                        <div className="flex flex-wrap gap-2.5 mb-5">
                            {selectedGenres.map(g => (
                                <span key={g} className="bg-primary text-white text-[10px] font-black uppercase tracking-widest px-4 py-2 rounded-xl flex items-center gap-2 shadow-md">
                                    {g}
                                    <button type="button" onClick={() => toggleGenre(g)} className="hover:text-blue-200 transition-colors p-0.5">
                                        <XMarkIcon className="h-3.5 w-3.5" />
                                    </button>
                                </span>
                            ))}
                        </div>
                        <div className="flex flex-wrap gap-2 pt-5 border-t border-slate-200/60 max-h-48 overflow-y-auto custom-scrollbar pr-2">
                            {GENRES.map(g => (
                                <button
                                    key={g}
                                    type="button"
                                    onClick={() => toggleGenre(g)}
                                    className={`px-4 py-2 rounded-xl text-[10px] font-black uppercase tracking-[0.1em] transition-all ${
                                        selectedGenres.includes(g) 
                                            ? 'bg-primary text-white border border-primary' 
                                            : 'bg-white dark:bg-slate-900 text-slate-500 border border-slate-200 dark:border-slate-700'
                                    }`}
                                >
                                    {g}
                                </button>
                            ))}
                        </div>
                    </div>
                </div>

                <div className="md:col-span-2">
                    <label className={labelClass(false)}>Avaliação (0 a 10)</label>
                    <div className="flex items-center gap-4 p-5 bg-slate-50 dark:bg-slate-800 border border-slate-200 rounded-2xl">
                        <input 
                            type="range" 
                            min="0" 
                            max="10" 
                            step="0.1" 
                            value={rating} 
                            onChange={(e) => setRating(parseFloat(e.target.value))}
                            className="flex-1 h-2 bg-slate-200 rounded-lg appearance-none cursor-pointer accent-amber-500"
                        />
                        <div className="flex items-center gap-2">
                            <input 
                                type="number" 
                                min="0" 
                                max="10" 
                                step="0.1" 
                                value={rating} 
                                onChange={(e) => setRating(parseFloat(e.target.value) || 0)}
                                className="w-20 bg-white dark:bg-slate-900 border border-slate-200 rounded-xl px-2 py-1.5 text-center font-black text-amber-500"
                            />
                            <StarIconFilled className="h-5 w-5 text-amber-500" />
                        </div>
                    </div>
                </div>
            </div>

            <div className="p-7 bg-blue-50/40 dark:bg-blue-900/10 rounded-[2.5rem] border border-blue-100 dark:border-blue-800/50 flex items-center justify-between">
                <div className="flex-1">
                    <h4 className="text-sm font-black text-slate-800 dark:text-slate-200 mb-1 uppercase tracking-wide">✦ Inteligência Artificial</h4>
                    <p className="text-[11px] text-slate-500 dark:text-slate-400 font-medium">Gere resumos e sinopses automáticas baseadas no título e autores.</p>
                </div>
                <button 
                    type="button" 
                    onClick={handleGenerateSummary} 
                    disabled={isGeneratingSummary || isSubmitting || !title || authors.length === 0} 
                    className="px-6 py-3 text-[10px] font-black uppercase tracking-widest rounded-xl bg-primary text-white shadow-md active:scale-95 disabled:opacity-50"
                >
                    {isGeneratingSummary ? 'Gerando...' : 'Gerar Resumo'}
                </button>
            </div>

            <div className="space-y-3">
                <label className={labelClass(false)}>Resumo & Sinopse</label>
                <textarea 
                  value={summary} 
                  onChange={(e) => setSummary(e.target.value)} 
                  rows={4} 
                  className="w-full bg-slate-50 dark:bg-slate-800 border border-slate-200 rounded-[1.5rem] px-5 py-4 outline-none focus:border-primary text-sm leading-relaxed" 
                  placeholder="Descrição da obra..."
                ></textarea>
            </div>

            <div className="space-y-3">
                <label className={labelClass(false)}>Notas Pessoais</label>
                <textarea 
                    value={notes} 
                    onChange={(e) => setNotes(e.target.value)} 
                    rows={4} 
                    className="w-full bg-slate-50 dark:bg-slate-800 border border-slate-200 rounded-[1.5rem] px-5 py-4 outline-none focus:border-primary text-sm leading-relaxed" 
                    placeholder="Suas anotações..."
                ></textarea>
            </div>

            <div className="flex justify-end gap-4 pt-8 border-t border-slate-100 mt-6">
                <button 
                  type="button" 
                  onClick={onClose} 
                  disabled={isSubmitting}
                  className="px-8 py-3.5 rounded-2xl text-slate-500 font-black text-[11px] uppercase tracking-widest hover:bg-slate-100"
                >
                  Cancelar
                </button>
                <button 
                  type="submit" 
                  disabled={isSubmitting}
                  className="px-10 py-3.5 rounded-2xl bg-slate-900 dark:bg-slate-100 text-white dark:text-slate-900 font-black text-[11px] uppercase tracking-widest shadow-2xl active:scale-95 disabled:bg-slate-400 flex items-center gap-3"
                >
                  {isSubmitting ? 'Salvando...' : 'Salvar Livro'}
                </button>
            </div>
        </form>
      </div>
    </div>
  );
};

import React from 'react';
import type { Book, StatusConfigs } from '../types';
import { BookStatus, STATUS_COLORS, STATUS_CONFIGS } from '../types';
import { StarIcon, StarIconFilled, PencilIcon, TrashIcon, BookOpenIcon, Square2StackIcon } from './Icons';

interface BookListItemProps {
  book: Book;
  onEdit: (book: Book) => void;
  onDelete: (book: Book) => void;
  onDuplicate: (book: Book) => void;
  onUpdateStatus?: (book: Book, status: BookStatus) => void;
  statusConfigs?: StatusConfigs;
}

const StarRating: React.FC<{ rating: number }> = ({ rating }) => {
  return (
    <div className="flex items-center gap-0.5">
      {[...Array(10)].map((_, index) => {
        const starIndex = index + 1;
        const diff = rating - index;
        const isFull = diff >= 1;
        const isPartial = diff > 0 && diff < 1;
        const fillPercentage = isPartial ? diff * 100 : (isFull ? 100 : 0);

        return (
          <div key={index} className="relative h-3.5 w-3.5">
            <StarIcon className="absolute inset-0 h-3.5 w-3.5 text-slate-200 dark:text-slate-700" />
            <div 
              className="absolute inset-0 overflow-hidden" 
              style={{ width: `${fillPercentage}%` }}
            >
              <StarIconFilled className="h-3.5 w-3.5 text-amber-400" />
            </div>
          </div>
        );
      })}
    </div>
  );
};

const formatDate = (dateStr: string) => {
    if (!dateStr) return '';
    const [year, month, day] = dateStr.split('-');
    return `${day}/${month}/${year}`;
}

const getGenreColor = (genre: string) => {
    const palettes = [
        { bg: 'bg-indigo-50 dark:bg-indigo-900/20', text: 'text-indigo-600 dark:text-indigo-400', border: 'border-indigo-100 dark:border-indigo-800/50' },
        { bg: 'bg-rose-50 dark:bg-rose-900/20', text: 'text-rose-600 dark:text-rose-400', border: 'border-rose-100 dark:border-rose-800/50' },
        { bg: 'bg-emerald-50 dark:bg-emerald-900/20', text: 'text-emerald-600 dark:text-emerald-400', border: 'border-emerald-100 dark:border-emerald-800/50' },
        { bg: 'bg-amber-50 dark:bg-amber-900/20', text: 'text-amber-600 dark:text-amber-400', border: 'border-amber-100 dark:border-amber-900/30' },
        { bg: 'bg-violet-50 dark:bg-violet-900/20', text: 'text-violet-600 dark:text-violet-400', border: 'border-violet-100 dark:border-violet-800/50' },
        { bg: 'bg-cyan-50 dark:bg-cyan-900/20', text: 'text-cyan-600 dark:text-cyan-400', border: 'border-cyan-100 dark:border-cyan-800/50' },
        { bg: 'bg-orange-50 dark:bg-orange-900/20', text: 'text-orange-600 dark:text-orange-400', border: 'border-orange-100 dark:border-orange-800/50' },
        { bg: 'bg-fuchsia-50 dark:bg-fuchsia-900/20', text: 'text-fuchsia-600 dark:text-fuchsia-400', border: 'border-fuchsia-100 dark:border-fuchsia-800/50' },
    ];
    let hash = 0;
    for (let i = 0; i < genre.length; i++) {
        hash = genre.charCodeAt(i) + ((hash << 5) - hash);
    }
    return palettes[Math.abs(hash) % palettes.length];
};

