export const getAIRecommendations = async (readBooks: { title: string, genre: string, rating?: number }[]): Promise<Recommendation[]> => {
  const model = 'gemini-3-flash-preview';
  try {
    return await callGenAI(async (ai) => {
      // Ordena livros lidos por nota para dar contexto de prioridade
      const highRated = readBooks.filter(b => (b.rating || 0) >= 8);
      const lowRated = readBooks.filter(b => (b.rating || 0) < 6 && b.rating !== undefined);

      let context = "";
      if (readBooks.length > 0) {
        context = `
          O usuário tem o seguinte histórico de leitura:
          LIVROS FAVORITOS (Notas Altas): ${highRated.map(b => `${b.title} (${b.genre}) - Nota: ${b.rating}`).join(', ')}.
          LIVROS QUE NÃO AGRADARAM TANTO (Notas Baixas): ${lowRated.map(b => `${b.title} (${b.genre}) - Nota: ${b.rating}`).join(', ')}.
          OUTROS: ${readBooks.filter(b => (b.rating || 0) >= 6 && (b.rating || 0) < 8).map(b => `${b.title} (${b.genre})`).join(', ')}.

          Instrução importante: Dê muito mais peso aos LIVROS FAVORITOS para gerar as novas sugestões. Evite temas similares aos LIVROS QUE NÃO AGRADARAM.
        `;
      } else {
        context = "O usuário ainda não tem livros lidos. Recomende 3 clássicos essenciais de gêneros variados (Ficção, Biografia, Suspense) que costumam ter notas altíssimas.";
      }

      const prompt = `
        Aja como um bibliotecário especialista e curador literário. 
        ${context}
        Com base no perfil psicológico e literário extraído desse histórico, recomende exatamente 3 livros novos em Português.
        Para cada livro, forneça um motivo curto e convincente da recomendação, mencionando por que ele se alinha aos livros que o usuário avaliou com notas altas.
        Gere um link de busca na Amazon Brasil (https://www.amazon.com.br/s?k=NOME+DO+LIVRO) para o campo buyLink.
        Responda estritamente em JSON seguindo o esquema fornecido.
      `;

      const response: GenerateContentResponse = await ai.models.generateContent({
        model,
        contents: prompt,
        config: {
          responseMimeType: "application/json",
          responseSchema: {
            type: Type.ARRAY,
            items: {
              type: Type.OBJECT,
              properties: {
                title: { type: Type.STRING },
                author: { type: Type.STRING },
                reason: { type: Type.STRING },
                genre: { type: Type.STRING },
                buyLink: { type: Type.STRING },
              },
              required: ["title", "author", "reason", "genre", "buyLink"]
            }
          }
        }
      });
      return JSON.parse(response.text || '[]');
    }, model);
  } catch (error: any) {
    console.error("Erro ao obter recomendações:", error);
    return [];
  }
};

import React, { useMemo, useState, useEffect } from 'react';
import type { ReadingStats, Book, DateFilter, Recommendation } from '../types';
import { BookStatus } from '../types';
import { StatCard } from './StatCard';
import { CurrentlyReading } from './CurrentlyReading';
import { MonthlyChart } from './MonthlyChart';
import { TypePieChart } from './TypePieChart';
import { ReadingGoal } from './ReadingGoal';
import { Recommendations } from './Recommendations';
import { LatestReadings } from './LatestReadings';
import { BookOpenIcon, ChartBarIcon, StarIcon, TagIcon, HeartIcon } from './Icons';
import { getAIRecommendations } from '../services/geminiService';

interface DashboardProps {
  stats: ReadingStats;
  currentlyReading: Book | null;
  updateBook: (book: Book) => Promise<void>;
  dateFilter: DateFilter;
  setDateFilter: (filter: DateFilter) => void;
  selectedYear: number;
  setSelectedYear: (year: number) => void;
  availableYears: number[];
  books: Book[];
  customRange?: { start: string; end: string };
  setCustomRange?: (range: { start: string; end: string }) => void;
  readingGoal: number;
  onSetReadingGoal: (val: number) => void;
}

export const Dashboard: React.FC<DashboardProps> = ({ 
  stats, 
  currentlyReading, 
  updateBook, 
  dateFilter, 
  setDateFilter,
  selectedYear,
  setSelectedYear,
  availableYears,
  books,
  customRange,
  setCustomRange,
  readingGoal,
  onSetReadingGoal
}) => {
  const [aiRecs, setAiRecs] = useState<Recommendation[]>([]);
  const [isLoadingRecs, setIsLoadingRecs] = useState(false);

  const fetchRecs = async () => {
    setIsLoadingRecs(true);
    // Extraímos os livros lidos incluindo a nota (rating) para a análise da IA
    const readBooksContext = books
      .filter(b => b.status === BookStatus.Read)
      .map(b => ({ 
        title: b.title, 
        genre: b.genre,
        rating: b.rating 
      }));

    try {
      const recs = await getAIRecommendations(readBooksContext);
      setAiRecs(recs);
    } catch (err) {
      console.error("Erro ao carregar recomendações:", err);
    } finally {
      setIsLoadingRecs(false);
    }
  };

  useEffect(() => {
    if (aiRecs.length === 0) {
        fetchRecs();
    }
  }, []);

  const booksReadThisYear = useMemo(() => {
    const currentYear = new Date().getFullYear();
    return books.filter(b => 
      b.status === BookStatus.Read && 
      b.dateFinished && 
      new Date(b.dateFinished).getFullYear() === currentYear
    ).length;
  }, [books]);

  const periodTitle = useMemo(() => {
    if (dateFilter === 'thisYear') return 'Ano Atual';
    if (dateFilter === 'allTime') return 'Total';
    if (dateFilter === 'specificYear') return `Ano ${selectedYear}`;
    if (dateFilter === 'custom' && customRange) {
        return `Personalizado`;
    }
    return '';
  }, [dateFilter, customRange, selectedYear]);

  const latestReadBooks = useMemo(() => {
    return books
      .filter(b => b.status === BookStatus.Read && b.dateFinished)
      .sort((a, b) => (b.dateFinished || '').localeCompare(a.dateFinished || ''))
      .slice(0, 5);
  }, [books]);

  return (
    <div className="max-w-7xl mx-auto space-y-16 pb-20 px-2 sm:px-0">
      <div className="flex flex-col xl:flex-row justify-between items-start xl:items-center gap-8">
        <div>
            <h2 className="text-4xl font-black font-serif text-slate-900 dark:text-slate-50 tracking-tight italic">Painel de Controle</h2>
            <p className="text-slate-500 dark:text-slate-400 text-[10px] font-black uppercase tracking-[0.25em] mt-2 ml-1">✦ Sincronizado com sua biblioteca digital</p>
        </div>

        <div className="flex flex-col sm:flex-row items-stretch sm:items-center gap-4 bg-white dark:bg-slate-900 p-2 rounded-[2rem] border border-slate-200 dark:border-slate-800 shadow-xl w-full sm:w-auto">
            <div className="flex items-center p-1.5 bg-slate-50 dark:bg-slate-800 rounded-2xl border border-slate-100 dark:border-slate-700">
                <button
                    onClick={() => setDateFilter('thisYear')}
                    className={`px-6 py-2.5 text-[10px] font-black uppercase tracking-widest rounded-xl transition-all ${dateFilter === 'thisYear' ? 'bg-primary text-white shadow-lg' : 'text-slate-400 dark:text-slate-500 hover:text-primary'}`}
                >
                    Ano
                </button>
                <button
                    onClick={() => setDateFilter('specificYear')}
                    className={`px-6 py-2.5 text-[10px] font-black uppercase tracking-widest rounded-xl transition-all ${dateFilter === 'specificYear' ? 'bg-primary text-white shadow-lg' : 'text-slate-400 dark:text-slate-500 hover:text-primary'}`}
                >
                    Anos
                </button>
                <button
                    onClick={() => setDateFilter('allTime')}
                    className={`px-6 py-2.5 text-[10px] font-black uppercase tracking-widest rounded-xl transition-all ${dateFilter === 'allTime' ? 'bg-primary text-white shadow-lg' : 'text-slate-400 dark:text-slate-500 hover:text-primary'}`}
                >
                    Tudo
                </button>
            </div>

            {dateFilter === 'specificYear' && (
                <div className="flex items-center gap-2 animate-in fade-in slide-in-from-right-4 duration-500 px-2">
                    <select 
                        value={selectedYear}
                        onChange={(e) => setSelectedYear(Number(e.target.value))}
                        className="bg-white dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-xl px-4 py-2.5 text-[10px] font-black uppercase tracking-[0.2em] text-slate-700 dark:text-slate-300 outline-none focus:border-primary transition-colors cursor-pointer"
                    >
                        {availableYears.map(year => (
                            <option key={year} value={year}>{year}</option>
                        ))}
                    </select>
                </div>
            )}
        </div>
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-12 gap-10">
        <div className="lg:col-span-8">
          {currentlyReading ? (
            <CurrentlyReading book={currentlyReading} updateBook={updateBook} />
          ) : (
            <div className="bg-white dark:bg-slate-900 border-2 border-dashed border-slate-200 dark:border-slate-800 p-16 rounded-[3rem] flex flex-col items-center justify-center text-center h-full group">
              <div className="bg-slate-50 dark:bg-slate-800 p-6 rounded-3xl mb-6 group-hover:scale-110 transition-transform duration-500">
                <BookOpenIcon className="h-12 w-12 text-slate-300 dark:text-slate-600" />
              </div>
              <h2 className="text-2xl font-black text-slate-900 dark:text-slate-50 mb-3 font-serif italic">Nenhuma leitura ativa</h2>
              <p className="text-slate-400 dark:text-slate-500 max-w-xs text-sm font-medium">Sua estante está cheia de aventuras esperando por você.</p>
            </div>
          )}
        </div>
        <div className="lg:col-span-4 flex flex-col gap-8">
          <ReadingGoal 
            current={booksReadThisYear} 
            goal={readingGoal} 
            onSetGoal={onSetReadingGoal} 
          />
          <StatCard 
            icon={<StarIcon className="h-7 w-7" />} 
            title="Avaliação Média" 
            value={stats.yearly.avgRating.toFixed(1)}
            subtitle="Estrelas"
            description="Média baseada em todas as suas leituras finalizadas no período selecionado."
          />
        </div>
      </div>

      <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-8">
        <StatCard 
            icon={<BookOpenIcon className="h-7 w-7" />} 
            title="Total Lidos"
            value={stats.yearly.booksRead.toString()} 
            subtitle={periodTitle}
        />
        <StatCard 
            icon={<TagIcon className="h-7 w-7" />} 
            title="Páginas Lidas"
            value={stats.yearly.pagesRead.toLocaleString('pt-BR')}
            subtitle={periodTitle}
        />
        <StatCard 
            icon={<ChartBarIcon className="h-7 w-7" />} 
            title="Na Fila (TBR)" 
            value={stats.tbrCount.toString()}
            subtitle="Livros"
        />
        <StatCard 
            icon={<HeartIcon className="h-7 w-7" />} 
            title="Wishlist" 
            value={stats.wishlistCount.toString()}
            subtitle="Desejos"
        />
      </div>

      <LatestReadings books={latestReadBooks} />

      <Recommendations 
        suggestions={aiRecs} 
        isLoading={isLoadingRecs} 
        onRefresh={fetchRecs} 
      />

      <div className="grid grid-cols-1 xl:grid-cols-12 gap-10">
        <div className="xl:col-span-8 bg-white dark:bg-slate-900 p-10 rounded-[3rem] shadow-soft border border-slate-100 dark:border-slate-800 transition-all hover:shadow-2xl hover:border-primary/5">
            <div className="flex flex-col md:flex-row justify-between items-start md:items-center mb-10 gap-6">
            <div>
                <h2 className="text-3xl font-black font-serif text-slate-900 dark:text-slate-50 italic">Evolução de Leitura</h2>
                <p className="text-slate-400 dark:text-slate-500 text-[10px] font-black uppercase tracking-[0.2em] mt-2">✦ Estatísticas Mensais: {periodTitle}</p>
            </div>
            <div className="flex gap-8 bg-slate-50 dark:bg-slate-800/50 p-4 rounded-2xl border border-slate-100 dark:border-slate-700">
                <div className="flex items-center gap-3">
                    <div className="w-3.5 h-3.5 rounded-full bg-blue-500 shadow-sm shadow-blue-500/40"></div>
                    <span className="text-[10px] font-black text-slate-500 dark:text-slate-400 uppercase tracking-widest">Livros</span>
                </div>
                <div className="flex items-center gap-3">
                    <div className="w-3.5 h-3.5 rounded-full bg-indigo-500 shadow-sm shadow-indigo-500/40"></div>
                    <span className="text-[10px] font-black text-slate-500 dark:text-slate-400 uppercase tracking-widest">Páginas</span>
                </div>
            </div>
            </div>
            <MonthlyChart data={stats.monthly} />
        </div>

        <div className="xl:col-span-4 bg-white dark:bg-slate-900 p-10 rounded-[3rem] shadow-soft border border-slate-100 dark:border-slate-800 flex flex-col min-h-[500px] overflow-hidden">
            <h2 className="text-2xl font-black font-serif text-slate-900 dark:text-slate-50 mb-8 italic text-center xl:text-left">Distribuição</h2>
            <div className="flex-1 flex items-center justify-center -mt-4">
                <TypePieChart data={stats.byType} />
            </div>
            <p className="text-[9px] font-black text-slate-400 dark:text-slate-600 uppercase tracking-widest text-center mt-4">✦ Análise baseada em toda sua estante</p>
        </div>
      </div>
    </div>
  );
};

import React, { useState, useMemo, useEffect } from 'react';
import { useBookData } from './hooks/useBookData';
import { Header } from './components/Header';
import { Dashboard } from './components/Dashboard';
import { AddBookModal } from './components/AddBookModal';
import { SettingsModal } from './components/SettingsModal';
import { PlusIcon, XMarkIcon } from './components/Icons';
import type { Book, NewBook, Profile } from './types';
import { BookList } from './components/BookList';
import { ConfirmationModal } from './components/ConfirmationModal';
import { BookStatus } from './types';
import { Wishlist } from './components/Wishlist';
import { BottomNav } from './components/BottomNav';
import { Auth } from './components/Auth';
import { StatsView } from './components/StatsView';
import { PricePaidModal } from './components/PricePaidModal'; 
import { BookSearch } from './components/BookSearch';
import { supabase } from './services/supabase';
import { dbService } from './services/database';

export default function App() {
  const [session, setSession] = useState<any>(null);
  const [isAuthLoading, setIsAuthLoading] = useState(true);
  const [userProfile, setUserProfile] = useState<Profile | null>(null);
  const [hasApiKey, setHasApiKey] = useState<boolean>(true);

  useEffect(() => {
    supabase.auth.getSession()
      .then(({ data: { session } }) => {
        setSession(session);
      })
      .catch((err) => {
        console.warn("⚠️ Não foi possível sincronizar sessão inicial (Offline/Fetch Error).");
      })
      .finally(() => {
        setIsAuthLoading(false);
      });

    const { data: { subscription } } = supabase.auth.onAuthStateChange((_event, session) => {
      setSession(session);
    });
    return () => subscription.unsubscribe();
  }, []);

  useEffect(() => {
    if (session) {
      dbService.getProfile().then(profile => {
        if (profile) {
          setUserProfile(profile);
          if (profile.readingGoal) setReadingGoal(profile.readingGoal);
          checkPlatformApiKey();
        }
      });
    }
  }, [session]);

  const checkPlatformApiKey = async () => {
    if (window.aistudio) {
        const selected = await window.aistudio.hasSelectedApiKey();
        setHasApiKey(selected);
    } else {
        const envKey = process.env.API_KEY;
        setHasApiKey(!!(envKey && envKey !== 'undefined' && envKey !== ''));
    }
  };

  const { 
    books, stats, currentlyReading, addBook, updateBook, deleteBook, 
    dateFilter, setDateFilter, selectedYear, setSelectedYear, availableYears,
    customRange, setCustomRange, isLocalMode, schemaError, isLoading
  } = useBookData();

  const [theme, setTheme] = useState<'light' | 'dark'>(() => (localStorage.getItem('theme') as 'light' | 'dark') || 'light');
  const [readingGoal, setReadingGoal] = useState(() => parseInt(localStorage.getItem('biblio_tech_goal') || '12', 10));

  const handleSetReadingGoal = async (val: number) => {
    try {
        setReadingGoal(val);
        localStorage.setItem('biblio_tech_goal', val.toString());
        await dbService.updateReadingGoal(val);
        showToast("Meta de leitura atualizada.");
    } catch (err: any) {
        showToast(`Erro ao salvar meta: ${err.message}`);
    }
  };

  const handleUpdateProfile = async (updates: Partial<Profile>) => {
    if (userProfile) {
        try {
            const newProfile = { ...userProfile, ...updates };
            setUserProfile(newProfile);
            await dbService.updateProfile(updates);
            checkPlatformApiKey();
            showToast("Perfil atualizado.");
        } catch (err: any) {
            showToast(`Erro ao atualizar perfil: ${err.message}`);
        }
    }
  };

  const [isModalOpen, setIsModalOpen] = useState(false);
  const [isSettingsOpen, setIsSettingsOpen] = useState(false);
  const [view, setView] = useState<'dashboard' | 'list' | 'wishlist' | 'stats' | 'search'>('dashboard');
  const [editingBook, setEditingBook] = useState<Book | null>(null);
  const [isDuplicating, setIsDuplicating] = useState(false);
  const [deletingBook, setDeletingBook] = useState<Book | null>(null);
  const [convertingBook, setConvertingBook] = useState<Book | null>(null); 
  const [defaultStatusForModal, setDefaultStatusForModal] = useState<BookStatus | undefined>();
  const [toastMessage, setToastMessage] = useState<string | null>(null);

  useEffect(() => {
    theme === 'dark' ? document.documentElement.classList.add('dark') : document.documentElement.classList.remove('dark');
    localStorage.setItem('theme', theme);
  }, [theme]);

  const showToast = (message: string) => {
    setToastMessage(message);
    setTimeout(() => setToastMessage(null), 3500);
  };

  const handleAddBook = async (newBook: NewBook) => {
    try {
        await addBook(newBook);
        setIsModalOpen(false);
        showToast(`"${newBook.title}" salvo!`);
    } catch (err: any) {
        showToast(`Erro ao salvar: ${err.message}`);
    }
  };

  const handleUpdateBook = async (updatedBook: Book) => {
    try {
        await updateBook(updatedBook);
        setIsModalOpen(false);
        showToast(`"${updatedBook.title}" atualizado.`);
    } catch (err: any) {
        showToast(`Erro ao atualizar: ${err.message}`);
    }
  };

  const handleFinishConversion = async (price: number) => {
    if (convertingBook) {
      const updated: Book = {
        ...convertingBook,
        status: BookStatus.TBR,
        wasWishlist: true,
        pricePaid: price,
        dateAdded: new Date().toISOString().split('T')[0] 
      };
      await handleUpdateBook(updated);
      setConvertingBook(null);
      showToast("Movido para sua estante!");
    }
  };

  const openAddModal = (status?: BookStatus) => {
    setEditingBook(null);
    setIsDuplicating(false);
    setDefaultStatusForModal(status);
    setIsModalOpen(true);
  };

  const handleDuplicateRequest = (book: Book) => {
    setEditingBook(book);
    setIsDuplicating(true);
    setIsModalOpen(true);
  };

  if (isAuthLoading) return <div className="min-h-screen bg-background flex items-center justify-center"><div className="w-10 h-10 border-4 border-primary border-t-transparent rounded-full animate-spin"></div></div>;
  if (!session) return <Auth />;
  if (isLoading) return <div className="min-h-screen bg-background flex flex-col items-center justify-center p-4"><div className="w-12 h-12 border-4 border-primary border-t-transparent rounded-full animate-spin mb-4"></div><p className="text-[10px] font-black uppercase tracking-widest text-slate-400">Sincronizando...</p></div>;

  return (
    <div className="min-h-screen bg-background dark:bg-slate-950 text-text-main dark:text-slate-200 pb-24 relative transition-colors duration-300">
      <Header 
        profile={userProfile} onLogoClick={() => setView('dashboard')} onSettingsClick={() => setIsSettingsOpen(true)}
        theme={theme} toggleTheme={() => setTheme(t => t === 'light' ? 'dark' : 'light')} 
        isConnected={!isLocalMode} hasApiKey={hasApiKey}
      />

      {schemaError && (
        <div className="bg-red-600 text-white px-6 py-3 text-center text-[10px] font-black uppercase tracking-widest flex items-center justify-center gap-4 animate-in slide-in-from-top duration-500">
          <div className="flex-1">
             ⚠️ Erro de Sincronização: {schemaError.detail || "O banco de dados está desatualizado."} 
             <span className="block mt-1 font-bold opacity-80">Rode o script SQL do arquivo instrucoes_sql.txt no painel do Supabase!</span>
          </div>
        </div>
      )}

      {!hasApiKey && !schemaError && (
        <div className="bg-red-500 text-white px-6 py-2 text-center text-[10px] font-black uppercase tracking-widest animate-pulse cursor-pointer" onClick={() => setIsSettingsOpen(true)}>
          IA Indisponível: Clique aqui para configurar sua Chave de API nas Preferências.
        </div>
      )}

      <main className="p-4 md:p-8">
        {view === 'dashboard' && (
          <Dashboard 
            stats={stats} 
            currentlyReading={currentlyReading} 
            updateBook={handleUpdateBook} 
            dateFilter={dateFilter} 
            setDateFilter={setDateFilter} 
            selectedYear={selectedYear} 
            setSelectedYear={setSelectedYear} 
            availableYears={availableYears} 
            books={books} 
            customRange={customRange} 
            setCustomRange={setCustomRange} 
            readingGoal={readingGoal} 
            onSetReadingGoal={handleSetReadingGoal} 
            addBook={handleAddBook}
          />
        )}
        {view === 'list' && <BookList books={books.filter(b => b.status !== BookStatus.Wishlist)} onEdit={(b) => { setEditingBook(b); setIsDuplicating(false); setIsModalOpen(true); }} onDelete={setDeletingBook} onDuplicate={handleDuplicateRequest} onUpdateBook={handleUpdateBook} />}
        {view === 'wishlist' && <Wishlist books={books.filter(b => b.status === BookStatus.Wishlist)} onEdit={(b) => { setEditingBook(b); setIsDuplicating(false); setIsModalOpen(true); }} onDelete={setDeletingBook} onDuplicate={handleDuplicateRequest} onMoveToShelf={(b) => setConvertingBook(b)} onAddWishlistItem={() => openAddModal(BookStatus.Wishlist)} />}
        {view === 'stats' && <StatsView books={books} availableYears={availableYears} />}
        {view === 'search' && <BookSearch onAddWishlist={handleAddBook} existingBooks={books} />}
      </main>

      <div className="fixed bottom-24 right-6 flex flex-col gap-3">
        <button onClick={() => openAddModal()} className="bg-primary text-background p-4 rounded-full shadow-2xl hover:bg-blue-700 transition-all z-40 active:scale-95"><PlusIcon className="h-6 w-6" /></button>
      </div>

      <BottomNav view={view} setView={setView} />
      {toastMessage && <div className="fixed bottom-32 left-1/2 -translate-x-1/2 z-[60] animate-in fade-in slide-in-from-bottom-4 duration-500"><div className="bg-slate-900 text-white px-6 py-3.5 rounded-2xl shadow-2xl border border-white/10 flex items-center gap-3"><p className="text-[11px] font-black uppercase tracking-widest">{toastMessage}</p></div></div>}

      {isModalOpen && <AddBookModal onClose={() => setIsModalOpen(false)} onAddBook={handleAddBook} onUpdateBook={handleUpdateBook} bookToEdit={editingBook} isDuplicating={isDuplicating} defaultStatus={defaultStatusForModal} existingBooks={books} />}

      {convertingBook && <PricePaidModal book={convertingBook} onClose={() => setConvertingBook(null)} onConfirm={handleFinishConversion} />}

      {isSettingsOpen && <SettingsModal onClose={() => setIsSettingsOpen(false)} readingGoal={readingGoal} onSetReadingGoal={handleSetReadingGoal} profile={userProfile} onUpdateProfile={handleUpdateProfile} />}

      {deletingBook && <ConfirmationModal isOpen={!!deletingBook} onClose={() => setDeletingBook(null)} onConfirm={async () => { await deleteBook(deletingBook.id); setDeletingBook(null); showToast(`Removido.`); }} title="Excluir" message={`Apagar "${deletingBook.title}"?`} />}
    </div>
  );
}

import React, { useMemo, useState, useEffect } from 'react';
import type { ReadingStats, Book, DateFilter, Recommendation, NewBook } from '../types';
import { BookStatus, BookType } from '../types';
import { StatCard } from './StatCard';
import { CurrentlyReading } from './CurrentlyReading';
import { MonthlyChart } from './MonthlyChart';
import { TypePieChart } from './TypePieChart';
import { ReadingGoal } from './ReadingGoal';
import { Recommendations } from './Recommendations';
import { LatestReadings } from './LatestReadings';
import { BookOpenIcon, ChartBarIcon, StarIcon, TagIcon, HeartIcon } from './Icons';
import { getAIRecommendations } from '../services/geminiService';

interface DashboardProps {
  stats: ReadingStats;
  currentlyReading: Book | null;
  updateBook: (book: Book) => Promise<void>;
  dateFilter: DateFilter;
  setDateFilter: (filter: DateFilter) => void;
  selectedYear: number;
  setSelectedYear: (year: number) => void;
  availableYears: number[];
  books: Book[];
  customRange?: { start: string; end: string };
  setCustomRange?: (range: { start: string; end: string }) => void;
  readingGoal: number;
  onSetReadingGoal: (val: number) => void;
  addBook: (book: NewBook) => Promise<void>;
}

export const Dashboard: React.FC<DashboardProps> = ({ 
  stats, 
  currentlyReading, 
  updateBook, 
  dateFilter, 
  setDateFilter,
  selectedYear,
  setSelectedYear,
  availableYears,
  books,
  customRange,
  setCustomRange,
  readingGoal,
  onSetReadingGoal,
  addBook
}) => {
  const [aiRecs, setAiRecs] = useState<Recommendation[]>([]);
  const [isLoadingRecs, setIsLoadingRecs] = useState(false);

  const fetchRecs = async () => {
    setIsLoadingRecs(true);
    // Extraímos os livros lidos incluindo a nota (rating) para a análise da IA
    const readBooksContext = books
      .filter(b => b.status === BookStatus.Read)
      .map(b => ({ 
        title: b.title, 
        genre: b.genre,
        rating: b.rating 
      }));

    try {
      const recs = await getAIRecommendations(readBooksContext);
      setAiRecs(recs);
    } catch (err) {
      console.error("Erro ao carregar recomendações:", err);
    } finally {
      setIsLoadingRecs(false);
    }
  };

  useEffect(() => {
    if (aiRecs.length === 0) {
        fetchRecs();
    }
  }, []);

  const booksReadThisYear = useMemo(() => {
    const currentYear = new Date().getFullYear();
    return books.filter(b => 
      b.status === BookStatus.Read && 
      b.dateFinished && 
      new Date(b.dateFinished).getFullYear() === currentYear
    ).length;
  }, [books]);

  const periodTitle = useMemo(() => {
    if (dateFilter === 'thisYear') return 'Ano Atual';
    if (dateFilter === 'allTime') return 'Total';
    if (dateFilter === 'specificYear') return `Ano ${selectedYear}`;
    if (dateFilter === 'custom' && customRange) {
        return `Personalizado`;
    }
    return '';
  }, [dateFilter, customRange, selectedYear]);

  const latestReadBooks = useMemo(() => {
    return books
      .filter(b => b.status === BookStatus.Read && b.dateFinished)
      .sort((a, b) => (b.dateFinished || '').localeCompare(a.dateFinished || ''))
      .slice(0, 5);
  }, [books]);

  const handleAddRecommendation = async (rec: Recommendation) => {
    const newBook: NewBook = {
      title: rec.title,
      author: rec.author,
      genre: rec.genre,
      status: BookStatus.Wishlist,
      type: BookType.Book,
      pages: 0,
      buyLink: rec.buyLink,
      summary: rec.reason, // Usamos o motivo da IA como resumo inicial
      dateAdded: new Date().toISOString().split('T')[0],
      wasWishlist: true
    };
    await addBook(newBook);
  };

  return (
    <div className="max-w-7xl mx-auto space-y-16 pb-20 px-2 sm:px-0">
      <div className="flex flex-col xl:flex-row justify-between items-start xl:items-center gap-8">
        <div>
            <h2 className="text-4xl font-black font-serif text-slate-900 dark:text-slate-50 tracking-tight italic">Painel de Controle</h2>
            <p className="text-slate-500 dark:text-slate-400 text-[10px] font-black uppercase tracking-[0.25em] mt-2 ml-1">✦ Sincronizado com sua biblioteca digital</p>
        </div>

        <div className="flex flex-col sm:flex-row items-stretch sm:items-center gap-4 bg-white dark:bg-slate-900 p-2 rounded-[2rem] border border-slate-200 dark:border-slate-800 shadow-xl w-full sm:w-auto">
            <div className="flex items-center p-1.5 bg-slate-50 dark:bg-slate-800 rounded-2xl border border-slate-100 dark:border-slate-700">
                <button
                    onClick={() => setDateFilter('thisYear')}
                    className={`px-6 py-2.5 text-[10px] font-black uppercase tracking-widest rounded-xl transition-all ${dateFilter === 'thisYear' ? 'bg-primary text-white shadow-lg' : 'text-slate-400 dark:text-slate-500 hover:text-primary'}`}
                >
                    Ano
                </button>
                <button
                    onClick={() => setDateFilter('specificYear')}
                    className={`px-6 py-2.5 text-[10px] font-black uppercase tracking-widest rounded-xl transition-all ${dateFilter === 'specificYear' ? 'bg-primary text-white shadow-lg' : 'text-slate-400 dark:text-slate-500 hover:text-primary'}`}
                >
                    Anos
                </button>
                <button
                    onClick={() => setDateFilter('allTime')}
                    className={`px-6 py-2.5 text-[10px] font-black uppercase tracking-widest rounded-xl transition-all ${dateFilter === 'allTime' ? 'bg-primary text-white shadow-lg' : 'text-slate-400 dark:text-slate-500 hover:text-primary'}`}
                >
                    Tudo
                </button>
            </div>

            {dateFilter === 'specificYear' && (
                <div className="flex items-center gap-2 animate-in fade-in slide-in-from-right-4 duration-500 px-2">
                    <select 
                        value={selectedYear}
                        onChange={(e) => setSelectedYear(Number(e.target.value))}
                        className="bg-white dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-xl px-4 py-2.5 text-[10px] font-black uppercase tracking-[0.2em] text-slate-700 dark:text-slate-300 outline-none focus:border-primary transition-colors cursor-pointer"
                    >
                        {availableYears.map(year => (
                            <option key={year} value={year}>{year}</option>
                        ))}
                    </select>
                </div>
            )}
        </div>
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-12 gap-10">
        <div className="lg:col-span-8">
          {currentlyReading ? (
            <CurrentlyReading book={currentlyReading} updateBook={updateBook} />
          ) : (
            <div className="bg-white dark:bg-slate-900 border-2 border-dashed border-slate-200 dark:border-slate-800 p-16 rounded-[3rem] flex flex-col items-center justify-center text-center h-full group">
              <div className="bg-slate-50 dark:bg-slate-800 p-6 rounded-3xl mb-6 group-hover:scale-110 transition-transform duration-500">
                <BookOpenIcon className="h-12 w-12 text-slate-300 dark:text-slate-600" />
              </div>
              <h2 className="text-2xl font-black text-slate-900 dark:text-slate-50 mb-3 font-serif italic">Nenhuma leitura ativa</h2>
              <p className="text-slate-400 dark:text-slate-500 max-w-xs text-sm font-medium">Sua estante está cheia de aventuras esperando por você.</p>
            </div>
          )}
        </div>
        <div className="lg:col-span-4 flex flex-col gap-8">
          <ReadingGoal 
            current={booksReadThisYear} 
            goal={readingGoal} 
            onSetGoal={onSetReadingGoal} 
          />
          <StatCard 
            icon={<StarIcon className="h-7 w-7" />} 
            title="Avaliação Média" 
            value={stats.yearly.avgRating.toFixed(1)}
            subtitle="Estrelas"
            description="Média baseada em todas as suas leituras finalizadas no período selecionado."
          />
        </div>
      </div>

      <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-8">
        <StatCard 
            icon={<BookOpenIcon className="h-7 w-7" />} 
            title="Total Lidos"
            value={stats.yearly.booksRead.toString()} 
            subtitle={periodTitle}
        />
        <StatCard 
            icon={<TagIcon className="h-7 w-7" />} 
            title="Páginas Lidas"
            value={stats.yearly.pagesRead.toLocaleString('pt-BR')}
            subtitle={periodTitle}
        />
        <StatCard 
            icon={<ChartBarIcon className="h-7 w-7" />} 
            title="Na Fila (TBR)" 
            value={stats.tbrCount.toString()}
            subtitle="Livros"
        />
        <StatCard 
            icon={<HeartIcon className="h-7 w-7" />} 
            title="Wishlist" 
            value={stats.wishlistCount.toString()}
            subtitle="Desejos"
        />
      </div>

      <LatestReadings books={latestReadBooks} />

      <Recommendations 
        suggestions={aiRecs} 
        isLoading={isLoadingRecs} 
        onRefresh={fetchRecs} 
        onAddWishlist={handleAddRecommendation}
        existingBooks={books}
      />

      <div className="grid grid-cols-1 xl:grid-cols-12 gap-10">
        <div className="xl:col-span-8 bg-white dark:bg-slate-900 p-10 rounded-[3rem] shadow-soft border border-slate-100 dark:border-slate-800 transition-all hover:shadow-2xl hover:border-primary/5">
            <div className="flex flex-col md:flex-row justify-between items-start md:items-center mb-10 gap-6">
            <div>
                <h2 className="text-3xl font-black font-serif text-slate-900 dark:text-slate-50 italic">Evolução de Leitura</h2>
                <p className="text-slate-400 dark:text-slate-500 text-[10px] font-black uppercase tracking-[0.2em] mt-2">✦ Estatísticas Mensais: {periodTitle}</p>
            </div>
            <div className="flex gap-8 bg-slate-50 dark:bg-slate-800/50 p-4 rounded-2xl border border-slate-100 dark:border-slate-700">
                <div className="flex items-center gap-3">
                    <div className="w-3.5 h-3.5 rounded-full bg-blue-500 shadow-sm shadow-blue-500/40"></div>
                    <span className="text-[10px] font-black text-slate-500 dark:text-slate-400 uppercase tracking-widest">Livros</span>
                </div>
                <div className="flex items-center gap-3">
                    <div className="w-3.5 h-3.5 rounded-full bg-indigo-500 shadow-sm shadow-indigo-500/40"></div>
                    <span className="text-[10px] font-black text-slate-500 dark:text-slate-400 uppercase tracking-widest">Páginas</span>
                </div>
            </div>
            </div>
            <MonthlyChart data={stats.monthly} />
        </div>

        <div className="xl:col-span-4 bg-white dark:bg-slate-900 p-10 rounded-[3rem] shadow-soft border border-slate-100 dark:border-slate-800 flex flex-col min-h-[500px] overflow-hidden">
            <h2 className="text-2xl font-black font-serif text-slate-900 dark:text-slate-50 mb-8 italic text-center xl:text-left">Distribuição</h2>
            <div className="flex-1 flex items-center justify-center -mt-4">
                <TypePieChart data={stats.byType} />
            </div>
            <p className="text-[9px] font-black text-slate-400 dark:text-slate-600 uppercase tracking-widest text-center mt-4">✦ Análise baseada em toda sua estante</p>
        </div>
      </div>
    </div>
  );
};

import React, { useState } from 'react';
import { Recommendation, Book } from '../types';
import { ExternalLinkIcon, HeartIcon } from './Icons';

interface RecommendationsProps {
  suggestions: Recommendation[];
  isLoading: boolean;
  onRefresh: () => void;
  onAddWishlist: (rec: Recommendation) => Promise<void>;
  existingBooks: Book[];
}

export const Recommendations: React.FC<RecommendationsProps> = ({ suggestions, isLoading, onRefresh, onAddWishlist, existingBooks }) => {
  const [localAddedTitles, setLocalAddedTitles] = useState<Set<string>>(new Set());
  const hasNoSuggestions = !isLoading && suggestions.length === 0;

  const isAlreadyInLibrary = (title: string) => {
    return existingBooks.some(b => b.title.toLowerCase() === title.toLowerCase()) || localAddedTitles.has(title.toLowerCase());
  };

  const handleAdd = async (rec: Recommendation) => {
    await onAddWishlist(rec);
    setLocalAddedTitles(prev => new Set(prev).add(rec.title.toLowerCase()));
  };

  return (
    <div className="space-y-8 animate-in fade-in duration-700">
      <div className="flex flex-col sm:flex-row justify-between items-start sm:items-end gap-4">
        <div>
          <div className="flex items-center gap-3 mb-2">
            <h2 className="text-3xl font-black font-serif text-slate-900 dark:text-slate-50 italic tracking-tight">
              Curadoria Digital
            </h2>
            <span className="flex items-center gap-1.5 px-3 py-1 rounded-full bg-primary/10 text-primary text-[10px] font-black uppercase tracking-widest ring-1 ring-primary/20 animate-pulse">
              <span className="w-1.5 h-1.5 rounded-full bg-primary"></span>
              IA Intelligence
            </span>
          </div>
          <p className="text-slate-400 dark:text-slate-500 text-sm font-medium italic">
            Sugestões personalizadas para expandir seus horizontes literários.
          </p>
        </div>
        <button 
          onClick={onRefresh}
          disabled={isLoading}
          className="group flex items-center gap-2 text-[10px] font-black uppercase tracking-[0.2em] text-slate-400 hover:text-primary transition-all disabled:opacity-30"
        >
          {isLoading ? (
            <span className="flex items-center gap-2">
              <div className="w-3 h-3 border-2 border-primary border-t-transparent rounded-full animate-spin"></div>
              Consultando...
            </span>
          ) : (
            <>
              <svg xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24" strokeWidth={2.5} stroke="currentColor" className="w-4 h-4 group-hover:rotate-180 transition-transform duration-500">
                <path strokeLinecap="round" strokeLinejoin="round" d="M16.023 9.348h4.992v-.001M2.985 19.644v-4.992m0 0h4.992m-4.993 0 3.181 3.183a8.25 8.25 0 0 0 13.803-3.7M4.031 9.865a8.25 8.25 0 0 1 13.803-3.7l3.181 3.182m0-4.991v4.99" />
              </svg>
              Atualizar Recomendações
            </>
          )}
        </button>
      </div>

      <div className="grid grid-cols-1 md:grid-cols-3 gap-8">
        {isLoading ? (
            [1, 2, 3].map(i => (
                <div key={i} className="bg-white dark:bg-slate-900 p-8 rounded-[2.5rem] border border-slate-100 dark:border-slate-800 space-y-6 relative overflow-hidden">
                    <div className="absolute top-0 left-0 w-full h-1 bg-slate-50 dark:bg-slate-800">
                        <div className="h-full bg-primary/20 w-1/3 animate-[shimmer_2s_infinite]"></div>
                    </div>
                    <div className="h-4 bg-slate-100 dark:bg-slate-800 rounded-full w-24"></div>
                    <div className="space-y-3">
                        <div className="h-6 bg-slate-50 dark:bg-slate-800 rounded-full w-full"></div>
                        <div className="h-6 bg-slate-50 dark:bg-slate-800 rounded-full w-2/3"></div>
                    </div>
                    <div className="space-y-2">
                        <div className="h-2.5 bg-slate-50 dark:bg-slate-800 rounded-full w-full"></div>
                        <div className="h-2.5 bg-slate-50 dark:bg-slate-800 rounded-full w-full"></div>
                        <div className="h-2.5 bg-slate-50 dark:bg-slate-800 rounded-full w-3/4"></div>
                    </div>
                </div>
            ))
        ) : hasNoSuggestions ? (
            <div className="md:col-span-3 py-16 bg-slate-50/50 dark:bg-slate-900/50 rounded-[3rem] border-2 border-dashed border-slate-100 dark:border-slate-800 flex flex-col items-center justify-center text-center">
                <p className="text-slate-400 font-bold italic">Não foi possível gerar recomendações agora. Tente novamente mais tarde.</p>
            </div>
        ) : (
            suggestions.map((rec, idx) => {
                const alreadyAdded = isAlreadyInLibrary(rec.title);
                return (
                    <div key={idx} className="group bg-white dark:bg-slate-900 p-8 rounded-[2.5rem] border border-slate-100 dark:border-slate-800 shadow-soft hover:shadow-2xl hover:-translate-y-2 transition-all duration-500 cursor-default relative overflow-hidden flex flex-col h-full">
                        {/* Background Detail */}
                        <div className="absolute -right-12 -top-12 w-40 h-40 bg-primary/5 dark:bg-primary/10 rounded-full blur-3xl group-hover:scale-150 transition-transform duration-700"></div>

                        <div className="relative z-10 flex-1">
                            <div className="flex items-center gap-2 mb-6">
                                <span className="px-3 py-1 rounded-lg bg-slate-50 dark:bg-slate-800 border border-slate-100 dark:border-slate-700 text-slate-400 dark:text-slate-500 text-[9px] font-black uppercase tracking-widest">
                                    {rec.genre}
                                </span>
                            </div>

                            <h3 className="text-2xl font-black text-slate-900 dark:text-slate-50 leading-tight mb-2 group-hover:text-primary transition-colors font-serif italic">
                                {rec.title}
                            </h3>
                            <p className="text-sm text-slate-400 dark:text-slate-500 font-bold mb-6 tracking-tight">de {rec.author}</p>

                            <div className="relative">
                                <div className="absolute -left-4 top-0 bottom-0 w-1 bg-primary/20 rounded-full"></div>
                                <p className="text-xs text-slate-500 dark:text-slate-400 leading-relaxed font-medium italic pl-2">
                                    "{rec.reason}"
                                </p>
                            </div>
                        </div>

                        <div className="relative z-10 mt-8 pt-6 border-t border-slate-50 dark:border-slate-800 space-y-3">
                            {rec.buyLink && (
                                <a 
                                    href={rec.buyLink}
                                    target="_blank"
                                    rel="noopener noreferrer"
                                    className="w-full py-3.5 bg-slate-900 dark:bg-slate-100 text-white dark:text-slate-900 text-[10px] font-black uppercase tracking-[0.2em] rounded-2xl flex items-center justify-center gap-3 hover:bg-primary dark:hover:bg-primary dark:hover:text-white transition-all shadow-xl active:scale-95"
                                >
                                    Adquirir Obra <ExternalLinkIcon className="h-4 w-4" />
                                </a>
                            )}
                            {alreadyAdded ? (
                                <div className="w-full py-3.5 bg-emerald-50 dark:bg-emerald-900/20 text-emerald-600 dark:text-emerald-400 text-[10px] font-black uppercase tracking-[0.2em] rounded-2xl flex items-center justify-center border border-emerald-100 dark:border-emerald-800">
                                    Já na Lista
                                </div>
                            ) : (
                                <button 
                                    onClick={() => handleAdd(rec)}
                                    className="w-full py-3.5 bg-white dark:bg-slate-800 text-primary border border-primary/20 dark:border-slate-700 text-[10px] font-black uppercase tracking-[0.2em] rounded-2xl flex items-center justify-center gap-3 hover:bg-primary/5 transition-all active:scale-95"
                                >
                                    <HeartIcon className="h-4 w-4" />
                                    Salvar nos Desejos
                                </button>
                            )}
                        </div>
                    </div>
                );
            })
        )}
      </div>
    </div>
  );
};

