                </div>
                <h2 className="text-3xl font-black font-serif italic text-slate-900 dark:text-white leading-tight">
                    {book.title}
                </h2>
                <p className="text-lg font-bold text-slate-400 dark:text-slate-500 mt-1">
                    de {authorsList.join(', ')}
