            )}

            <span className="px-2.5 py-1 md:px-3 md:py-1.5 rounded-lg md:rounded-xl text-[8px] md:text-[10px] font-black uppercase tracking-widest border bg-slate-50 dark:bg-slate-800 text-slate-500 border-slate-100">
